bool _isIgnorableAuthError(Object error, StackTrace stack) {
  final message = error.toString().toLowerCase();
  // GoTrue's recoverSession() throws AuthRetryableFetchException when the
  // device is offline. These are expected and should not crash the app.
  return message.contains('authretryablefetchexception') ||
      message.contains('failed host lookup') ||
      message.contains('socketexception') ||
      (message.contains('clientexception') && message.contains('supabase'));
}

// Notification limits (mirrors lib/utils/notification_limits.dart,
// supabase/functions/_shared/notification_limits.ts, DB CHECKs).
// FCM/APNs = 4096 bytes total; byte-based because Hebrew/emoji are multi-byte.
const int kBroadcastTitleMaxChars = 60;
const int kBroadcastTitleMaxBytes = 200;
const int kBroadcastMessageMaxChars = 180;
const int kBroadcastMessageMaxBytes = 1000;
const int kBroadcastActionTextMaxChars = 30;

int _notifUtf8Bytes(String s) => utf8.encode(s).length;

String? _validateBroadcastTitle(String? v, LocalizationState l10n) {
  final t = (v ?? '').trim();
  if (t.isEmpty) return l10n.getString('adminBroadcastsTitleRequired');
  if (t.length > kBroadcastTitleMaxChars) {
    return l10n
        .getString('adminBroadcastsTitleTooLong')
        .replaceAll('{max}', '$kBroadcastTitleMaxChars')
        .replaceAll('{actual}', '${t.length}');
  }
  final b = _notifUtf8Bytes(t);
  if (b > kBroadcastTitleMaxBytes) {
    return l10n
        .getString('adminBroadcastsTitleTooManyBytes')
        .replaceAll('{max}', '$kBroadcastTitleMaxBytes')
        .replaceAll('{actual}', '$b');
  }
  return null;
}

String? _validateBroadcastMessage(String? v, LocalizationState l10n) {
  final t = (v ?? '').trim();
  if (t.isEmpty) return l10n.getString('adminBroadcastsMessageRequired');
  if (t.length > kBroadcastMessageMaxChars) {
    return l10n
        .getString('adminBroadcastsMessageTooLong')
        .replaceAll('{max}', '$kBroadcastMessageMaxChars')
        .replaceAll('{actual}', '${t.length}');
  }
  final b = _notifUtf8Bytes(t);
  if (b > kBroadcastMessageMaxBytes) {
    return l10n
        .getString('adminBroadcastsMessageTooManyBytes')
        .replaceAll('{max}', '$kBroadcastMessageMaxBytes')
        .replaceAll('{actual}', '$b');
  }
  return null;
}

String? _validateBroadcastActionText(String? v, [LocalizationState? l10n]) {
  final t = (v ?? '').trim();
  if (t.isEmpty) return null;
  if (t.length > kBroadcastActionTextMaxChars) {
    final template =
        l10n?.getString('adminBroadcastsActionTextTooLong') ??
        'Max {max} chars ({actual})';
    return template
        .replaceAll('{max}', '$kBroadcastActionTextMaxChars')
        .replaceAll('{actual}', '${t.length}');
  }
  return null;
}

/// Live "typed / max" counter text, resolved from Supabase translations
/// (`adminBroadcastsCounter`) with English fallback in `_defaultTranslations`.
/// Byte count matters because Hebrew/emoji are multi-byte (FCM = 4096B).
(String, bool) _broadcastCounter(
  String raw,
  int maxChars,
  int maxBytes,
  LocalizationState l10n,
) {
  final t = raw.trim();
  final chars = t.length;
  final bytes = _notifUtf8Bytes(t);
  final over = chars > maxChars || bytes > maxBytes;
  final text = l10n
      .getString('adminBroadcastsCounter')
      .replaceAll('{chars}', '$chars')
      .replaceAll('{maxChars}', '$maxChars')
      .replaceAll('{bytes}', '$bytes')
      .replaceAll('{maxBytes}', '$maxBytes');
  return (text, over);
}

Widget _broadcastCounterLine(
  String raw,
  int maxChars,
  int maxBytes,
  BuildContext context,
  LocalizationState l10n,
) {
  final (text, over) = _broadcastCounter(raw, maxChars, maxBytes, l10n);
  return Align(
    alignment: Alignment.centerLeft,
    child: Padding(
      padding: const EdgeInsets.only(top: 2),
      child: Text(
        text,
        style: Theme.of(context).textTheme.bodySmall?.copyWith(
          color: over ? Theme.of(context).colorScheme.error : Colors.grey,
        ),
      ),
    ),
  );
}

Future<void> main() async {
  WidgetsFlutterBinding.ensureInitialized();

  // Suppress auth recovery errors from GoTrue when offline.
  // GoTrue internally calls recoverSession() / refreshSession() which attempt
  // to refresh the access token. When the device is offline these fail with
  // AuthRetryableFetchException (wrapping SocketException). These are expected
  // and should not cause the app to display a red error screen.
  PlatformDispatcher.instance.onError = (error, stack) {
    if (_isIgnorableAuthError(error, stack)) {
      debugPrint('🔐 [ADMIN] Suppressing expected auth-recovery error: $error');
      return true;
    }
    return false;
  };

  final prevFlutterErrorHandler = FlutterError.onError;
  FlutterError.onError = (FlutterErrorDetails details) {
    final error = details.exception;
    final stack = details.stack ?? StackTrace.current;
    if (_isIgnorableAuthError(error, stack)) {
      debugPrint('🔐 [ADMIN] Suppressing expected auth-recovery error: $error');
      return;
    }
    prevFlutterErrorHandler?.call(details);
    FlutterError.presentError(details);
  };

  // Initialize Hive for offline storage first
  await AdminLocalDbService.instance;

  // Early connectivity probe: if there is no network transport at all, force
  // offline mode immediately so every provider skips doomed Supabase calls.
  try {
    final connectivityResults = await Connectivity().checkConnectivity();
    final hasTransport = !connectivityResults.contains(ConnectivityResult.none);
    if (!hasTransport) {
      debugPrint(
        '⏱️ [ADMIN BOOTSTRAP] No network transport detected - forcing offline mode',
      );
      adminOfflineCacheManager.setSupabaseAvailability(false, force: true);
    }
  } catch (e) {
    debugPrint('⏱️ [ADMIN BOOTSTRAP] Connectivity check failed: $e');
  }

  final config = await _resolveSupabaseRuntimeConfig();
  final supabaseUrl = config.url;
  final supabaseAnonKey = config.anonKey;

  if (supabaseUrl.isNotEmpty && supabaseAnonKey.isNotEmpty) {
    // Add timeout for Supabase initialization to prevent hanging when service
    // is unavailable (Same pattern as main MatchMe app).
    const supabaseInitTimeout = Duration(seconds: 15);
    try {
      await Supabase.initialize(
        url: supabaseUrl,
        publishableKey: supabaseAnonKey,
      ).timeout(
        supabaseInitTimeout,
        onTimeout: () {
          debugPrint(
            '⚠️ [ADMIN BOOTSTRAP] Supabase initialization timed out after ${supabaseInitTimeout.inSeconds}s',
          );
          throw TimeoutException(
            'Supabase initialization timeout',
            supabaseInitTimeout,
          );
        },
      );
    } on TimeoutException {
      debugPrint(
        '⚠️ [ADMIN BOOTSTRAP] Supabase initialization timeout caught - using offline mode',
      );
      adminOfflineCacheManager.setSupabaseAvailability(false, force: true);
    } catch (e) {
      debugPrint('⚠️ [ADMIN BOOTSTRAP] Supabase initialization error: $e');
      // Continue with offline mode
    }
  }

  // Attempt offline session recovery if Supabase initialization produced no session
  if (supabaseUrl.isNotEmpty && supabaseAnonKey.isNotEmpty) {
    try {
      if (Supabase.instance.client.auth.currentSession == null) {
        debugPrint(
          '⏱️ [ADMIN BOOTSTRAP] No session after init, attempting persisted session recovery...',
        );
        await AdminSessionService.recoverPersistedSupabaseSession().timeout(
          const Duration(seconds: 3),
        );
      }
    } catch (e) {
      debugPrint('⚠️ [ADMIN BOOTSTRAP] Session recovery failed: $e');
    }
  }

  await LocalizationNotifier.initSavedLocale();

  runApp(
    ProviderScope(
      overrides: [
        // Initialize the sync manager provider
        adminSyncManagerProvider.overrideWith((ref) => AdminSyncManager(ref)),
      ],
      child: const AdminApp(),
    ),
  );
}

void _disposeTextControllersLater(List<TextEditingController> controllers) {
  unawaited(
    Future<void>.delayed(const Duration(milliseconds: 250)).then((_) {
      for (final c in controllers) {
        c.dispose();
      }
    }),
  );
}

bool isRtlText(String text) {
  bool isStrongRtl(int rune) {
    return (rune >= 0x0590 && rune <= 0x08FF) ||
        (rune >= 0xFB1D && rune <= 0xFEFC);
  }

  bool isStrongLtr(int rune) {
    return (rune >= 0x0041 && rune <= 0x005A) ||
        (rune >= 0x0061 && rune <= 0x007A);
  }

  for (final rune in text.runes) {
    if (isStrongRtl(rune)) return true;
    if (isStrongLtr(rune)) return false;
  }
  return false;
}

class _AdminCacheHit<T> {
  final T data;
  final bool isFresh;

  const _AdminCacheHit({required this.data, required this.isFresh});
}

class _AdminCacheEntry {
  final int tsMs;
  final Object? data;

  const _AdminCacheEntry({required this.tsMs, required this.data});
}

class _AdminCache {
  static const Duration ttl = Duration(minutes: 5);
  static final Map<String, _AdminCacheEntry> _memory = {};

  static int _nowMs() => DateTime.now().millisecondsSinceEpoch;

  static bool _isFresh(int tsMs) {
    return (_nowMs() - tsMs) <= ttl.inMilliseconds;
  }

  static Future<_AdminCacheEntry?> _readPersisted(String key) async {
    final prefs = await SharedPreferences.getInstance();
    final raw = prefs.getString(key);
    if (raw == null || raw.trim().isEmpty) return null;
    try {
      final decoded = jsonDecode(raw);
      if (decoded is! Map) return null;
      final ts = decoded['ts'];
      final data = decoded['data'];
      final tsMs = ts is int ? ts : int.tryParse(ts.toString());
      if (tsMs == null) return null;
      return _AdminCacheEntry(tsMs: tsMs, data: data);
    } catch (_) {
      return null;
    }
  }

  static Future<_AdminCacheEntry?> readRaw(String key) async {
    final mem = _memory[key];
    if (mem != null) return mem;
    final entry = await _readPersisted(key);
    if (entry == null) return null;
    _memory[key] = entry;
    return entry;
  }

  /// Synchronously read and decode from in-memory cache.
  /// Returns null if not in memory or decode fails.
  static T? readMemorySync<T>(String key, T Function(Object? raw) decode) {
    final entry = _memory[key];
    if (entry == null) return null;
    try {
      return decode(entry.data);
    } catch (_) {
      return null;
    }
  }

  static Future<void> writeRaw(String key, Object? data) async {
    final entry = _AdminCacheEntry(tsMs: _nowMs(), data: data);
    _memory[key] = entry;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString(
      key,
      jsonEncode(<String, Object?>{'ts': entry.tsMs, 'data': data}),
    );
  }

  static Future<_AdminCacheHit<T>?> read<T>(
    String key,
    T Function(Object? raw) decode,
  ) async {
    final entry = await readRaw(key);
    if (entry == null) return null;
    try {
      return _AdminCacheHit<T>(
        data: decode(entry.data),
        isFresh: _isFresh(entry.tsMs),
      );
    } catch (_) {
      return null;
    }
  }

  static Future<void> write<T>(
    String key,
    Object? Function(T value) encode,
    T value,
  ) async {
    await writeRaw(key, encode(value));
  }
}

String uiLanguageNameFallback(LocalizationState l10n, String code) {
  final normalized = code.trim().toLowerCase();
  return switch (normalized) {
    'en' => l10n.getString('adminIntentsInterestsLocaleEn'),
    'es' => l10n.getString('adminIntentsInterestsLocaleEs'),
    'he' => l10n.getString('adminIntentsInterestsLocaleHe'),
    _ => normalized.toUpperCase(),
  };
}

/// Check if translations for a specific language code are cached in the admin
/// local cache. Returns true if cached translations exist and are non-empty.
Future<bool> _isAdminLanguageCached(String code) async {
  Map<String, String> decode(Object? raw) {
    if (raw is! Map) return const {};
    final out = <String, String>{};
    for (final e in raw.entries) {
      final k = e.key.toString();
      final v = e.value?.toString() ?? '';
      if (k.isNotEmpty) out[k] = v;
    }
    return out;
  }

  final cacheKey = 'admin_cache:l10n:$code';
  final cached = await _AdminCache.read<Map<String, String>>(cacheKey, decode);
  return cached != null && cached.data.isNotEmpty;
}

/// Build language options for the admin language picker, including whether
/// each language can be used in the current connectivity state. The logic
/// mirrors the main MatchMe app's [languageOptionsProvider]:
/// - English is always available offline.
/// - Other languages are only available offline if their translations have
///   been previously downloaded and cached.
Future<List<Map<String, dynamic>>> _buildAdminLanguageOptions(
  LocalizationState l10n,
) async {
  final names = await loadUiLanguageDisplayNames();
  final isOffline = adminOfflineCacheManager.shouldUseCachedData();

  final result = <Map<String, dynamic>>[];
  final codes = names.keys.toList(growable: false)..sort();

  for (final code in codes) {
    final normalized = code.trim().toLowerCase();
    final display =
        names[normalized] ?? uiLanguageNameFallback(l10n, normalized);
    final isCached = await _isAdminLanguageCached(code);
    final canUse = !isOffline || code == 'en' || isCached;

    result.add(<String, dynamic>{
      'code': code,
      'display': display,
      'canUse': canUse,
    });
  }

  return result;
}

/// Shows a dialog explaining that a language has not been downloaded and
/// cannot be selected while offline. Identical to the main MatchMe app's
/// [_showOfflineLanguageUnavailableDialog] in auth_screen.dart.
Future<void> _showAdminOfflineLanguageUnavailableDialog(
  BuildContext context,
  LocalizationState l10n,
) async {
  await showDialog<void>(
    context: context,
    builder: (BuildContext ctx) => AlertDialog(
      icon: const Icon(Icons.cloud_off_rounded, size: 32, color: Colors.orange),
      title: Text(l10n.getString('offlineLanguageUnavailableTitle')),
      content: Text(l10n.getString('offlineLanguageUnavailableMessage')),
      actions: [
        TextButton(
          onPressed: () => Navigator.of(ctx).pop(),
          child: Text(l10n.getString('offlineOkButton')),
        ),
      ],
    ),
  );
}

String maskUserDisplayName(String raw) {
  final s = raw.trim();
  if (s.isEmpty) return s;
  final parts = s
      .split(RegExp(r'\s+'))
      .map((e) => e.trim())
      .where((e) => e.isNotEmpty)
      .toList(growable: false);
  if (parts.isEmpty) return s;
  if (parts.length == 1) return parts.first;
  final first = parts.first;
  final last = parts.last;
  if (last.isEmpty) return first;
  return '$first ${last[0].toUpperCase()}.';
}

Future<Map<String, String>> loadUiLanguageDisplayNames() async {
  Map<String, String> decode(Object? raw) {
    if (raw is! Map) return const {};
    final m = Map<String, dynamic>.from(raw);
    final out = <String, String>{};
    for (final entry in m.entries) {
      final k = entry.key.toString().trim().toLowerCase();
      final v = (entry.value ?? '').toString().trim();
      if (k.isEmpty || v.isEmpty) continue;
      out[k] = v;
    }
    return out;
  }

  const cacheKey = 'admin_cache:app_languages:v1:display_name:en_es_he';
  final cached = await _AdminCache.read<Map<String, String>>(cacheKey, decode);
  if (cached != null) {
    if (cached.isFresh) return cached.data;
    unawaited(_AdminCache.readRaw(cacheKey).then((_) {}));
  }

  // Try Hive as a secondary cache (from sync manager's _syncSupportedLanguages)
  Map<String, String> hiveNames() {
    try {
      final rows = AdminLocalDbService.shared.loadSectionDataSync(
        'supported_languages',
      );
      if (rows.isEmpty) return const {};
      final out = <String, String>{};
      for (final m in rows) {
        final code = (m['language_code'] ?? '').toString().trim().toLowerCase();
        final name = (m['display_name'] ?? '').toString().trim();
        if (code.isEmpty || name.isEmpty) continue;
        out[code] = name;
      }
      return out;
    } catch (_) {
      return const {};
    }
  }

  try {
    final rowsRaw = await publicReferenceDataService
        .fetchSupportedLanguages()
        .timeout(const Duration(seconds: 8));

    final rows = List<Map<String, dynamic>>.from(rowsRaw);
    final out = <String, String>{};
    for (final m in rows) {
      final code = (m['language_code'] ?? '').toString().trim().toLowerCase();
      final name = (m['display_name'] ?? '').toString().trim();
      if (code.isEmpty || name.isEmpty) continue;
      out[code] = name;
    }

    // Also persist to Hive for offline availability
    try {
      await AdminLocalDbService.shared.saveSectionData(
        'supported_languages',
        rows,
      );
    } catch (_) {}

    await _AdminCache.write<Map<String, String>>(cacheKey, (v) => v, out);
    return out;
  } catch (_) {
    final hive = hiveNames();
    if (hive.isNotEmpty) return hive;
    return cached?.data ?? const {};
  }
}

class _SupabaseRuntimeConfig {
  final String url;
  final String anonKey;
  const _SupabaseRuntimeConfig({required this.url, required this.anonKey});
}

String _stripOptionalQuotes(String value) {
  final trimmed = value.trim();
  if (trimmed.length >= 2 &&
      ((trimmed.startsWith('"') && trimmed.endsWith('"')) ||
          (trimmed.startsWith("'") && trimmed.endsWith("'")))) {
    return trimmed.substring(1, trimmed.length - 1);
  }
  return trimmed;
}

String _sanitizeSupabaseAnonKey(String value) {
  return _stripOptionalQuotes(value).replaceAll(RegExp(r'\s+'), '');
}

Map<String, String> _parseDotEnvString(String raw) {
  final map = <String, String>{};
  for (final line in raw.split('\n')) {
    final trimmed = line.trim();
    if (trimmed.isEmpty) continue;
    if (trimmed.startsWith('#')) continue;
    final eq = trimmed.indexOf('=');
    if (eq <= 0) continue;
    final key = trimmed.substring(0, eq).trim();
    final value = trimmed.substring(eq + 1).trim();
    if (key.isEmpty) continue;
    map[key] = _stripOptionalQuotes(value);
  }
  return map;
}

Future<Map<String, String>> _loadDotEnvFromAssets() async {
  try {
    final raw = await rootBundle.loadString('assets/.env');
    return _parseDotEnvString(raw);
  } catch (_) {
    return const {};
  }
}

Future<_SupabaseRuntimeConfig> _resolveSupabaseRuntimeConfig() async {
  var url = const String.fromEnvironment('SUPABASE_URL');
  var anonKey = const String.fromEnvironment('SUPABASE_ANON_KEY');

  final qp = Uri.base.queryParameters;
  if (url.isEmpty) {
    url = qp['SUPABASE_URL'] ?? qp['supabase_url'] ?? '';
  }
  if (anonKey.isEmpty) {
    anonKey = qp['SUPABASE_ANON_KEY'] ?? qp['supabase_anon_key'] ?? '';
  }

  if (url.isEmpty || anonKey.isEmpty) {
    final env = await _loadDotEnvFromAssets();
    if (url.isEmpty) url = env['SUPABASE_URL'] ?? '';
    if (anonKey.isEmpty) anonKey = env['SUPABASE_ANON_KEY'] ?? '';
  }

  return _SupabaseRuntimeConfig(
    url: _stripOptionalQuotes(url),
    anonKey: _sanitizeSupabaseAnonKey(anonKey),
  );
}

String _normalizeErrorText(Object error) {
  if (error is AuthException) {
    return error.message.trim().toLowerCase();
  }
  return error.toString().trim().toLowerCase();
}

bool _errorTextContainsAny(String text, List<String> needles) {
  for (final needle in needles) {
    if (text.contains(needle)) return true;
  }
  return false;
}

bool _isLikelyNetworkError(Object error) {
  final text = _normalizeErrorText(error);
  return _errorTextContainsAny(text, const [
    'clientexception',
    'connection closed',
    'connection refused',
    'connection reset',
    'failed host lookup',
    'handshakeexception',
    'network request failed',
    'network is unreachable',
    'socketexception',
    'timed out',
    'timeout',
    'xmlhttprequest error',
  ]);
}

String _adminLoginErrorKeyForAuthException(AuthException error) {
  final text = _normalizeErrorText(error);
  if (_errorTextContainsAny(text, const [
    'bad credentials',
    'email or password',
    'invalid credentials',
    'invalid login credentials',
    'invalid_grant',
  ])) {
    return 'authInvalidCredentials';
  }
  if (_errorTextContainsAny(text, const [
    'email not confirmed',
    'email_not_confirmed',
  ])) {
    return 'authEmailNotConfirmed';
  }
  if (_isLikelyNetworkError(error)) {
    return 'authNetworkError';
  }
  return 'authLoginServiceError';
}

String _adminLoginErrorKeyForUnexpectedError(Object error) {
  if (_isLikelyNetworkError(error)) {
    return 'authNetworkError';
  }
  return 'authLoginServiceError';
}

String _adminAccessErrorKeyForError(Object error) {
  if (_isLikelyNetworkError(error)) {
    return 'authNetworkError';
  }
  return 'adminAuthCheckFailed';
}

class LocalizationState {
  final Locale locale;
  final TextDirection textDirection;
  final Map<String, String> strings;
  final bool isLoading;

  const LocalizationState({
    required this.locale,
    required this.textDirection,
    required this.strings,
    required this.isLoading,
  });

  factory LocalizationState.initial() => const LocalizationState(
    locale: Locale('en'),
    textDirection: TextDirection.ltr,
    strings: {},
    isLoading: true,
  );

  LocalizationState copyWith({
    Locale? locale,
    TextDirection? textDirection,
    Map<String, String>? strings,
    bool? isLoading,
  }) {
    return LocalizationState(
      locale: locale ?? this.locale,
      textDirection: textDirection ?? this.textDirection,
      strings: strings ?? this.strings,
      isLoading: isLoading ?? this.isLoading,
    );
  }

  String getString(String key) {
    final translation = strings[key];
    if (translation != null && translation.isNotEmpty) return translation;
    final fallback = _defaultTranslations[key];
    if (fallback != null && fallback.isNotEmpty) return fallback;
    return '$key...';
  }
}

DateFormat _adminDateTimeFormat(LocalizationState l10n) {
  final code = l10n.locale.languageCode.trim();
  final locale = code.isEmpty ? 'en' : code;
  return DateFormat.yMMMd(locale).add_jm();
}

String _formatAdminDateTime(LocalizationState l10n, DateTime dt) {
  return _adminDateTimeFormat(l10n).format(dt.toLocal());
}

class LocalizationNotifier extends Notifier<LocalizationState> {
  int _loadSeq = 0;

  static String? _savedLocale;

  static Future<void> initSavedLocale() async {
    final prefs = await SharedPreferences.getInstance();
    _savedLocale = prefs.getString('admin_ui_locale');
  }

  @override
  LocalizationState build() {
    final initial = _savedLocale != null
        ? supportedLocales.firstWhere(
            (l) => l.languageCode == _savedLocale,
            orElse: () => const Locale('en'),
          )
        : supportedLocales.firstWhere(
            (l) =>
                l.languageCode ==
                WidgetsBinding.instance.platformDispatcher.locale.languageCode,
            orElse: () => const Locale('en'),
          );
    Future.microtask(() => setLocale(initial.languageCode));
    return LocalizationState.initial();
  }

  static const supportedLocales = <Locale>[
    Locale('en'),
    Locale('es'),
    Locale('he'),
  ];

  Future<void> setLocale(String languageCode, {bool force = false}) async {
    final locale = supportedLocales.firstWhere(
      (l) => l.languageCode == languageCode,
      orElse: () => const Locale('en'),
    );

    if (!force &&
        state.locale.languageCode == locale.languageCode &&
        !state.isLoading) {
      return;
    }

    final requestId = ++_loadSeq;
    final direction = (locale.languageCode == 'he')
        ? TextDirection.rtl
        : TextDirection.ltr;

    Map<String, String> decodeStringMap(Object? raw) {
      if (raw is! Map) return const {};
      final out = <String, String>{};
      for (final e in raw.entries) {
        final k = e.key.toString();
        final v = e.value?.toString() ?? '';
        if (k.isNotEmpty) out[k] = v;
      }
      return out;
    }

    final cacheKey = 'admin_cache:l10n:${locale.languageCode}';
    final cached = await _AdminCache.read<Map<String, String>>(
      cacheKey,
      decodeStringMap,
    );
    if (requestId != _loadSeq) return;

    state = state.copyWith(
      locale: locale,
      textDirection: direction,
      strings: cached?.data ?? const {},
      isLoading: cached == null,
    );

    _savedLocale = locale.languageCode;
    final prefs = await SharedPreferences.getInstance();
    await prefs.setString('admin_ui_locale', locale.languageCode);

    if (!force && cached != null && cached.isFresh) return;

    final strings = await _fetchTranslations(locale.languageCode);
    if (requestId != _loadSeq) return;

    state = state.copyWith(strings: strings, isLoading: false);
    await _AdminCache.write<Map<String, String>>(cacheKey, (v) => v, strings);
  }

  Future<void> patchTranslationValue({
    required String locale,
    required String key,
    required String value,
  }) async {
    Map<String, String> decodeStringMap(Object? raw) {
      if (raw is! Map) return const {};
      final out = <String, String>{};
      for (final e in raw.entries) {
        final k = e.key.toString();
        final v = e.value?.toString() ?? '';
        if (k.isNotEmpty) out[k] = v;
      }
      return out;
    }

    final trimmedLocale = locale.trim().toLowerCase();
    final trimmedKey = key.trim();
    if (trimmedLocale.isEmpty || trimmedKey.isEmpty) return;

    final cacheKey = 'admin_cache:l10n:$trimmedLocale';
    final cached = await _AdminCache.read<Map<String, String>>(
      cacheKey,
      decodeStringMap,
    );
    if (cached != null) {
      final updated = Map<String, String>.from(cached.data);
      updated[trimmedKey] = value;
      await _AdminCache.write<Map<String, String>>(cacheKey, (v) => v, updated);
    }

    if (state.locale.languageCode == trimmedLocale) {
      final updated = Map<String, String>.from(state.strings);
      updated[trimmedKey] = value;
      state = state.copyWith(strings: updated);
    }
  }

  Future<Map<String, String>> _fetchTranslations(String languageCode) async {
    // Skip edge-function call when offline to avoid long timeouts.
    if (!adminOfflineCacheManager.isSupabaseAvailable) {
      return const {};
    }

    try {
      return await publicReferenceDataService
          .fetchTranslations(languageCode)
          .timeout(const Duration(seconds: 10));
    } catch (_) {
      return const {};
    }
  }
}

final localizationProvider =
    NotifierProvider<LocalizationNotifier, LocalizationState>(() {
      return LocalizationNotifier();
    });

final sessionProvider = StreamProvider<Session?>((ref) {
  final controller = StreamController<Session?>();
  final auth = Supabase.instance.client.auth;

  bool disposed = false;
  bool initialEventEmitted = false;
  Timer? initialEventTimeout;

  Future<void> emitInitialEvent() async {
    if (initialEventEmitted || disposed) return;
    initialEventEmitted = true;
    initialEventTimeout?.cancel();
    if (auth.currentSession == null) {
      await AdminSessionService.recoverPersistedSupabaseSession();
    }
    if (!disposed) {
      controller.add(auth.currentSession);
    }
  }

  controller.add(auth.currentSession);

  final sub = auth.onAuthStateChange.listen(
    (event) {
      if (disposed) return;

      Session? effectiveSession = event.session;
      if (effectiveSession == null && auth.currentSession != null) {
        effectiveSession = auth.currentSession;
      }

      if (!initialEventEmitted &&
          event.event == AuthChangeEvent.initialSession &&
          effectiveSession == null) {
        initialEventEmitted = true;
        initialEventTimeout?.cancel();
        unawaited(() async {
          final recovered =
              await AdminSessionService.recoverPersistedSupabaseSession();
          if (!disposed) {
            controller.add(recovered ? auth.currentSession : null);
          }
        }());
        return;
      }

      if (!initialEventEmitted) {
        initialEventEmitted = true;
        initialEventTimeout?.cancel();
      }

      if (event.event == AuthChangeEvent.signedOut) {
        if (AdminSessionService.consumeExplicitUserSignOutFlag()) {
          unawaited(
            AdminSessionService.clearPersistedSupabaseSessionSnapshot(),
          );
        }
      } else if (effectiveSession != null) {
        unawaited(AdminSessionService.persistCurrentSupabaseSessionSnapshot());
      }

      if (event.event == AuthChangeEvent.signedIn && effectiveSession != null) {
        unawaited(AdminSessionService.setSessionCreatedAt());
      }

      controller.add(effectiveSession);
    },
    onError: (Object error, StackTrace stackTrace) {
      if (_isIgnorableAuthError(error, stackTrace)) return;
      debugPrint('[ADMIN] Auth stream error: $error');
    },
  );

  if (auth.currentSession == null) {
    initialEventTimeout = Timer(
      const Duration(seconds: 1),
      () => unawaited(emitInitialEvent()),
    );
  }

  ref.onDispose(() {
    disposed = true;
    initialEventTimeout?.cancel();
    sub.cancel();
    controller.close();
  });

  return controller.stream;
});

final isAdminProvider = FutureProvider<bool>((ref) async {
  final sessionAsync = ref.watch(sessionProvider);
  final session = sessionAsync.asData?.value;
  if (session == null) return false;

  final userId = session.user.id;
  bool decodeBool(Object? raw) {
    if (raw == true) return true;
    if (raw == false) return false;
    return raw.toString().toLowerCase() == 'true';
  }

  final cacheKey = 'admin_cache:is_admin:v1:$userId';
  final cached = await _AdminCache.read<bool>(cacheKey, decodeBool);
  if (cached != null && cached.isFresh) return cached.data;

  try {
    final row = await Supabase.instance.client
        .from('users')
        .select('is_admin')
        .eq('id', userId)
        .maybeSingle()
        .timeout(const Duration(seconds: 2));
    final isAdmin = row != null && row['is_admin'] == true;
    await _AdminCache.write<bool>(cacheKey, (v) => v, isAdmin);
    return isAdmin;
  } catch (_) {
    return cached?.data ?? false;
  }
});

