class _BootstrapGate extends ConsumerWidget {
  const _BootstrapGate();

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final l10n = ref.watch(localizationProvider);

    // When offline mode is already forced (timeout or connectivity check),
    // skip the Supabase instance check and go directly to the auth gate.
    // The auth gate will show the login screen (no recovered session) or
    // an appropriate offline message.
    if (adminOfflineCacheManager.shouldUseCachedData()) {
      return const _AuthGate();
    }

    var isSupabaseReady = true;
    try {
      Supabase.instance.client;
    } catch (_) {
      isSupabaseReady = false;
    }
    if (!isSupabaseReady) {
      // Check if we're offline as a fallback — the flag might have been
      // set by the connectivity probe but Supabase.init might still be
      // running. If we can't reach Supabase, go to auth gate anyway.
      if (adminOfflineCacheManager.shouldUseCachedData()) {
        return const _AuthGate();
      }
      return _MessageScaffold(
        title: l10n.getString('adminAppTitle'),
        body: l10n.getString('supabaseConfigMissing'),
      );
    }

    if (l10n.isLoading) {
      return _MessageScaffold(
        title: l10n.getString('adminAppTitle'),
        body: l10n.getString('generalLoading'),
        showSpinner: true,
      );
    }

    return const _AuthGate();
  }
}

class _AuthGate extends ConsumerWidget {
  const _AuthGate();

  static String? _lastForcedSignOutCheckedUserId;

  Future<void> _checkAdminForcedSignOut(WidgetRef ref, Session session) async {
    final userId = session.user.id;
    if (_lastForcedSignOutCheckedUserId == userId) return;
    _lastForcedSignOutCheckedUserId = userId;

    // Use session_created_at stored at login time
    final createdAt = await AdminSessionService.getSessionCreatedAt();
    if (createdAt == null) return;

    try {
      final row = await Supabase.instance.client
          .from('app_config')
          .select('config_value')
          .eq('config_key', 'auth.forced_sign_out_days')
          .maybeSingle()
          .timeout(const Duration(seconds: 5));
      final rawDays = row?['config_value'];
      final days = switch (rawDays) {
        int v => v,
        num v => v.toInt(),
        String v => int.tryParse(v.replaceAll('"', '')) ?? 0,
        _ => 0,
      };
      if (days <= 0) return;
      if (DateTime.now().isBefore(createdAt.add(Duration(days: days)))) return;
      await AdminSessionService.persistSignOutReason(
        reason: 'Forced sign-out after $days days',
        source: 'adminForcedSignOutCheck',
      );
      AdminSessionService.markExplicitUserSignOut();
      await Supabase.instance.client.auth.signOut();
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final sessionAsync = ref.watch(sessionProvider);

    ref.listen<AsyncValue<Session?>>(sessionProvider, (prev, next) {
      next.whenData((session) {
        if (session != null) {
          unawaited(_checkAdminForcedSignOut(ref, session));
        }
      });
    });

    return sessionAsync.when(
      data: (session) {
        if (session == null) return const _LoginScreen();
        final isAdminAsync = ref.watch(isAdminProvider);
        return isAdminAsync.when(
          data: (isAdmin) {
            if (!isAdmin) {
              return const _KickoutToLogin(messageKey: 'adminNotAuthorized');
            }
            return const _AdminShell();
          },
          loading: () {
            final l10n = ref.watch(localizationProvider);
            return _MessageScaffold(
              title: l10n.getString('adminAppTitle'),
              body: l10n.getString('generalLoading'),
              showSpinner: true,
            );
          },
          error: (err, st) {
            final l10n = ref.watch(localizationProvider);
            return _MessageScaffold(
              title: l10n.getString('adminAppTitle'),
              body: l10n.getString('adminAuthCheckFailed'),
            );
          },
        );
      },
      loading: () {
        final l10n = ref.watch(localizationProvider);
        return _MessageScaffold(
          title: l10n.getString('adminAppTitle'),
          body: l10n.getString('generalLoading'),
          showSpinner: true,
        );
      },
      error: (err, st) {
        final l10n = ref.watch(localizationProvider);
        return _MessageScaffold(
          title: l10n.getString('adminAppTitle'),
          body: l10n.getString('authStreamError'),
        );
      },
    );
  }
}

class _KickoutToLogin extends ConsumerStatefulWidget {
  final String messageKey;

  const _KickoutToLogin({required this.messageKey});

  @override
  ConsumerState<_KickoutToLogin> createState() => _KickoutToLoginState();
}

class _KickoutToLoginState extends ConsumerState<_KickoutToLogin> {
  bool _started = false;

  @override
  void initState() {
    super.initState();
    Future.microtask(_run);
  }

  Future<void> _run() async {
    if (_started) return;
    _started = true;
    await AdminSessionService.persistSignOutReason(
      reason: 'User not authorized as admin',
      source: 'kickout',
    );
    ref.read(adminLoginBannerKeyProvider.notifier).setKey(widget.messageKey);
    try {
      // NOT marking as explicit — preserve persisted session for offline recovery
      await Supabase.instance.client.auth.signOut();
    } catch (_) {}
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    return _MessageScaffold(
      title: l10n.getString('adminAppTitle'),
      body: l10n.getString('generalLoading'),
      showSpinner: true,
    );
  }
}

class _MessageScaffold extends StatelessWidget {
  final String title;
  final String body;
  final bool showSpinner;

  const _MessageScaffold({
    required this.title,
    required this.body,
    this.showSpinner = false,
  });

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: Text(title)),
      body: SafeArea(
        child: Center(
          child: ConstrainedBox(
            constraints: const BoxConstraints(maxWidth: 520),
            child: Padding(
              padding: const EdgeInsets.all(24),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  if (showSpinner) ...[
                    const CircularProgressIndicator(),
                    const SizedBox(height: 16),
                  ],
                  Text(body, textAlign: TextAlign.center),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }
}

class _LoginScreen extends ConsumerStatefulWidget {
  const _LoginScreen();

  @override
  ConsumerState<_LoginScreen> createState() => _LoginScreenState();
}

class _LoginScreenState extends ConsumerState<_LoginScreen>
    with SingleTickerProviderStateMixin {
  static const _rememberAdminEmailKey = 'admin_login:remembered_email:v1';
  static const _rememberAdminEmailEnabledKey =
      'admin_login:remember_email_enabled:v1';

  final _emailController = TextEditingController();
  final _passwordController = TextEditingController();
  final _formKey = GlobalKey<FormState>();
  final _emailFocusNode = FocusNode();
  final _passwordFocusNode = FocusNode();
  bool _isSubmitting = false;
  bool _obscurePassword = true;
  bool _rememberEmail = false;
  String? _errorKey;
  int _debugTapCount = 0;
  Timer? _debugTapTimer;
  late final AnimationController _entranceController;
  late final Animation<double> _fadeAnimation;
  late final Animation<double> _scaleAnimation;
  late final Animation<Offset> _slideAnimation;
  late final Future<List<Map<String, dynamic>>> _loginLanguageOptionsFuture =
      _lazyLanguageOptions();

  Future<List<Map<String, dynamic>>> _lazyLanguageOptions() async {
    // Capture a snapshot of the current localization state at creation time.
    // This lazy future is initialized once in initState so the FutureBuilder
    // always receives the same future instance, avoiding mid-lifecycle
    // rebuild flickers.
    return _buildAdminLanguageOptions(ref.read(localizationProvider));
  }

  @override
  void initState() {
    super.initState();
    _entranceController = AnimationController(
      vsync: this,
      duration: const Duration(milliseconds: 520),
    );
    _fadeAnimation = CurvedAnimation(
      parent: _entranceController,
      curve: Curves.easeOutCubic,
    );
    _scaleAnimation = Tween<double>(begin: 0.985, end: 1).animate(
      CurvedAnimation(parent: _entranceController, curve: Curves.easeOutBack),
    );
    _slideAnimation =
        Tween<Offset>(begin: const Offset(0, 0.04), end: Offset.zero).animate(
          CurvedAnimation(
            parent: _entranceController,
            curve: Curves.easeOutCubic,
          ),
        );
    _emailController.addListener(_clearInlineError);
    _passwordController.addListener(_clearInlineError);
    unawaited(_loadRememberedEmail());
    unawaited(_entranceController.forward());
  }

  void _clearInlineError() {
    if (_errorKey == null || !mounted) return;
    setState(() {
      _errorKey = null;
    });
  }

  Future<void> _loadRememberedEmail() async {
    final prefs = await SharedPreferences.getInstance();
    final remember = prefs.getBool(_rememberAdminEmailEnabledKey) ?? false;
    final email = prefs.getString(_rememberAdminEmailKey)?.trim() ?? '';
    if (!mounted) return;
    setState(() {
      _rememberEmail = remember;
      if (remember && email.isNotEmpty) {
        _emailController.text = email;
      }
    });
  }

  Future<void> _persistRememberedEmailPreference() async {
    final prefs = await SharedPreferences.getInstance();
    await prefs.setBool(_rememberAdminEmailEnabledKey, _rememberEmail);
    if (_rememberEmail) {
      await prefs.setString(
        _rememberAdminEmailKey,
        _emailController.text.trim(),
      );
    } else {
      await prefs.remove(_rememberAdminEmailKey);
    }
  }

  Future<void> _setRememberEmail(bool value) async {
    setState(() {
      _rememberEmail = value;
    });
    await _persistRememberedEmailPreference();
  }

  bool _isValidEmail(String value) {
    final trimmed = value.trim();
    if (trimmed.isEmpty) return false;
    return RegExp(r'^[^@\s]+@[^@\s]+\.[^@\s]+$').hasMatch(trimmed);
  }

  bool _isRetryableErrorKey(String? key) {
    return key == 'authNetworkError' || key == 'authLoginServiceError';
  }

  Widget _buildLoginHeader({
    required ColorScheme colorScheme,
    required TextTheme textTheme,
    required LocalizationState l10n,
    required bool compact,
  }) {
    return Column(
      crossAxisAlignment: compact
          ? CrossAxisAlignment.center
          : CrossAxisAlignment.start,
      children: [
        GestureDetector(
          onTap: () {
            // Re-bind l10n from the outer scope if needed; we just call the handler
            _onDebugLogoTap();
          },
          child: Container(
            width: compact ? 76 : 84,
            height: compact ? 76 : 84,
            decoration: BoxDecoration(
              gradient: LinearGradient(
                colors: [
                  colorScheme.primaryContainer,
                  colorScheme.secondaryContainer,
                ],
                begin: Alignment.topLeft,
                end: Alignment.bottomRight,
              ),
              shape: BoxShape.circle,
              boxShadow: [
                BoxShadow(
                  color: colorScheme.primary.withValues(alpha: 0.14),
                  blurRadius: 28,
                  offset: const Offset(0, 12),
                ),
              ],
            ),
            child: Icon(
              Icons.admin_panel_settings_outlined,
              color: colorScheme.onPrimaryContainer,
              size: compact ? 38 : 42,
            ),
          ),
        ),
        SizedBox(height: compact ? 24 : 28),
        Text(
          l10n.getString('adminLoginTitle'),
          textAlign: compact ? TextAlign.center : TextAlign.start,
          style: (compact ? textTheme.headlineSmall : textTheme.headlineMedium)
              ?.copyWith(fontWeight: FontWeight.w700),
        ),
        const SizedBox(height: 10),
        Text(
          l10n.getString('adminLoginSubtitle'),
          textAlign: compact ? TextAlign.center : TextAlign.start,
          style: textTheme.titleMedium?.copyWith(
            color: colorScheme.onSurfaceVariant,
            height: 1.35,
          ),
        ),
        const SizedBox(height: 18),
        Align(
          alignment: compact
              ? Alignment.center
              : AlignmentDirectional.centerStart,
          child: Container(
            padding: const EdgeInsets.symmetric(horizontal: 14, vertical: 9),
            decoration: BoxDecoration(
              color: colorScheme.secondaryContainer,
              borderRadius: BorderRadius.circular(999),
              border: Border.all(
                color: colorScheme.outlineVariant.withValues(alpha: 0.7),
              ),
            ),
            child: Text(
              l10n.getString('adminLoginAuthorizedOnly'),
              style: textTheme.labelLarge?.copyWith(
                color: colorScheme.onSecondaryContainer,
                fontWeight: FontWeight.w700,
                letterSpacing: 0.2,
              ),
            ),
          ),
        ),
        const SizedBox(height: 18),
        Text(
          l10n.getString('adminLoginHelper'),
          textAlign: compact ? TextAlign.center : TextAlign.start,
          style: textTheme.bodyLarge?.copyWith(
            color: colorScheme.onSurfaceVariant,
            height: 1.45,
          ),
        ),
      ],
    );
  }

  Widget _buildTroublePanel({
    required ColorScheme colorScheme,
    required TextTheme textTheme,
    required LocalizationState l10n,
  }) {
    return Container(
      padding: const EdgeInsets.all(18),
      decoration: BoxDecoration(
        color: colorScheme.surfaceContainerHighest.withValues(alpha: 0.72),
        borderRadius: BorderRadius.circular(18),
        border: Border.all(
          color: colorScheme.outlineVariant.withValues(alpha: 0.65),
        ),
      ),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Row(
            children: [
              Icon(
                Icons.tips_and_updates_outlined,
                size: 20,
                color: colorScheme.primary,
              ),
              const SizedBox(width: 10),
              Expanded(
                child: Text(
                  l10n.getString('adminLoginTroubleTitle'),
                  style: textTheme.titleSmall?.copyWith(
                    fontWeight: FontWeight.w700,
                  ),
                ),
              ),
            ],
          ),
          const SizedBox(height: 10),
          Text(
            l10n.getString('adminLoginTroubleBody'),
            style: textTheme.bodyMedium?.copyWith(
              color: colorScheme.onSurfaceVariant,
              height: 1.4,
            ),
          ),
        ],
      ),
    );
  }

  @override
  void dispose() {
    _entranceController.dispose();
    _emailController.dispose();
    _passwordController.dispose();
    _emailFocusNode.dispose();
    _passwordFocusNode.dispose();
    super.dispose();
  }

  void _onDebugLogoTap() {
    _debugTapCount++;
    _debugTapTimer?.cancel();
    _debugTapTimer = Timer(const Duration(seconds: 3), () {
      _debugTapCount = 0;
    });
    if (_debugTapCount >= 7) {
      _debugTapCount = 0;
      _debugTapTimer?.cancel();
      _showDebugSignOutReasonDialog();
    }
  }

  Future<void> _showDebugSignOutReasonDialog() async {
    final reason = await AdminSessionService.getLastSignOutReason();
    final l10n = ref.read(localizationProvider);
    if (!mounted) return;
    showDialog<void>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Debug: Last Sign-Out'),
        content: Text(
          reason != null
              ? 'Reason: ${reason['reason']}\n'
                    'Source: ${reason['source']}\n'
                    'Time: ${reason['timestamp']}'
              : 'No sign-out reason recorded.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(),
            child: Text(l10n.getString('generalClose')),
          ),
        ],
      ),
    );
  }

  Future<void> _signIn() async {
    if (_isSubmitting) return;
    final isValid = _formKey.currentState?.validate() ?? false;
    if (!isValid) return;

    setState(() {
      _isSubmitting = true;
      _errorKey = null;
    });
    ref.read(adminLoginBannerKeyProvider.notifier).setKey(null);
    await _persistRememberedEmailPreference();

    try {
      await Supabase.instance.client.auth.signInWithPassword(
        email: _emailController.text.trim(),
        password: _passwordController.text,
      );
    } on AuthException catch (error, st) {
      developer.log(
        'Admin sign-in failed',
        name: 'matchme_admin.auth',
        error: error,
        stackTrace: st,
      );
      _errorKey = _adminLoginErrorKeyForAuthException(error);
    } catch (error, st) {
      developer.log(
        'Admin sign-in failed unexpectedly',
        name: 'matchme_admin.auth',
        error: error,
        stackTrace: st,
      );
      _errorKey = _adminLoginErrorKeyForUnexpectedError(error);
    }

    if (_errorKey == null) {
      final userId = Supabase.instance.client.auth.currentUser?.id;
      if (userId == null) {
        _errorKey = 'authLoginServiceError';
      } else {
        try {
          final row = await Supabase.instance.client
              .from('users')
              .select('is_admin')
              .eq('id', userId)
              .maybeSingle();
          final isAdmin = row != null && row['is_admin'] == true;
          if (!isAdmin) {
            ref
                .read(adminLoginBannerKeyProvider.notifier)
                .setKey('adminNotAuthorized');
            try {
              await Supabase.instance.client.auth.signOut();
            } catch (_) {}
          }
        } catch (error, st) {
          developer.log(
            'Admin access check failed after sign-in',
            name: 'matchme_admin.auth',
            error: error,
            stackTrace: st,
          );
          _errorKey = _adminAccessErrorKeyForError(error);
        }
      }
    }

    if (!mounted) return;
    setState(() {
      _isSubmitting = false;
    });
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final locale = l10n.locale.languageCode;
    final bannerKey = ref.watch(adminLoginBannerKeyProvider);
    final colorScheme = Theme.of(context).colorScheme;
    final textTheme = Theme.of(context).textTheme;

    return Scaffold(
      appBar: AppBar(
        title: Text(l10n.getString('adminLoginTitle')),
        actions: [
          Padding(
            padding: const EdgeInsets.symmetric(horizontal: 12),
            child: DropdownButtonHideUnderline(
              child: FutureBuilder<List<Map<String, dynamic>>>(
                future: _loginLanguageOptionsFuture,
                builder: (context, snapshot) {
                  final languageOptions = snapshot.data ?? [];

                  return DropdownButton<String>(
                    value: locale,
                    items: languageOptions
                        .map((lang) {
                          final code = lang['code'] as String;
                          final display = lang['display'] as String;
                          final canUse = lang['canUse'] as bool;

                          return DropdownMenuItem<String>(
                            value: code,
                            child: Row(
                              mainAxisSize: MainAxisSize.min,
                              children: [
                                Text(
                                  display,
                                  style: TextStyle(
                                    color: canUse ? null : Colors.grey.shade400,
                                  ),
                                ),
                                if (!canUse)
                                  Padding(
                                    padding: const EdgeInsets.only(left: 6),
                                    child: Icon(
                                      Icons.lock_outline,
                                      size: 16,
                                      color: Colors.grey.shade400,
                                    ),
                                  ),
                              ],
                            ),
                          );
                        })
                        .toList(growable: false),
                    onChanged: (value) async {
                      if (value == null) return;
                      final selected = languageOptions
                          .cast<Map<String, dynamic>?>()
                          .firstWhere(
                            (l) => l?['code'] == value,
                            orElse: () => null,
                          );
                      final canUse = selected?['canUse'] as bool? ?? true;
                      if (!canUse && context.mounted) {
                        await _showAdminOfflineLanguageUnavailableDialog(
                          context,
                          l10n,
                        );
                        return;
                      }
                      ref.read(localizationProvider.notifier).setLocale(value);
                    },
                  );
                },
              ),
            ),
          ),
        ],
      ),
      body: SafeArea(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final isWide = constraints.maxWidth >= 980;
            final horizontalPadding = constraints.maxWidth >= 1200
                ? 40.0
                : 24.0;
            final cardPadding = isWide
                ? const EdgeInsets.symmetric(horizontal: 36, vertical: 34)
                : constraints.maxWidth >= 600
                ? const EdgeInsets.all(32)
                : const EdgeInsets.all(24);

            final formContent = Form(
              key: _formKey,
              child: AutofillGroup(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    if (!isWide) ...[
