                      focusNode: _emailFocusNode,
                      decoration: InputDecoration(
                        labelText: l10n.getString('authEmail'),
                        prefixIcon: const Icon(Icons.email_outlined),
                        filled: true,
                      ),
                      keyboardType: TextInputType.emailAddress,
                      textInputAction: TextInputAction.next,
                      autofillHints: const [
                        AutofillHints.username,
                        AutofillHints.email,
                      ],
                      autocorrect: false,
                      enableSuggestions: false,
                      onFieldSubmitted: (_) {
                        _passwordFocusNode.requestFocus();
                      },
                      validator: (v) {
                        final value = v?.trim() ?? '';
                        if (value.isEmpty) {
                          return l10n.getString('authEmailRequired');
                        }
                        if (!_isValidEmail(value)) {
                          return l10n.getString('authEmailInvalid');
                        }
                        return null;
                      },
                    ),
                    const SizedBox(height: 16),
                    TextFormField(
                      controller: _passwordController,
                      focusNode: _passwordFocusNode,
                      decoration: InputDecoration(
                        labelText: l10n.getString('authPassword'),
                        prefixIcon: const Icon(Icons.lock_outline),
                        filled: true,
                        suffixIcon: IconButton(
                          tooltip: l10n.getString(
                            _obscurePassword
                                ? 'authPasswordShow'
                                : 'authPasswordHide',
                          ),
                          onPressed: () {
                            setState(() {
                              _obscurePassword = !_obscurePassword;
                            });
                          },
                          icon: Icon(
                            _obscurePassword
                                ? Icons.visibility_outlined
                                : Icons.visibility_off_outlined,
                          ),
                        ),
                      ),
                      obscureText: _obscurePassword,
                      textInputAction: TextInputAction.done,
                      autofillHints: const [AutofillHints.password],
                      onFieldSubmitted: (_) => _signIn(),
                      validator: (v) {
                        if (v == null || v.isEmpty) {
                          return l10n.getString('authPasswordRequired');
                        }
                        return null;
                      },
                    ),
                    const SizedBox(height: 10),
                    CheckboxListTile(
                      value: _rememberEmail,
