class _LazyIndexedStack extends StatefulWidget {
  final int index;
  final List<Widget> children;

  const _LazyIndexedStack({required this.index, required this.children});

  @override
  State<_LazyIndexedStack> createState() => _LazyIndexedStackState();
}

class _LazyIndexedStackState extends State<_LazyIndexedStack> {
  late final List<bool> _built = List<bool>.filled(
    widget.children.length,
    false,
  );

  @override
  void initState() {
    super.initState();
    if (widget.children.isNotEmpty) {
      final i = widget.index.clamp(0, widget.children.length - 1);
      _built[i] = true;
    }
  }

  @override
  void didUpdateWidget(covariant _LazyIndexedStack oldWidget) {
    super.didUpdateWidget(oldWidget);

    if (widget.children.length != oldWidget.children.length) {
      final old = List<bool>.from(_built);
      _built
        ..clear()
        ..addAll(List<bool>.filled(widget.children.length, false));
      for (var i = 0; i < old.length && i < _built.length; i++) {
        _built[i] = old[i];
      }
    }

    if (widget.children.isNotEmpty) {
      final i = widget.index.clamp(0, widget.children.length - 1);
      if (!_built[i]) {
        _built[i] = true;
      }
    }
  }

  @override
  Widget build(BuildContext context) {
    if (widget.children.isEmpty) return const SizedBox.shrink();

    final i = widget.index.clamp(0, widget.children.length - 1);
    return Stack(
      children: [
        for (var idx = 0; idx < widget.children.length; idx++)
          Offstage(
            offstage: idx != i,
            child: TickerMode(
              enabled: idx == i,
              child: _built[idx]
                  ? widget.children[idx]
                  : const SizedBox.shrink(),
            ),
          ),
      ],
    );
  }
}

class _AdminShell extends ConsumerStatefulWidget {
