class _AdminShellState extends ConsumerState<_AdminShell>
    with WidgetsBindingObserver {
  _AdminSection _selected = _AdminSection.dashboard;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    final syncManager = ref.read(adminSyncManagerProvider);
    syncManager.onAppLifecycleStateChanged(state);
  }

  Future<void> _signOut() async {
    try {
      ref.read(adminLoginBannerKeyProvider.notifier).setKey(null);
      AdminSessionService.markExplicitUserSignOut();
      await Supabase.instance.client.auth.signOut();
    } catch (_) {}
  }

