  Future<void> _showLanguagePicker(
    BuildContext context,
    WidgetRef ref,
    LocalizationState l10n,
  ) async {
    final languageOptions = await _buildAdminLanguageOptions(l10n);

    if (!context.mounted) return;

    await showDialog<void>(
      context: context,
      builder: (dialogContext) {
        final currentCode = l10n.locale.languageCode;

        return AlertDialog(
          title: Text(l10n.getString('authSelectLanguage')),
          content: SizedBox(
            width: double.maxFinite,
            child: ListView.builder(
              shrinkWrap: true,
              itemCount: languageOptions.length,
              itemBuilder: (context, index) {
                final lang = languageOptions[index];
                final code = lang['code'] as String;
                final display = lang['display'] as String;
                final canUse = lang['canUse'] as bool;
                final isActive = code == currentCode;
                final textColor = canUse
                    ? (isActive ? Colors.black : null)
                    : Colors.grey.shade400;

                return ListTile(
                  selected: isActive,
                  leading: Icon(
                    canUse
                        ? (isActive ? Icons.check_circle : Icons.language)
                        : Icons.lock_outline,
                    color: textColor,
                  ),
                  title: Text(
                    display,
                    style: TextStyle(
                      color: textColor,
                      fontWeight: isActive ? FontWeight.bold : null,
                    ),
                  ),
                  onTap: () async {
                    if (!canUse) {
                      Navigator.of(dialogContext).pop();
                      if (context.mounted) {
                        await _showAdminOfflineLanguageUnavailableDialog(
                          context,
                          l10n,
                        );
                      }
                      return;
                    }

                    Navigator.of(dialogContext).pop();
                    ref.read(localizationProvider.notifier).setLocale(code);
                  },
                );
              },
            ),
          ),
        );
      },
    );
  }

  List<Widget> _appBarActions(LocalizationState l10n) {
    return [
      IconButton(
        tooltip: l10n.getString('adminChangeLanguage'),
        icon: const Icon(Icons.translate),
        onPressed: () => _showLanguagePicker(context, ref, l10n),
      ),
      IconButton(
        tooltip: l10n.getString('authSignOut'),
        onPressed: _signOut,
        icon: l10n.textDirection == TextDirection.rtl
            ? Transform(
                alignment: Alignment.center,
                transform: Matrix4.diagonal3Values(-1.0, 1.0, 1.0),
                child: const Icon(Icons.logout),
              )
            : const Icon(Icons.logout),
      ),
    ];
  }

  String _sectionTitle(LocalizationState l10n, _AdminSection section) {
    return switch (section) {
      _AdminSection.dashboard => l10n.getString('adminNavDashboard'),
      _AdminSection.appConfig => l10n.getString('adminNavAppConfig'),
      _AdminSection.translations => l10n.getString('adminNavTranslations'),
      _AdminSection.subscriptions => l10n.getString('adminNavSubscriptions'),
      _AdminSection.sponsoredAds => l10n.getString('adminNavSponsoredAds'),
      _AdminSection.broadcasts => l10n.getString('adminNavBroadcasts'),
      _AdminSection.intentsInterests => l10n.getString(
        'adminNavIntentsInterests',
      ),
      _AdminSection.userVerification => l10n.getString('adminNavVerification'),
      _AdminSection.profileEdits => l10n.getString('adminNavProfileEdits'),
      _AdminSection.eventImportFeedback => l10n.getString(
        'adminNavEventFeedback',
      ),
      _AdminSection.promoCodes => l10n.getString('adminNavPromoCodes'),
      _AdminSection.matchInspector => l10n.getString('adminNavMatchInspector'),
      _AdminSection.userMatchManagement => l10n.getString(
        'adminNavUserMatchManagement',
      ),
      _AdminSection.delivery => 'Delivery',
      _AdminSection.systemHealth => l10n.getString('adminNavSystemHealth'),
    };
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);

    return Directionality(
      textDirection: l10n.textDirection,
      child: LayoutBuilder(
        builder: (context, constraints) {
          final selectedIndex = _AdminSection.values.indexOf(_selected);
          final content = _LazyIndexedStack(
            index: selectedIndex,
            children: [
              _DashboardScreen(
                onOpenSystemHealth:
                    () => setState(() => _selected = _AdminSection.systemHealth),
              ),
              const _AppConfigScreen(),
              const _TranslationsScreen(),
              const _SubscriptionsScreen(),
              const _SponsoredAdsScreen(),
              const _BroadcastsScreen(),
              const _IntentsInterestsScreen(),
              const _UserVerificationScreen(),
              const _ProfileEditRequestsScreen(),
              const _EventImportFeedbackScreen(),
              const _PromoCodesScreen(),
              const _MatchInspectorScreen(),
              const _UserMatchManagementScreen(),
              const _DeliveryScreen(),
              const _SystemHealthScreen(),
            ],
          );
          final useDrawerLayout =
              constraints.maxWidth < 720 || constraints.maxHeight < 520;
          final titleText = _sectionTitle(l10n, _selected);
          if (useDrawerLayout) {
            return Scaffold(
              appBar: AppBar(
                title: Text(titleText),
                actions: _appBarActions(l10n),
              ),
              drawer: NavigationDrawer(
                selectedIndex: selectedIndex,
                onDestinationSelected: (index) {
                  setState(() {
                    _selected = _AdminSection.values[index];
                  });
                  Navigator.of(context).pop();
                },
                children: [
                  Padding(
                    padding: const EdgeInsets.fromLTRB(16, 24, 16, 8),
                    child: Text(
                      l10n.getString('adminAppTitle'),
                      style: Theme.of(context).textTheme.titleLarge,
                    ),
                  ),
                  const Divider(height: 1),
                  ..._drawerDestinations(l10n),
                ],
              ),
              body: SafeArea(
                child: Column(
                  children: [
                    AdminOfflineIndicator(
                      t: (key, {params}) => l10n.getString(key),
                    ),
                    Expanded(child: content),
                  ],
                ),
              ),
            );
          }

          final isWide = constraints.maxWidth >= 1000;
          final rail = NavigationRail(
            selectedIndex: selectedIndex,
            onDestinationSelected: (index) {
              setState(() {
                _selected = _AdminSection.values[index];
              });
            },
            destinations: _railDestinations(l10n),
            extended: isWide,
          );

          return Scaffold(
            appBar: AppBar(
              title: Text(titleText),
              actions: _appBarActions(l10n),
            ),
            body: SafeArea(
              child: Column(
                children: [
                  AdminOfflineIndicator(
                    t: (key, {params}) => l10n.getString(key),
                  ),
                  Expanded(
                    child: Row(
                      children: [
                        rail,
                        const VerticalDivider(width: 1),
                        Expanded(child: content),
                      ],
                    ),
                  ),
                ],
              ),
            ),
          );
        },
      ),
    );
  }
}

/// Pulsing green dot indicating a live/realtime data feed.
class _LivePulseIndicator extends StatefulWidget {
  const _LivePulseIndicator();

  @override
  State<_LivePulseIndicator> createState() => _LivePulseIndicatorState();
}

class _LivePulseIndicatorState extends State<_LivePulseIndicator>
    with SingleTickerProviderStateMixin {
  late final AnimationController _controller;
  late final Animation<double> _animation;

  @override
  void initState() {
    super.initState();
    _controller = AnimationController(
      vsync: this,
      duration: const Duration(seconds: 2),
    )..repeat(reverse: true);
    _animation = Tween<double>(begin: 0.4, end: 1.0).animate(_controller);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    return FadeTransition(
      opacity: _animation,
      child: Container(
        width: 8,
        height: 8,
        decoration: const BoxDecoration(
          color: Colors.green,
          shape: BoxShape.circle,
        ),
      ),
    );
  }
}

class _AdminDashboardWindowHeaderDelegate
    extends SliverPersistentHeaderDelegate {
  final String window;
  final ValueChanged<String> onChanged;
  final LocalizationState l10n;
  final double height;

  const _AdminDashboardWindowHeaderDelegate({
    required this.window,
    required this.onChanged,
    required this.l10n,
    required this.height,
  });

  @override
  double get minExtent => height;

  @override
  double get maxExtent => height;

  @override
  Widget build(
    BuildContext context,
    double shrinkOffset,
    bool overlapsContent,
  ) {
    return SizedBox(
      height: maxExtent,
      child: Material(
        color: Theme.of(context).scaffoldBackgroundColor,
        child: Padding(
          padding: const EdgeInsets.symmetric(horizontal: 16),
          child: SizedBox(
            width: double.infinity,
            height: maxExtent,
            child: DecoratedBox(
              decoration: ShapeDecoration(
                color: Theme.of(context).scaffoldBackgroundColor,
                shape: const StadiumBorder(),
              ),
              child: ClipPath(
                clipper: ShapeBorderClipper(shape: const StadiumBorder()),
                child: Stack(
                  children: [
                    Row(
                      children: [
                        _buildWindowOption(
                          context: context,
                          value: '24h',
                          label: l10n.getString('adminDashboardWindow24h'),
                          isFirst: true,
                        ),
                        _buildWindowOption(
                          context: context,
                          value: '7d',
                          label: l10n.getString('adminDashboardWindow7d'),
                          isFirst: false,
                        ),
                      ],
                    ),
                    Positioned.fill(
                      child: IgnorePointer(
                        child: DecoratedBox(
                          decoration: ShapeDecoration(
                            shape: StadiumBorder(
                              side: BorderSide(
                                color: Theme.of(context).colorScheme.outline,
                                width: 1.5,
                              ),
                            ),
                          ),
                        ),
                      ),
                    ),
                  ],
                ),
              ),
            ),
          ),
        ),
      ),
    );
  }

  Widget _buildWindowOption({
    required BuildContext context,
    required String value,
    required String label,
    required bool isFirst,
  }) {
    final isSelected = window == value;
    final colorScheme = Theme.of(context).colorScheme;
    return Expanded(
      child: Semantics(
        button: true,
        selected: isSelected,
        label: label,
        child: InkWell(
          onTap: isSelected ? null : () => onChanged(value),
          child: Container(
            height: maxExtent,
            decoration: BoxDecoration(
              color: isSelected ? colorScheme.primaryContainer : null,
              border: isFirst
                  ? BorderDirectional(
                      end: BorderSide(color: colorScheme.outline, width: 1.5),
                    )
                  : null,
            ),
            alignment: Alignment.center,
            padding: const EdgeInsets.symmetric(horizontal: 12),
            child: Row(
              mainAxisAlignment: MainAxisAlignment.center,
              children: [
                if (isSelected) ...[
                  Icon(Icons.check, size: 20, color: colorScheme.onSurface),
                  const SizedBox(width: 6),
                ],
                Flexible(
                  child: Text(
                    label,
                    maxLines: 1,
                    overflow: TextOverflow.ellipsis,
                    style: TextStyle(
                      color: colorScheme.onSurface,
                      fontSize: Theme.of(
                        context,
                      ).textTheme.labelLarge?.fontSize,
                      fontWeight: Theme.of(
                        context,
                      ).textTheme.labelLarge?.fontWeight,
                    ),
                  ),
                ),
              ],
            ),
          ),
        ),
      ),
    );
  }

  @override
  bool shouldRebuild(
    covariant _AdminDashboardWindowHeaderDelegate oldDelegate,
  ) => oldDelegate.window != window || oldDelegate.l10n != l10n;
}

class _DashboardScreen extends ConsumerStatefulWidget {
  const _DashboardScreen({this.onOpenSystemHealth});

  /// Opens the System Health nav section (set by the admin shell).
  final VoidCallback? onOpenSystemHealth;

  @override
  ConsumerState<_DashboardScreen> createState() => _DashboardScreenState();
}

class _DashboardScreenState extends ConsumerState<_DashboardScreen>
    with WidgetsBindingObserver {
  bool _isLoading = true;
  String? _errorKey;
  Map<String, dynamic>? _data;
  String _window = '24h';
  String? _dataWindow; // Tracks which time window _data belongs to
  bool _isFetching = false;
  Timer? _scheduledReload;
  Timer? _periodicRefresh;
  DateTime _lastReloadAt = DateTime.fromMillisecondsSinceEpoch(0);
  RealtimeChannel? _channel;
  RealtimeChannel? _liveCountChannel;
  StreamSubscription<bool>? _availabilitySub;

  // Realtime user counts (LIVE section)
  Map<String, dynamic>? _realtimeData;
  Timer? _realtimeBackupTimer;

  // Prefetched LIVE drilldown user lists so tapping a count shows the
  // users instantly instead of waiting for the drilldown's own RPC.
  final Map<String, List<Map<String, dynamic>>> _liveDrilldownCache = {};
  final Map<String, int?> _liveDrilldownTotals = {};
  DateTime? _lastLivePrefetchAt;
  int _lastPrefetchedOnlineCount = -1;
  int _lastPrefetchedVisibleCount = -1;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    final cur = WidgetsBinding.instance.lifecycleState;
    _isAppForeground =
        cur == null ||
        (cur != AppLifecycleState.paused &&
            cur != AppLifecycleState.hidden &&
            cur != AppLifecycleState.detached);
    _setupRealtime();
    // Listen for connectivity restoration to auto-refresh dashboard
    _availabilitySub = adminOfflineCacheManager.availabilityStream.listen((
      available,
    ) {
      if (!mounted) return;
      if (available) {
        // LIVE counts keep updating even in background; the heavy windowed
        // dashboard reload stays foreground-only to save battery/data.
        unawaited(_loadRealtime(force: true));
        if (!_isAppForeground) return;
        unawaited(_load(force: true, showLoading: false));
      }
    });
    // Periodic fallback refresh ensures all dashboard data (including revenue,
    // AI usage, edge functions) stays continuously updated. Resets on every
    // realtime tick so the timer only fires during quiet periods.
    _startPeriodicRefresh();
    // 5s backup timer for LIVE realtime counts (primary: Supabase Realtime)
    _startRealtimeBackupTimer();
    // Direct subscription to user_activity for instant LIVE count updates
    _setupLiveCountChannel();
    // Load from memory cache synchronously for immediate display (like external ads)
    _loadFromMemoryCache();
    // Then fetch fresh data
    unawaited(_load());
    unawaited(_loadRealtime());
    unawaited(_prefetchLiveDrilldown());
  }

  /// Synchronously load from in-memory cache for immediate display.
  /// Also checks Hive persistent cache as a fallback.
  void _loadFromMemoryCache() {
    try {
      Map<String, dynamic> decodeMap(Object? raw) {
        if (raw is! Map) return <String, dynamic>{};
        return Map<String, dynamic>.from(raw);
      }

      final cacheKey = 'admin_cache:dashboard:v1:$_window';
      var cached = _AdminCache.readMemorySync<Map<String, dynamic>>(
        cacheKey,
        decodeMap,
      );

      // Fall back to Hive persistent cache if not in memory
      if (cached == null || cached.isEmpty) {
        try {
          final hiveData = _getCachedDashboardSync();
          if (hiveData != null && hiveData.isNotEmpty) {
            cached = hiveData;
            // Warm up in-memory cache
            _AdminCache.writeRaw(cacheKey, hiveData);
          }
        } catch (_) {}
      }

      if (cached != null && cached.isNotEmpty) {
        setState(() {
          _data = cached;
          _dataWindow = _window;
          _isLoading = false;
        });
      }
    } catch (e) {
      // Ignore errors - will fall back to async _load()
    }
  }

  /// Synchronously load dashboard from Hive cache if available.
  Map<String, dynamic>? _getCachedDashboardSync() {
    try {
      final localDb = AdminLocalDbService.shared;
      return localDb.loadDashboardSync(window: _window);
    } catch (_) {
      return null;
    }
  }

  bool _isAppForeground = true;

  void _pausePolling() {
    // Background behavior: pause only the heavy windowed dashboard polling.
    // The lightweight LIVE online/visible counts (5s backup timer + realtime
    // channel) intentionally keep running so the cards don't freeze while
    // the app is backgrounded (OS permitting — see _loadRealtime).
    _periodicRefresh?.cancel();
    _scheduledReload?.cancel();
  }

  void _resumePolling() {
    if (!mounted) return;
    _startPeriodicRefresh();
    _startRealtimeBackupTimer();
    _scheduleReload();
    unawaited(_loadRealtime(force: false));
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      if (!_isAppForeground) {
        _isAppForeground = true;
        _resumePolling();
      } else {
        _scheduleReload();
        unawaited(_loadRealtime(force: false));
      }
    } else if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      if (_isAppForeground) {
        _isAppForeground = false;
        _pausePolling();
      }
    }
  }

  void _setupRealtime() {
    try {
      final channel = Supabase.instance.client.channel('admin-dashboard');

      void onAnyChange(PostgresChangePayload payload) {
        // LIVE counts refresh in background too; only the heavy full reload
        // (charts/revenue/AI) is foreground-gated via _scheduleReload().
        final table =
            ((payload.newRecord['last_table'] ??
                        payload.oldRecord['last_table']) ??
                    '')
                .toString();
        final op =
            ((payload.newRecord['last_op'] ?? payload.oldRecord['last_op']) ??
                    '')
                .toString();

        // Apply optimistic increments immediately for instant counter feedback
        if (table == 'chat_messages' && op == 'INSERT') {
          _applyMessageIncrement();
        } else if (op == 'INSERT') {
          _applyInsertIncrement(table);
        }

        // Always schedule a full reload on any tick — optimistic increments
        // only cover counters; revenue, AI usage, edge functions, and charts
        // need the full RPC refresh. The 800ms debounce batches rapid changes.
        _scheduleReload();

        // Also refresh the LIVE realtime counts on every tick
        unawaited(_loadRealtime(force: false));
      }

      channel.onPostgresChanges(
        event: PostgresChangeEvent.all,
        schema: 'public',
        table: 'admin_dashboard_tick',
        callback: onAnyChange,
      );

      channel.subscribe((status, error) {
        if (error != null) {
          // Re-subscribe on error with a short delay to avoid reconnect storms
          Future.delayed(const Duration(seconds: 2), () {
            if (!mounted) return;
            final old = _channel;
            if (old != null) {
              Supabase.instance.client.removeChannel(old);
            }
            _channel = null;
            _setupRealtime();
          });
        }
      });
      _channel = channel;
    } catch (_) {
      // Retry subscription on setup failure
      Future.delayed(const Duration(seconds: 5), () {
        if (!mounted) return;
        _setupRealtime();
      });
    }
  }

  void _scheduleReload() {
    if (!mounted) return;
    if (!_isAppForeground) return;
    _scheduledReload?.cancel();
    _scheduledReload = Timer(const Duration(milliseconds: 800), () {
      if (!mounted) return;
      if (!_isAppForeground) return;
      final now = DateTime.now();
      if (now.difference(_lastReloadAt) < const Duration(seconds: 2)) {
        return;
      }
      _lastReloadAt = now;
      unawaited(_load(force: true, showLoading: false));
    });
  }

  // ── Direct realtime subscription for LIVE user counts ──────────────

  Timer? _liveCountDebounce;

  void _setupLiveCountChannel() {
    try {
      // LIVE visible counts also depend on users (visibility settings) and
      // user_locations (15-min freshness), not just user_activity heartbeats.
      // Subscribe to all three so a visibility toggle or location update
      // refreshes the cards instantly instead of waiting for the 5s timer.
      // presence_tick is the RLS-safe logon/logoff signal: a single-row table
      // touched by DB triggers whenever any user's presence flips (login,
      // explicit logout, stale-online cleanup). The raw-table subscriptions
      // only deliver rows this admin can read under RLS; the tick table is
      // readable by every authenticated user, so login/logout always lands.
      // Counts still come from the SECURITY DEFINER RPC — no user data on
      // the tick itself.
      void onLiveChange(_) {
        // No foreground guard: LIVE cards keep updating in background.
        _liveCountDebounce?.cancel();
        _liveCountDebounce = Timer(const Duration(milliseconds: 800), () {
          if (mounted) unawaited(_loadRealtime(force: true));
        });
      }

      final channel = Supabase.instance.client
          .channel('live_user_counts')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_activity',
            callback: onLiveChange,
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'users',
            callback: onLiveChange,
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_locations',
            callback: onLiveChange,
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'presence_tick',
            callback: onLiveChange,
          )
          .subscribe((status, error) {
            if (error != null) {
              // Re-subscribe on error with a short delay to avoid reconnect
              // storms (same recovery as the admin-dashboard tick channel).
              Future.delayed(const Duration(seconds: 2), () {
                if (!mounted) return;
                final old = _liveCountChannel;
                if (old != null) {
                  Supabase.instance.client.removeChannel(old);
                }
                _liveCountChannel = null;
                _setupLiveCountChannel();
              });
            }
          });
      _liveCountChannel = channel;
    } catch (_) {}
  }

  // ── Realtime user counts (LIVE section) ──────────────────────────

  /// Fetches current online + visible user counts from the lightweight
  /// admin_get_realtime_user_counts() RPC. This is independent of the
  /// time-window toggle and always reflects the live state.
  /// Runs in background as well (only [mounted] + offline gated) so the
  /// LIVE cards don't freeze when the app is backgrounded. The OS may still
  /// suspend timers/sockets after a while — resume triggers a refresh.
  Future<void> _loadRealtime({bool force = true}) async {
    if (!mounted) return;
    if (adminOfflineCacheManager.shouldUseCachedData()) return;
    try {
      final res = await Supabase.instance.client
          .rpc('admin_get_realtime_user_counts')
          .timeout(const Duration(seconds: 10));
      if (!mounted) return;
      final map = (res is Map)
          ? Map<String, dynamic>.from(res)
          : <String, dynamic>{};
      setState(() {
        _realtimeData = map;
      });
      unawaited(_prefetchLiveDrilldown());
    } catch (_) {
      // Silently fail — will retry on next tick/timer.
    }
  }

  /// Prefetches the LIVE drilldown user lists in the background so tapping
  /// an online/visible count shows the users immediately. Runs on a throttle:
  /// immediately when the live counts changed, otherwise at most every 15s.
  /// (15s keeps the tap-instant cache fresh without spamming the drilldown
  /// RPC; the drilldown screen itself refreshes every 5s once opened.)
  Future<void> _prefetchLiveDrilldown() async {
    if (!mounted) return;
    // Background-safe like _loadRealtime so tap-in drilldowns are fresh
    // even after the app sat in background.
    if (adminOfflineCacheManager.shouldUseCachedData()) return;
    final now = DateTime.now();
    final last = _lastLivePrefetchAt;
    final countsChanged =
        _toInt(_realtimeData?['online_users']) != _lastPrefetchedOnlineCount ||
        _toInt(_realtimeData?['visible_users']) != _lastPrefetchedVisibleCount;
    if (last != null &&
        !countsChanged &&
        now.difference(last) < const Duration(seconds: 15)) {
      return;
    }
    _lastLivePrefetchAt = now;
    _lastPrefetchedOnlineCount = _toInt(_realtimeData?['online_users']);
    _lastPrefetchedVisibleCount = _toInt(_realtimeData?['visible_users']);

    List<Map<String, dynamic>> decodeRows(Object? raw) {
      if (raw is! List) return const <Map<String, dynamic>>[];
      return raw
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList(growable: false);
    }

    for (final metric in const ['online_users_live', 'visible_users_live']) {
      try {
        final res = await Supabase.instance.client
            .rpc(
              'admin_get_dashboard_drilldown',
              params: {
                'p_window': _window,
                'p_metric': metric,
                'p_param': null,
                'p_limit': 200,
                'p_offset': 0,
              },
            )
            .timeout(const Duration(seconds: 10));
        if (!mounted) return;
        final map = (res is Map)
            ? Map<String, dynamic>.from(res)
            : <String, dynamic>{};
        _liveDrilldownCache[metric] = decodeRows(map['rows']);
        _liveDrilldownTotals[metric] = (map['total_count'] is num)
            ? (map['total_count'] as num).toInt()
            : null;
      } catch (_) {
        // Keep the previous cache on failure; the drilldown refreshes itself.
      }
    }
  }

  /// 15-second backup timer for realtime counts. Ensures counts stay
  /// fresh even if Supabase Realtime ticks are delayed or lost.
  /// Runs in background (no foreground guard) so LIVE cards don't freeze.
  void _startRealtimeBackupTimer() {
    _realtimeBackupTimer?.cancel();
    _realtimeBackupTimer = Timer.periodic(const Duration(seconds: 5), (_) {
      if (!mounted) return;
      if (adminOfflineCacheManager.shouldUseCachedData()) return;
      unawaited(_loadRealtime(force: false));
    });
  }

  int _toInt(dynamic v) {
    if (v is int) return v;
    if (v is num) return v.toInt();
    return int.tryParse((v ?? '').toString()) ?? 0;
  }

  bool _applyMessageIncrement() {
    final current = _data;
    if (current == null || current.isEmpty) return false;
    final engagement = current['engagement'];
    if (engagement is! Map) return false;

    final next = Map<String, dynamic>.from(current);
    final nextEngagement = Map<String, dynamic>.from(engagement);
    nextEngagement['messages_sent'] =
        _toInt(nextEngagement['messages_sent']) + 1;
    next['engagement'] = nextEngagement;

    final series = current['engagement_series'];
    if (series is List && series.isNotEmpty) {
      final last = series.last;
      if (last is Map) {
        final nextSeries = series
            .map((e) => e is Map ? Map<String, dynamic>.from(e) : e)
            .toList(growable: false);
        final lastMap = Map<String, dynamic>.from(last);
        lastMap['messages'] = _toInt(lastMap['messages']) + 1;
        nextSeries[nextSeries.length - 1] = lastMap;
        next['engagement_series'] = nextSeries;
      }
    }

    if (!mounted) return false;
    setState(() {
      _data = next;
    });
    return true;
  }

  bool _applyInsertIncrement(String table) {
    final current = _data;
    if (current == null || current.isEmpty) return false;

    final engagement = current['engagement'];
    final operations = current['operations'];
    if (engagement is! Map || operations is! Map) return false;

    final next = Map<String, dynamic>.from(current);
    final nextEngagement = Map<String, dynamic>.from(engagement);
    final nextOperations = Map<String, dynamic>.from(operations);

    bool bumpEngagementKey(String key) {
      nextEngagement[key] = _toInt(nextEngagement[key]) + 1;
      next['engagement'] = nextEngagement;
      return true;
    }

    bool bumpOperationsKey(String key) {
      nextOperations[key] = _toInt(nextOperations[key]) + 1;
      next['operations'] = nextOperations;
      return true;
    }

    bool bumpSeriesKey(String key) {
      final series = current['engagement_series'];
      if (series is! List || series.isEmpty) return false;
      final last = series.last;
      if (last is! Map) return false;
      final nextSeries = series
          .map((e) => e is Map ? Map<String, dynamic>.from(e) : e)
          .toList(growable: false);
      final lastMap = Map<String, dynamic>.from(last);
      lastMap[key] = _toInt(lastMap[key]) + 1;
      nextSeries[nextSeries.length - 1] = lastMap;
      next['engagement_series'] = nextSeries;
      return true;
    }

    bool applied = false;

    switch (table) {
      case 'matches':
        applied = bumpEngagementKey('matches_created');
        applied = bumpSeriesKey('matches') || applied;
        break;
      case 'users':
        applied = bumpEngagementKey('new_users');
        applied = bumpSeriesKey('signups') || applied;
        break;
      case 'profile_edit_requests':
        applied = bumpOperationsKey('profile_edits_pending');
        break;
      case 'admin_broadcasts':
        applied = bumpOperationsKey('broadcasts_draft');
        break;
      case 'notification_queue':
        applied = bumpOperationsKey('notifications_pending');
        break;
    }

    if (!applied || !mounted) return false;
    setState(() {
      _data = next;
    });
    return true;
  }

  Future<void> _load({bool force = false, bool showLoading = true}) async {
    if (_isFetching) return;
    Map<String, dynamic> decodeMap(Object? raw) {
      if (raw is! Map) return <String, dynamic>{};
      return Map<String, dynamic>.from(raw);
    }

    final cacheKey = 'admin_cache:dashboard:v1:$_window';
    var hadCached = false;
    final hasExisting = (_dataWindow == _window && _data?.isNotEmpty == true);

    // Preload from Hive immediately so the UI renders cached data without
    // waiting for Supabase timeouts or connectivity detection to stabilize.
    if (!hasExisting) {
      await _loadFromHiveCache();
    }

    // Always display cached data immediately for fast UI rendering, but
    // never skip the Supabase fetch — we want the dashboard to reflect
    // live stats every time it is shown.  The cached data is a placeholder
    // while the network call completes.
    if (!force) {
      final cached = await _AdminCache.read<Map<String, dynamic>>(
        cacheKey,
        decodeMap,
      );
      if (!mounted) return;
      if (cached != null && cached.data.isNotEmpty) {
        setState(() {
          _data = cached.data;
          _dataWindow = _window;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
      }
    }

    if (!mounted) return;

    // If the cache manager reports Supabase unavailable, skip the RPC call
    // and load from persistent cache instead.
    final isOffline = adminOfflineCacheManager.shouldUseCachedData();
    if (isOffline && !force) {
      final loaded = await _loadFromHiveCache();
      if (!mounted) return;
      if (!loaded && !hadCached && !hasExisting) {
        setState(() {
          _errorKey = 'adminDashboardLoadFailed';
          _isLoading = false;
        });
      }
      return;
    }
    // Don't hit network while the app is backgrounded / screen off.
    if (!_isAppForeground) return;

    final shouldShowLoading = showLoading && !(hadCached || hasExisting);

    if (shouldShowLoading) {
      setState(() {
        _isLoading = true;
        _errorKey = null;
      });
    }

    try {
      _isFetching = true;
      final res = await Supabase.instance.client
          .rpc('admin_get_dashboard_stats', params: {'p_window': _window})
          .timeout(const Duration(seconds: 20));

      final map = decodeMap(res);

      // Reset the periodic fallback timer — activity detected
      _resetPeriodicRefresh();

      // Save to _AdminCache (memory + shared prefs)
      await _AdminCache.write<Map<String, dynamic>>(cacheKey, (v) => v, map);

      // Save to Hive for persistent offline fallback
      await _saveDashboardToHive(map);

      if (!mounted) return;

      if (_data != map) {
        setState(() {
          _data = map;
          _dataWindow = _window;
          _isLoading = false;
          _errorKey = null;
        });
      } else if (_isLoading) {
        setState(() {
          _isLoading = false;
          _errorKey = null;
        });
      }
    } catch (_) {
      if (!mounted) return;

      // Try loading from Hive persistent cache before showing error
      final hiveLoaded = await _loadFromHiveCache();
      if (!mounted) return;

      if (!hiveLoaded && !hadCached && !hasExisting) {
        // No data available from any cache source - show error
        setState(() {
          _errorKey = 'adminDashboardLoadFailed';
          _isLoading = false;
        });
      } else {
        // We have cached data (from Hive, _AdminCache, or prior state) - stay silent
        adminOfflineCacheManager.setSupabaseAvailability(false);
      }
    } finally {
      _isFetching = false;
    }
  }

  /// Load dashboard data from Hive persistent cache.
  /// Returns true if data was loaded.
  Future<bool> _loadFromHiveCache() async {
    try {
      final localDb = await AdminLocalDbService.instance;
      final hiveData = await localDb.loadDashboard(window: _window);
      if (hiveData != null && hiveData.isNotEmpty) {
        if (!mounted) return true;
        setState(() {
          _data = hiveData;
          _dataWindow = _window;
          _isLoading = false;
          _errorKey = null;
        });
        return true;
      }
    } catch (_) {}
    return false;
  }

  /// Persist dashboard data to Hive for offline use.
  Future<void> _saveDashboardToHive(Map<String, dynamic> data) async {
    try {
      final localDb = await AdminLocalDbService.instance;
      await localDb.saveDashboard(data, window: _window);
    } catch (_) {}
  }

  /// Start a periodic fallback refresh timer (every minute).
  /// This ensures the full dashboard data (including the cumulative
  /// windowed counts) stays continuously updated even when realtime ticks
  /// are delayed or the WebSocket temporarily drops. Note: heartbeats in
  /// user_activity do not emit admin_dashboard_tick events, so cumulative
  /// counts would otherwise stall between ticks from other tables.
  void _startPeriodicRefresh() {
    _periodicRefresh?.cancel();
    if (!_isAppForeground) return;
    _periodicRefresh = Timer.periodic(const Duration(minutes: 1), (_) {
      if (!mounted) return;
      if (!_isAppForeground) return;
      if (adminOfflineCacheManager.shouldUseCachedData()) return;
      unawaited(_load(force: true, showLoading: false));
    });
  }

  /// Reset the periodic refresh timer (called after any successful load or tick).
  void _resetPeriodicRefresh() {
    _periodicRefresh?.cancel();
    _startPeriodicRefresh();
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _availabilitySub?.cancel();
    _periodicRefresh?.cancel();
    _scheduledReload?.cancel();
    _realtimeBackupTimer?.cancel();
    _liveCountDebounce?.cancel();
    final channel = _channel;
    if (channel != null) {
      Supabase.instance.client.removeChannel(channel);
    }
    final liveCh = _liveCountChannel;
    if (liveCh != null) {
      Supabase.instance.client.removeChannel(liveCh);
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);

    if (_isLoading) {
      return _MessageScaffold(
        title: l10n.getString('adminNavDashboard'),
        body: l10n.getString('generalLoading'),
        showSpinner: true,
      );
    }

    if (_errorKey != null) {
      return _MessageScaffold(
        title: l10n.getString('adminNavDashboard'),
        body: l10n.getString(_errorKey!),
      );
    }

    // Show skeletons only when there is no data at all (including cache).
    // Previously this also checked _isFetching, which caused skeleton loaders
    // to flash for up to 20 s on every RPC timeout when the device is offline,
    // even though valid cached data was already available in _data.
    final isDataLoading = _data == null || (_data?.isEmpty ?? true);
    final data = _data ?? const <String, dynamic>{};
    final engagement = (data['engagement'] as Map?) ?? const {};
    final operations = (data['operations'] as Map?) ?? const {};
    final revenue = (data['revenue'] as Map?) ?? const {};
    final ai = (data['ai'] as Map?) ?? const {};
    final edgeFunctions = (data['edge_functions'] as Map?) ?? const {};

    List<Map<String, dynamic>> decodeListOfMaps(Object? raw) {
      if (raw is! List) return const <Map<String, dynamic>>[];
      return raw
          .whereType<Map>()
          .map((e) => Map<String, dynamic>.from(e))
          .toList(growable: false);
    }

    final aiUsage = decodeListOfMaps(ai['usage']);
    final aiRecentErrors = decodeListOfMaps(ai['recent_errors']);
    final aiQuotaStatus = (ai['quota_status'] is Map)
        ? Map<String, dynamic>.from(ai['quota_status'] as Map)
        : const <String, dynamic>{};
    final aiQuotaProviders = decodeListOfMaps(aiQuotaStatus['providers']);
    final aiQuotaUpdatedAt = DateTime.tryParse(
      (aiQuotaStatus['updated_at'] ?? '').toString(),
    );
    final edgeUsage = decodeListOfMaps(edgeFunctions['usage']);
    final edgeRecentErrors = decodeListOfMaps(edgeFunctions['recent_errors']);

    final series = (data['engagement_series'] is List)
        ? List<Map<String, dynamic>>.from(
            (data['engagement_series'] as List).whereType<Map>().map(
              (e) => Map<String, dynamic>.from(e),
            ),
          )
        : const <Map<String, dynamic>>[];

    final windowLabelKey = _window == '7d'
        ? 'adminDashboardWindow7d'
        : 'adminDashboardWindow24h';
    final bucketKey = _window == '7d'
        ? 'adminDashboardBucketDay'
        : 'adminDashboardBucketHour';
    final barsKey = _window == '7d'
        ? 'adminDashboardSeriesBucketsDaily'
        : 'adminDashboardSeriesBucketsHourly';

    final numFmt = NumberFormat.compact(locale: l10n.locale.languageCode);
    String fmtInt(dynamic v) {
      final n = (v is num)
          ? v.toInt()
          : int.tryParse((v ?? '').toString()) ?? 0;
      return numFmt.format(n);
    }

    String fmtNum(dynamic v) {
      final n = (v is num) ? v : num.tryParse((v ?? '').toString()) ?? 0;
      return numFmt.format(n);
    }

    String aiProviderLabel(String provider) {
      final p = provider.trim().toLowerCase();
      if (p == 'deepl') return l10n.getString('adminAiProviderDeepL');
      if (p == 'gemini') return l10n.getString('adminAiProviderGemini');
      return provider;
    }

    String aiQuotaWindowLabel(String window) {
      final w = window.trim().toLowerCase();
      if (w == 'billing_period') {
        return l10n.getString('adminDashboardAIQuotaWindowBillingPeriod');
      }
      if (w == '24h') return l10n.getString('adminDashboardWindow24h');
      if (w == '7d') return l10n.getString('adminDashboardWindow7d');
      return window;
    }

    String aiQuotaStatusLabel(String status) {
      final s = status.trim().toLowerCase();
      return switch (s) {
        'ok' => l10n.getString('adminAiQuotaStatusOk'),
        'warn' => l10n.getString('adminAiQuotaStatusWarn'),
        'critical' => l10n.getString('adminAiQuotaStatusCritical'),
        _ => l10n.getString('adminAiQuotaStatusUnknown'),
      };
    }

    List<int> seriesInts(String key) {
      return series
          .map((e) {
            final v = e[key];
            if (v is num) return v.toInt();
            return int.tryParse((v ?? '').toString()) ?? 0;
          })
          .toList(growable: false);
    }

    List<DateTime> seriesTimes() {
      return series
          .map((e) => DateTime.tryParse((e['t'] ?? '').toString()))
          .whereType<DateTime>()
          .toList(growable: false);
    }

    final bucketStarts = seriesTimes();

    final paidByTier = (revenue['paid_by_tier'] is Map)
        ? Map<String, dynamic>.from(revenue['paid_by_tier'] as Map)
        : const <String, dynamic>{};
    final earningsByCurrency = (revenue['earnings_by_currency'] is Map)
        ? Map<String, dynamic>.from(revenue['earnings_by_currency'] as Map)
        : const <String, dynamic>{};

    void openDrilldown({
      required String titleKey,
      required String metric,
      String? param,
    }) {
      // Refresh the dashboard totals in the background so the card count
      // behind the drilldown catches up with reality immediately — the
      // drilldown fetches fresh data on open, the card otherwise lags.
      // LIVE cards come from _realtimeData (not _data), so refresh those
      // for live metrics and the windowed stats for everything else.
      if (metric == 'online_users_live' || metric == 'visible_users_live') {
        unawaited(_loadRealtime(force: true));
      }
      unawaited(_load(force: true, showLoading: false));
      Navigator.of(context).push(
        MaterialPageRoute(
          builder: (_) => _AdminDashboardDrilldownScreen(
            titleKey: titleKey,
            window: _window,
            metric: metric,
            param: param,
            initialRows: _liveDrilldownCache[metric],
            initialTotalCount: _liveDrilldownTotals[metric],
          ),
        ),
      );
    }

    String formatEarnings(Map<String, dynamic> byCurrency) {
      if (byCurrency.isEmpty) return fmtInt(0);
      const currencyLocale = 'en_US';
      final currencyEntries = byCurrency.entries
          .map((e) {
            final code = e.key.toString().trim();
            final v = e.value;
            final amount = (v is num)
                ? v.toDouble()
                : double.tryParse('$v') ?? 0;
            if (code.isEmpty) return null;
            try {
              String symbol = '';
              int? decimalDigits;
              try {
                final fmt = NumberFormat.simpleCurrency(
                  locale: currencyLocale,
                  name: code,
                );
                symbol = fmt.currencySymbol;
                decimalDigits = fmt.decimalDigits;
              } catch (_) {}

              if (symbol.trim().toUpperCase() == code.toUpperCase()) {
                symbol = '';
              }

              final numeric = NumberFormat.currency(
                locale: currencyLocale,
                name: code,
                symbol: '',
                decimalDigits: decimalDigits,
              ).format(amount).trim();

              if (symbol.isEmpty) return '$numeric $code';
              return '$symbol$numeric $code';
            } catch (_) {
              final n = NumberFormat('#,##0.00', currencyLocale).format(amount);
              return '$n $code';
            }
          })
          .whereType<String>()
          .toList(growable: false);
      if (currencyEntries.isEmpty) return fmtInt(0);
      final combined = currencyEntries.join(' • ');
      return '\u2066$combined\u2069';
    }

