class _AdminDrilldownColumn {
  final String key;
  final String labelKey;
  final bool numeric;

  const _AdminDrilldownColumn({
    required this.key,
    required this.labelKey,
    this.numeric = false,
  });
}

class _AdminDashboardDrilldownScreen extends ConsumerStatefulWidget {
  final String titleKey;
  final String window;
  final String metric;
  final String? param;
  final List<Map<String, dynamic>>? initialRows;
  final int? initialTotalCount;

  const _AdminDashboardDrilldownScreen({
    required this.titleKey,
    required this.window,
    required this.metric,
    this.param,
    this.initialRows,
    this.initialTotalCount,
  });

  @override
  ConsumerState<_AdminDashboardDrilldownScreen> createState() =>
      _AdminDashboardDrilldownScreenState();
}

class _AdminDashboardDrilldownScreenState
    extends ConsumerState<_AdminDashboardDrilldownScreen>
    with WidgetsBindingObserver {
  static const _pageSize = 200;
  static const _liveRefreshInterval = Duration(seconds: 5);
  static const _cumulativeRefreshInterval = Duration(seconds: 30);
  bool _isLoading = false;
  bool _isLoadingMore = false;
  bool _hasMore = false;
  String? _errorKey;
  int _offset = 0;
  List<Map<String, dynamic>> _rows = const [];
  Timer? _liveRefreshTimer;
  Timer? _cumulativeRefreshTimer;
  int? _totalCount;
  RealtimeChannel? _liveChannel;
  String _searchQuery = '';
  bool _isAppForeground = true;

  bool get _isLiveMetric =>
      widget.metric == 'online_users_live' ||
      widget.metric == 'visible_users_live';

  /// True when the drilldown rows are user-centric (have user_name/user_id
  /// columns). Search matches name/ID for these; all other drilldowns match
  /// any column value.
  bool get _isUserListMetric =>
      _isLiveMetric ||
      widget.metric == 'online_users' ||
      widget.metric == 'visible_users' ||
      widget.metric == 'new_users' ||
      widget.metric == 'messages_sent' ||
      widget.metric == 'verification_pending' ||
      widget.metric == 'verification_analyzing' ||
      widget.metric == 'profile_edits_pending' ||
      widget.metric == 'notifications_pending' ||
      widget.metric == 'notifications_failed' ||
      widget.metric == 'paid_active_users' ||
      widget.metric == 'paid_expiring_7d' ||
      widget.metric == 'paid_by_tier';

  List<Map<String, dynamic>> get _filteredRows {
    if (_searchQuery.isEmpty) return _rows;
    final q = _searchQuery.toLowerCase();
    if (_isUserListMetric) {
      return _rows.where((r) {
        final name = (r['user_name'] as String? ?? '').toLowerCase();
        final id = (r['user_id'] as String? ?? '').toLowerCase();
        return name.contains(q) || id.contains(q);
      }).toList();
    }
    final cols = _columnsForMetric(widget.metric);
    return _rows.where((r) {
      for (final c in cols) {
        final v = r[c.key];
        if (v == null || v is Map || v is List) continue;
        if (v.toString().toLowerCase().contains(q)) return true;
      }
      return false;
    }).toList();
  }

  List<Map<String, dynamic>> _decodeListOfMaps(Object? raw) {
    if (raw is! List) return const <Map<String, dynamic>>[];
    return raw
        .whereType<Map>()
        .map((e) => Map<String, dynamic>.from(e))
        .toList(growable: false);
  }

  Future<void> _load({required bool more, bool force = false}) async {
    if (more && (!_hasMore || _isLoadingMore)) return;
    if (!more && _isLoading) return;

    var hadCached = false;
    if (!mounted) return;
    // Silent refreshes (live metrics and forced periodic refreshes) keep the
    // current rows on screen while fetching — no loading state, no clearing.
    final silentRefresh = _isLiveMetric || force;
    setState(() {
      if (more) {
        _isLoadingMore = true;
      } else {
        if (!silentRefresh || _rows.isEmpty) {
          _isLoading = true;
        }
        _errorKey = null;
        if (!silentRefresh || _rows.isEmpty) {
          _offset = 0;
          _rows = const [];
        }
      }
    });

    if (!more && !_isLiveMetric && !force) {
      List<Map<String, dynamic>> decodeListMap(Object? raw) {
        if (raw is! List) return const [];
        final out = <Map<String, dynamic>>[];
        for (final item in raw) {
          if (item is Map) out.add(Map<String, dynamic>.from(item));
        }
        return out;
      }

      final paramKey = widget.param ?? 'none';
      final cacheKey =
          'admin_cache:drilldown:v1:${widget.window}:${widget.metric}:$paramKey';
      final hiveKey = 'drilldown:${widget.window}:${widget.metric}:$paramKey';
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (cached != null) {
        setState(() {
          _rows = cached.data;
          _hasMore = false;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        // Do NOT short-circuit on fresh cache: opening a drilldown must
        // always reflect the current data (e.g. last_activity). The cached
        // rows above only serve as an instant placeholder — the RPC below
        // replaces them within a second. If the RPC fails, the cached rows
        // remain (offline fallback).
      }
      // Try Hive fallback if AdminCache missed
      if (!hadCached) {
        try {
          final hiveData = await AdminLocalDbService.shared.loadSectionData(
            hiveKey,
          );
          if (hiveData.isNotEmpty && mounted) {
            setState(() {
              _rows = hiveData;
              _hasMore = false;
              _isLoading = false;
              _errorKey = null;
            });
            hadCached = true;
          }
        } catch (_) {}
      }
    }

    if (!mounted) return;
    if (!_isAppForeground) {
      if (mounted) {
        setState(() {
          _isLoading = false;
          _isLoadingMore = false;
        });
      }
      return;
    }

    try {
      final nextOffset = more ? _offset : 0;
      final raw = await Supabase.instance.client
          .rpc(
            'admin_get_dashboard_drilldown',
            params: {
              'p_window': widget.window,
              'p_metric': widget.metric,
              'p_param': widget.param,
              'p_limit': _pageSize,
              'p_offset': nextOffset,
            },
          )
          .timeout(const Duration(seconds: 20));

      final map = (raw is Map)
          ? Map<String, dynamic>.from(raw)
          : <String, dynamic>{};
      final rows = _decodeListOfMaps(map['rows']);
      final hasMore = map['has_more'] == true;
      final totalCount = (map['total_count'] is num)
          ? (map['total_count'] as num).toInt()
          : null;

      if (!more && !_isLiveMetric) {
        final paramKey = widget.param ?? 'none';
        final cacheKey =
            'admin_cache:drilldown:v1:${widget.window}:${widget.metric}:$paramKey';
        final hiveKey = 'drilldown:${widget.window}:${widget.metric}:$paramKey';
        await _AdminCache.write<List<Map<String, dynamic>>>(
          cacheKey,
          (v) => v,
          rows,
        );
        try {
          await AdminLocalDbService.shared.saveSectionData(hiveKey, rows);
        } catch (_) {}
      }

      if (!mounted) return;
      setState(() {
        _hasMore = hasMore;
        _offset = nextOffset + rows.length;
        if (more) {
          _rows = [..._rows, ...rows];
        } else {
          _rows = rows;
        }
        _totalCount = totalCount;
        _errorKey = null;
      });
    } catch (e) {
      if (!mounted) return;
      final msg = e.toString().toLowerCase();
      final isNetworkError =
          msg.contains('socketexception') ||
          msg.contains('failed host lookup') ||
          msg.contains('clientexception');
      if (!isNetworkError) {
        debugPrint('[Drilldown] RPC failed (${widget.metric}): $e');
      }
      if (!hadCached) {
        setState(() {
          if (adminOfflineCacheManager.shouldUseCachedData()) {
            _errorKey = 'adminDrilldownOfflineNotCached';
          } else {
            _errorKey = 'adminDrilldownLoadFailed';
          }
        });
      }
    } finally {
      if (mounted) {
        setState(() {
          _isLoading = false;
          _isLoadingMore = false;
        });
      }
    }
  }

