  Widget _cellValue(
    LocalizationState l10n,
    String metric,
    String key,
    Object? raw,
  ) {
    if (raw == null) return const SizedBox.shrink();
    if (key == 'is_pinned') {
      // LIVE drilldowns: badge users holding an active pinned home-base
      // location so admins can tell "pinned (available, not heartbeating)"
      // apart from genuinely live users at a glance.
      final pinned = raw == true;
      return Tooltip(
        message: l10n.getString(
          pinned ? 'adminDrilldownPinnedActive' : 'adminDrilldownPinnedNone',
        ),
        child: Icon(
          pinned ? Icons.push_pin : Icons.push_pin_outlined,
          size: 16,
          color: pinned
              ? Colors.orange
              : Theme.of(context).colorScheme.onSurface.withValues(alpha: 0.3),
        ),
      );
    }
    if (raw is bool) {
      return raw
          ? const Icon(Icons.check, size: 18)
          : const Icon(Icons.close, size: 18);
    }
    if (key == 'earnings') {
      Map<String, dynamic> map = const <String, dynamic>{};
      if (raw is Map) {
        map = Map<String, dynamic>.from(raw);
      } else if (raw is String) {
        try {
          final decoded = jsonDecode(raw);
          if (decoded is Map) {
            map = Map<String, dynamic>.from(decoded);
          }
        } catch (_) {}
      }

      final locale = l10n.locale.languageCode.trim();
      final safeLocale = locale.isEmpty ? 'en' : locale;
      final zero = NumberFormat.compact(locale: safeLocale).format(0);
      if (map.isEmpty) return Text(zero);
      final parts = map.entries
          .map((e) {
            final code = e.key.toString().trim();
            final v = e.value;
            final amount = (v is num)
                ? v.toDouble()
                : double.tryParse('$v') ?? 0;
            if (code.isEmpty) return null;
            try {
              String symbol = '';
              try {
                symbol = NumberFormat.simpleCurrency(
                  locale: safeLocale,
                  name: code,
                ).currencySymbol;
              } catch (_) {}

              if (symbol.trim().toUpperCase() == code.toUpperCase()) {
                symbol = '';
              }

              final numeric = NumberFormat.currency(
                locale: safeLocale,
                name: code,
                symbol: '',
              ).format(amount).trim();

              if (symbol.isEmpty) return '$numeric $code';
              return '$symbol$numeric $code';
            } catch (_) {
              final n = NumberFormat('#,##0.00', safeLocale).format(amount);
              return '$n $code';
            }
          })
          .whereType<String>()
          .toList(growable: false);

      if (parts.isEmpty) return Text(zero);
      return Text(
        parts.join(' • '),
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
      );
    }
    if (key == 'user_name' ||
        key == 'user1_name' ||
        key == 'user2_name' ||
        key == 'reviewer_name') {
      final s = raw.toString();
      return Text(
        maskUserDisplayName(s),
        maxLines: 2,
        overflow: TextOverflow.ellipsis,
        textDirection: isRtlText(maskUserDisplayName(s))
            ? TextDirection.rtl
            : TextDirection.ltr,
      );
    }
    if (key == 'basis' && raw is List) {
      String labelFor(String code) {
        switch (code) {
          case 'proximity':
            return l10n.getString('adminDrilldownBasisProximity');
          case 'event':
            return l10n.getString('adminDrilldownBasisEvent');
          case 'shared_intent':
            return l10n.getString('adminDrilldownBasisSharedIntent');
          case 'shared_interest':
            return l10n.getString('adminDrilldownBasisSharedInterest');
          default:
            return l10n.getString('adminDrilldownUnknown');
        }
      }

      final labels = raw
          .map((e) => e?.toString() ?? '')
          .where((s) => s.isNotEmpty)
          .map(labelFor)
          .toList(growable: false);
      if (labels.isEmpty) return const SizedBox.shrink();
      return Text(labels.join(', '));
    }
    final s = raw.toString();
    if (key.endsWith('_at') || key.endsWith('_at_utc')) {
      final dt = DateTime.tryParse(s);
      if (dt != null) {
        return Text(_formatAdminDateTime(l10n, dt));
      }
    }
    if (raw is num) return Text(raw.toString());
    return Text(s, maxLines: 2, overflow: TextOverflow.ellipsis);
  }

  void _pauseDrilldownPolling() {
    _liveRefreshTimer?.cancel();
    _cumulativeRefreshTimer?.cancel();
    _liveChannelDebounce?.cancel();
  }

  void _resumeDrilldownPolling() {
    if (!mounted) return;
    _pauseDrilldownPolling();
    if (_isLiveMetric) {
      _liveRefreshTimer = Timer.periodic(_liveRefreshInterval, (_) {
        if (!mounted) return;
        if (!_isAppForeground) return;
        unawaited(_load(more: false));
      });
    } else {
      _cumulativeRefreshTimer = Timer.periodic(_cumulativeRefreshInterval, (_) {
        if (!mounted) return;
        if (!_isAppForeground) return;
        unawaited(_load(more: false, force: true));
      });
    }
    // Refresh immediately on resume so stale data is not shown.
    unawaited(_load(more: false, force: _isLiveMetric ? false : true));
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      if (!_isAppForeground) {
        _isAppForeground = true;
        _resumeDrilldownPolling();
      }
    } else if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      if (_isAppForeground) {
        _isAppForeground = false;
        _pauseDrilldownPolling();
      }
    }
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    final cur = WidgetsBinding.instance.lifecycleState;
    _isAppForeground =
        cur == null ||
        (cur != AppLifecycleState.paused &&
            cur != AppLifecycleState.hidden &&
            cur != AppLifecycleState.detached);
    final initialRows = widget.initialRows;
    if (initialRows != null && initialRows.isNotEmpty) {
      _rows = initialRows;
      _totalCount = widget.initialTotalCount;
      _hasMore = false;
    }
    unawaited(_load(more: false));
    if (_isAppForeground) {
      if (_isLiveMetric) {
        _liveRefreshTimer = Timer.periodic(_liveRefreshInterval, (_) {
          if (!mounted) return;
          if (!_isAppForeground) return;
          unawaited(_load(more: false));
        });
        _setupLiveSubscription();
      } else {
        // Cumulative (windowed) drilldowns have no realtime tick source, so
        // keep them fresh with a periodic forced refresh. The cache is used
        // only for the instant first paint; force skips it on later ticks.
        _cumulativeRefreshTimer = Timer.periodic(_cumulativeRefreshInterval, (
          _,
        ) {
          if (!mounted) return;
          if (!_isAppForeground) return;
          unawaited(_load(more: false, force: true));
        });
      }
    } else {
      // Start subscription even when backgrounded so resume is instant, but
      // polling timers stay paused until foreground.
      if (_isLiveMetric) _setupLiveSubscription();
    }
  }

  Timer? _liveChannelDebounce;

  void _setupLiveSubscription() {
    try {
      // LIVE visible rows also depend on user_locations freshness, so
      // subscribe there too (in addition to heartbeats + visibility).
      final channel = Supabase.instance.client
          .channel('drilldown_live_${widget.metric}')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_activity',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'users',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_locations',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .subscribe();
      _liveChannel = channel;
    } catch (_) {}
  }

  void _debouncedLiveRefresh() {
    if (!_isAppForeground) return;
    _liveChannelDebounce?.cancel();
    _liveChannelDebounce = Timer(const Duration(milliseconds: 800), () {
      if (mounted) unawaited(_load(more: false));
    });
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _liveRefreshTimer?.cancel();
    _cumulativeRefreshTimer?.cancel();
    _liveChannelDebounce?.cancel();
    final ch = _liveChannel;
    if (ch != null) {
      Supabase.instance.client.removeChannel(ch);
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final displayParam = () {
      final raw = widget.param;
      if (raw == null) return null;
      if (widget.metric == 'ai_usage' && raw.contains('|')) {
        final parts = raw
            .split('|')
            .map((e) => e.trim())
            .where((e) => e.isNotEmpty)
            .toList(growable: false);
        if (parts.isNotEmpty) return parts.join(' • ');
      }
      return raw;
    }();
    final title = displayParam == null
        ? l10n.getString(widget.titleKey)
        : '${l10n.getString(widget.titleKey)}: $displayParam';
    final rows = _filteredRows;
    final columns = _columnsForMetric(widget.metric);

    return Scaffold(
      appBar: AppBar(
        title: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Text(title, overflow: TextOverflow.ellipsis),
            if (_totalCount != null) ...[
