// ── Admin User Map Screen ──────────────────────────────────────────────

class _AdminUserMapScreen extends ConsumerStatefulWidget {
  final String mode; // 'online' or 'visible'
  final double? focusLat;
  final double? focusLng;
  final String? focusName;
  final String? focusUserId;

  const _AdminUserMapScreen({
    required this.mode,
    this.focusLat,
    this.focusLng,
    this.focusName,
    this.focusUserId,
  });

  @override
  ConsumerState<_AdminUserMapScreen> createState() =>
      _AdminUserMapScreenState();
}

class _AdminUserMapScreenState extends ConsumerState<_AdminUserMapScreen>
    with WidgetsBindingObserver {
  List<Map<String, dynamic>> _users = const [];
  // Totals reported by admin_get_user_map_locations: all users under the
  // mode filter vs. the pinnable subset. They differ when users have no
  // location row (e.g. invisible users, whose location is never uploaded).
  int? _totalCount;
  int _withoutLocation = 0;
  bool _isLoading = true;
  String? _error;
  Timer? _refreshTimer;
  RealtimeChannel? _liveChannel;
  Timer? _liveChannelDebounce;
  bool _isAppForeground = true;
  final MapController _mapController = MapController();
  final ValueNotifier<double> _cameraZoom = ValueNotifier(12);
  final ValueNotifier<LatLng?> _cameraCenter = ValueNotifier(null);
  static final Map<String, String> _photoUrlCache = {};
  static final Map<String, DateTime> _photoUrlCachedAt = {};
  static final Map<String, DateTime> _missingPhotoUntil = {};

  bool _isKnownPhotoMissing(String path) {
    final until = _missingPhotoUntil[path];
    if (until == null) return false;
    if (until.isAfter(DateTime.now())) return true;
    _missingPhotoUntil.remove(path);
    return false;
  }

  void _setupRealtime() {
    try {
      // Map pins depend on user_locations rows as well as heartbeats and
      // visibility settings — subscribe to all three for instant refresh.
      final channel = Supabase.instance.client
          .channel('map_live_users')
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_activity',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'users',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .onPostgresChanges(
            event: PostgresChangeEvent.all,
            schema: 'public',
            table: 'user_locations',
            callback: (_) => _debouncedLiveRefresh(),
          )
          .subscribe();
      _liveChannel = channel;
    } catch (_) {}
  }

  void _debouncedLiveRefresh() {
    if (!_isAppForeground) return;
    _liveChannelDebounce?.cancel();
    _liveChannelDebounce = Timer(const Duration(milliseconds: 800), () {
      if (mounted) _load(showLoading: false);
    });
  }

  void _pauseMapPolling() {
    _refreshTimer?.cancel();
    _liveChannelDebounce?.cancel();
  }

  void _resumeMapPolling() {
    if (!mounted) return;
    _pauseMapPolling();
    _refreshTimer = Timer.periodic(const Duration(seconds: 5), (_) {
      if (!mounted) return;
      if (!_isAppForeground) return;
      _load(showLoading: false);
    });
    _load(showLoading: false);
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      if (!_isAppForeground) {
        _isAppForeground = true;
        _resumeMapPolling();
      }
    } else if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      if (_isAppForeground) {
        _isAppForeground = false;
        _pauseMapPolling();
      }
    }
  }

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    final cur = WidgetsBinding.instance.lifecycleState;
    _isAppForeground =
        cur == null ||
        (cur != AppLifecycleState.paused &&
            cur != AppLifecycleState.hidden &&
            cur != AppLifecycleState.detached);
    _load();
    _setupRealtime();
    if (_isAppForeground) {
      _refreshTimer = Timer.periodic(const Duration(seconds: 5), (_) {
        if (!mounted) return;
        if (!_isAppForeground) return;
        _load(showLoading: false);
      });
    }
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _refreshTimer?.cancel();
    _liveChannelDebounce?.cancel();
    final ch = _liveChannel;
    if (ch != null) {
      Supabase.instance.client.removeChannel(ch);
    }
    _cameraZoom.dispose();
    _cameraCenter.dispose();
    super.dispose();
  }

  Future<void> _load({bool showLoading = true}) async {
    if (!mounted) return;
    if (!_isAppForeground && !showLoading) return;
    if (!_isAppForeground && showLoading && _users.isNotEmpty) return;
    if (showLoading) {
      setState(() {
        _isLoading = true;
        _error = null;
      });
    }
    try {
      final res = await Supabase.instance.client
          .rpc('admin_get_user_map_locations', params: {'p_mode': widget.mode})
          .timeout(const Duration(seconds: 15));
      if (!mounted) return;
      final map = (res is Map)
          ? Map<String, dynamic>.from(res)
          : <String, dynamic>{};
      final rawList = map['users'];
      final list = (rawList is List)
          ? rawList
                .whereType<Map>()
                .map((e) => Map<String, dynamic>.from(e))
                .toList()
          : <Map<String, dynamic>>[];
      int? total;
      final totalRaw = widget.mode == 'visible'
          ? map['total_visible']
          : map['total_online'];
      if (totalRaw is num) {
        total = totalRaw.toInt();
      } else if (totalRaw != null) {
        total = int.tryParse(totalRaw.toString());
      }
      int withoutLocation = 0;
      final withoutRaw = map['without_location'];
      if (withoutRaw is num) {
        withoutLocation = withoutRaw.toInt();
      } else if (withoutRaw != null) {
        withoutLocation = int.tryParse(withoutRaw.toString()) ?? 0;
      }
      await _resolvePhotoUrls(list);
      if (!mounted) return;
      setState(() {
        _users = list;
        _totalCount = total;
        _withoutLocation = withoutLocation;
        _isLoading = false;
        _error = null;
      });
    } catch (e) {
      if (!mounted) return;
      final msg = e.toString().toLowerCase();
      final isNetworkError =
          msg.contains('socketexception') ||
          msg.contains('failed host lookup') ||
          msg.contains('clientexception');
      if (!isNetworkError) {
        debugPrint('[UserMap] RPC failed (${widget.mode}): $e');
      }
      if (_users.isEmpty && showLoading) {
        setState(() {
          _error = ref
              .read(localizationProvider)
              .getString('adminMapFailedToLoad');
          _isLoading = false;
        });
      } else {
        setState(() {
          _isLoading = false;
        });
      }
    }
  }

  LatLng? _computeCenter() {
    if (_displayUsers.isEmpty) return null;
    double lat = 0, lng = 0;
    for (final u in _displayUsers) {
      final la = (u['latitude'] as num?)?.toDouble();
      final lo = (u['longitude'] as num?)?.toDouble();
      if (la != null && lo != null) {
        lat += la;
        lng += lo;
      }
    }
    final n = _displayUsers.length.toDouble();
    return n > 0 ? LatLng(lat / n, lng / n) : null;
  }

  double _computeZoom() {
    if (_displayUsers.length <= 1) return 12;
    double minLat = 90, maxLat = -90, minLng = 180, maxLng = -180;
    for (final u in _displayUsers) {
      final la = (u['latitude'] as num?)?.toDouble();
      final lo = (u['longitude'] as num?)?.toDouble();
      if (la == null || lo == null) continue;
      if (la < minLat) minLat = la;
      if (la > maxLat) maxLat = la;
      if (lo < minLng) minLng = lo;
      if (lo > maxLng) maxLng = lo;
    }
    final latSpread = maxLat - minLat;
    final lngSpread = maxLng - minLng;
    final spread = latSpread > lngSpread ? latSpread : lngSpread;
    if (spread < 0.01) return 14;
    if (spread < 0.05) return 13;
    if (spread < 0.2) return 12;
    if (spread < 1) return 10;
    if (spread < 5) return 8;
    if (spread < 20) return 6;
    return 4;
  }

  /// Users to render: the RPC result filtered to the focused user when
  /// viewing a specific user. Returns empty when the user has gone
  /// offline/invisible so the marker disappears and the empty state shows.
  List<Map<String, dynamic>> get _displayUsers {
    final focusId = widget.focusUserId;
    if (focusId == null || focusId.isEmpty) return _users;
    return _users
        .where((u) => (u['user_id'] ?? '').toString() == focusId)
        .toList();
  }

  bool get _hasFocusFilter {
    final focusId = widget.focusUserId;
    return focusId != null && focusId.isNotEmpty;
  }

  /// Badge text: pins on screen, or "X of Y" when the server reports more
  /// users under the filter than have pinnable locations.
  String _badgeText(LocalizationState l10n) {
    final shown = _displayUsers.length;
    final total = _totalCount;
    final template = l10n.getString('adminMapUsersCount');
    if (!_hasFocusFilter && total != null && total > shown) {
      return template.replaceAll('{count}', '$shown of $total');
    }
    return template.replaceAll('{count}', '$shown');
  }

  /// True when the banner explaining unpinnable users should be shown.
  bool get _showWithoutLocationBanner =>
      !_hasFocusFilter && _withoutLocation > 0 && _displayUsers.isNotEmpty;

  String _firstNameLastInitial(String name) {
    final parts = name.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty) return name;
    if (parts.length == 1) return parts[0];
    return '${parts[0]} ${parts[parts.length - 1].substring(0, 1)}.';
  }

  String _initials(String name) {
    final parts = name.trim().split(RegExp(r'\s+'));
    if (parts.isEmpty) return '?';
    if (parts.length == 1) return parts[0].substring(0, 1).toUpperCase();
    return '${parts[0].substring(0, 1)}${parts[parts.length - 1].substring(0, 1)}'
        .toUpperCase();
  }

  String? _resolvePhotoUrl(String? raw) {
    if (raw == null || raw.trim().isEmpty) return null;
    final trimmed = raw.trim();
    // 'profile-photos' is a private bucket: public URLs always fail with 400,
    // so never fall back to getPublicUrl here. Only use signed URLs (populated
    // asynchronously by _resolvePhotoUrls) or already-full URLs.
    if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
      return trimmed;
    }
    return _photoUrlCache[trimmed];
  }

  Future<void> _resolvePhotoUrls(List<Map<String, dynamic>> users) async {
    if (!mounted) return;
    final client = Supabase.instance.client;
    final toResolve = <String>[];
    final now = DateTime.now();
    const maxAge = Duration(minutes: 50);
    for (final u in users) {
      final raw = (u['photo_url'] as String?)?.trim();
      if (raw == null || raw.isEmpty) continue;
      if (raw.startsWith('http://') || raw.startsWith('https://')) {
        _photoUrlCache[raw] = raw;
        _photoUrlCachedAt[raw] = now;
        continue;
      }
      if (_photoUrlCache.containsKey(raw)) {
        final cachedAt = _photoUrlCachedAt[raw];
        if (cachedAt != null && now.difference(cachedAt) < maxAge) continue;
        _photoUrlCache.remove(raw);
        _photoUrlCachedAt.remove(raw);
      }
      if (_isKnownPhotoMissing(raw)) continue;
      toResolve.add(raw);
    }
    if (toResolve.isEmpty) return;
    final results = await Future.wait(
      toResolve.map((raw) async {
        try {
          // Verify the object still exists before signing: createSignedUrl
          // succeeds even for deleted objects, and fetching a signed URL for
          // a missing object fails on the client (failed image decode ->
          // CanvasKit "texImage2D: no image" warnings).
          await client.storage.from('profile-photos').info(raw);
          final url = await client.storage
              .from('profile-photos')
              .createSignedUrl(raw, 3600);
          return MapEntry(raw, url);
        } on StorageException catch (e) {
          final msg = e.message.toLowerCase();
          if (msg.contains('404') || msg.contains('not found')) {
            _missingPhotoUntil[raw] = DateTime.now().add(
              const Duration(minutes: 10),
            );
          }
          return MapEntry(raw, null);
        } catch (_) {
          // Do NOT fall back to getPublicUrl: the bucket is private, so a
          // public URL would 400. Leave the entry uncached so the next
          // refresh retries the signed URL.
          return MapEntry(raw, null);
        }
      }),
      eagerError: false,
    );
    if (!mounted) return;
    for (final e in results) {
      final url = e.value;
      if (url != null && url.trim().isNotEmpty) {
        _photoUrlCache[e.key] = url;
        _photoUrlCachedAt[e.key] = DateTime.now();
      }
    }
  }

  Widget _buildProfileCircle(
    String name,
    String? photoUrl, {
    double size = 44,
    bool highlighted = false,
  }) {
    return Container(
      width: size,
      height: size,
      decoration: BoxDecoration(
        shape: BoxShape.circle,
        color: highlighted ? Colors.red : Colors.deepPurple,
        border: Border.all(color: Colors.white, width: highlighted ? 3 : 2),
        boxShadow: [
          BoxShadow(
            color: (highlighted ? Colors.red : Colors.black).withValues(
              alpha: 0.3,
            ),
            blurRadius: highlighted ? 12 : 4,
            spreadRadius: highlighted ? 2 : 0,
            offset: highlighted ? Offset.zero : const Offset(0, 2),
          ),
        ],
      ),
      clipBehavior: Clip.hardEdge,
      child: (photoUrl != null && photoUrl.isNotEmpty)
          ? Image(
              image: NetworkImage(photoUrl),
              fit: BoxFit.cover,
              frameBuilder: (ctx, child, frame, wasSynchronouslyLoaded) {
                if (wasSynchronouslyLoaded || frame != null) return child;
                return Center(
                  child: Text(
                    _initials(name),
                    style: TextStyle(
                      color: Colors.white,
                      fontWeight: FontWeight.bold,
                      fontSize: size * 0.35,
                    ),
                  ),
                );
              },
              errorBuilder: (_, _, _) => Center(
                child: Text(
                  _initials(name),
                  style: TextStyle(
                    color: Colors.white,
                    fontWeight: FontWeight.bold,
                    fontSize: size * 0.35,
                  ),
                ),
              ),
            )
          : Center(
              child: Text(
                _initials(name),
                style: TextStyle(
                  color: Colors.white,
                  fontWeight: FontWeight.bold,
                  fontSize: size * 0.35,
                ),
              ),
            ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final title = widget.mode == 'visible'
        ? l10n.getString('adminDashboardVisibleUsers')
        : l10n.getString('adminDashboardOnlineUsers');

    return Scaffold(
      appBar: AppBar(
        title: Text('$title - ${l10n.getString('adminDrilldownMap')}'),
        actions: [
          if (_users.isNotEmpty)
            Padding(
              padding: const EdgeInsets.only(right: 16),
              child: Center(
                child: Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 10,
                    vertical: 4,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.green.withValues(alpha: 0.15),
                    borderRadius: BorderRadius.circular(12),
                  ),
                  child: Text(
                    _badgeText(l10n),
                    style: const TextStyle(
                      color: Colors.green,
                      fontWeight: FontWeight.bold,
                      fontSize: 13,
                    ),
                  ),
                ),
              ),
            ),
          IconButton(
            tooltip: l10n.getString('generalRefresh'),
            onPressed: () => _load(),
            icon: const Icon(Icons.refresh),
          ),
        ],
      ),
      body: _isLoading
          ? const Center(child: CircularProgressIndicator())
