    );
  }

  Widget _buildMap() {
    final l10n = ref.watch(localizationProvider);
    final center = widget.focusLat != null && widget.focusLng != null
        ? LatLng(widget.focusLat!, widget.focusLng!)
        : _computeCenter() ?? const LatLng(20, 0);
    final zoom = widget.focusLat != null ? 18.0 : _computeZoom();
    final bottomInset = MediaQuery.of(context).viewPadding.bottom;

    return LayoutBuilder(
      builder: (context, constraints) {
        if (constraints.maxWidth == 0 || constraints.maxHeight == 0) {
          return const SizedBox.shrink();
        }
        return Stack(
          children: [
            FlutterMap(
              mapController: _mapController,
              options: MapOptions(
                initialCenter: center,
                initialZoom: zoom,
                minZoom: 2,
                maxZoom: 18,
                onPositionChanged: (camera, hasGesture) {
                  _cameraZoom.value = camera.zoom;
                  _cameraCenter.value = camera.center;
                },
              ),
              children: [
                TileLayer(
                  urlTemplate: 'https://tile.openstreetmap.org/{z}/{x}/{y}.png',
                  userAgentPackageName: 'matchme.admin',
                ),
                MarkerLayer(markers: _buildMarkers()),
              ],
            ),
            // Banner: users under the filter with no location row
            // (e.g. invisible users, whose location is never uploaded)
            // have no pin. Shown so the pin count never looks wrong
            // next to the LIVE card/drilldown totals.
            if (_showWithoutLocationBanner)
              Positioned(
                top: 12,
                left: 0,
                right: 0,
                child: Center(
                  child: Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 12,
                      vertical: 6,
                    ),
                    decoration: BoxDecoration(
                      color: Theme.of(
                        context,
                      ).colorScheme.surface.withValues(alpha: 0.92),
                      borderRadius: BorderRadius.circular(16),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withValues(alpha: 0.15),
                          blurRadius: 4,
                          offset: const Offset(0, 2),
                        ),
                      ],
                    ),
                    child: Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        const Icon(Icons.location_off_outlined, size: 16),
                        const SizedBox(width: 6),
                        Flexible(
                          child: Text(
                            l10n
                                .getString('adminMapWithoutLocation')
                                .replaceAll('{count}', '$_withoutLocation'),
                            style: const TextStyle(fontSize: 12),
                          ),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
            // Scale indicator
            Positioned(
              bottom: 12 + bottomInset,
              left: 12,
              child: ValueListenableBuilder<double>(
                valueListenable: _cameraZoom,
                builder: (context, zoomVal, _) {
                  return ValueListenableBuilder<LatLng?>(
                    valueListenable: _cameraCenter,
                    builder: (context, centerVal, _) {
                      return _buildScaleIndicator(context, zoomVal, centerVal);
                    },
                  );
                },
              ),
            ),
            // Center on focus user button
            Positioned(
              right: 12,
              bottom: 110 + bottomInset,
              child: FloatingActionButton.small(
                heroTag: null,
                backgroundColor: Theme.of(context).colorScheme.surface,
                onPressed: (widget.focusLat != null && widget.focusLng != null)
                    ? () {
                        _mapController.move(
                          LatLng(widget.focusLat!, widget.focusLng!),
                          15,
                        );
                      }
                    : null,
                child: Icon(
                  Icons.my_location,
                  color: (widget.focusLat != null && widget.focusLng != null)
                      ? Theme.of(context).colorScheme.primary
                      : Colors.grey,
                ),
              ),
            ),
            // Zoom controls
            Positioned(
              right: 12,
              bottom: 12 + bottomInset,
              child: _MapZoomControls(
                controller: _mapController,
                minZoom: 2,
                maxZoom: 18,
              ),
            ),
          ],
        );
      },
    );
  }

  Widget _buildScaleIndicator(
    BuildContext context,
    double zoom,
    LatLng? cameraCenter,
  ) {
    final center = cameraCenter;
    if (center == null) return const SizedBox.shrink();

    final mpp = 156543.03392 * cos(center.latitude * pi / 180) / pow(2, zoom);
    if (mpp <= 0 || mpp.isNaN) return const SizedBox.shrink();

    final refBarPixels = 80.0;
    final groundMeters = refBarPixels * mpp;
    final niceMeters = _niceScaleDistance(groundMeters);
    final barWidth = niceMeters / mpp;
    final label = niceMeters >= 1000
        ? '${(niceMeters / 1000).toStringAsFixed(niceMeters % 1000 == 0 ? 0 : 1)} km'
        : '${niceMeters.toStringAsFixed(niceMeters == niceMeters.roundToDouble() ? 0 : 0)} m';

    return Material(
      elevation: 2,
      borderRadius: BorderRadius.circular(4),
      color: Theme.of(context).colorScheme.surface.withValues(alpha: 0.88),
      child: SizedBox(
        width: max(barWidth, 40.0),
        height: 28,
        child: CustomPaint(
          painter: _ScaleBarPainter(
            barWidth: barWidth,
            label: label,
            color: Theme.of(context).colorScheme.onSurface,
          ),
        ),
      ),
    );
  }

  List<Marker> _buildMarkers() {
    final markers = <Marker>[];

    if (widget.focusLat != null && widget.focusLng != null) {
      final focusId = widget.focusUserId;
      final focusUser = (focusId != null && focusId.isNotEmpty)
          ? _users
                .where((u) => (u['user_id'] ?? '').toString() == focusId)
                .firstOrNull
          : null;
      if (focusUser != null) {
        final focusName = widget.focusName ?? 'User';
        final displayName = _firstNameLastInitial(focusName);
        final focusPhotoUrl = _resolvePhotoUrl(
          focusUser['photo_url'] as String?,
        );
        markers.add(
          Marker(
            point: LatLng(widget.focusLat!, widget.focusLng!),
            width: 60,
            height: 72,
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                _buildProfileCircle(
                  focusName,
                  focusPhotoUrl,
                  size: 44,
                  highlighted: true,
                ),
                const SizedBox(height: 2),
                Container(
                  padding: const EdgeInsets.symmetric(
                    horizontal: 6,
                    vertical: 1,
                  ),
                  decoration: BoxDecoration(
                    color: Colors.white,
                    borderRadius: BorderRadius.circular(4),
                    boxShadow: [
                      BoxShadow(
                        color: Colors.black.withValues(alpha: 0.2),
                        blurRadius: 2,
                      ),
                    ],
                  ),
                  child: Text(
                    displayName,
                    style: const TextStyle(
                      fontSize: 10,
                      fontWeight: FontWeight.w600,
                    ),
                    overflow: TextOverflow.ellipsis,
                  ),
                ),
              ],
            ),
          ),
        );
      }
    }

    if (widget.focusUserId == null || widget.focusUserId!.isEmpty) {
      for (final u in _users) {
        final lat = (u['latitude'] as num?)?.toDouble();
        final lng = (u['longitude'] as num?)?.toDouble();
        if (lat == null || lng == null) continue;
        final name = (u['user_name'] as String?) ?? 'User';
        final photoUrl = _resolvePhotoUrl(u['photo_url'] as String?);
        final displayName = _firstNameLastInitial(name);
        markers.add(
          Marker(
            point: LatLng(lat, lng),
            width: 60,
            height: 72,
            child: GestureDetector(
              onTap: () => _showUserPopup(u),
              child: Column(
                mainAxisSize: MainAxisSize.min,
                children: [
                  _buildProfileCircle(name, photoUrl, size: 36),
                  const SizedBox(height: 2),
                  Container(
                    padding: const EdgeInsets.symmetric(
                      horizontal: 5,
                      vertical: 1,
                    ),
                    decoration: BoxDecoration(
                      color: Colors.white,
                      borderRadius: BorderRadius.circular(4),
                      boxShadow: [
                        BoxShadow(
                          color: Colors.black.withValues(alpha: 0.2),
                          blurRadius: 2,
                        ),
                      ],
                    ),
                    child: Text(
                      displayName,
                      style: const TextStyle(
                        fontSize: 9,
                        fontWeight: FontWeight.w600,
                      ),
                      overflow: TextOverflow.ellipsis,
                    ),
                  ),
                ],
              ),
            ),
          ),
        );
      }
    } // end: only show all users when no specific focus

    return markers;
  }

  void _showUserPopup(Map<String, dynamic> user) {
    final name = user['user_name'] as String? ?? 'Unknown';
    final userId = user['user_id'] as String? ?? '';
    final lastActivity = user['last_activity'] as String?;
    final photoUrl = _resolvePhotoUrl(user['photo_url'] as String?);
    final initials = _initials(name);

    showModalBottomSheet(
      context: context,
      useSafeArea: true,
      isScrollControlled: true,
      shape: const RoundedRectangleBorder(
        borderRadius: BorderRadius.vertical(top: Radius.circular(16)),
      ),
      builder: (ctx) => SafeArea(
        top: false,
        child: Padding(
          padding: EdgeInsets.only(
            left: 20,
            right: 20,
            top: 16,
            bottom: MediaQuery.of(ctx).viewInsets.bottom + 16,
          ),
          child: Column(
            mainAxisSize: MainAxisSize.min,
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              Center(
                child: Container(
                  width: 40,
                  height: 4,
                  decoration: BoxDecoration(
                    color: Colors.grey[300],
                    borderRadius: BorderRadius.circular(2),
                  ),
                ),
              ),
              const SizedBox(height: 16),
              Row(
                children: [
                  CircleAvatar(
                    radius: 22,
                    backgroundColor: Colors.deepPurple,
                    backgroundImage: (photoUrl != null && photoUrl.isNotEmpty)
                        ? NetworkImage(photoUrl)
                        : null,
                    onBackgroundImageError:
                        (photoUrl != null && photoUrl.isNotEmpty)
                        ? (_, _) {}
                        : null,
                    child: (photoUrl == null || photoUrl.isEmpty)
                        ? Text(
                            initials,
                            style: const TextStyle(
                              color: Colors.white,
                              fontWeight: FontWeight.bold,
                              fontSize: 16,
                            ),
                          )
                        : null,
                  ),
                  const SizedBox(width: 12),
                  Expanded(
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.start,
                      children: [
                        Text(
                          name,
                          style: Theme.of(context).textTheme.titleMedium,
                        ),
                        Text(
                          userId.length > 8 ? userId.substring(0, 8) : userId,
                          style: Theme.of(context).textTheme.bodySmall,
                        ),
                      ],
                    ),
                  ),
                ],
              ),
              if (lastActivity != null) ...[
                const SizedBox(height: 12),
                Row(
                  children: [
                    Icon(Icons.access_time, size: 16, color: Colors.grey[600]),
                    const SizedBox(width: 6),
                    Flexible(
                      child: Text(
                        ref
                            .read(localizationProvider)
                            .getString('adminMapLastActive')
                            .replaceAll('{time}', lastActivity),
                        style: Theme.of(context).textTheme.bodySmall,
                        overflow: TextOverflow.ellipsis,
                      ),
                    ),
                  ],
                ),
              ],
            ],
          ),
        ),
      ),
    );
  }
}

double _niceScaleDistance(double meters) {
  const magnitudes = <double>[
    1,
    2,
    5,
    10,
    20,
    50,
    100,
    200,
    500,
    1000,
    2000,
    5000,
    10000,
    20000,
    50000,
    100000,
  ];
  for (final m in magnitudes) {
    if (meters >= m * 0.7 && meters <= m * 1.5) return m;
  }
  return magnitudes.last;
}

class _ScaleBarPainter extends CustomPainter {
  final double barWidth;
  final String label;
  final Color color;

  _ScaleBarPainter({
    required this.barWidth,
    required this.label,
    required this.color,
  });

  @override
  void paint(Canvas canvas, Size size) {
    final paint = Paint()
      ..color = color
      ..strokeWidth = 2
      ..style = PaintingStyle.stroke;

    final barY = size.height / 2;
    final barLeft = 4.0;
    final barRight = barLeft + min(barWidth, size.width - 8);

    canvas.drawLine(Offset(barLeft, barY), Offset(barRight, barY), paint);
    canvas.drawLine(
      Offset(barLeft, barY - 4),
      Offset(barLeft, barY + 4),
      paint,
    );
    canvas.drawLine(
      Offset(barRight, barY - 4),
      Offset(barRight, barY + 4),
      paint,
    );

    final tp = TextPainter(
      text: TextSpan(
        text: label,
        style: TextStyle(
          fontSize: 10,
          color: color,
          fontWeight: FontWeight.w500,
        ),
      ),
      textDirection: TextDirection.ltr,
    )..layout();
    tp.paint(canvas, Offset(barLeft, barY - 14));
  }

  @override
  bool shouldRepaint(_ScaleBarPainter old) =>
      old.barWidth != barWidth || old.label != label || old.color != color;
}

class _MapZoomControls extends StatelessWidget {
  final MapController controller;
  final double minZoom;
  final double maxZoom;

  const _MapZoomControls({
    required this.controller,
    required this.minZoom,
    required this.maxZoom,
  });

  void _zoom(double delta) {
    final camera = controller.camera;
    final nextZoom = (camera.zoom + delta).clamp(minZoom, maxZoom);
    controller.move(camera.center, nextZoom);
  }

  @override
  Widget build(BuildContext context) {
    return Material(
      color: Colors.transparent,
      child: Column(
        mainAxisSize: MainAxisSize.min,
        children: [
          FloatingActionButton.small(
            heroTag: null,
            backgroundColor: Theme.of(context).colorScheme.surface,
            onPressed: () => _zoom(1),
            child: const Icon(Icons.add),
          ),
          const SizedBox(height: 8),
          FloatingActionButton.small(
            heroTag: null,
            backgroundColor: Theme.of(context).colorScheme.surface,
            onPressed: () => _zoom(-1),
            child: const Icon(Icons.remove),
          ),
        ],
      ),
    );
  }
}

class _AdminKeyValueRow extends StatelessWidget {
