class _AdminSparkBars extends StatelessWidget {
  final List<int> values;
  final Color color;
  final String label;
  final String? oldestLabel;
  final String? newestLabel;
  final List<DateTime>? bucketStarts;
  final String? bucketWindow;
  final String? tooltipTemplate;
  final LocalizationState l10n;

  const _AdminSparkBars({
    required this.values,
    required this.color,
    required this.label,
    required this.l10n,
    this.oldestLabel,
    this.newestLabel,
    this.bucketStarts,
    this.bucketWindow,
    this.tooltipTemplate,
  });

  String _bucketRange(DateTime bucketStartUtc, String window) {
    final start = bucketStartUtc.toLocal();
    if (window == '24h') {
      final fmt = DateFormat.Hm(l10n.locale.languageCode);
      final end = start.add(const Duration(hours: 1));
      return '${fmt.format(start)}–${fmt.format(end)}';
    }
    final fmt = DateFormat.Md(l10n.locale.languageCode);
    return fmt.format(start);
  }

  String _bucketXAxisLabel(DateTime bucketStartUtc, String window) {
    final start = bucketStartUtc.toLocal();
    if (window == '24h') {
      final fmt = DateFormat.Hm(l10n.locale.languageCode);
      return fmt.format(start);
    }
    final fmt = DateFormat.Md(l10n.locale.languageCode);
    return fmt.format(start);
  }

  @override
  Widget build(BuildContext context) {
    final maxValue = values.isEmpty
        ? 0
        : values.reduce((a, b) => a > b ? a : b);
    final barCount = values.isEmpty ? 1 : values.length;
    final isRtl = Directionality.of(context) == TextDirection.rtl;
    final oldest = oldestLabel ?? '';
    final newest = newestLabel ?? '';
    final starts = bucketStarts;
    final window = bucketWindow ?? '24h';
    final template = tooltipTemplate ?? '{label}: {value} ({range})';
    final barWidth = window == '24h' ? 46.0 : 64.0;
    final labelLines = 1;
    final labelHeight = 16.0;
    final chartHeight = 96.0 + 6.0 + labelHeight;

    return Column(
      crossAxisAlignment: CrossAxisAlignment.stretch,
      children: [
        Text(label, style: Theme.of(context).textTheme.titleSmall),
        const SizedBox(height: 8),
        SizedBox(
          height: chartHeight,
          child: SingleChildScrollView(
            scrollDirection: Axis.horizontal,
            reverse: !isRtl,
            child: ConstrainedBox(
              constraints: BoxConstraints(minWidth: barWidth * barCount),
              child: Row(
                crossAxisAlignment: CrossAxisAlignment.end,
                children: [
                  for (var i = 0; i < barCount; i++)
                    SizedBox(
                      width: barWidth,
                      child: Padding(
                        padding: const EdgeInsets.symmetric(horizontal: 2),
                        child: Column(
                          mainAxisAlignment: MainAxisAlignment.end,
                          children: [
                            Tooltip(
                              message: () {
                                final value = values.isEmpty ? 0 : values[i];
                                final range =
                                    (starts != null &&
                                        starts.length == values.length &&
                                        i < starts.length)
                                    ? _bucketRange(starts[i], window)
                                    : '';
                                return template
                                    .replaceAll('{label}', label)
                                    .replaceAll('{value}', value.toString())
                                    .replaceAll('{range}', range);
                              }(),
                              child: Container(
                                height: (values.isEmpty || maxValue <= 0)
                                    ? 2
                                    : (96 * (values[i] / maxValue))
                                          .clamp(2, 96)
                                          .toDouble(),
                                decoration: BoxDecoration(
                                  color: color.withValues(alpha: 0.85),
                                  borderRadius: BorderRadius.circular(6),
                                ),
                              ),
                            ),
                            const SizedBox(height: 6),
                            SizedBox(
                              height: labelHeight,
                              child: Center(
                                child: Text(
                                  (starts != null &&
                                          starts.length == values.length &&
                                          i < starts.length)
                                      ? _bucketXAxisLabel(starts[i], window)
                                      : '',
                                  textAlign: TextAlign.center,
                                  maxLines: labelLines,
                                  overflow: TextOverflow.ellipsis,
                                  style: Theme.of(context).textTheme.bodySmall,
                                ),
                              ),
                            ),
                          ],
                        ),
                      ),
                    ),
                ],
              ),
            ),
          ),
        ),
        if (oldest.isNotEmpty && newest.isNotEmpty) ...[
          const SizedBox(height: 6),
          DefaultTextStyle(
            style:
                Theme.of(context).textTheme.bodySmall?.copyWith(
                  color: Theme.of(context).colorScheme.onSurfaceVariant,
                ) ??
                const TextStyle(),
            child: Row(
              children: [
                Text(isRtl ? newest : oldest),
                const Spacer(),
                Text(isRtl ? oldest : newest),
              ],
            ),
          ),
        ],
      ],
    );
  }
}

enum _TaxonomyEntity { intents, interests }

enum _TaxonomyScope { all, social, business }

class _AdminTaxonomyRow {
  final int id;
  final String key;
  final int? parentId;
  final String translationKey;
  final int sortOrder;
  final bool isSocial;
  final bool isBusiness;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  const _AdminTaxonomyRow({
    required this.id,
    required this.key,
    required this.parentId,
    required this.translationKey,
    required this.sortOrder,
    required this.isSocial,
    required this.isBusiness,
    required this.createdAt,
    required this.updatedAt,
  });

  static DateTime? _tryDate(dynamic v) {
    if (v == null) return null;
    if (v is DateTime) return v;
    return DateTime.tryParse(v.toString());
  }

  static int _toInt(dynamic v) {
    if (v is int) return v;
    if (v is num) return v.toInt();
    return int.tryParse((v ?? '').toString()) ?? 0;
  }

  static bool _toBool(dynamic v) {
    if (v is bool) return v;
    final s = (v ?? '').toString().trim().toLowerCase();
    return s == 'true' || s == '1' || s == 't' || s == 'yes' || s == 'y';
  }

  factory _AdminTaxonomyRow.fromRow(Map<String, dynamic> row) {
    final parentRaw = row['parent_id'];
    final parent = parentRaw == null ? null : _toInt(parentRaw);
    return _AdminTaxonomyRow(
      id: _toInt(row['id']),
      key: (row['key'] ?? '').toString(),
      parentId: parent == 0 ? null : parent,
      translationKey: (row['translation_key'] ?? '').toString(),
      sortOrder: _toInt(row['sort_order']),
      isSocial: _toBool(row['is_social']),
      isBusiness: _toBool(row['is_business']),
      createdAt: _tryDate(row['created_at']),
      updatedAt: _tryDate(row['updated_at']),
    );
  }
}

class _IntentsInterestsScreen extends ConsumerStatefulWidget {
  const _IntentsInterestsScreen();

  @override
  ConsumerState<_IntentsInterestsScreen> createState() =>
      _IntentsInterestsScreenState();
}

class _IntentsInterestsScreenState
    extends ConsumerState<_IntentsInterestsScreen> {
  bool _isLoading = true;
  String? _errorKey;

  _TaxonomyEntity _entity = _TaxonomyEntity.intents;
  _TaxonomyScope _scope = _TaxonomyScope.all;
  String _query = '';

  List<_AdminTaxonomyRow> _intents = const [];
  List<_AdminTaxonomyRow> _interests = const [];

  // Realtime + poll fallback so taxonomy changes made by another admin
  // appear without a refresh button or restart.
  late final List<AdminRealtimeRefresher> _refreshers = [
    AdminRealtimeRefresher(
      channelName: 'admin_intents',
      table: 'intents',
      onChange: () {
        if (mounted && !_isLoading) unawaited(_load(force: true));
      },
    ),
    AdminRealtimeRefresher(
      channelName: 'admin_interests',
      table: 'interests',
      onChange: () {
        if (mounted && !_isLoading) unawaited(_load(force: true));
      },
    ),
  ];

  @override
  void initState() {
    super.initState();
    unawaited(_load());
    for (final r in _refreshers) {
      r.start();
    }
  }

  @override
  void dispose() {
    for (final r in _refreshers) {
      r.dispose();
    }
    super.dispose();
  }

  Future<void> _load({bool force = false}) async {
    List<Map<String, dynamic>> decodeListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final entityKey = _entity == _TaxonomyEntity.intents
        ? 'intents'
        : 'interests';
    final cacheKey = 'admin_cache:$entityKey:v1';
    var hadCached = false;

    if (!mounted) return;

    if (!force) {
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (cached != null) {
        final raw = cached.data;
        final rows =
            raw
                .map((r) => _AdminTaxonomyRow.fromRow(r))
                .where((r) => r.id != 0 && r.key.isNotEmpty)
                .toList(growable: false)
              ..sort((a, b) {
                final c = a.sortOrder.compareTo(b.sortOrder);
                if (c != 0) return c;
                return a.key.compareTo(b.key);
              });
        setState(() {
          if (_entity == _TaxonomyEntity.intents) {
            _intents = rows;
          } else {
            _interests = rows;
          }
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached) {
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionData(
          entityKey,
        );
        if (hiveData.isNotEmpty && mounted) {
          final rows =
              hiveData
                  .map((r) => _AdminTaxonomyRow.fromRow(r))
                  .where((r) => r.id != 0 && r.key.isNotEmpty)
                  .toList(growable: false)
                ..sort((a, b) {
                  final c = a.sortOrder.compareTo(b.sortOrder);
                  if (c != 0) return c;
                  return a.key.compareTo(b.key);
                });
          setState(() {
            if (_entity == _TaxonomyEntity.intents) {
              _intents = rows;
            } else {
              _interests = rows;
            }
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _isLoading = !hadCached;
      _errorKey = null;
    });

    try {
      final client = Supabase.instance.client;
      final rpcName = _entity == _TaxonomyEntity.intents
          ? 'admin_list_intents'
          : 'admin_list_interests';
      final raw = await client.rpc(rpcName, params: const <String, dynamic>{});
      final list = raw is List ? raw : const [];
      final mapList = List<Map<String, dynamic>>.from(
        list,
      ).map((r) => Map<String, dynamic>.from(r)).toList(growable: false);

      await _AdminCache.write<List<Map<String, dynamic>>>(
        cacheKey,
        (v) => v,
        mapList,
      );
      try {
        await AdminLocalDbService.shared.saveSectionData(entityKey, mapList);
      } catch (_) {}

      final rows =
          mapList
              .map(_AdminTaxonomyRow.fromRow)
              .where((r) => r.id != 0 && r.key.isNotEmpty)
              .toList(growable: false)
            ..sort((a, b) {
              final c = a.sortOrder.compareTo(b.sortOrder);
              if (c != 0) return c;
              return a.key.compareTo(b.key);
            });

      if (!mounted) return;
      setState(() {
        if (_entity == _TaxonomyEntity.intents) {
          _intents = rows;
        } else {
          _interests = rows;
        }
        _isLoading = false;
        _errorKey = null;
      });
    } on PostgrestException catch (e, st) {
      developer.log(
        'taxonomy list PostgREST error',
        name: 'MatchMeAdmin',
        error: e,
        stackTrace: st,
      );
      if (!mounted) return;
      if (hadCached) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminIntentsInterestsLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _isLoading = false;
          _errorKey = 'adminIntentsInterestsOfflineNotCached';
        });
      } else {
        final msg = '${e.message} ${e.hint ?? ''} ${e.details ?? ''}';
        final lower = msg.toLowerCase();
        final key = lower.contains('not authorized')
            ? 'adminNotAuthorized'
            : msg.contains('No API key found') ||
                  msg.contains('apikey') ||
                  msg.contains('No `apikey`')
            ? 'supabaseConfigMissing'
            : lower.contains('could not find the function') ||
                  lower.contains('schema cache') ||
                  lower.contains('pgrst202') ||
                  lower.contains('function') && lower.contains('admin_list_')
            ? 'adminIntentsInterestsRpcMissing'
            : 'adminIntentsInterestsLoadFailed';
        setState(() {
          _isLoading = false;
          _errorKey = key;
        });
      }
    } catch (e, st) {
      developer.log(
        'taxonomy list failed',
        name: 'MatchMeAdmin',
        error: e,
        stackTrace: st,
      );
      if (!mounted) return;
      if (hadCached) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminIntentsInterestsLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _isLoading = false;
          _errorKey = 'adminIntentsInterestsOfflineNotCached';
        });
      } else {
        setState(() {
          _isLoading = false;
          _errorKey = 'adminIntentsInterestsLoadFailed';
        });
      }
    }
  }

  List<_AdminTaxonomyRow> _visibleRows(LocalizationState l10n) {
    final rows = _entity == _TaxonomyEntity.intents ? _intents : _interests;
    final q = _query.trim().toLowerCase();

    bool matchesScope(_AdminTaxonomyRow r) {
      return switch (_scope) {
        _TaxonomyScope.all => true,
        _TaxonomyScope.social => r.isSocial,
        _TaxonomyScope.business => r.isBusiness,
      };
    }

    bool matchesQuery(_AdminTaxonomyRow r) {
      if (q.isEmpty) return true;
      final localized = l10n.getString(r.translationKey).toLowerCase();
      return r.key.toLowerCase().contains(q) ||
          r.translationKey.toLowerCase().contains(q) ||
          localized.contains(q);
    }

    return rows
        .where((r) => matchesScope(r) && matchesQuery(r))
        .toList(growable: false);
  }

  Future<void> _upsertRow({
    required _TaxonomyEntity entity,
    _AdminTaxonomyRow? existing,
    int? fixedParentId,
  }) async {
    final l10n = ref.read(localizationProvider);
    final formKey = GlobalKey<FormState>();

    final isEditing = existing != null;
    final keyController = TextEditingController(text: existing?.key ?? '');
    final translationKeyController = TextEditingController(
      text: existing?.translationKey ?? '',
    );
    final sortOrderController = TextEditingController(
      text: (existing?.sortOrder ?? 0).toString(),
    );
    final enController = TextEditingController();
    final esController = TextEditingController();
    final heController = TextEditingController();

    var parentId = fixedParentId ?? existing?.parentId;
    var isSocial = existing?.isSocial ?? true;
    var isBusiness = existing?.isBusiness ?? false;

    final rows = entity == _TaxonomyEntity.intents ? _intents : _interests;
    final parents =
        rows.where((r) => r.parentId == null).toList(growable: false)
          ..sort((a, b) {
            final c = a.sortOrder.compareTo(b.sortOrder);
            if (c != 0) return c;
            return a.key.compareTo(b.key);
          });

    var isSubmitting = false;

    String titleKey() {
      if (entity == _TaxonomyEntity.intents) {
        return isEditing
            ? 'adminIntentsInterestsEditIntent'
            : 'adminIntentsInterestsAddIntent';
      }
      return isEditing
          ? 'adminIntentsInterestsEditInterest'
          : 'adminIntentsInterestsAddInterest';
    }

    var didLoadText = false;
    var isTextLoading = false;
    var textLoadFailed = false;

    Future<void> loadText(
      NavigatorState dialogNavigator,
      void Function(void Function()) setDialogState,
    ) async {
      final translationKey = translationKeyController.text.trim();
      if (translationKey.isEmpty) return;

      if (!dialogNavigator.mounted) return;
      setDialogState(() {
        isTextLoading = true;
        textLoadFailed = false;
      });

      try {
        final byLocale = <String, String>{};
        for (final locale in const ['en', 'es', 'he']) {
          final translations = await publicReferenceDataService
              .fetchTranslations(locale);
          final value = translations[translationKey];
          if (value != null && value.isNotEmpty) {
            byLocale[locale] = value;
          }
        }

        if (!dialogNavigator.mounted) return;
        setDialogState(() {
          enController.text = byLocale['en'] ?? '';
          esController.text = byLocale['es'] ?? '';
          heController.text = byLocale['he'] ?? '';
          isTextLoading = false;
          textLoadFailed = false;
        });
      } catch (_) {
        if (!dialogNavigator.mounted) return;
        setDialogState(() {
          isTextLoading = false;
          textLoadFailed = true;
        });
      }
    }

    Future<void> submit(
      BuildContext dialogCtx,
      void Function(void Function()) setDialogState,
    ) async {
      if (!(formKey.currentState?.validate() ?? false)) return;

      final sortOrder = int.tryParse(sortOrderController.text.trim()) ?? 0;
      final key = keyController.text.trim();
      final translationKey = translationKeyController.text.trim();

      if (!dialogCtx.mounted) return;
      setDialogState(() {
        isSubmitting = true;
      });

      try {
        final client = Supabase.instance.client;
        final rpcName = entity == _TaxonomyEntity.intents
            ? 'admin_upsert_intent'
            : 'admin_upsert_interest';
        await client.rpc(
          rpcName,
          params: {
            'p_id': existing?.id,
            'p_key': key,
            'p_parent_id': parentId,
            'p_translation_key': translationKey,
            'p_sort_order': sortOrder,
            'p_is_social': isSocial,
            'p_is_business': isBusiness,
          },
        );

        await client.rpc(
          'admin_bulk_upsert_translations',
          params: {
            'p_items': [
              {
                'locale': 'en',
                'key': translationKey,
                'value': enController.text,
              },
              {
                'locale': 'es',
                'key': translationKey,
                'value': esController.text,
              },
              {
                'locale': 'he',
                'key': translationKey,
                'value': heController.text,
              },
            ],
          },
        );

        final notifier = ref.read(localizationProvider.notifier);
        await notifier.patchTranslationValue(
          locale: 'en',
          key: translationKey,
          value: enController.text,
        );
        await notifier.patchTranslationValue(
          locale: 'es',
          key: translationKey,
          value: esController.text,
        );
        await notifier.patchTranslationValue(
          locale: 'he',
          key: translationKey,
          value: heController.text,
        );

        if (!mounted || !dialogCtx.mounted) return;
        Navigator.of(dialogCtx).pop();
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(l10n.getString('adminSaved'))));
        unawaited(_load(force: true));
      } catch (_) {
        if (!mounted || !dialogCtx.mounted) return;
        setDialogState(() {
          isSubmitting = false;
        });
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(l10n.getString('adminIntentsInterestsSaveFailed')),
          ),
        );
      }
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          if (!didLoadText) {
            didLoadText = true;
            final dialogNavigator = Navigator.of(ctx);
            Future.microtask(() => loadText(dialogNavigator, setDialogState));
          }

          final parentEnabled = !isEditing && fixedParentId == null;
          return AlertDialog(
            title: Text(l10n.getString(titleKey())),
            content: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 720),
              child: Form(
                key: formKey,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      TextFormField(
                        controller: keyController,
                        enabled: !isEditing,
                        decoration: InputDecoration(
                          labelText: l10n.getString('adminIntentsInterestsKey'),
                        ),
                        validator: (v) {
                          if ((v ?? '').trim().isEmpty) {
                            return l10n.getString(
                              'adminIntentsInterestsKeyRequired',
                            );
                          }
                          return null;
                        },
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: translationKeyController,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsTranslationKey',
                          ),
                        ),
                        validator: (v) {
                          if ((v ?? '').trim().isEmpty) {
                            return l10n.getString(
                              'adminIntentsInterestsTranslationKeyRequired',
                            );
                          }
                          return null;
                        },
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: sortOrderController,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsSortOrder',
                          ),
                        ),
                        keyboardType: TextInputType.number,
                      ),
                      const SizedBox(height: 12),
                      DropdownMenu<int?>(
                        enabled: parentEnabled,
                        initialSelection: parentId,
                        label: Text(
                          l10n.getString('adminIntentsInterestsParent'),
                        ),
                        dropdownMenuEntries: [
                          DropdownMenuEntry(
                            value: null,
                            label: l10n.getString(
                              'adminIntentsInterestsNoParent',
                            ),
                          ),
                          ...parents.map(
                            (p) => DropdownMenuEntry(
                              value: p.id,
                              label:
                                  '${l10n.getString(p.translationKey)} (${p.key})',
                            ),
                          ),
                        ],
                        onSelected: parentEnabled
                            ? (v) => setDialogState(() => parentId = v)
                            : null,
                      ),
                      const SizedBox(height: 8),
                      CheckboxListTile(
                        value: isSocial,
                        onChanged: (v) =>
                            setDialogState(() => isSocial = v ?? false),
                        title: Text(
                          l10n.getString('adminIntentsInterestsIsSocial'),
                        ),
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.leading,
                      ),
                      CheckboxListTile(
                        value: isBusiness,
                        onChanged: (v) =>
                            setDialogState(() => isBusiness = v ?? false),
                        title: Text(
                          l10n.getString('adminIntentsInterestsIsBusiness'),
                        ),
                        contentPadding: EdgeInsets.zero,
                        controlAffinity: ListTileControlAffinity.leading,
                      ),
                      const SizedBox(height: 12),
                      Row(
                        children: [
                          Expanded(
                            child: Text(
                              l10n.getString('adminIntentsInterestsEditText'),
                              style: Theme.of(ctx).textTheme.titleMedium,
                            ),
                          ),
                          IconButton(
                            tooltip: l10n.getString('generalRefresh'),
                            onPressed: isTextLoading
                                ? null
                                : () => loadText(
                                    Navigator.of(ctx),
                                    setDialogState,
                                  ),
                            icon: const Icon(Icons.refresh),
                          ),
                        ],
                      ),
                      if (textLoadFailed)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: Text(
                            l10n.getString('adminIntentsInterestsLoadFailed'),
                            style: Theme.of(ctx).textTheme.bodyMedium?.copyWith(
                              color: Theme.of(ctx).colorScheme.error,
                            ),
                          ),
                        ),
                      TextFormField(
                        controller: enController,
                        enabled: !isTextLoading,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleEn',
                          ),
                        ),
                        maxLines: null,
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: esController,
                        enabled: !isTextLoading,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleEs',
                          ),
                        ),
                        maxLines: null,
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: heController,
                        enabled: !isTextLoading,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleHe',
                          ),
                        ),
                        textDirection: TextDirection.rtl,
                        textAlign: TextAlign.right,
                        maxLines: null,
                      ),
                    ],
                  ),
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: isSubmitting ? null : () => Navigator.of(ctx).pop(),
                child: Text(l10n.getString('generalCancel')),
              ),
              FilledButton(
                onPressed: isSubmitting
                    ? null
                    : () => submit(ctx, setDialogState),
                child: isSubmitting
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : Text(l10n.getString('generalSave')),
              ),
            ],
          );
        },
      ),
    );

    _disposeTextControllersLater([
      keyController,
      translationKeyController,
      sortOrderController,
      enController,
      esController,
      heController,
    ]);
  }

  Future<void> _deleteRow({
    required _TaxonomyEntity entity,
    required _AdminTaxonomyRow row,
  }) async {
    final l10n = ref.read(localizationProvider);

    final titleKey = entity == _TaxonomyEntity.intents
        ? 'adminIntentsInterestsDeleteIntentTitle'
        : 'adminIntentsInterestsDeleteInterestTitle';
    final bodyKey = entity == _TaxonomyEntity.intents
        ? 'adminIntentsInterestsDeleteIntentBody'
        : 'adminIntentsInterestsDeleteInterestBody';

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(l10n.getString(titleKey)),
        content: Text(l10n.getString(bodyKey).replaceAll('{key}', row.key)),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(l10n.getString('generalCancel')),
          ),
          FilledButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: Text(l10n.getString('generalDelete')),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    try {
      final client = Supabase.instance.client;
      final rpcName = entity == _TaxonomyEntity.intents
          ? 'admin_delete_intent'
          : 'admin_delete_interest';
      await client.rpc(rpcName, params: {'p_id': row.id});
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(l10n.getString('adminDeleted'))));
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(l10n.getString('adminIntentsInterestsDeleteFailed')),
        ),
      );
    }
  }

  Future<void> _editTranslationText(_AdminTaxonomyRow row) async {
    final l10n = ref.read(localizationProvider);
    final translationKey = row.translationKey.trim();
    if (translationKey.isEmpty) return;

    final enController = TextEditingController();
    final esController = TextEditingController();
    final heController = TextEditingController();

    var didLoad = false;
    var isLoading = true;
    var loadFailed = false;
    var isSubmitting = false;

    Future<void> load(
      NavigatorState dialogNavigator,
      StateSetter setDialogState,
    ) async {
      try {
        final byLocale = <String, String>{};
        for (final locale in const ['en', 'es', 'he']) {
          final translations = await publicReferenceDataService
              .fetchTranslations(locale);
          final value = translations[translationKey];
          if (value != null && value.isNotEmpty) {
            byLocale[locale] = value;
          }
        }

        if (!dialogNavigator.mounted) return;
        setDialogState(() {
          enController.text = byLocale['en'] ?? '';
          esController.text = byLocale['es'] ?? '';
          heController.text = byLocale['he'] ?? '';
          isLoading = false;
          loadFailed = false;
        });
      } catch (_) {
        if (!dialogNavigator.mounted) return;
        setDialogState(() {
          isLoading = false;
          loadFailed = true;
        });
      }
    }

    Future<void> submit(
      BuildContext dialogCtx,
      StateSetter setDialogState,
    ) async {
      if (!dialogCtx.mounted) return;
      setDialogState(() => isSubmitting = true);
      try {
        await Supabase.instance.client
            .rpc(
              'admin_bulk_upsert_translations',
              params: {
                'p_items': [
                  {
                    'locale': 'en',
                    'key': translationKey,
                    'value': enController.text,
                  },
                  {
                    'locale': 'es',
                    'key': translationKey,
                    'value': esController.text,
                  },
                  {
                    'locale': 'he',
                    'key': translationKey,
                    'value': heController.text,
                  },
                ],
              },
            )
            .timeout(const Duration(seconds: 20));

        final notifier = ref.read(localizationProvider.notifier);
        await notifier.patchTranslationValue(
          locale: 'en',
          key: translationKey,
          value: enController.text,
        );
        await notifier.patchTranslationValue(
          locale: 'es',
          key: translationKey,
          value: esController.text,
        );
        await notifier.patchTranslationValue(
          locale: 'he',
          key: translationKey,
          value: heController.text,
        );

        if (!mounted || !dialogCtx.mounted) return;
        Navigator.of(dialogCtx).pop();
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(l10n.getString('adminSaved'))));
      } catch (_) {
        if (!mounted || !dialogCtx.mounted) return;
        setDialogState(() => isSubmitting = false);
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(l10n.getString('adminIntentsInterestsSaveFailed')),
          ),
        );
      }
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          if (!didLoad) {
            didLoad = true;
            final dialogNavigator = Navigator.of(ctx);
            Future.microtask(() => load(dialogNavigator, setDialogState));
          }

          return AlertDialog(
            title: Text(
              l10n
                  .getString('adminIntentsInterestsEditTextTitle')
                  .replaceAll('{key}', translationKey),
            ),
            content: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 720),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      l10n.getString('adminIntentsInterestsTranslationKey'),
                      style: Theme.of(ctx).textTheme.labelMedium,
                    ),
                    const SizedBox(height: 6),
                    SelectableText(translationKey),
                    const SizedBox(height: 12),
                    if (isLoading)
                      Padding(
                        padding: const EdgeInsets.symmetric(vertical: 12),
                        child: Text(l10n.getString('generalLoading')),
                      )
                    else ...[
                      if (loadFailed)
                        Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: Text(
                            l10n.getString('adminIntentsInterestsLoadFailed'),
                            style: Theme.of(ctx).textTheme.bodyMedium?.copyWith(
                              color: Theme.of(ctx).colorScheme.error,
                            ),
                          ),
                        ),
                      TextFormField(
                        controller: enController,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleEn',
                          ),
                        ),
                        minLines: 1,
                        maxLines: null,
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: esController,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleEs',
                          ),
                        ),
                        minLines: 1,
                        maxLines: null,
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: heController,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminIntentsInterestsLocaleHe',
                          ),
                        ),
                        textDirection: TextDirection.rtl,
                        textAlign: TextAlign.right,
                        minLines: 1,
                        maxLines: null,
                      ),
                    ],
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: isSubmitting ? null : () => Navigator.of(ctx).pop(),
                child: Text(l10n.getString('generalCancel')),
              ),
              FilledButton(
                onPressed: (isSubmitting || isLoading)
                    ? null
                    : () => submit(ctx, setDialogState),
                child: isSubmitting
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : Text(l10n.getString('generalSave')),
              ),
            ],
          );
        },
      ),
    );

    _disposeTextControllersLater([enController, esController, heController]);
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final rows = _visibleRows(l10n);

    final parents =
        rows.where((r) => r.parentId == null).toList(growable: false)
          ..sort((a, b) {
            final c = a.sortOrder.compareTo(b.sortOrder);
            if (c != 0) return c;
            return a.key.compareTo(b.key);
          });

    final childrenByParent = <int, List<_AdminTaxonomyRow>>{};
    for (final r in rows) {
      final pid = r.parentId;
      if (pid == null) continue;
      (childrenByParent[pid] ??= <_AdminTaxonomyRow>[]).add(r);
    }
    for (final entry in childrenByParent.entries) {
      entry.value.sort((a, b) {
        final c = a.sortOrder.compareTo(b.sortOrder);
        if (c != 0) return c;
        return a.key.compareTo(b.key);
      });
    }

    Widget body() {
      if (_isLoading) {
        return Center(child: Text(l10n.getString('generalLoading')));
      }
      if (_errorKey != null) {
        return Center(
          child: Text(
            l10n.getString(_errorKey!),
            style: Theme.of(context).textTheme.bodyMedium?.copyWith(
              color: Theme.of(context).colorScheme.error,
            ),
          ),
        );
      }
      if (parents.isEmpty) {
        return Center(
          child: Text(l10n.getString('adminIntentsInterestsEmpty')),
        );
      }

      return ListView(
        padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
        children: [
          for (final p in parents) ...[
            Card(
              color: Theme.of(context).colorScheme.surfaceContainerHighest,
              child: ListTile(
                leading: Icon(
                  Icons.label_important_outline,
                  color: Theme.of(context).colorScheme.primary,
                ),
                title: Text(
                  l10n.getString(p.translationKey),
                  overflow: TextOverflow.ellipsis,
                  style: Theme.of(context).textTheme.titleMedium?.copyWith(
                    fontWeight: FontWeight.w700,
                  ),
                ),
                subtitle: Text(p.key),
                trailing: PopupMenuButton<String>(
                  onSelected: (value) async {
                    if (value == 'add_child') {
                      await _upsertRow(entity: _entity, fixedParentId: p.id);
                      return;
                    }
                    if (value == 'edit') {
                      await _upsertRow(entity: _entity, existing: p);
                      return;
                    }
                    if (value == 'edit_text') {
                      await _editTranslationText(p);
                      return;
                    }
                    if (value == 'delete') {
                      await _deleteRow(entity: _entity, row: p);
                      return;
                    }
                  },
                  itemBuilder: (ctx) => [
                    PopupMenuItem(
                      value: 'add_child',
                      child: Text(
                        l10n.getString('adminIntentsInterestsAddChild'),
                      ),
                    ),
                    PopupMenuItem(
                      value: 'edit',
                      child: Text(l10n.getString('generalEdit')),
                    ),
                    PopupMenuItem(
                      value: 'edit_text',
                      child: Text(
                        l10n.getString('adminIntentsInterestsEditText'),
                      ),
                    ),
                    PopupMenuItem(
                      value: 'delete',
                      child: Text(l10n.getString('generalDelete')),
                    ),
                  ],
                ),
              ),
            ),
            for (final c
                in childrenByParent[p.id] ?? const <_AdminTaxonomyRow>[])
              Padding(
                padding: const EdgeInsetsDirectional.only(start: 16),
                child: Card(
                  child: ListTile(
                    title: Text(
                      l10n.getString(c.translationKey),
                      overflow: TextOverflow.ellipsis,
                    ),
                    subtitle: Text(c.key),
                    trailing: PopupMenuButton<String>(
                      onSelected: (value) async {
                        if (value == 'edit') {
                          await _upsertRow(entity: _entity, existing: c);
                          return;
                        }
                        if (value == 'edit_text') {
                          await _editTranslationText(c);
                          return;
                        }
                        if (value == 'delete') {
                          await _deleteRow(entity: _entity, row: c);
                          return;
                        }
                      },
                      itemBuilder: (ctx) => [
                        PopupMenuItem(
                          value: 'edit',
                          child: Text(l10n.getString('generalEdit')),
                        ),
                        PopupMenuItem(
                          value: 'edit_text',
                          child: Text(
                            l10n.getString('adminIntentsInterestsEditText'),
                          ),
                        ),
                        PopupMenuItem(
                          value: 'delete',
                          child: Text(l10n.getString('generalDelete')),
                        ),
                      ],
                    ),
                  ),
                ),
              ),
          ],
        ],
      );
    }

    String entityLabel(_TaxonomyEntity e) {
      return switch (e) {
        _TaxonomyEntity.intents => l10n.getString(
          'adminIntentsInterestsTabIntents',
        ),
        _TaxonomyEntity.interests => l10n.getString(
          'adminIntentsInterestsTabInterests',
        ),
      };
    }

    String scopeLabel(_TaxonomyScope s) {
      return switch (s) {
        _TaxonomyScope.all => l10n.getString('adminIntentsInterestsFilterAll'),
        _TaxonomyScope.social => l10n.getString(
          'adminIntentsInterestsFilterSocial',
        ),
        _TaxonomyScope.business => l10n.getString(
          'adminIntentsInterestsFilterBusiness',
        ),
      };
    }

    final addKey = _entity == _TaxonomyEntity.intents
        ? 'adminIntentsInterestsAddIntent'
        : 'adminIntentsInterestsAddInterest';

    return LayoutBuilder(
      builder: (context, constraints) {
        final isWide = constraints.maxWidth >= 980;
        final padding = EdgeInsets.all(isWide ? 24 : 12);

        return Padding(
          padding: padding,
          child: Column(
            crossAxisAlignment: CrossAxisAlignment.stretch,
            children: [
              Wrap(
                spacing: 12,
                runSpacing: 12,
                crossAxisAlignment: WrapCrossAlignment.center,
                children: [
                  SegmentedButton<_TaxonomyEntity>(
                    segments: [
                      ButtonSegment(
                        value: _TaxonomyEntity.intents,
                        label: Text(entityLabel(_TaxonomyEntity.intents)),
                      ),
                      ButtonSegment(
                        value: _TaxonomyEntity.interests,
                        label: Text(entityLabel(_TaxonomyEntity.interests)),
                      ),
                    ],
                    selected: {_entity},
                    onSelectionChanged: (selection) {
                      if (selection.isEmpty) return;
                      final next = selection.first;
                      if (next == _entity) return;
                      setState(() {
                        _entity = next;
                        _errorKey = null;
                      });
                      unawaited(_load(force: true));
                    },
                  ),
                  SegmentedButton<_TaxonomyScope>(
                    segments: [
                      ButtonSegment(
                        value: _TaxonomyScope.all,
                        label: Text(scopeLabel(_TaxonomyScope.all)),
                      ),
                      ButtonSegment(
                        value: _TaxonomyScope.social,
                        label: Text(scopeLabel(_TaxonomyScope.social)),
                      ),
                      ButtonSegment(
                        value: _TaxonomyScope.business,
                        label: Text(scopeLabel(_TaxonomyScope.business)),
                      ),
                    ],
                    selected: {_scope},
                    onSelectionChanged: (selection) {
                      if (selection.isEmpty) return;
                      setState(() => _scope = selection.first);
                    },
                  ),
                  SizedBox(
                    width: 320,
                    child: TextField(
                      decoration: InputDecoration(
                        labelText: l10n.getString(
                          'adminIntentsInterestsSearchHint',
                        ),
                        prefixIcon: const Icon(Icons.search),
                      ),
                      onChanged: (v) => setState(() => _query = v),
                    ),
                  ),
                  FilledButton.icon(
                    onPressed: () => _upsertRow(entity: _entity),
                    icon: const Icon(Icons.add),
                    label: Text(l10n.getString(addKey)),
                  ),
                  OutlinedButton.icon(
                    onPressed: () => _load(force: true),
                    icon: const Icon(Icons.refresh),
                    label: Text(l10n.getString('generalRefresh')),
                  ),
                ],
              ),
              const SizedBox(height: 12),
              Expanded(child: body()),
            ],
          ),
        );
      },
    );
  }
}

class _AdminBroadcastRow {
  final String id;
  final String title;
  final String message;
  final String messageType;
  final String? automationType;
  final bool automationEnabled;
  final String? actionUrl;
  final String actionUrlText;
  final DateTime? scheduledAt;
  final DateTime? sentAt;
  final String status;
  final Map<String, dynamic> filterCriteria;
  final int? targetUserCount;
  final int actualSentCount;
  final int skippedCount;
  final String? createdBy;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  const _AdminBroadcastRow({
    required this.id,
    required this.title,
    required this.message,
    required this.messageType,
    required this.automationType,
    required this.automationEnabled,
    required this.actionUrl,
    required this.actionUrlText,
    required this.scheduledAt,
    required this.sentAt,
    required this.status,
    required this.filterCriteria,
    required this.targetUserCount,
    required this.actualSentCount,
    required this.skippedCount,
    required this.createdBy,
    required this.createdAt,
    required this.updatedAt,
  });

  static DateTime? _tryDate(dynamic v) {
    if (v == null) return null;
    if (v is DateTime) return v;
    return DateTime.tryParse(v.toString());
  }

  factory _AdminBroadcastRow.fromRow(Map<String, dynamic> row) {
    final rawCriteria = row['filter_criteria'];
    final criteria = rawCriteria is Map
        ? Map<String, dynamic>.from(rawCriteria)
        : <String, dynamic>{};
    return _AdminBroadcastRow(
      id: (row['id'] ?? '').toString(),
      title: (row['title'] ?? '').toString(),
      message: (row['message'] ?? '').toString(),
      messageType: (row['message_type'] ?? 'info').toString(),
      automationType: row['automation_type']?.toString(),
      automationEnabled: (row['automation_enabled'] as bool?) ?? false,
      actionUrl: row['action_url']?.toString(),
      actionUrlText: (row['action_url_text'] ?? '').toString(),
      scheduledAt: _tryDate(row['scheduled_at']),
      sentAt: _tryDate(row['sent_at']),
      status: (row['status'] ?? 'draft').toString(),
      filterCriteria: criteria,
      targetUserCount: row['target_user_count'] as int?,
      actualSentCount: (row['actual_sent_count'] as int?) ?? 0,
      skippedCount: (row['skipped_count'] as int?) ?? 0,
      createdBy: row['created_by']?.toString(),
      createdAt: _tryDate(row['created_at']),
      updatedAt: _tryDate(row['updated_at']),
    );
  }
}

class _BroadcastsScreen extends ConsumerStatefulWidget {
  const _BroadcastsScreen();

  @override
  ConsumerState<_BroadcastsScreen> createState() => _BroadcastsScreenState();
}

class _BroadcastsScreenState extends ConsumerState<_BroadcastsScreen> {
  bool _isLoading = true;
  String? _errorKey;
  List<_AdminBroadcastRow> _rows = const [];
  RealtimeChannel? _channel;
  Timer? _scheduledRealtimeRefresh;
  Timer? _pollTimer;
  int _realtimeRetries = 0;
  final ValueNotifier<int> _detailsRefreshTick = ValueNotifier<int>(0);
  final Set<String> _pendingRealtimeBroadcastIds = <String>{};
  String? _detailsRefreshBroadcastId;
  final Set<String> _resendInFlightIds = <String>{};

  String _query = '';
  String _status = 'all';
  String _timeFilter = 'all';

  @override
  void initState() {
    super.initState();
    _setupRealtime();
    unawaited(_load());
    // Fallback for when realtime delivery is unavailable (publication
    // membership off, or a socket the reconnect logic can't recover):
    // delivery progress and list changes still appear, just delayed.
    _pollTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted && !_isLoading) {
        unawaited(_load(force: true));
      }
    });
  }

  void _setupRealtime() {
    try {
      final channel = Supabase.instance.client.channel('admin-broadcasts');

      void onBroadcastChange(PostgresChangePayload payload) {
        final rawId = (payload.newRecord['id'] ?? payload.oldRecord['id'])
            ?.toString()
            .trim();
        _queueRealtimeRefresh((rawId == null || rawId.isEmpty) ? null : rawId);
      }

      void onDeliveryChange(PostgresChangePayload payload) {
        final rawId =
            (payload.newRecord['broadcast_id'] ??
                    payload.oldRecord['broadcast_id'])
                ?.toString()
                .trim();
        _queueRealtimeRefresh((rawId == null || rawId.isEmpty) ? null : rawId);
      }

      channel.onPostgresChanges(
        event: PostgresChangeEvent.all,
        schema: 'public',
        table: 'admin_broadcasts',
        callback: onBroadcastChange,
      );
      channel.onPostgresChanges(
        event: PostgresChangeEvent.all,
        schema: 'public',
        table: 'admin_broadcast_deliveries',
        callback: onDeliveryChange,
      );

      channel.subscribe((status, error) {
        // Bounded re-subscribe when the channel dies without a clean close;
        // the 30s poll covers us in the meantime and afterwards.
        if (mounted &&
            _realtimeRetries < 3 &&
            (status == RealtimeSubscribeStatus.channelError ||
                status == RealtimeSubscribeStatus.timedOut)) {
          _realtimeRetries++;
          Future.delayed(const Duration(seconds: 2), () {
            if (!mounted) return;
            final old = _channel;
            _channel = null;
            if (old != null) {
              try {
                Supabase.instance.client.removeChannel(old);
              } catch (_) {}
            }
            _setupRealtime();
          });
        }
      });
      _channel = channel;
    } catch (_) {}
  }

  void _queueRealtimeRefresh(String? broadcastId) {
    if (!mounted) return;
    if (broadcastId != null && broadcastId.isNotEmpty) {
      _pendingRealtimeBroadcastIds.add(broadcastId);
    }

    _scheduledRealtimeRefresh?.cancel();
    _scheduledRealtimeRefresh = Timer(const Duration(milliseconds: 800), () {
      if (!mounted) return;

      final affectedIds = _pendingRealtimeBroadcastIds.toSet();
      _pendingRealtimeBroadcastIds.clear();

      _detailsRefreshBroadcastId = switch (affectedIds.length) {
        0 => null,
        1 => affectedIds.first,
        _ => null,
      };
      _detailsRefreshTick.value++;

      unawaited(_load(force: true));
    });
  }

  Future<void> _load({bool force = false}) async {
    List<Map<String, dynamic>> decodeListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final cacheKey = 'admin_cache:broadcasts:v1';
    var hadCached = false;

    if (!force) {
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (cached != null) {
        final list = cached.data
            .map((r) => _AdminBroadcastRow.fromRow(r))
            .toList(growable: false);
        setState(() {
          _rows = list;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached) {
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionData(
          'broadcasts',
        );
        if (hiveData.isNotEmpty && mounted) {
          final list = hiveData
              .map((r) => _AdminBroadcastRow.fromRow(r))
              .toList(growable: false);
          setState(() {
            _rows = list;
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _isLoading = !hadCached;
      _errorKey = null;
    });

    try {
      final rows = await Supabase.instance.client
          .from('admin_broadcasts')
          .select(
            'id, title, message, message_type, automation_type, automation_enabled, action_url, action_url_text, scheduled_at, sent_at, status, filter_criteria, skipped_count, target_user_count, actual_sent_count, created_by, created_at, updated_at',
          )
          .order('created_at', ascending: false)
          .limit(500)
          .timeout(const Duration(seconds: 12));

      final raw = rows
          .map((r) => Map<String, dynamic>.from(r as Map))
          .toList(growable: false);
      await _AdminCache.write<List<Map<String, dynamic>>>(
        cacheKey,
        (v) => v,
        raw,
      );
      try {
        await AdminLocalDbService.shared.saveSectionData('broadcasts', raw);
      } catch (_) {}

      final list = raw
          .map((r) => _AdminBroadcastRow.fromRow(r))
          .toList(growable: false);

      if (!mounted) return;
      setState(() {
        _rows = list;
        _isLoading = false;
      });
    } catch (_) {
      if (!mounted) return;
      if (hadCached) {
        // Suppress error toasts when offline — the cached data is
        // still displayed and the offline indicator banner is already visible.
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminBroadcastsLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _errorKey = 'adminBroadcastsOfflineNotCached';
          _isLoading = false;
        });
      } else {
        setState(() {
          _errorKey = 'adminBroadcastsLoadFailed';
          _isLoading = false;
        });
      }
    }
  }

  String _timeFilterLabel(LocalizationState l10n, String value) {
    return switch (value) {
      'all' => l10n.getString('adminBroadcastsTimeAll'),
      'upcoming' => l10n.getString('adminBroadcastsTimeUpcoming'),
      'past' => l10n.getString('adminBroadcastsTimePast'),
      _ => value,
    };
  }

  String _statusLabel(LocalizationState l10n, String value) {
    return switch (value) {
      'all' => l10n.getString('adminStatusAll'),
      'draft' => l10n.getString('adminBroadcastsStatusDraft'),
      'scheduled' => l10n.getString('adminBroadcastsStatusScheduled'),
      'sending' => l10n.getString('adminBroadcastsStatusSending'),
      'sent' => l10n.getString('adminBroadcastsStatusSent'),
      'failed' => l10n.getString('adminBroadcastsStatusFailed'),
      'cancelled' => l10n.getString('adminBroadcastsStatusCancelled'),
      _ => value,
    };
  }

  String _typeLabel(LocalizationState l10n, String value) {
    return switch (value) {
      'info' => l10n.getString('adminBroadcastsTypeInfo'),
      'warning' => l10n.getString('adminBroadcastsTypeWarning'),
      'promotion' => l10n.getString('adminBroadcastsTypePromotion'),
      'update' => l10n.getString('adminBroadcastsTypeUpdate'),
      _ => value,
    };
  }

  bool _isBirthdayAutomation(_AdminBroadcastRow row) {
    return row.automationEnabled && row.automationType == 'birthday';
  }

  bool _isProfileReminderAutomation(_AdminBroadcastRow row) {
    return row.automationEnabled && row.automationType == 'profile_reminder';
  }

  bool _isAnyAutomation(_AdminBroadcastRow row) {
    return _isBirthdayAutomation(row) || _isProfileReminderAutomation(row);
  }

  String _automationLabel(LocalizationState l10n, _AdminBroadcastRow row) {
    if (_isBirthdayAutomation(row)) {
      return l10n.getString('adminBroadcastsAutomationBirthday');
    }
    if (_isProfileReminderAutomation(row)) {
      return l10n.getString('adminBroadcastsAutomationProfileReminder');
    }
    return row.automationType ?? '';
  }

  bool _matchesFilters(_AdminBroadcastRow row) {
    if (_status != 'all' && row.status != _status) return false;

    // Status-based time buckets (not raw dates): overdue scheduled stays
    // upcoming, automations (birthday / profile reminder) are always active
    // and excluded from past/upcoming unless explicitly filtered.
    final isAuto = _isAnyAutomation(row);
    if (_timeFilter == 'upcoming') {
      if (isAuto) return false;
      if (row.status != 'scheduled' && row.status != 'sending') return false;
      final s = row.scheduledAt;
      if (s == null) return row.status == 'scheduled';
      if (!s.isAfter(DateTime.now().subtract(const Duration(minutes: 1)))) {
        // Overdue scheduled still needs attention – keep in upcoming.
        return row.status == 'scheduled';
      }
    } else if (_timeFilter == 'past') {
      if (isAuto) return false;
      if (row.status != 'sent' &&
          row.status != 'failed' &&
          row.status != 'cancelled') {
        return false;
      }
    }

    final q = _query.trim().toLowerCase();
    if (q.isEmpty) return true;
    return row.title.toLowerCase().contains(q) ||
        row.message.toLowerCase().contains(q) ||
        row.id.toLowerCase().contains(q) ||
        row.status.toLowerCase().contains(q) ||
        row.messageType.toLowerCase().contains(q) ||
        (row.actionUrl ?? '').toLowerCase().contains(q);
  }

  Future<void> _delete(LocalizationState l10n, _AdminBroadcastRow row) async {
    if (!mounted) return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(l10n.getString('adminBroadcastsDeleteTitle')),
        content: Text(
          l10n
              .getString('adminBroadcastsDeleteBody')
              .replaceAll('{title}', row.title),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(l10n.getString('generalCancel')),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: Text(l10n.getString('generalDelete')),
          ),
        ],
      ),
    );
    if (confirmed != true) return;

    setState(() {
      _rows = _rows.where((r) => r.id != row.id).toList(growable: false);
    });

    try {
      await Supabase.instance.client
          .from('admin_broadcasts')
          .delete()
          .eq('id', row.id)
          .timeout(const Duration(seconds: 20));
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(l10n.getString('adminDeleted'))));
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      unawaited(_load(force: true));
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(l10n.getString('adminBroadcastsDeleteFailed'))),
      );
    }
  }

  Future<bool> _confirmBroadcastSend({
    required LocalizationState l10n,
    required _AdminBroadcastRow row,
    required DateTime? scheduledAtUtc,
  }) async {
    if (!mounted) return false;

    final criteria = _deepCloneCriteria(row.filterCriteria);

    bool hasHeLanguage(Map<String, dynamic> c) {
      final legacy = (c['ui_language'] ?? '').toString().trim().toLowerCase();
      if (legacy == 'he') return true;
      final list = c['ui_languages'];
      if (list is List) {
        return list.any((e) => e.toString().trim().toLowerCase() == 'he');
      }
      return false;
    }

    final isRtl = hasHeLanguage(criteria);

    return (await showDialog<bool>(
          context: context,
          builder: (ctx) {
            int? targetCount;
            bool isCounting = true;
            bool countFailed = false;

            Future<void> startCount(StateSetter setState) async {
              setState(() {
                isCounting = true;
                countFailed = false;
              });
              final count = await _countTargetUsers(criteria);
              if (!ctx.mounted) return;
              setState(() {
                isCounting = false;
                targetCount = count;
                countFailed = count == null;
              });
            }

            return StatefulBuilder(
              builder: (ctx2, setState) {
                if (isCounting && targetCount == null && !countFailed) {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    if (!ctx2.mounted) return;
                    if (!isCounting || targetCount != null || countFailed) {
                      return;
                    }
                    unawaited(startCount(setState));
                  });
                }

                final overCap = targetCount != null && targetCount! > 20000;
                final canConfirm =
                    !isCounting &&
                    targetCount != null &&
                    targetCount! > 0 &&
                    !overCap &&
                    !countFailed;

                final confirmBody = scheduledAtUtc == null
                    ? l10n.getString('adminBroadcastsConfirmSendNowBody')
                    : l10n
                          .getString('adminBroadcastsConfirmScheduleBody')
                          .replaceAll(
                            '{time}',
                            _formatAdminDateTime(l10n, scheduledAtUtc),
                          );

                final actionUrl = (row.actionUrl ?? '').trim();
                final actionText = row.actionUrlText.trim();

                return AlertDialog(
                  title: Text(l10n.getString('adminBroadcastsConfirmTitle')),
                  content: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 780),
                    child: SingleChildScrollView(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.stretch,
                        children: [
                          Text(
                            confirmBody,
                            style: Theme.of(ctx2).textTheme.bodyMedium,
                          ),
                          const SizedBox(height: 16),
                          Text(
                            l10n.getString('adminBroadcastsPreview'),
                            style: Theme.of(ctx2).textTheme.titleSmall,
                          ),
                          const SizedBox(height: 8),
                          Directionality(
                            textDirection: isRtl
                                ? TextDirection.rtl
                                : TextDirection.ltr,
                            child: Card(
                              margin: EdgeInsets.zero,
                              child: Padding(
                                padding: const EdgeInsets.all(12),
                                child: Column(
                                  crossAxisAlignment:
                                      CrossAxisAlignment.stretch,
                                  children: [
                                    Text(
                                      row.title,
                                      style: Theme.of(
                                        ctx2,
                                      ).textTheme.titleMedium,
                                      textDirection: isRtlText(row.title)
                                          ? TextDirection.rtl
                                          : TextDirection.ltr,
                                    ),
                                    const SizedBox(height: 8),
                                    Text(
                                      row.message,
                                      textAlign: isRtlText(row.message)
                                          ? TextAlign.right
                                          : TextAlign.left,
                                      textDirection: isRtlText(row.message)
                                          ? TextDirection.rtl
                                          : TextDirection.ltr,
                                    ),
                                    // Button only renders with a URL – text alone
                                    // does nothing client-side. Matches editor
                                    // previewCard.
                                    if (actionUrl.isNotEmpty) ...[
                                      const SizedBox(height: 12),
                                      Align(
                                        alignment: Alignment.centerLeft,
                                        child: OutlinedButton(
                                          onPressed: null,
                                          child: Text(
                                            actionText.isEmpty
                                                ? l10n.getString(
                                                    'adminBroadcastsActionUrlTextDefault',
                                                  )
                                                : actionText,
                                          ),
                                        ),
                                      ),
                                    ],
                                  ],
                                ),
                              ),
                            ),
                          ),
                          const SizedBox(height: 16),
                          Row(
                            children: [
                              if (isCounting)
                                const SizedBox(
                                  width: 16,
                                  height: 16,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                  ),
                                ),
                              if (isCounting) const SizedBox(width: 10),
                              Expanded(
                                child: Text(
                                  isCounting
                                      ? l10n.getString('generalLoading')
                                      : targetCount == null
                                      ? l10n.getString(
                                          'adminBroadcastsTargetUnknown',
                                        )
                                      : l10n
                                            .getString(
                                              'adminBroadcastsTargetCountValue',
                                            )
                                            .replaceAll(
                                              '{count}',
                                              targetCount.toString(),
                                            ),
                                  style: Theme.of(ctx2).textTheme.bodyMedium
                                      ?.copyWith(
                                        color:
                                            (!isCounting &&
                                                (countFailed ||
                                                    targetCount == null))
                                            ? Theme.of(ctx2).colorScheme.error
                                            : null,
                                      ),
                                ),
                              ),
                              const SizedBox(width: 10),
                              OutlinedButton(
                                // Allow inspecting audience even when count
                                // failed or is zero – list RPC is independent.
                                onPressed: isCounting
                                    ? null
                                    : () async {
                                        await _openTargetUsersList(
                                          l10n: l10n,
                                          criteria: _deepCloneCriteria(
                                            criteria,
                                          ),
                                          targetCount: targetCount,
                                          listLimit: 50,
                                        );
                                      },
                                child: Text(
                                  l10n.getString('adminBroadcastsViewUsers'),
                                ),
                              ),
                            ],
                          ),
                          if (overCap)
                            Padding(
                              padding: const EdgeInsets.only(top: 8),
                              child: Text(
                                l10n
                                    .getString('adminBroadcastsAudienceOverCap')
                                    .replaceAll(
                                      '{count}',
                                      '${targetCount ?? 0}',
                                    ),
                                style: Theme.of(ctx2).textTheme.bodySmall
                                    ?.copyWith(
                                      color: Theme.of(ctx2).colorScheme.error,
                                    ),
                              ),
                            ),
                          if (targetCount != null &&
                              targetCount! > 5000 &&
                              !overCap)
                            Padding(
                              padding: const EdgeInsets.only(top: 8),
                              child: Text(
                                l10n
                                    .getString('adminBroadcastsAudienceLarge')
                                    .replaceAll(
                                      '{count}',
                                      '${targetCount ?? 0}',
                                    ),
                                style: Theme.of(ctx2).textTheme.bodySmall,
                              ),
                            ),
                        ],
                      ),
                    ),
                  ),
                  actions: [
                    TextButton(
                      onPressed: () => Navigator.of(ctx2).pop(false),
                      child: Text(l10n.getString('generalCancel')),
                    ),
                    ElevatedButton(
                      onPressed: canConfirm
                          ? () => Navigator.of(ctx2).pop(true)
                          : null,
                      child: Text(
                        scheduledAtUtc == null
                            ? l10n.getString('adminBroadcastsSendNow')
                            : l10n.getString('adminBroadcastsSchedule'),
                      ),
                    ),
                  ],
                );
              },
            );
          },
        )) ??
        false;
  }

  Future<void> _sendNow(LocalizationState l10n, _AdminBroadcastRow row) async {
    if (row.status != 'draft' &&
        row.status != 'failed' &&
        row.status != 'cancelled') {
      return;
    }
    final confirmed = await _confirmBroadcastSend(
      l10n: l10n,
      row: row,
      scheduledAtUtc: null,
    );
    if (!confirmed) return;

    try {
      await Supabase.instance.client
          .from('admin_broadcasts')
          .update({
            'status': 'scheduled',
            'scheduled_at': DateTime.now().toUtc().toIso8601String(),
          })
          .eq('id', row.id)
          .timeout(const Duration(seconds: 20));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text('Queued – sends on next cron run (watch status)'),
        ),
      );
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(l10n.getString('adminBroadcastsSaveFailed'))),
      );
    }
  }

  Future<void> _scheduleDraft(
    LocalizationState l10n,
    _AdminBroadcastRow row,
  ) async {
    if (row.status != 'draft' &&
        row.status != 'failed' &&
        row.status != 'cancelled' &&
        row.status != 'scheduled') {
      return;
    }
    final picked = await _pickDateTime(
      initial: DateTime.now().add(const Duration(minutes: 5)),
    );
    if (picked == null) return;
    if (!mounted) return;
    if (!picked.isAfter(DateTime.now().add(const Duration(minutes: 1)))) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            l10n.getString('adminBroadcastsRescheduleMustBeFuture'),
          ),
        ),
      );
      return;
    }

    final confirmed = await _confirmBroadcastSend(
      l10n: l10n,
      row: row,
      scheduledAtUtc: picked.toUtc(),
    );
    if (!confirmed) return;

    try {
      await Supabase.instance.client
          .from('admin_broadcasts')
          .update({
            'status': 'scheduled',
            'scheduled_at': picked.toUtc().toIso8601String(),
          })
          .eq('id', row.id)
          .timeout(const Duration(seconds: 20));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            'Scheduled for ${_formatAdminDateTime(l10n, picked.toUtc())} – cron sends automatically',
          ),
        ),
      );
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(l10n.getString('adminBroadcastsSaveFailed'))),
      );
    }
  }

  Future<DateTime?> _pickDateTime({DateTime? initial}) async {
    final now = DateTime.now();
    final date = await showDatePicker(
      context: context,
      firstDate: DateTime(now.year - 1),
      lastDate: DateTime(now.year + 5),
      initialDate: initial?.toLocal() ?? now,
    );
    if (date == null) return null;
    if (!mounted) return null;
    final time = await showTimePicker(
      context: context,
      initialTime: TimeOfDay.fromDateTime(initial?.toLocal() ?? now),
    );
    if (time == null) return null;
    if (!mounted) return null;
    return DateTime(date.year, date.month, date.day, time.hour, time.minute);
  }

  Map<String, dynamic> _deepCloneCriteria(Map<String, dynamic> v) {
    try {
      final cloned = jsonDecode(jsonEncode(v));
      if (cloned is Map) return Map<String, dynamic>.from(cloned);
    } catch (_) {}
    return Map<String, dynamic>.from(v);
  }

  Future<int?> _countTargetUsers(Map<String, dynamic> criteria) async {
    int? decodeInt(Object? raw) {
      if (raw == null) return null;
      if (raw is int) return raw;
      if (raw is num) return raw.toInt();
      return int.tryParse(raw.toString());
    }

    try {
      final result = await Supabase.instance.client
          .rpc('count_target_users', params: {'filter_criteria': criteria})
          .timeout(const Duration(seconds: 12));
      return decodeInt(result);
    } catch (_) {
      return null;
    }
  }

  Future<void> _openTargetUsersList({
    required LocalizationState l10n,
    required Map<String, dynamic> criteria,
    required int? targetCount,
    int listLimit = 50,
  }) async {
    final isWideList = MediaQuery.of(context).size.width >= 900;

    Future<List<Map<String, dynamic>>> loadPage({
      required int limit,
      required int offset,
    }) async {
      final result = await Supabase.instance.client
          .rpc(
            'admin_list_target_users_for_broadcast',
            params: {
              'filter_criteria': criteria,
              'p_limit': limit,
              'p_offset': offset,
            },
          )
          .timeout(const Duration(seconds: 12));
      if (result is List) {
        return result
            .whereType<Map>()
            .map((e) => Map<String, dynamic>.from(e))
            .toList();
      }
      return const [];
    }

    Widget buildListContent({required VoidCallback close}) {
      List<Map<String, dynamic>> rows = const [];
      bool isLoading = true;
      bool isLoadingMore = false;
      bool loadFailed = false;
      bool hasMore = false;

      Future<void> loadInitial(
        BuildContext listCtx,
        StateSetter setState,
      ) async {
        if (!listCtx.mounted) return;
        setState(() {
          isLoading = true;
          loadFailed = false;
        });
        try {
          final page = await loadPage(limit: listLimit, offset: 0);
          if (!listCtx.mounted) return;
          setState(() {
            rows = page;
            hasMore = page.length >= listLimit;
            isLoading = false;
            loadFailed = false;
          });
        } catch (_) {
          if (!listCtx.mounted) return;
          setState(() {
            isLoading = false;
            loadFailed = true;
          });
        }
      }

      Future<void> loadMore(BuildContext listCtx, StateSetter setState) async {
        if (isLoadingMore || !hasMore) return;
        if (!listCtx.mounted) return;
        setState(() {
          isLoadingMore = true;
        });
        try {
          final page = await loadPage(limit: listLimit, offset: rows.length);
          if (!listCtx.mounted) return;
          setState(() {
            rows = [...rows, ...page];
            hasMore = page.length >= listLimit;
            isLoadingMore = false;
          });
        } catch (_) {
          if (!listCtx.mounted) return;
          setState(() {
            isLoadingMore = false;
          });
        }
      }

      DateTime? tryDate(dynamic v) {
        if (v == null) return null;
        if (v is DateTime) return v;
        return DateTime.tryParse(v.toString());
      }

      return StatefulBuilder(
        builder: (ctx, setState) {
          if (isLoading) {
            WidgetsBinding.instance.addPostFrameCallback((_) {
              if (!mounted) return;
              if (!isLoading) return;
              if (!ctx.mounted) return;
              loadInitial(ctx, setState);
            });
          }

          final body = isLoading
              ? Center(child: Text(l10n.getString('generalLoading')))
              : loadFailed
              ? Center(
                  child: Text(
                    l10n.getString('adminBroadcastsTargetUsersLoadFailed'),
                    style: Theme.of(ctx).textTheme.bodyMedium?.copyWith(
                      color: Theme.of(ctx).colorScheme.error,
                    ),
                  ),
                )
              : rows.isEmpty
              ? Center(
                  child: Text(
                    l10n.getString('adminBroadcastsTargetUsersEmpty'),
                  ),
                )
              : ListView.separated(
                  padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
                  itemCount: rows.length + (hasMore ? 1 : 0),
                  separatorBuilder: (ctx, index) => const Divider(height: 1),
                  itemBuilder: (ctx, i) {
                    if (hasMore && i == rows.length) {
                      return Padding(
                        padding: const EdgeInsets.symmetric(vertical: 12),
                        child: Center(
                          child: OutlinedButton(
                            onPressed: isLoadingMore
                                ? null
                                : () => loadMore(ctx, setState),
                            child: isLoadingMore
                                ? const SizedBox(
                                    width: 18,
                                    height: 18,
                                    child: CircularProgressIndicator(
                                      strokeWidth: 2,
                                    ),
                                  )
                                : Text(l10n.getString('generalLoadMore')),
                          ),
                        ),
                      );
                    }

                    final row = rows[i];
                    final id = (row['user_id'] ?? row['id'] ?? '').toString();
                    final name = (row['name'] ?? '').toString().trim();
                    final displayName = maskUserDisplayName(name);
                    final platform = (row['platform'] ?? '').toString().trim();
                    final lastActive = tryDate(row['last_active_at']);
                    final lastActiveText = lastActive == null
                        ? ''
                        : DateFormat.yMMMd().add_jm().format(
                            lastActive.toLocal(),
                          );

                    return ListTile(
                      title: Text(
                        name.isEmpty ? id : displayName,
                        textAlign: isRtlText(name.isEmpty ? id : displayName)
                            ? TextAlign.right
                            : TextAlign.left,
                        textDirection:
                            isRtlText(name.isEmpty ? id : displayName)
                            ? TextDirection.rtl
                            : TextDirection.ltr,
                      ),
                      subtitle: Text(
                        lastActiveText.isEmpty ? id : '$id\n$lastActiveText',
                      ),
                      isThreeLine: lastActiveText.isNotEmpty,
                      trailing: platform.isEmpty
                          ? null
                          : _MetaChip(
                              label: l10n.getString(
                                'adminBroadcastsFilterPlatform',
                              ),
                              value: platform,
                            ),
                    );
                  },
                );

          return Column(
            children: [
              Padding(
                padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
                child: Row(
                  children: [
                    Expanded(
                      child: Column(
                        crossAxisAlignment: CrossAxisAlignment.start,
                        children: [
                          Text(
                            l10n.getString('adminBroadcastsTargetUsersTitle'),
                            style: Theme.of(ctx).textTheme.titleLarge,
                          ),
                          const SizedBox(height: 4),
                          Text(
                            targetCount == null
                                ? l10n.getString('adminBroadcastsTargetUnknown')
                                : l10n
                                      .getString(
                                        'adminBroadcastsTargetCountValue',
                                      )
                                      .replaceAll(
                                        '{count}',
                                        targetCount.toString(),
                                      ),
                            style: Theme.of(ctx).textTheme.bodySmall,
                          ),
                        ],
                      ),
                    ),
                    IconButton(
                      tooltip: l10n.getString('generalClose'),
                      onPressed: close,
                      icon: const Icon(Icons.close),
                    ),
                  ],
                ),
              ),
              const Divider(height: 1),
              Expanded(child: body),
            ],
          );
        },
      );
    }

    if (isWideList) {
      await showDialog<void>(
        context: context,
        builder: (ctx) {
          final safeHeight =
              MediaQuery.of(ctx).size.height -
              MediaQuery.of(ctx).viewPadding.vertical;
          return Dialog(
            child: SizedBox(
              width: 640,
              height: safeHeight * 0.85,
              child: buildListContent(close: () => Navigator.of(ctx).pop()),
            ),
          );
        },
      );
      return;
    }

    await showModalBottomSheet<void>(
      context: context,
      isScrollControlled: true,
      useSafeArea: true,
      showDragHandle: true,
      builder: (ctx) {
        final safeHeight =
            MediaQuery.of(ctx).size.height -
            MediaQuery.of(ctx).viewPadding.vertical;
        final height = safeHeight * 0.92;
        return SizedBox(
          height: height,
          child: buildListContent(close: () => Navigator.of(ctx).pop()),
        );
      },
    );
  }

  String _newResendRequestId() {
    // UUIDv4 globally unique across admins/devices. Server composite unique
    // (source, request) makes replay idempotent without cross-source clashes.
    final rnd = DateTime.now().toUtc().microsecondsSinceEpoch;
    final u = UniqueKey().toString().replaceAll(RegExp(r'[^0-9a-zA-Z]'), '');
    return 'req-${rnd.toRadixString(16)}-$u';
  }

  Future<void> _resendNow(
    LocalizationState l10n,
    _AdminBroadcastRow row,
  ) async {
    if (_resendInFlightIds.contains(row.id)) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(content: Text('Resend already in progress…')),
      );
      return;
    }
    // Same audience preview/count as initial send – resend can hit 0 or cap.
    final confirmed = await _confirmBroadcastSend(
      l10n: l10n,
      row: row,
      scheduledAtUtc: null,
    );
    if (!confirmed) return;
    if (!mounted) return;
    _resendInFlightIds.add(row.id);
    final requestId = _newResendRequestId();
    try {
      await Supabase.instance.client
          .rpc(
            'admin_resend_broadcast_now',
            params: {'p_broadcast_id': row.id, 'p_request_id': requestId},
          )
          .timeout(const Duration(seconds: 30));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        const SnackBar(
          content: Text(
            'Resend queued – cron fans out in chunks (watch status)',
          ),
        ),
      );
      unawaited(_load(force: true));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text('${l10n.getString('adminBroadcastsResendFailed')}: $e'),
        ),
      );
    } finally {
      _resendInFlightIds.remove(row.id);
    }
  }

  Future<void> _cancelScheduled(
    LocalizationState l10n,
    _AdminBroadcastRow row,
  ) async {
    if (row.status != 'scheduled' && row.status != 'sending') return;
    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: const Text('Cancel scheduled broadcast?'),
        content: Text(
          '“${row.title}” will not send. Already-queued pushes may still deliver.',
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(l10n.getString('generalCancel')),
          ),
          ElevatedButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: const Text('Cancel broadcast'),
          ),
        ],
      ),
    );
    if (confirmed != true) return;
    try {
      await Supabase.instance.client
          .from('admin_broadcasts')
          .update({'status': 'cancelled'})
          .eq('id', row.id)
          .timeout(const Duration(seconds: 20));
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(const SnackBar(content: Text('Broadcast cancelled')));
      unawaited(_load(force: true));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text('Cancel failed: $e')));
    }
  }

  Future<void> _rescheduleSent(
    LocalizationState l10n,
    _AdminBroadcastRow row,
  ) async {
    final picked = await _pickDateTime(
      initial: DateTime.now().add(const Duration(minutes: 5)),
    );
    if (picked == null) return;
    if (!mounted) return;
    if (!picked.isAfter(DateTime.now().add(const Duration(minutes: 1)))) {
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            l10n.getString('adminBroadcastsRescheduleMustBeFuture'),
          ),
        ),
      );
      return;
    }

    final confirmed = await _confirmBroadcastSend(
      l10n: l10n,
      row: row,
      scheduledAtUtc: picked.toUtc(),
    );
    if (!confirmed) return;
    if (!mounted) return;

    try {
      await Supabase.instance.client
          .rpc(
            'admin_reschedule_broadcast',
            params: {
              'p_broadcast_id': row.id,
              'p_scheduled_at': picked.toUtc().toIso8601String(),
            },
          )
          .timeout(const Duration(seconds: 30));

      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(l10n.getString('adminBroadcastsRescheduled'))),
      );
      unawaited(_load(force: true));
    } catch (e) {
      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(
            '${l10n.getString('adminBroadcastsRescheduleFailed')}: $e',
          ),
        ),
      );
    }
  }

  Future<Map<String, dynamic>?> _fetchStats(String broadcastId) async {
    try {
      final result = await Supabase.instance.client
          .rpc('get_broadcast_stats', params: {'p_broadcast_id': broadcastId})
          .timeout(const Duration(seconds: 12));
      Map<String, dynamic>? stats;
      if (result is List && result.isNotEmpty) {
        stats = Map<String, dynamic>.from(result.first as Map);
      } else if (result is Map) {
        stats = Map<String, dynamic>.from(result);
      }
      if (stats != null) {
        try {
          await AdminLocalDbService.shared.saveSectionDataMap(
            'broadcast_stats:$broadcastId',
            stats,
          );
        } catch (_) {}
      }
      return stats;
    } catch (_) {
      // Return cached data on error (legacy broadcast_id fallback removed –
      // function only exposes p_broadcast_id).
      try {
        return await AdminLocalDbService.shared.loadSectionDataMap(
          'broadcast_stats:$broadcastId',
        );
      } catch (_) {
        return null;
      }
    }
  }

  Future<_AdminBroadcastRow?> _fetchBroadcastRow(String broadcastId) async {
    try {
      final result = await Supabase.instance.client
          .from('admin_broadcasts')
          .select(
            'id, title, message, message_type, automation_type, automation_enabled, action_url, action_url_text, scheduled_at, sent_at, status, filter_criteria, skipped_count, target_user_count, actual_sent_count, created_by, created_at, updated_at',
          )
          .eq('id', broadcastId)
          .maybeSingle()
          .timeout(const Duration(seconds: 12));
      if (result != null) {
        final row = _AdminBroadcastRow.fromRow(
          Map<String, dynamic>.from(result as Map),
        );
        try {
          await AdminLocalDbService.shared.saveSectionData(
            'broadcast_row:$broadcastId',
            [Map<String, dynamic>.from(result as Map)],
          );
        } catch (_) {}
        return row;
      }
    } catch (_) {
      // Return cached row on error
      try {
        final cached = await AdminLocalDbService.shared.loadSectionData(
          'broadcast_row:$broadcastId',
        );
        if (cached.isNotEmpty) {
          return _AdminBroadcastRow.fromRow(cached.first);
        }
      } catch (_) {}
    }
    return null;
  }

