        return AlertDialog(
          title: Text(l10n.getString('adminBroadcastsDetailsTitle')),
          content: ConstrainedBox(
            constraints: BoxConstraints(
              maxWidth: 840,
              maxHeight:
                  (MediaQuery.of(ctx).size.height -
