  @override
  void dispose() {
    _pollTimer?.cancel();
    _scheduledRealtimeRefresh?.cancel();
    _detailsRefreshTick.dispose();
    final channel = _channel;
    if (channel != null) {
      Supabase.instance.client.removeChannel(channel);
    }
    super.dispose();
  }

  Future<void> _showEditor(
    LocalizationState l10n, {
    _AdminBroadcastRow? existing,
  }) async {
    if (!mounted) return;

    final formKey = GlobalKey<FormState>();
    var isSubmitting = false;

    var mode = 'single';
    var birthdayAutomationEnabled =
        existing?.automationEnabled == true &&
        existing?.automationType == 'birthday';
    var profileReminderAutomationEnabled =
        existing?.automationEnabled == true &&
        existing?.automationType == 'profile_reminder';

    Timer? targetingCountDebounce;
    String? lastTargetingCountRequest;
    int? targetingCount;
    bool isTargetingCounting = false;
    bool targetingCountFailed = false;
    bool didInitTargetingCount = false;

    Timer? recipientsUiLangDebounce;
    String? lastRecipientsUiLangRequest;
    Set<String>? recipientsUiLanguages;
    bool isRecipientsUiLanguagesLoading = false;
    bool recipientsUiLanguagesFailed = false;
    bool didInitRecipientsUiLanguages = false;

    final typeController = ValueNotifier<String>(
      existing?.messageType ?? 'info',
    );
    final actionUrlController = TextEditingController(
      text: existing?.actionUrl ?? '',
    );

    final titleEnController = TextEditingController(
      text: existing?.title ?? '',
    );
    final messageEnController = TextEditingController(
      text: existing?.message ?? '',
    );
    final actionTextEnController = TextEditingController(
      text: existing?.actionUrlText ?? '',
    );

    final titleEsController = TextEditingController();
    final messageEsController = TextEditingController();
    final actionTextEsController = TextEditingController();

    final titleHeController = TextEditingController();
    final messageHeController = TextEditingController();
    final actionTextHeController = TextEditingController();

    final criteriaController = TextEditingController(
      text: const JsonEncoder.withIndent('  ').convert(
        existing?.filterCriteria ?? <String, dynamic>{'all_users': true},
      ),
    );

    Map<String, dynamic>? parseCriteria() {
      try {
        final parsed = jsonDecode(
          criteriaController.text.trim().isEmpty
              ? '{}'
              : criteriaController.text,
        );
        if (parsed is Map) {
          return Map<String, dynamic>.from(parsed);
        }
        return null;
      } catch (_) {
        return null;
      }
    }

    Map<String, dynamic> deepCloneCriteria(Map<String, dynamic> v) {
      try {
        final cloned = jsonDecode(jsonEncode(v));
        if (cloned is Map) return Map<String, dynamic>.from(cloned);
      } catch (_) {}
      return Map<String, dynamic>.from(v);
    }

    List<String> asStringList(dynamic raw) {
      if (raw is List) {
        return raw
            .map((e) => e.toString().trim())
            .where((e) => e.isNotEmpty)
            .toList();
      }
      if (raw is Set) {
        return raw
            .map((e) => e.toString().trim())
            .where((e) => e.isNotEmpty)
            .toList();
      }
      return const [];
    }

    bool asBool(dynamic raw) {
      if (raw == true) return true;
      if (raw == false) return false;
      return raw.toString().trim().toLowerCase() == 'true';
    }

    int? asInt(dynamic raw) {
      if (raw is int) return raw;
      if (raw is num) return raw.toInt();
      return int.tryParse(raw.toString().trim());
    }

    Future<List<Map<String, String>>> loadGenderOptions() async {
      List<Map<String, String>> decodeListMap(Object? raw) {
        if (raw is! List) return const [];
        final out = <Map<String, String>>[];
        for (final item in raw) {
          if (item is! Map) continue;
          final m = Map<String, dynamic>.from(item);
          out.add({
            'key': (m['key'] ?? '').toString(),
            'displayKey': (m['displayKey'] ?? '').toString(),
          });
        }
        return out;
      }

      Object? encodeListMap(List<Map<String, String>> value) {
        return value
            .map(
              (m) => {
                'key': m['key'] ?? '',
                'displayKey': m['displayKey'] ?? '',
              },
            )
            .toList(growable: false);
      }

      const cacheKey = 'admin_cache:gender_options:v1';
      final cached = await _AdminCache.read<List<Map<String, String>>>(
        cacheKey,
        decodeListMap,
      );
      if (cached != null && cached.isFresh) return cached.data;

      try {
        final rows = await publicReferenceDataService
            .fetchGenderOptions()
            .timeout(const Duration(seconds: 8));

        final list = List<Map<String, dynamic>>.from(rows)
            .map(
              (r) => <String, String>{
                'key': (r['gender_key'] ?? '').toString().trim().toLowerCase(),
                'displayKey': (r['display_name_key'] ?? '').toString().trim(),
              },
            )
            .where((m) => m['key']!.isNotEmpty)
            .toList(growable: false);

        await _AdminCache.write<List<Map<String, String>>>(
          cacheKey,
          encodeListMap,
          list,
        );
        return list;
      } catch (_) {
        return cached?.data ??
            const [
              {'key': 'male', 'displayKey': 'gender_male'},
              {'key': 'female', 'displayKey': 'gender_female'},
              {'key': 'non_binary', 'displayKey': 'gender_non_binary'},
            ];
      }
    }

    Future<List<String>> loadSubscriptionTierIds() async {
      List<String> decodeStringList(Object? raw) {
        if (raw is! List) return const [];
        return raw
            .map((e) => e.toString())
            .where((e) => e.trim().isNotEmpty)
            .toList();
      }

      Object? encodeStringList(List<String> value) {
        return value;
      }

      const cacheKey = 'admin_cache:subscription_tier_ids:v1';
      final cached = await _AdminCache.read<List<String>>(
        cacheKey,
        decodeStringList,
      );
      if (cached != null && cached.isFresh) return cached.data;

      try {
        final rows = await Supabase.instance.client
            .from('subscription_tiers')
            .select('id, is_active, sort_order')
            .order('sort_order', ascending: true)
            .timeout(const Duration(seconds: 8));
        final list = List<Map<String, dynamic>>.from(rows)
            .where((r) => r['id'] != null)
            .where((r) => (r['is_active'] as bool?) ?? true)
            .map((r) => (r['id'] ?? '').toString().trim())
            .where((id) => id.isNotEmpty)
            .toList(growable: false);

        final base = list.isEmpty ? const ['plus', 'gold', 'platinum'] : list;
        final out = <String>['free'];
        for (final id in base) {
          if (id.trim().isEmpty) continue;
          if (id.trim().toLowerCase() == 'free') continue;
          out.add(id);
        }
        await _AdminCache.write<List<String>>(cacheKey, encodeStringList, out);
        return out;
      } catch (_) {
        return cached?.data ?? const ['free', 'plus', 'gold', 'platinum'];
      }
    }

    void requestTargetingCount(
      BuildContext dialogCtx,
      StateSetter setDialogState,
      Map<String, dynamic> criteria,
    ) {
      targetingCountDebounce?.cancel();
      targetingCountDebounce = Timer(
        const Duration(milliseconds: 350),
        () async {
          if (!mounted || !dialogCtx.mounted) return;
          final requestKey = jsonEncode(criteria);
          lastTargetingCountRequest = requestKey;
          setDialogState(() {
            isTargetingCounting = true;
            targetingCountFailed = false;
          });
          final count = await _countTargetUsers(criteria);
          if (!mounted || !dialogCtx.mounted) return;
          if (lastTargetingCountRequest != requestKey) return;
          setDialogState(() {
            isTargetingCounting = false;
            targetingCount = count;
            targetingCountFailed = count == null;
          });
        },
      );
    }

    void requestRecipientsUiLanguages(
      BuildContext dialogCtx,
      StateSetter setDialogState,
      Map<String, dynamic> criteria,
    ) {
      recipientsUiLangDebounce?.cancel();
      recipientsUiLangDebounce = Timer(
        const Duration(milliseconds: 350),
        () async {
          if (!mounted || !dialogCtx.mounted) return;

          final userIds = asStringList(criteria['user_ids']);
          if (userIds.isEmpty) {
            lastRecipientsUiLangRequest = null;
            setDialogState(() {
              isRecipientsUiLanguagesLoading = false;
              recipientsUiLanguagesFailed = false;
              recipientsUiLanguages = null;
            });
            return;
          }

          final normalizedIds = userIds.map((e) => e.toLowerCase()).toList()
            ..sort();
          final requestKey = jsonEncode(normalizedIds);
          lastRecipientsUiLangRequest = requestKey;
          setDialogState(() {
            isRecipientsUiLanguagesLoading = true;
            recipientsUiLanguagesFailed = false;
          });

          try {
            final rows = await Supabase.instance.client.rpc(
              'admin_get_user_ui_languages',
              params: {'p_user_ids': normalizedIds},
            );
            if (!mounted || !dialogCtx.mounted) return;
            if (lastRecipientsUiLangRequest != requestKey) return;

            final list = rows is List ? rows : const [];
            final langs = <String>{};

            for (final raw in list) {
              if (raw is! Map) continue;
              final m = Map<String, dynamic>.from(raw);
              final lang =
                  (m['ui_language'] ??
                          m['preferred_language'] ??
                          m['language'] ??
                          'en')
                      .toString()
                      .trim()
                      .toLowerCase();
              final normalized = (lang == 'es' || lang == 'he') ? lang : 'en';
              langs.add(normalized);
            }

            if (langs.isEmpty) {
              langs.add('en');
            }

            setDialogState(() {
              isRecipientsUiLanguagesLoading = false;
              recipientsUiLanguagesFailed = false;
              recipientsUiLanguages = langs;
            });
          } catch (_) {
            if (!mounted || !dialogCtx.mounted) return;
            if (lastRecipientsUiLangRequest != requestKey) return;
            setDialogState(() {
              isRecipientsUiLanguagesLoading = false;
              recipientsUiLanguagesFailed = true;
              recipientsUiLanguages = null;
            });
          }
        },
      );
    }

    bool looksLikeUrl(String value) {
      final trimmed = value.trim();
      if (trimmed.isEmpty) return true;
      // Strict to match DB check_notification_limits (^https?://.+\..+)
      // and TS adminInputViolations so UI never accepts what send rejects.
      if (!RegExp(r'^https?://.+\..+').hasMatch(trimmed)) return false;
      final uri = Uri.tryParse(trimmed);
      if (uri == null) return false;
      if (!uri.hasScheme) return false;
      if (uri.scheme != 'https' && uri.scheme != 'http') return false;
      return uri.host.isNotEmpty;
    }

    Future<Map<String, dynamic>?> editTargetingFilters({
      required Map<String, dynamic> initial,
      required bool allowUiLanguageFilters,
      required Map<String, String> uiLanguageDisplayNames,
    }) async {
      final genders = await loadGenderOptions();
      final tiers = await loadSubscriptionTierIds();
      if (!mounted) return null;

      final isWide = MediaQuery.of(context).size.width >= 900;

      Widget buildContent({
        required Map<String, dynamic> startValue,
        required void Function(Map<String, dynamic> value) closeWithValue,
        required VoidCallback closeWithoutValue,
      }) {
        var draft = deepCloneCriteria(startValue);
        Timer? countDebounce;
        String? lastCountRequest;
        int? targetCount;
        bool isCounting = false;
        bool countFailed = false;
        bool didInitCount = false;
        int listLimit = 50;

        String uiLanguageName(String code) {
          final normalized = code.trim().toLowerCase();
          return uiLanguageDisplayNames[normalized] ??
              uiLanguageNameFallback(l10n, normalized);
        }

        List<String> currentList(String key) =>
            asStringList(draft[key]).map((e) => e.toLowerCase()).toList();
        void setList(String key, List<String> values) {
          final clean = values
              .map((e) => e.trim())
              .where((e) => e.isNotEmpty)
              .toList(growable: false);
          if (clean.isEmpty) {
            draft.remove(key);
          } else {
            draft[key] = clean;
          }
        }

        bool currentBool(String key) => asBool(draft[key]);

        int? currentInt(String key) => asInt(draft[key]);
        void setInt(String key, int? value) {
          if (value == null) {
            draft.remove(key);
          } else {
            draft[key] = value;
          }
        }

        Map<String, dynamic>? currentAgeRange() {
          final raw = draft['age_range'];
          if (raw is Map) return Map<String, dynamic>.from(raw);
          return null;
        }

        void setAgeRange({required int min, required int max}) {
          draft['age_range'] = <String, dynamic>{'min': min, 'max': max};
        }

        void clearAgeRange() {
          draft.remove('age_range');
        }

        String statusLabel(LocalizationState l10n, String s) {
          return switch (s) {
            'unverified' => l10n.getString('adminStatusUnverified'),
            'analyzing' => l10n.getString('adminStatusAnalyzing'),
            'pending' => l10n.getString('adminStatusPending'),
            'approved' => l10n.getString('adminStatusApproved'),
            'rejected' => l10n.getString('adminStatusRejected'),
            _ => s,
          };
        }

        String platformLabel(LocalizationState l10n, String p) {
          return switch (p) {
            'ios' => l10n.getString('adminPlatformIos'),
            'android' => l10n.getString('adminPlatformAndroid'),
            'web' => l10n.getString('adminPlatformWeb'),
            _ => p,
          };
        }

        String genderLabel(LocalizationState l10n, String key) {
          final found = genders.firstWhere(
            (g) =>
                (g['key'] ?? '').trim().toLowerCase() ==
                key.trim().toLowerCase(),
            orElse: () => const <String, String>{},
          );
          final displayKey = (found['displayKey'] ?? '').trim();
          if (displayKey.isNotEmpty) {
            return l10n.getString(displayKey);
          }
          final transKey = 'gender_${key.trim().toLowerCase()}';
          return l10n.getString(transKey);
        }

        String tierLabel(LocalizationState l10n, String id) {
          final key = id.trim().toLowerCase();
          if (key == 'free') return l10n.getString('adminSubscriptionTierFree');
          return id;
        }

        const List<int> lastActiveOptions = [1, 3, 7, 14, 30, 90];

        Future<void> openTargetUsersList(Map<String, dynamic> criteria) async {
          final isWideList = MediaQuery.of(context).size.width >= 900;

          Future<List<Map<String, dynamic>>> loadPage({
            required int limit,
            required int offset,
          }) async {
            final result = await Supabase.instance.client
                .rpc(
                  'admin_list_target_users_for_broadcast',
                  params: {
                    'filter_criteria': criteria,
                    'p_limit': limit,
                    'p_offset': offset,
                  },
                )
                .timeout(const Duration(seconds: 12));
            if (result is List) {
              return result
                  .whereType<Map>()
                  .map((e) => Map<String, dynamic>.from(e))
                  .toList();
            }
            return const [];
          }

          Widget buildListContent({required VoidCallback close}) {
            List<Map<String, dynamic>> rows = const [];
            bool isLoading = true;
            bool isLoadingMore = false;
            bool loadFailed = false;
            bool hasMore = false;

            Future<void> loadInitial(
              BuildContext listCtx,
              StateSetter setState,
            ) async {
              if (!listCtx.mounted) return;
              setState(() {
                isLoading = true;
                loadFailed = false;
              });
              try {
                final page = await loadPage(limit: listLimit, offset: 0);
                if (!listCtx.mounted) return;
                setState(() {
                  rows = page;
                  hasMore = page.length >= listLimit;
                  isLoading = false;
                  loadFailed = false;
                });
              } catch (_) {
                if (!listCtx.mounted) return;
                setState(() {
                  isLoading = false;
                  loadFailed = true;
                });
              }
            }

            Future<void> loadMore(
              BuildContext listCtx,
              StateSetter setState,
            ) async {
              if (isLoadingMore || !hasMore) return;
              if (!listCtx.mounted) return;
              setState(() {
                isLoadingMore = true;
              });
              try {
                final page = await loadPage(
                  limit: listLimit,
                  offset: rows.length,
                );
                if (!listCtx.mounted) return;
                setState(() {
                  rows = [...rows, ...page];
                  hasMore = page.length >= listLimit;
                  isLoadingMore = false;
                });
              } catch (_) {
                if (!listCtx.mounted) return;
                setState(() {
                  isLoadingMore = false;
                });
              }
            }

            DateTime? tryDate(dynamic v) {
              if (v == null) return null;
              if (v is DateTime) return v;
              return DateTime.tryParse(v.toString());
            }

            return StatefulBuilder(
              builder: (ctx, setState) {
                if (isLoading) {
                  WidgetsBinding.instance.addPostFrameCallback((_) {
                    if (!mounted) return;
                    if (!isLoading) return;
                    if (!ctx.mounted) return;
                    loadInitial(ctx, setState);
                  });
                }

                final body = isLoading
                    ? Center(child: Text(l10n.getString('generalLoading')))
                    : loadFailed
                    ? Center(
                        child: Text(
                          l10n.getString(
                            'adminBroadcastsTargetUsersLoadFailed',
                          ),
                          style: Theme.of(ctx).textTheme.bodyMedium?.copyWith(
                            color: Theme.of(ctx).colorScheme.error,
                          ),
                        ),
                      )
                    : rows.isEmpty
                    ? Center(
                        child: Text(
                          l10n.getString('adminBroadcastsTargetUsersEmpty'),
                        ),
                      )
                    : ListView.separated(
                        padding: const EdgeInsets.fromLTRB(12, 12, 12, 12),
                        itemCount: rows.length + (hasMore ? 1 : 0),
                        separatorBuilder: (ctx, index) =>
                            const Divider(height: 1),
                        itemBuilder: (ctx, i) {
                          if (hasMore && i == rows.length) {
                            return Padding(
                              padding: const EdgeInsets.symmetric(vertical: 12),
                              child: Center(
                                child: OutlinedButton(
                                  onPressed: isLoadingMore
                                      ? null
                                      : () => loadMore(ctx, setState),
                                  child: isLoadingMore
                                      ? const SizedBox(
                                          width: 18,
                                          height: 18,
                                          child: CircularProgressIndicator(
                                            strokeWidth: 2,
                                          ),
                                        )
                                      : Text(l10n.getString('generalLoadMore')),
                                ),
                              ),
                            );
                          }

                          final row = rows[i];
                          final id = (row['user_id'] ?? row['id'] ?? '')
                              .toString();
                          final name = (row['name'] ?? '').toString().trim();
                          final displayName = maskUserDisplayName(name);
                          final platform = (row['platform'] ?? '')
                              .toString()
                              .trim();
                          final lastActive = tryDate(row['last_active_at']);
                          final lastActiveText = lastActive == null
                              ? ''
                              : DateFormat.yMMMd().add_jm().format(
                                  lastActive.toLocal(),
                                );

                          return ListTile(
                            title: Text(
                              name.isEmpty ? id : displayName,
                              textAlign:
                                  isRtlText(name.isEmpty ? id : displayName)
                                  ? TextAlign.right
                                  : TextAlign.left,
                              textDirection:
                                  isRtlText(name.isEmpty ? id : displayName)
                                  ? TextDirection.rtl
                                  : TextDirection.ltr,
                            ),
                            subtitle: Text(
                              lastActiveText.isEmpty
                                  ? id
                                  : '$id\n$lastActiveText',
                            ),
                            isThreeLine: lastActiveText.isNotEmpty,
                            trailing: platform.isEmpty
                                ? null
                                : _MetaChip(
                                    label: l10n.getString(
                                      'adminBroadcastsFilterPlatform',
                                    ),
                                    value: platform,
                                  ),
                          );
                        },
                      );

                return Column(
                  children: [
                    Padding(
                      padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
                      child: Row(
                        children: [
                          Expanded(
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Text(
                                  l10n.getString(
                                    'adminBroadcastsTargetUsersTitle',
                                  ),
                                  style: Theme.of(ctx).textTheme.titleLarge,
                                ),
                                const SizedBox(height: 4),
                                Text(
                                  targetCount == null
                                      ? l10n.getString(
                                          'adminBroadcastsTargetUnknown',
                                        )
                                      : l10n
                                            .getString(
                                              'adminBroadcastsTargetCountValue',
                                            )
                                            .replaceAll(
                                              '{count}',
                                              targetCount.toString(),
                                            ),
                                  style: Theme.of(ctx).textTheme.bodySmall,
                                ),
                              ],
                            ),
                          ),
                          IconButton(
                            tooltip: l10n.getString('generalClose'),
                            onPressed: close,
                            icon: const Icon(Icons.close),
                          ),
                        ],
                      ),
                    ),
                    const Divider(height: 1),
                    Expanded(child: body),
                  ],
                );
              },
            );
          }

          if (isWideList) {
            await showDialog<void>(
              context: context,
              builder: (ctx) {
                final safeHeight =
                    MediaQuery.of(ctx).size.height -
                    MediaQuery.of(ctx).viewPadding.vertical;
                return Dialog(
                  child: SizedBox(
                    width: 640,
                    height: safeHeight * 0.85,
                    child: buildListContent(
                      close: () => Navigator.of(ctx).pop(),
                    ),
                  ),
                );
              },
            );
            return;
          }

          await showModalBottomSheet<void>(
            context: context,
            isScrollControlled: true,
            useSafeArea: true,
            showDragHandle: true,
            builder: (ctx) {
              final safeHeight =
                  MediaQuery.of(ctx).size.height -
                  MediaQuery.of(ctx).viewPadding.vertical;
              final height = safeHeight * 0.92;
              return SizedBox(
                height: height,
                child: buildListContent(close: () => Navigator.of(ctx).pop()),
              );
            },
          );
        }

        return StatefulBuilder(
          builder: (ctx, setSheetState) {
            void closeWithoutValueSafe() {
              countDebounce?.cancel();
              closeWithoutValue();
            }

            void closeWithValueSafe(Map<String, dynamic> value) {
              countDebounce?.cancel();
              closeWithValue(value);
            }

            void requestTargetCount() {
              if (!ctx.mounted) return;
              final requestKey = jsonEncode(draft);
              lastCountRequest = requestKey;
              countFailed = false;
              isCounting = true;
              setSheetState(() {});

              countDebounce?.cancel();
              countDebounce = Timer(
                const Duration(milliseconds: 350),
                () async {
                  final expectedKey = lastCountRequest;
                  if (expectedKey == null) return;

                  Map<String, dynamic> criteria;
                  try {
                    final decoded = jsonDecode(expectedKey);
                    criteria = decoded is Map
                        ? Map<String, dynamic>.from(decoded)
                        : <String, dynamic>{};
                  } catch (_) {
                    criteria = <String, dynamic>{};
                  }

                  int? count;
                  try {
                    count = await _countTargetUsers(criteria);
                  } catch (_) {
                    count = null;
                  }
                  if (!mounted) return;
                  if (!ctx.mounted) return;
                  if (lastCountRequest != expectedKey) return;

                  setSheetState(() {
                    isCounting = false;
                    targetCount = count;
                    countFailed = count == null;
                  });
                },
              );
            }

            if (!didInitCount) {
              didInitCount = true;
              isCounting = true;
              countFailed = false;
              WidgetsBinding.instance.addPostFrameCallback((_) {
                if (!mounted) return;
                if (!ctx.mounted) return;
                requestTargetCount();
              });
            }

            final allUsers = currentBool('all_users');
            final lastActiveDays = currentInt('last_active_days');
            final genderSelected = currentList('gender');
            final tierSelected = currentList('subscription_tiers');
            final verificationSelected = currentList('verification_status');
            final profileCompletionSelected = currentList('profile_completion');
            final platformSelected = currentList('platform');
            final uiLanguages = (() {
              final out = <String>{...currentList('ui_languages')};
              final legacy = (draft['ui_language'] ?? '')
                  .toString()
                  .trim()
                  .toLowerCase();
              if (legacy == 'en' || legacy == 'es' || legacy == 'he') {
                out.add(legacy);
              }
              return out.toList(growable: false);
            })();

            String currentStatusMode() {
              final raw = (draft['status'] ?? '')
                  .toString()
                  .trim()
                  .toLowerCase();
              if (raw == 'visible' || raw == 'invisible' || raw == 'offline') {
                return raw;
              }
              final legacy = (draft['visibility'] ?? '')
                  .toString()
                  .trim()
                  .toLowerCase();
              if (legacy == 'visible' || legacy == 'invisible') return legacy;
              if (asBool(draft['visible_only'])) return 'visible';
              return 'all';
            }

            final statusMode = currentStatusMode();

            final age = currentAgeRange();
            final ageMin = asInt(age?['min']) ?? 18;
            final ageMax = asInt(age?['max']) ?? 80;
            final hasAge = age != null;

            void toggleStringInList(String key, String value) {
              final v = value.trim().toLowerCase();
              var next = currentList(key);
              if (next.contains(v)) {
                next = next.where((e) => e != v).toList(growable: false);
              } else {
                next = [...next, v];
              }
              setSheetState(() {
                setList(key, next);
              });
              requestTargetCount();
            }

            void toggleUiLanguage(String code) {
              final v = code.trim().toLowerCase();
              if (v != 'en' && v != 'es' && v != 'he') return;
              final base =
                  <String>{
                        ...currentList('ui_languages'),
                        ...(draft['ui_language'] == null
                            ? const <String>{}
                            : <String>{
                                draft['ui_language']
                                    .toString()
                                    .trim()
                                    .toLowerCase(),
                              }),
                      }
                      .where((e) => e == 'en' || e == 'es' || e == 'he')
                      .toList(growable: false);

              var next = base;
              if (next.contains(v)) {
                next = next.where((e) => e != v).toList(growable: false);
              } else {
                next = [...next, v];
              }

              setSheetState(() {
                draft.remove('ui_language');
                setList('ui_languages', next);
              });
              requestTargetCount();
            }

            Widget sectionTitle(String title) {
              return Padding(
                padding: const EdgeInsets.only(top: 18, bottom: 8),
                child: Text(title, style: Theme.of(ctx).textTheme.titleSmall),
              );
            }

            final content = ListView(
              padding: const EdgeInsets.fromLTRB(16, 12, 16, 16),
              children: [
                SwitchListTile(
                  value: allUsers,
                  onChanged: (v) {
                    setSheetState(() {
                      if (v) {
                        draft = <String, dynamic>{'all_users': true};
                      } else {
                        draft.remove('all_users');
                      }
                    });
                    requestTargetCount();
                  },
                  title: Text(l10n.getString('adminBroadcastsFilterAllUsers')),
                ),
                if (!allUsers) ...[
                  sectionTitle(l10n.getString('adminBroadcastsFilterGender')),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: genders
                        .map((g) {
                          final key = (g['key'] ?? '').trim().toLowerCase();
                          if (key.isEmpty) return const SizedBox.shrink();
                          final isSelected = genderSelected.contains(key);
                          return FilterChip(
                            selected: isSelected,
                            onSelected: (_) =>
                                toggleStringInList('gender', key),
                            label: Text(genderLabel(l10n, key)),
                          );
                        })
                        .toList(growable: false),
                  ),
                  sectionTitle(l10n.getString('adminBroadcastsFilterAgeRange')),
                  Row(
                    children: [
                      Expanded(
                        child: Text(
                          hasAge
                              ? '${ageMin.toString()}–${ageMax.toString()}'
                              : l10n.getString('generalAny'),
                        ),
                      ),
                      TextButton(
                        onPressed: () {
                          setSheetState(() => clearAgeRange());
                          requestTargetCount();
                        },
                        child: Text(l10n.getString('generalClear')),
                      ),
                    ],
                  ),
                  RangeSlider(
                    values: RangeValues(ageMin.toDouble(), ageMax.toDouble()),
                    min: 18,
                    max: 80,
                    divisions: 62,
                    labels: RangeLabels(ageMin.toString(), ageMax.toString()),
                    onChanged: (values) {
                      setSheetState(() {
                        setAgeRange(
                          min: values.start.round(),
                          max: values.end.round(),
                        );
                      });
                      requestTargetCount();
                    },
                  ),
                  sectionTitle(
                    l10n.getString('adminBroadcastsFilterSubscriptionTiers'),
                  ),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: tiers
                        .map((id) {
                          final key = id.trim();
                          if (key.isEmpty) return const SizedBox.shrink();
                          final isSelected = tierSelected.contains(
                            key.toLowerCase(),
                          );
                          return FilterChip(
                            selected: isSelected,
                            onSelected: (_) =>
                                toggleStringInList('subscription_tiers', key),
                            label: Text(tierLabel(l10n, key)),
                          );
                        })
                        .toList(growable: false),
                  ),
                  sectionTitle(
                    l10n.getString('adminBroadcastsFilterVerificationStatus'),
                  ),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children:
                        const [
                              'unverified',
                              'analyzing',
                              'pending',
                              'approved',
                              'rejected',
                            ]
                            .map((s) {
                              final isSelected = verificationSelected.contains(
                                s,
                              );
                              return FilterChip(
                                selected: isSelected,
                                onSelected: (_) => toggleStringInList(
                                  'verification_status',
                                  s,
                                ),
                                label: Text(statusLabel(l10n, s)),
                              );
                            })
                            .toList(growable: false),
                  ),
                  sectionTitle(
                    l10n.getString('adminBroadcastsFilterProfileCompletion'),
                  ),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: const ['complete', 'incomplete']
                        .map((s) {
                          final isSelected = profileCompletionSelected.contains(
                            s,
                          );
                          return FilterChip(
                            selected: isSelected,
                            onSelected: (_) =>
                                toggleStringInList('profile_completion', s),
                            label: Text(
                              s == 'complete'
                                  ? l10n.getString(
                                      'adminBroadcastsProfileCompleted',
                                    )
                                  : l10n.getString(
                                      'adminBroadcastsProfileIncomplete',
                                    ),
                            ),
                          );
                        })
                        .toList(growable: false),
                  ),
                  sectionTitle(l10n.getString('adminBroadcastsFilterPlatform')),
                  Wrap(
                    spacing: 8,
                    runSpacing: 8,
                    children: const ['ios', 'android', 'web']
                        .map((p) {
                          final isSelected = platformSelected.contains(p);
                          return FilterChip(
                            selected: isSelected,
                            onSelected: (_) =>
                                toggleStringInList('platform', p),
                            label: Text(platformLabel(l10n, p)),
                          );
                        })
                        .toList(growable: false),
                  ),
                  sectionTitle(
                    l10n.getString('adminBroadcastsFilterLastActiveDays'),
                  ),
                  DropdownMenu<int?>(
                    initialSelection: lastActiveDays,
                    label: Text(
                      l10n.getString('adminBroadcastsLastActiveLabel'),
                    ),
                    dropdownMenuEntries: [
                      DropdownMenuEntry(
                        value: null,
                        label: l10n.getString('generalAny'),
                      ),
                      ...lastActiveOptions.map(
                        (d) => DropdownMenuEntry(
                          value: d,
                          label: l10n
                              .getString('adminBroadcastsLastActiveValue')
                              .replaceAll('{days}', d.toString()),
                        ),
                      ),
                    ],
                    onSelected: (v) {
                      setSheetState(() => setInt('last_active_days', v));
                      requestTargetCount();
                    },
                  ),
                  const SizedBox(height: 8),
                  sectionTitle(l10n.getString('adminBroadcastsFilterStatus')),
                  SegmentedButton<String>(
                    segments: [
                      ButtonSegment(
                        value: 'all',
                        label: Text(l10n.getString('adminBroadcastsStatusAll')),
                      ),
                      ButtonSegment(
                        value: 'visible',
                        label: Text(
                          l10n.getString('adminBroadcastsStatusVisible'),
                        ),
                      ),
                      ButtonSegment(
                        value: 'invisible',
                        label: Text(
                          l10n.getString('adminBroadcastsStatusInvisible'),
                        ),
                      ),
                      ButtonSegment(
                        value: 'offline',
                        label: Text(
                          l10n.getString('adminBroadcastsStatusOffline'),
                        ),
                      ),
                    ],
                    selected: {statusMode},
                    onSelectionChanged: (selection) {
                      if (selection.isEmpty) return;
                      final mode = selection.first;
                      setSheetState(() {
                        draft.remove('visible_only');
                        draft.remove('visibility');
                        if (mode == 'all') {
                          draft.remove('status');
                        } else {
                          draft['status'] = mode;
                        }
                      });
                      requestTargetCount();
                    },
                  ),
                  if (allowUiLanguageFilters) ...[
                    sectionTitle(
                      l10n.getString('adminBroadcastsFilterUiLanguages'),
                    ),
                    MenuAnchor(
                      menuChildren: ['en', 'es', 'he']
                          .map((code) {
                            final isSelected = uiLanguages.contains(code);
                            return SizedBox(
                              width: 260,
                              child: CheckboxListTile(
                                value: isSelected,
                                onChanged: (_) => toggleUiLanguage(code),
                                title: Text(uiLanguageName(code)),
                                controlAffinity:
                                    ListTileControlAffinity.leading,
                                dense: true,
                              ),
                            );
                          })
                          .toList(growable: false),
                      builder: (innerCtx, controller, child) {
                        final selectedNames = const ['en', 'es', 'he']
                            .where(uiLanguages.contains)
                            .map(uiLanguageName)
                            .toList(growable: false);
                        final display = selectedNames.isEmpty
                            ? l10n.getString('generalAny')
                            : selectedNames.join(', ');
                        return OutlinedButton.icon(
                          onPressed: () {
                            if (controller.isOpen) {
                              controller.close();
                            } else {
                              controller.open();
                            }
                          },
                          icon: const Icon(Icons.language),
                          label: Text(display, overflow: TextOverflow.ellipsis),
                        );
                      },
                    ),
                  ],
                ],
              ],
            );

            return Column(
              children: [
                Padding(
                  padding: const EdgeInsets.fromLTRB(16, 12, 8, 8),
                  child: Row(
                    children: [
                      Expanded(
                        child: Text(
                          l10n.getString(
                            'adminBroadcastsTargetingFiltersTitle',
                          ),
                          style: Theme.of(ctx).textTheme.titleLarge,
                        ),
                      ),
                      IconButton(
                        tooltip: l10n.getString('generalClose'),
                        onPressed: closeWithoutValueSafe,
                        icon: const Icon(Icons.close),
                      ),
                    ],
                  ),
                ),
                const Divider(height: 1),
                Expanded(child: content),
                const Divider(height: 1),
                Padding(
                  padding: EdgeInsets.fromLTRB(
                    16,
                    10,
                    16,
                    16 +
                        (() {
                          final mq = MediaQuery.of(ctx);
                          final a = mq.viewPadding.bottom;
                          final b = mq.systemGestureInsets.bottom;
                          return a > b ? a : b;
                        })(),
                  ),
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      Row(
                        children: [
                          if (isCounting)
                            const SizedBox(
                              width: 16,
                              height: 16,
                              child: CircularProgressIndicator(strokeWidth: 2),
                            ),
                          if (isCounting) const SizedBox(width: 10),
                          Expanded(
                            child: Text(
                              isCounting
                                  ? l10n.getString('generalLoading')
                                  : targetCount == null
                                  ? l10n.getString(
                                      'adminBroadcastsTargetUnknown',
                                    )
                                  : l10n
                                        .getString(
                                          'adminBroadcastsTargetCountValue',
                                        )
                                        .replaceAll(
                                          '{count}',
                                          targetCount.toString(),
                                        ),
                              style: Theme.of(ctx).textTheme.bodyMedium
                                  ?.copyWith(
                                    color:
                                        (countFailed || targetCount == null) &&
                                            !isCounting
                                        ? Theme.of(ctx).colorScheme.error
                                        : null,
                                  ),
                            ),
                          ),
                          const SizedBox(width: 10),
                          OutlinedButton(
                            onPressed: isCounting
                                ? null
                                : () async {
                                    await openTargetUsersList(
                                      deepCloneCriteria(draft),
                                    );
                                  },
                            child: Text(
                              l10n.getString('adminBroadcastsViewUsers'),
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 10),
                      Row(
                        children: [
                          TextButton(
                            onPressed: () {
                              // Empty {} fans out to everyone server-side, so
                              // Clear must be explicit all-users, never {}.
                              setSheetState(
                                () => draft = <String, dynamic>{
                                  'all_users': true,
                                },
                              );
                              requestTargetCount();
                            },
                            child: Text(l10n.getString('generalClear')),
                          ),
                          const Spacer(),
                          TextButton(
                            onPressed: closeWithoutValueSafe,
                            child: Text(l10n.getString('generalCancel')),
                          ),
                          const SizedBox(width: 8),
                          ElevatedButton(
                            onPressed: () => closeWithValueSafe(draft),
                            child: Text(l10n.getString('generalApply')),
                          ),
                        ],
                      ),
                    ],
                  ),
                ),
              ],
            );
          },
        );
      }

      if (isWide) {
        return showDialog<Map<String, dynamic>>(
          context: context,
          builder: (ctx) {
            return Dialog(
              insetPadding: const EdgeInsets.fromLTRB(64, 24, 24, 24),
              alignment: Alignment.centerRight,
              child: SizedBox(
                width: 460,
                height:
                    (MediaQuery.of(ctx).size.height -
                        MediaQuery.of(ctx).viewPadding.vertical) *
                    0.9,
                child: buildContent(
                  startValue: initial,
                  closeWithValue: (v) => Navigator.of(ctx).pop(v),
                  closeWithoutValue: () => Navigator.of(ctx).pop(),
                ),
              ),
            );
          },
        );
      }

      return showModalBottomSheet<Map<String, dynamic>>(
        context: context,
        isScrollControlled: true,
        useSafeArea: true,
        showDragHandle: true,
        builder: (ctx) {
          final safeHeight =
              MediaQuery.of(ctx).size.height -
              MediaQuery.of(ctx).viewPadding.vertical;
          final height = safeHeight * 0.92;
          return SizedBox(
            height: height,
            child: buildContent(
              startValue: initial,
              closeWithValue: (v) => Navigator.of(ctx).pop(v),
              closeWithoutValue: () => Navigator.of(ctx).pop(),
            ),
          );
        },
      );
    }

    Widget previewCard(
      BuildContext themeContext, {
      required String locale,
      required String title,
      required String message,
      required String actionText,
      required String actionUrl,
    }) {
      final dir = locale == 'he' ? TextDirection.rtl : TextDirection.ltr;
      return Directionality(
        textDirection: dir,
        child: Card(
          child: Padding(
            padding: const EdgeInsets.all(12),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Text(
                  title.trim(),
                  style: Theme.of(themeContext).textTheme.titleMedium,
                  textAlign: isRtlText(title.trim())
                      ? TextAlign.right
                      : TextAlign.left,
                  textDirection: isRtlText(title.trim())
                      ? TextDirection.rtl
                      : TextDirection.ltr,
                ),
                const SizedBox(height: 8),
                Text(
                  message.trim(),
                  textAlign: isRtlText(message.trim())
                      ? TextAlign.right
                      : TextAlign.left,
                  textDirection: isRtlText(message.trim())
                      ? TextDirection.rtl
                      : TextDirection.ltr,
                ),
                if (actionUrl.trim().isNotEmpty) ...[
                  const SizedBox(height: 12),
                  Align(
                    alignment: dir == TextDirection.rtl
                        ? Alignment.centerLeft
                        : Alignment.centerRight,
                    child: FilledButton(
                      onPressed: null,
                      child: Text(
                        actionText.trim().isEmpty
                            ? 'Learn More'
                            : actionText.trim(),
                      ),
                    ),
                  ),
                ],
              ],
            ),
          ),
        ),
      );
    }

    final uiLanguageDisplayNames = await loadUiLanguageDisplayNames();
    if (!mounted) return;

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          String uiLanguageName(String code, Map<String, String> names) {
            final normalized = code.trim().toLowerCase();
            return names[normalized] ??
                uiLanguageNameFallback(l10n, normalized);
          }

          final type = typeController.value;
          final actionUrl = actionUrlController.text;

          final isPerLanguage = mode == 'per_language';

          void setCriteria(Map<String, dynamic> next) {
            criteriaController.text = const JsonEncoder.withIndent(
              '  ',
            ).convert(next);
            requestTargetingCount(ctx, setDialogState, next);
            requestRecipientsUiLanguages(ctx, setDialogState, next);
            setDialogState(() {});
          }

          void removeCriteriaKey(String key) {
            final current = parseCriteria();
            if (current == null) return;
            current.remove(key);
            setCriteria(current);
          }

          void removeVisibilityCriteria() {
            final current = parseCriteria();
            if (current == null) return;
            current.remove('status');
            current.remove('visibility');
            current.remove('visible_only');
            setCriteria(current);
          }

          String criteriaLabel(String key) {
            return switch (key) {
              'all_users' => l10n.getString('adminBroadcastsFilterAllUsers'),
              'user_ids' => l10n.getString('adminBroadcastsRecipientsButton'),
              'gender' => l10n.getString('adminBroadcastsFilterGender'),
              'age_range' => l10n.getString('adminBroadcastsFilterAgeRange'),
              'subscription_tiers' => l10n.getString(
                'adminBroadcastsFilterSubscriptionTiers',
              ),
              'verification_status' => l10n.getString(
                'adminBroadcastsFilterVerificationStatus',
              ),
              'profile_completion' => l10n.getString(
                'adminBroadcastsFilterProfileCompletion',
              ),
              'platform' => l10n.getString('adminBroadcastsFilterPlatform'),
              'last_active_days' => l10n.getString(
                'adminBroadcastsFilterLastActiveDays',
              ),
              'status' => l10n.getString('adminBroadcastsFilterStatus'),
              'visible_only' => l10n.getString(
                'adminBroadcastsFilterVisibleOnly',
              ),
              'ui_language' => l10n.getString(
                'adminBroadcastsFilterUiLanguage',
              ),
              'ui_languages' => l10n.getString(
                'adminBroadcastsFilterUiLanguages',
              ),
              _ => key,
            };
          }

          String formatVerificationStatus(String s) {
            return switch (s) {
              'unverified' => l10n.getString('adminStatusUnverified'),
              'analyzing' => l10n.getString('adminStatusAnalyzing'),
              'pending' => l10n.getString('adminStatusPending'),
              'approved' => l10n.getString('adminStatusApproved'),
              'rejected' => l10n.getString('adminStatusRejected'),
              _ => s,
            };
          }

          String formatPlatform(String p) {
            return switch (p) {
              'ios' => l10n.getString('adminPlatformIos'),
              'android' => l10n.getString('adminPlatformAndroid'),
              'web' => l10n.getString('adminPlatformWeb'),
              _ => p,
            };
          }

          String formatListValue(String key, List<String> values) {
            final clean = values
                .map((e) => e.trim())
                .where((e) => e.isNotEmpty)
                .toList();
            if (clean.isEmpty) return '';
            if (key == 'verification_status') {
              return clean.map(formatVerificationStatus).join(', ');
            }
            if (key == 'platform') {
              return clean.map(formatPlatform).join(', ');
            }
            return clean.join(', ');
          }

          List<Widget> buildCriteriaChips(Map<String, dynamic> criteria) {
            final chips = <Widget>[];

            final userIds = asStringList(criteria['user_ids']);
            if (userIds.isNotEmpty) {
              chips.add(
                InputChip(
                  label: Text(
                    l10n
                        .getString('adminBroadcastsRecipientsChip')
                        .replaceAll('{count}', userIds.length.toString()),
                  ),
                  onDeleted: () => removeCriteriaKey('user_ids'),
                ),
              );
              // Do not return early: also show other active filters
              // (notably ui_language) so per-language copies stay legible.
              // Server treats user_ids as exclusive for delivery.
            } else if (asBool(criteria['all_users']) || criteria.isEmpty) {
              // Empty {} fans out to everyone server-side – surface as all.
              chips.add(
                InputChip(
                  label: Text(criteriaLabel('all_users')),
                  onDeleted: () => removeCriteriaKey('all_users'),
                ),
              );
              return chips;
            }
            if (userIds.isNotEmpty &&
                chips.isNotEmpty &&
                criteria.length == 1) {
              return chips;
            }

            final genders = asStringList(criteria['gender']);
            if (genders.isNotEmpty) {
              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('gender')}: ${formatListValue('gender', genders)}',
                  ),
                  onDeleted: () => removeCriteriaKey('gender'),
                ),
              );
            }

            final age = criteria['age_range'];
            if (age is Map) {
              final m = Map<String, dynamic>.from(age);
              final min = asInt(m['min']);
              final max = asInt(m['max']);
              if (min != null && max != null) {
                chips.add(
                  InputChip(
                    label: Text(
                      '${criteriaLabel('age_range')}: ${min.toString()}–${max.toString()}',
                    ),
                    onDeleted: () => removeCriteriaKey('age_range'),
                  ),
                );
              }
            }

            final tiers = asStringList(criteria['subscription_tiers']);
            if (tiers.isNotEmpty) {
              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('subscription_tiers')}: ${formatListValue('subscription_tiers', tiers)}',
                  ),
                  onDeleted: () => removeCriteriaKey('subscription_tiers'),
                ),
              );
            }

            final verification = asStringList(criteria['verification_status']);
            if (verification.isNotEmpty) {
              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('verification_status')}: ${formatListValue('verification_status', verification)}',
                  ),
                  onDeleted: () => removeCriteriaKey('verification_status'),
                ),
              );
            }

            final profileCompletion = asStringList(
              criteria['profile_completion'],
            );
            if (profileCompletion.isNotEmpty) {
              String completionLabel(String v) {
                return v == 'complete'
                    ? l10n.getString('adminBroadcastsProfileCompleted')
                    : l10n.getString('adminBroadcastsProfileIncomplete');
              }

              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('profile_completion')}: ${profileCompletion.map(completionLabel).join(', ')}',
                  ),
                  onDeleted: () => removeCriteriaKey('profile_completion'),
                ),
              );
            }

            final platforms = asStringList(criteria['platform']);
            if (platforms.isNotEmpty) {
              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('platform')}: ${formatListValue('platform', platforms)}',
                  ),
                  onDeleted: () => removeCriteriaKey('platform'),
                ),
              );
            }

            final lastActive = asInt(criteria['last_active_days']);
            if (lastActive != null) {
              chips.add(
                InputChip(
                  label: Text(
                    '${criteriaLabel('last_active_days')}: ${l10n.getString('adminBroadcastsLastActiveValue').replaceAll('{days}', lastActive.toString())}',
                  ),
                  onDeleted: () => removeCriteriaKey('last_active_days'),
                ),
              );
            }

            final status = (criteria['status'] ?? '')
                .toString()
                .trim()
                .toLowerCase();
            final legacyVis = (criteria['visibility'] ?? '')
                .toString()
                .trim()
                .toLowerCase();
            final legacyVisible = asBool(criteria['visible_only']);
            final mode =
                (status == 'visible' ||
                    status == 'invisible' ||
                    status == 'offline')
                ? status
                : (legacyVis == 'visible' || legacyVis == 'invisible')
                ? legacyVis
                : (legacyVisible ? 'visible' : 'all');
            if (mode == 'visible' || mode == 'invisible' || mode == 'offline') {
              final modeLabel = switch (mode) {
                'visible' => l10n.getString('adminBroadcastsStatusVisible'),
                'invisible' => l10n.getString('adminBroadcastsStatusInvisible'),
                'offline' => l10n.getString('adminBroadcastsStatusOffline'),
                _ => mode,
              };
              chips.add(
                InputChip(
                  label: Text('${criteriaLabel('status')}: $modeLabel'),
                  onDeleted: removeVisibilityCriteria,
                ),
              );
            }

            if (!isPerLanguage) {
              final uiLang = (criteria['ui_language'] ?? '')
                  .toString()
                  .trim()
                  .toLowerCase();
              final uiLangs =
                  <String>{
                        ...asStringList(
                          criteria['ui_languages'],
                        ).map((e) => e.toLowerCase()),
                        if (uiLang.isNotEmpty) uiLang,
                      }
                      .where((e) => e == 'en' || e == 'es' || e == 'he')
                      .toList(growable: false);
              if (uiLangs.isNotEmpty) {
                chips.add(
                  InputChip(
                    label: Text(
                      '${criteriaLabel('ui_languages')}: ${uiLangs.map((c) => uiLanguageName(c, uiLanguageDisplayNames)).join(', ')}',
                    ),
                    onDeleted: () {
                      removeCriteriaKey('ui_language');
                      removeCriteriaKey('ui_languages');
                    },
                  ),
                );
              }
            }

            return chips;
          }

          final previewEn = previewCard(
            ctx,
            locale: 'en',
            title: titleEnController.text,
            message: messageEnController.text,
            actionText: actionTextEnController.text,
            actionUrl: actionUrl,
          );
          final previewEs = isPerLanguage
              ? previewCard(
                  ctx,
                  locale: 'es',
                  title: titleEsController.text,
                  message: messageEsController.text,
                  actionText: actionTextEsController.text,
                  actionUrl: actionUrl,
                )
              : previewEn;
          final previewHe = isPerLanguage
              ? previewCard(
                  ctx,
                  locale: 'he',
                  title: titleHeController.text,
                  message: messageHeController.text,
                  actionText: actionTextHeController.text,
                  actionUrl: actionUrl,
                )
              : previewEn;

          Future<void> submit() async {
            if (!formKey.currentState!.validate()) return;

            final parsedCriteria = parseCriteria();
            if (parsedCriteria == null) {
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(l10n.getString('adminBroadcastsInvalidJson')),
                ),
              );
              return;
            }
            // Never persist ambiguous {} – it fans out to everyone.
            // Non-nullable local so closures capture a promotable type.
            Map<String, dynamic> criteria = parsedCriteria;
            if (criteria.isEmpty) {
              criteria = <String, dynamic>{'all_users': true};
            }
            // Action text without URL does nothing client-side – require URL.
            final pendingActionText = actionTextEnController.text.trim();
            final pendingActionUrl = actionUrlController.text.trim();
            if (pendingActionText.isNotEmpty && pendingActionUrl.isEmpty) {
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(
                    l10n.getString('adminBroadcastsActionUrlInvalid'),
                  ),
                ),
              );
              return;
            }

            setDialogState(() {
              isSubmitting = true;
            });

            try {
              final client = Supabase.instance.client;
              final nowUtc = DateTime.now().toUtc().toIso8601String();

              final userId = client.auth.currentUser?.id;

              if (existing != null) {
                await client
                    .from('admin_broadcasts')
                    .update({
                      'title': titleEnController.text.trim(),
                      'message': messageEnController.text.trim(),
                      'message_type': type,
                      'automation_type': birthdayAutomationEnabled
                          ? 'birthday'
                          : profileReminderAutomationEnabled
                          ? 'profile_reminder'
                          : null,
                      'automation_enabled':
                          birthdayAutomationEnabled ||
                          profileReminderAutomationEnabled,
                      'action_url': actionUrlController.text.trim().isEmpty
                          ? null
                          : actionUrlController.text.trim(),
                      'action_url_text':
                          actionTextEnController.text.trim().isEmpty
                          ? null
                          : actionTextEnController.text.trim(),
                      'filter_criteria': criteria,
                      'scheduled_at': null,
                      'sent_at': null,
                      'status': 'draft',
                      'updated_at': nowUtc,
                    })
                    .eq('id', existing.id);
              } else if (isPerLanguage) {
                Map<String, dynamic> criteriaFor(String locale) {
                  final merged = Map<String, dynamic>.from(criteria);
                  merged.remove('ui_language');
                  merged.remove('ui_languages');
                  merged['ui_language'] = locale;
                  return merged;
                }

                final selectedUserIds = asStringList(criteria['user_ids']);
                final actionUrl = actionUrlController.text.trim().isEmpty
                    ? null
                    : actionUrlController.text.trim();

                Map<String, dynamic> rowForLocale(
                  String locale,
                  List<String> userIds,
                ) {
                  final criteriaForUsers = criteriaFor(locale);
                  criteriaForUsers['user_ids'] = userIds;
                  return {
                    'title': switch (locale) {
                      'es' =>
                        titleEsController.text.trim().isEmpty
                            ? titleEnController.text.trim()
                            : titleEsController.text.trim(),
                      'he' =>
                        titleHeController.text.trim().isEmpty
                            ? titleEnController.text.trim()
                            : titleHeController.text.trim(),
                      _ => titleEnController.text.trim(),
                    },
                    'message': switch (locale) {
                      'es' =>
                        messageEsController.text.trim().isEmpty
                            ? messageEnController.text.trim()
                            : messageEsController.text.trim(),
                      'he' =>
                        messageHeController.text.trim().isEmpty
                            ? messageEnController.text.trim()
                            : messageHeController.text.trim(),
                      _ => messageEnController.text.trim(),
                    },
                    'message_type': type,
                    'automation_type': birthdayAutomationEnabled
                        ? 'birthday'
                        : profileReminderAutomationEnabled
                        ? 'profile_reminder'
                        : null,
                    'automation_enabled':
                        birthdayAutomationEnabled ||
                        profileReminderAutomationEnabled,
                    'action_url': actionUrl,
                    'action_url_text': switch (locale) {
                      'es' =>
                        actionTextEsController.text.trim().isEmpty
                            ? (actionTextEnController.text.trim().isEmpty
                                  ? null
                                  : actionTextEnController.text.trim())
                            : actionTextEsController.text.trim(),
                      'he' =>
                        actionTextHeController.text.trim().isEmpty
                            ? (actionTextEnController.text.trim().isEmpty
                                  ? null
                                  : actionTextEnController.text.trim())
                            : actionTextHeController.text.trim(),
                      _ =>
                        actionTextEnController.text.trim().isEmpty
                            ? null
                            : actionTextEnController.text.trim(),
                    },
                    'filter_criteria': criteriaForUsers,
                    'scheduled_at': null,
                    'sent_at': null,
                    'status': 'draft',
                    'created_by': userId,
                  };
                }

                final List<Map<String, dynamic>> payload;
                if (selectedUserIds.isEmpty) {
                  payload = [
                    rowForLocale('en', const []),
                    rowForLocale('es', const []),
                    rowForLocale('he', const []),
                  ];
                  payload[0]['filter_criteria'] = criteriaFor('en');
                  payload[1]['filter_criteria'] = criteriaFor('es');
                  payload[2]['filter_criteria'] = criteriaFor('he');
                } else {
                  final result = await client
                      .rpc(
                        'admin_get_user_ui_languages',
                        params: {'p_user_ids': selectedUserIds},
                      )
                      .timeout(const Duration(seconds: 12));

                  final byLang = <String, List<String>>{
                    'en': [],
                    'es': [],
                    'he': [],
                  };

                  final unknown = <String>{...selectedUserIds};

                  if (result is List) {
                    for (final row in result) {
                      if (row is! Map) continue;
                      final m = Map<String, dynamic>.from(row);
                      final id = (m['user_id'] ?? m['id'] ?? '')
                          .toString()
                          .trim();
                      if (id.isEmpty) continue;
                      final lang = (m['ui_language'] ?? m['language'] ?? 'en')
                          .toString()
                          .trim()
                          .toLowerCase();
                      final normalized = (lang == 'es' || lang == 'he')
                          ? lang
                          : 'en';
                      byLang[normalized]!.add(id);
                      unknown.remove(id);
                    }
                  }

                  if (unknown.isNotEmpty) {
                    byLang['en'] = [...byLang['en']!, ...unknown];
                  }

                  payload = [
                    if (byLang['en']!.isNotEmpty)
                      rowForLocale('en', byLang['en']!),
                    if (byLang['es']!.isNotEmpty)
                      rowForLocale('es', byLang['es']!),
                    if (byLang['he']!.isNotEmpty)
                      rowForLocale('he', byLang['he']!),
                  ];
                }

                await client.from('admin_broadcasts').insert(payload);
              } else {
                await client.from('admin_broadcasts').insert({
                  'title': titleEnController.text.trim(),
                  'message': messageEnController.text.trim(),
                  'message_type': type,
                  'automation_type': birthdayAutomationEnabled
                      ? 'birthday'
                      : profileReminderAutomationEnabled
                      ? 'profile_reminder'
                      : null,
                  'automation_enabled':
                      birthdayAutomationEnabled ||
                      profileReminderAutomationEnabled,
                  'action_url': actionUrlController.text.trim().isEmpty
                      ? null
                      : actionUrlController.text.trim(),
                  'action_url_text': actionTextEnController.text.trim().isEmpty
                      ? null
                      : actionTextEnController.text.trim(),
                  'filter_criteria': criteria,
                  'scheduled_at': null,
                  'sent_at': null,
                  'status': 'draft',
                  'created_by': userId,
                });
              }

              if (!mounted || !ctx.mounted) return;
              Navigator.of(ctx).pop();
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(content: Text(l10n.getString('adminSaved'))),
              );
              unawaited(_load(force: true));
            } catch (_) {
              if (!mounted || !ctx.mounted) return;
              if (!mounted) return;
              ScaffoldMessenger.of(context).showSnackBar(
                SnackBar(
                  content: Text(l10n.getString('adminBroadcastsSaveFailed')),
                ),
              );
            } finally {
              if (ctx.mounted) {
                setDialogState(() {
                  isSubmitting = false;
                });
              }
            }
          }

          final dialogTitle = existing == null
              ? l10n.getString('adminBroadcastsAdd')
              : l10n.getString('adminBroadcastsEdit');

          return Dialog(
            child: ConstrainedBox(
              constraints: BoxConstraints(
                maxWidth: 920,
                maxHeight:
                    (MediaQuery.of(ctx).size.height -
                        MediaQuery.of(ctx).viewPadding.vertical) *
                    0.9,
              ),
              child: Padding(
                padding: const EdgeInsets.fromLTRB(24, 20, 24, 16),
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.stretch,
                  children: [
                    Text(
                      dialogTitle,
                      style: Theme.of(ctx).textTheme.titleLarge,
                    ),
                    const SizedBox(height: 12),
                    Flexible(
                      fit: FlexFit.loose,
                      child: Form(
                        key: formKey,
                        child: SingleChildScrollView(
                          padding: const EdgeInsetsDirectional.only(end: 12),
                          child: Column(
                            mainAxisSize: MainAxisSize.min,
                            children: [
                              if (existing == null) const SizedBox(height: 8),
                              if (existing == null)
                                DropdownMenu<String>(
                                  width: 420,
                                  initialSelection: mode,
                                  label: Text(
                                    l10n.getString('adminBroadcastsMode'),
                                  ),
                                  dropdownMenuEntries: [
                                    DropdownMenuEntry(
                                      value: 'per_language',
                                      label: l10n.getString(
                                        'adminBroadcastsModePerLanguage',
                                      ),
                                    ),
                                    DropdownMenuEntry(
                                      value: 'single',
                                      label: l10n.getString(
                                        'adminBroadcastsModeSingle',
                                      ),
                                    ),
                                  ],
                                  onSelected: isSubmitting
                                      ? null
                                      : (v) => setDialogState(() {
                                          mode = v ?? 'single';
                                        }),
                                ),
                              if (existing == null) const SizedBox(height: 12),
                              DropdownMenu<String>(
                                width: 420,
                                initialSelection: type,
                                label: Text(
                                  l10n.getString('adminBroadcastsType'),
                                ),
                                dropdownMenuEntries:
                                    const [
                                          'info',
                                          'warning',
                                          'promotion',
                                          'update',
                                        ]
                                        .map(
                                          (t) => DropdownMenuEntry(
                                            value: t,
                                            label: _typeLabel(l10n, t),
                                          ),
                                        )
                                        .toList(growable: false),
                                onSelected: isSubmitting
                                    ? null
                                    : (v) => setDialogState(
                                        () =>
                                            typeController.value = v ?? 'info',
                                      ),
                              ),
                              const SizedBox(height: 12),
                              CheckboxListTile(
                                contentPadding: EdgeInsets.zero,
                                value: birthdayAutomationEnabled,
                                onChanged: isSubmitting
                                    ? null
                                    : (value) => setDialogState(() {
                                        birthdayAutomationEnabled =
                                            value ?? false;
                                        if (birthdayAutomationEnabled) {
                                          profileReminderAutomationEnabled =
                                              false;
                                        }
                                      }),
                                title: Text(
                                  l10n.getString(
                                    'adminBroadcastsBirthdayAutomationToggle',
                                  ),
                                ),
                                subtitle: Text(
                                  l10n.getString(
                                    'adminBroadcastsBirthdayAutomationHelp',
                                  ),
                                ),
                              ),
                              CheckboxListTile(
                                contentPadding: EdgeInsets.zero,
                                value: profileReminderAutomationEnabled,
                                onChanged: isSubmitting
                                    ? null
                                    : (value) => setDialogState(() {
                                        profileReminderAutomationEnabled =
                                            value ?? false;
                                        if (profileReminderAutomationEnabled) {
                                          birthdayAutomationEnabled = false;
                                        }
                                      }),
                                title: Text(
                                  l10n.getString(
                                    'adminBroadcastsProfileReminderAutomationToggle',
                                  ),
                                ),
                                subtitle: Text(
                                  l10n.getString(
                                    'adminBroadcastsProfileReminderAutomationHelp',
                                  ),
                                ),
                              ),
                              if (birthdayAutomationEnabled) ...[
                                const SizedBox(height: 12),
                                Container(
                                  width: double.infinity,
                                  padding: const EdgeInsets.all(12),
                                  decoration: BoxDecoration(
                                    color: Theme.of(
                                      ctx,
                                    ).colorScheme.surfaceContainerHighest,
                                    borderRadius: BorderRadius.circular(12),
                                  ),
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        l10n.getString(
                                          'adminBroadcastsBirthdayPlaceholdersTitle',
                                        ),
                                        style: Theme.of(
                                          ctx,
                                        ).textTheme.titleSmall,
                                      ),
                                      const SizedBox(height: 6),
                                      Text(
                                        l10n.getString(
                                          'adminBroadcastsBirthdayPlaceholdersBody',
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                              if (profileReminderAutomationEnabled) ...[
                                const SizedBox(height: 12),
                                Container(
                                  width: double.infinity,
                                  padding: const EdgeInsets.all(12),
                                  decoration: BoxDecoration(
                                    color: Theme.of(
                                      ctx,
                                    ).colorScheme.surfaceContainerHighest,
                                    borderRadius: BorderRadius.circular(12),
                                  ),
                                  child: Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.start,
                                    children: [
                                      Text(
                                        l10n.getString(
                                          'adminBroadcastsProfileReminderPlaceholdersTitle',
                                        ),
                                        style: Theme.of(
                                          ctx,
                                        ).textTheme.titleSmall,
                                      ),
                                      const SizedBox(height: 6),
                                      Text(
                                        l10n.getString(
                                          'adminBroadcastsProfileReminderPlaceholdersBody',
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                              const SizedBox(height: 12),
                              TextFormField(
                                controller: actionUrlController,
                                decoration: InputDecoration(
                                  labelText: l10n.getString(
                                    'adminBroadcastsActionUrl',
                                  ),
                                ),
                                validator: (v) {
                                  if (!looksLikeUrl(v ?? '')) {
                                    return l10n.getString(
                                      'adminBroadcastsActionUrlInvalid',
                                    );
                                  }
                                  return null;
                                },
                                onChanged: (_) => setDialogState(() {}),
                              ),
                              const SizedBox(height: 12),
                              Builder(
                                builder: (innerCtx) {
                                  final criteria = parseCriteria();
                                  final hasValidCriteria = criteria != null;
                                  final safeCriteria =
                                      criteria ?? <String, dynamic>{};
                                  final chips = buildCriteriaChips(
                                    safeCriteria,
                                  );

                                  if (!didInitTargetingCount) {
                                    didInitTargetingCount = true;
                                    if (criteria != null) {
                                      WidgetsBinding.instance
                                          .addPostFrameCallback((_) {
                                            if (!mounted || !ctx.mounted) {
                                              return;
                                            }
                                            requestTargetingCount(
                                              ctx,
                                              setDialogState,
                                              criteria,
                                            );
                                          });
                                    }
                                  }
                                  if (!didInitRecipientsUiLanguages) {
                                    didInitRecipientsUiLanguages = true;
                                    if (criteria != null) {
                                      WidgetsBinding.instance
                                          .addPostFrameCallback((_) {
                                            if (!mounted || !ctx.mounted) {
                                              return;
                                            }
                                            requestRecipientsUiLanguages(
                                              ctx,
                                              setDialogState,
                                              criteria,
                                            );
                                          });
                                    }
                                  }

                                  return Column(
                                    crossAxisAlignment:
                                        CrossAxisAlignment.stretch,
                                    children: [
                                      Row(
                                        children: [
                                          Expanded(
                                            child: Text(
                                              l10n.getString(
                                                'adminBroadcastsTargetingTitle',
                                              ),
                                              style: Theme.of(
                                                innerCtx,
                                              ).textTheme.titleSmall,
                                            ),
                                          ),
                                          OutlinedButton.icon(
                                            onPressed: isSubmitting
                                                ? null
                                                : () async {
                                                    final current =
                                                        parseCriteria();
                                                    if (current == null) {
                                                      if (!innerCtx.mounted) {
                                                        return;
                                                      }
                                                      ScaffoldMessenger.of(
                                                        innerCtx,
                                                      ).showSnackBar(
                                                        SnackBar(
                                                          content: Text(
                                                            l10n.getString(
                                                              'adminBroadcastsInvalidJson',
                                                            ),
                                                          ),
                                                        ),
                                                      );
                                                      return;
                                                    }
                                                    final initial =
                                                        Map<
                                                            String,
                                                            dynamic
                                                          >.from(current)
                                                          ..remove('user_ids');
                                                    final edited =
                                                        await editTargetingFilters(
                                                          initial: initial,
                                                          allowUiLanguageFilters:
                                                              true,
                                                          uiLanguageDisplayNames:
                                                              uiLanguageDisplayNames,
                                                        );
                                                    if (edited == null) return;
                                                    setCriteria(edited);
                                                  },
                                            icon: const Icon(
                                              Icons.tune_outlined,
                                            ),
                                            label: Text(
                                              l10n.getString('generalFilters'),
                                            ),
                                          ),
                                          const SizedBox(width: 8),
                                          OutlinedButton.icon(
                                            onPressed: isSubmitting
                                                ? null
                                                : () async {
                                                    Future<
                                                      List<Map<String, dynamic>>
                                                    >
                                                    searchUsers({
                                                      required String query,
                                                      required int limit,
                                                      required int offset,
                                                    }) async {
                                                      final result = await Supabase
                                                          .instance
                                                          .client
                                                          .rpc(
                                                            'admin_search_users',
                                                            params: {
                                                              'p_query': query,
                                                              'p_limit': limit,
                                                              'p_offset':
                                                                  offset,
                                                            },
                                                          )
                                                          .timeout(
                                                            const Duration(
                                                              seconds: 12,
                                                            ),
                                                          );
                                                      if (result is List) {
                                                        return result
                                                            .whereType<Map>()
                                                            .map(
                                                              (e) =>
                                                                  Map<
                                                                    String,
                                                                    dynamic
                                                                  >.from(e),
                                                            )
                                                            .toList();
                                                      }
                                                      return const [];
                                                    }

                                                    Future<List<String>?>
                                                    pickRecipients(
                                                      BuildContext
                                                      dialogContext, {
                                                      required List<String>
                                                      initialUserIds,
                                                    }) async {
                                                      final initialSet = <String>{
                                                        ...initialUserIds
                                                            .map(
                                                              (e) => e.trim(),
                                                            )
                                                            .where(
                                                              (e) =>
                                                                  e.isNotEmpty,
                                                            ),
                                                      };
                                                      Timer? searchDebounce;

                                                      try {
                                                        return await showDialog<
                                                          List<String>
                                                        >(
                                                          context:
                                                              dialogContext,
                                                          builder: (pickerCtx) {
                                                            final controller =
                                                                TextEditingController();

                                                            String query = '';
                                                            bool isLoading =
                                                                false;
                                                            bool isLoadingMore =
                                                                false;
                                                            bool loadFailed =
                                                                false;
                                                            bool hasMore =
                                                                false;
                                                            const int
                                                            pickerPageSize = 50;
                                                            // Server caps user_ids at 500 – enforce client-side.
                                                            const int
                                                            maxRecipients = 500;
                                                            List<
                                                              Map<
                                                                String,
                                                                dynamic
                                                              >
                                                            >
                                                            results = const [];
                                                            final selected =
                                                                <String>{
                                                                  ...initialSet,
                                                                };

                                                            Future<void> load(
                                                              StateSetter
                                                              setState, {
                                                              bool append =
                                                                  false,
                                                            }) async {
                                                              if (!pickerCtx
                                                                  .mounted) {
                                                                return;
                                                              }
                                                              if (append) {
                                                                if (isLoadingMore ||
                                                                    !hasMore) {
                                                                  return;
                                                                }
                                                                setState(() {
                                                                  isLoadingMore =
                                                                      true;
                                                                });
                                                              } else {
                                                                setState(() {
                                                                  isLoading =
                                                                      true;
                                                                  loadFailed =
                                                                      false;
                                                                });
                                                              }
                                                              try {
                                                                final page = await searchUsers(
                                                                  query: query,
                                                                  limit:
                                                                      pickerPageSize,
                                                                  offset: append
                                                                      ? results
                                                                            .length
                                                                      : 0,
                                                                );
                                                                if (!pickerCtx
                                                                    .mounted) {
                                                                  return;
                                                                }
                                                                setState(() {
                                                                  results =
                                                                      append
                                                                      ? [
                                                                          ...results,
                                                                          ...page,
                                                                        ]
                                                                      : page;
                                                                  hasMore =
                                                                      page.length >=
                                                                      pickerPageSize;
                                                                  isLoading =
                                                                      false;
                                                                  isLoadingMore =
                                                                      false;
                                                                  loadFailed =
                                                                      false;
                                                                });
                                                              } catch (_) {
                                                                if (!pickerCtx
                                                                    .mounted) {
                                                                  return;
                                                                }
                                                                setState(() {
                                                                  isLoading =
                                                                      false;
                                                                  isLoadingMore =
                                                                      false;
                                                                  loadFailed =
                                                                      append
                                                                      ? false
                                                                      : true;
                                                                });
                                                              }
                                                            }

                                                            return StatefulBuilder(
                                                              builder:
                                                                  (
                                                                    pickerCtx,
                                                                    setState,
                                                                  ) {
                                                                    if (results
                                                                            .isEmpty &&
                                                                        !isLoading &&
                                                                        !loadFailed) {
                                                                      WidgetsBinding.instance.addPostFrameCallback((
                                                                        _,
                                                                      ) {
                                                                        if (!pickerCtx
                                                                            .mounted) {
                                                                          return;
                                                                        }
                                                                        load(
                                                                          setState,
                                                                        );
                                                                      });
                                                                    }

                                                                    void
                                                                    scheduleSearch(
                                                                      String
                                                                      next,
                                                                    ) {
                                                                      query =
                                                                          next;
                                                                      searchDebounce
                                                                          ?.cancel();
                                                                      searchDebounce = Timer(
                                                                        const Duration(
                                                                          milliseconds:
                                                                              300,
                                                                        ),
                                                                        () => load(
                                                                          setState,
                                                                        ),
                                                                      );
                                                                      setState(
                                                                        () {},
                                                                      );
                                                                    }

                                                                    final maxHeight =
                                                                        MediaQuery.of(
                                                                          pickerCtx,
                                                                        ).size.height -
                                                                        MediaQuery.of(
                                                                          pickerCtx,
                                                                        ).viewPadding.vertical -
                                                                        120;
                                                                    final dialogHeight = maxHeight
                                                                        .clamp(
                                                                          360,
                                                                          620,
                                                                        )
                                                                        .toDouble();

                                                                    final body =
                                                                        isLoading
                                                                        ? Center(
                                                                            child: Text(
                                                                              l10n.getString(
                                                                                'generalLoading',
                                                                              ),
                                                                            ),
                                                                          )
                                                                        : loadFailed
                                                                        ? Center(
                                                                            child: Text(
                                                                              l10n.getString(
                                                                                'adminBroadcastsRecipientsLoadFailed',
                                                                              ),
                                                                              style:
                                                                                  Theme.of(
                                                                                    pickerCtx,
                                                                                  ).textTheme.bodyMedium?.copyWith(
                                                                                    color: Theme.of(
                                                                                      pickerCtx,
                                                                                    ).colorScheme.error,
                                                                                  ),
                                                                            ),
                                                                          )
                                                                        : results
                                                                              .isEmpty
                                                                        ? Center(
                                                                            child: Text(
                                                                              l10n.getString(
                                                                                'adminBroadcastsRecipientsEmpty',
                                                                              ),
                                                                            ),
                                                                          )
                                                                        : ListView.separated(
                                                                            itemCount:
                                                                                results.length +
                                                                                (hasMore
                                                                                    ? 1
                                                                                    : 0),
                                                                            separatorBuilder:
                                                                                (
                                                                                  _,
                                                                                  _,
                                                                                ) => const Divider(
                                                                                  height: 1,
                                                                                ),
                                                                            itemBuilder:
                                                                                (
                                                                                  rowCtx,
                                                                                  i,
                                                                                ) {
                                                                                  if (hasMore &&
                                                                                      i ==
                                                                                          results.length) {
                                                                                    return Padding(
                                                                                      padding: const EdgeInsets.symmetric(
                                                                                        vertical: 12,
                                                                                      ),
                                                                                      child: Center(
                                                                                        child: OutlinedButton(
                                                                                          onPressed: isLoadingMore
                                                                                              ? null
                                                                                              : () => load(
                                                                                                  setState,
                                                                                                  append: true,
                                                                                                ),
                                                                                          child: isLoadingMore
                                                                                              ? const SizedBox(
                                                                                                  width: 18,
                                                                                                  height: 18,
                                                                                                  child: CircularProgressIndicator(
                                                                                                    strokeWidth: 2,
                                                                                                  ),
                                                                                                )
                                                                                              : Text(
                                                                                                  l10n.getString(
                                                                                                    'generalLoadMore',
                                                                                                  ),
                                                                                                ),
                                                                                        ),
                                                                                      ),
                                                                                    );
                                                                                  }
                                                                                  final row = results[i];
                                                                                  final id =
                                                                                      (row['user_id'] ??
                                                                                              row['id'] ??
                                                                                              '')
                                                                                          .toString()
                                                                                          .trim();
                                                                                  final name =
                                                                                      (row['name'] ??
                                                                                              '')
                                                                                          .toString()
                                                                                          .trim();
                                                                                  final displayName = maskUserDisplayName(
                                                                                    name,
                                                                                  );
                                                                                  final title = name.isEmpty
                                                                                      ? id
                                                                                      : displayName;
                                                                                  final subtitle = name.isEmpty
                                                                                      ? ''
                                                                                      : id;
                                                                                  final checked = selected.contains(
                                                                                    id,
                                                                                  );
                                                                                  return CheckboxListTile(
                                                                                    value: checked,
                                                                                    onChanged:
                                                                                        (
                                                                                          v,
                                                                                        ) {
                                                                                          if (v ==
                                                                                              true) {
                                                                                            if (selected.length >=
                                                                                                maxRecipients) {
                                                                                              ScaffoldMessenger.of(
                                                                                                pickerCtx,
                                                                                              ).showSnackBar(
                                                                                                SnackBar(
                                                                                                  content: Text(
                                                                                                    'Max $maxRecipients recipients (server cap)',
                                                                                                  ),
                                                                                                ),
                                                                                              );
                                                                                              return;
                                                                                            }
                                                                                            selected.add(
                                                                                              id,
                                                                                            );
                                                                                          } else {
                                                                                            selected.remove(
                                                                                              id,
                                                                                            );
                                                                                          }
                                                                                          setState(
                                                                                            () {},
                                                                                          );
                                                                                        },
                                                                                    title: Text(
                                                                                      title,
                                                                                    ),
                                                                                    subtitle: subtitle.isEmpty
                                                                                        ? null
                                                                                        : Text(
                                                                                            subtitle,
                                                                                          ),
                                                                                    controlAffinity: ListTileControlAffinity.leading,
                                                                                  );
                                                                                },
                                                                          );

                                                                    return Dialog(
                                                                      child: ConstrainedBox(
                                                                        constraints: const BoxConstraints(
                                                                          maxWidth:
                                                                              780,
                                                                        ),
                                                                        child: SizedBox(
                                                                          height:
                                                                              dialogHeight,
                                                                          child: Column(
                                                                            children: [
                                                                              Padding(
                                                                                padding: const EdgeInsets.fromLTRB(
                                                                                  16,
                                                                                  12,
                                                                                  8,
                                                                                  8,
                                                                                ),
                                                                                child: Row(
                                                                                  children: [
                                                                                    Expanded(
                                                                                      child: Text(
                                                                                        l10n.getString(
                                                                                          'adminBroadcastsRecipientsTitle',
                                                                                        ),
                                                                                        style: Theme.of(
                                                                                          pickerCtx,
                                                                                        ).textTheme.titleLarge,
                                                                                      ),
                                                                                    ),
                                                                                    IconButton(
                                                                                      tooltip: l10n.getString(
                                                                                        'generalClose',
                                                                                      ),
                                                                                      onPressed: () =>
                                                                                          Navigator.of(
                                                                                            pickerCtx,
                                                                                          ).pop(
                                                                                            null,
                                                                                          ),
                                                                                      icon: const Icon(
                                                                                        Icons.close,
                                                                                      ),
                                                                                    ),
                                                                                  ],
                                                                                ),
                                                                              ),
                                                                              Padding(
                                                                                padding: const EdgeInsets.fromLTRB(
                                                                                  16,
                                                                                  0,
                                                                                  16,
                                                                                  12,
                                                                                ),
                                                                                child: Column(
                                                                                  crossAxisAlignment: CrossAxisAlignment.stretch,
                                                                                  children: [
                                                                                    TextField(
                                                                                      controller: controller,
                                                                                      onChanged: scheduleSearch,
                                                                                      decoration: InputDecoration(
                                                                                        labelText: l10n.getString(
                                                                                          'adminBroadcastsRecipientsSearchLabel',
                                                                                        ),
                                                                                        prefixIcon: const Icon(
                                                                                          Icons.search,
                                                                                        ),
                                                                                      ),
                                                                                    ),
                                                                                    const SizedBox(
                                                                                      height: 8,
                                                                                    ),
                                                                                    Text(
                                                                                      l10n
                                                                                          .getString(
                                                                                            'adminBroadcastsRecipientsSelectedValue',
                                                                                          )
                                                                                          .replaceAll(
                                                                                            '{count}',
                                                                                            selected.length.toString(),
                                                                                          ),
                                                                                      style: Theme.of(
                                                                                        pickerCtx,
                                                                                      ).textTheme.bodySmall,
                                                                                    ),
                                                                                  ],
                                                                                ),
                                                                              ),
                                                                              const Divider(
                                                                                height: 1,
                                                                              ),
                                                                              Expanded(
                                                                                child: body,
                                                                              ),
                                                                              const Divider(
                                                                                height: 1,
                                                                              ),
                                                                              Padding(
                                                                                padding: const EdgeInsets.fromLTRB(
                                                                                  16,
                                                                                  10,
                                                                                  16,
                                                                                  12,
                                                                                ),
                                                                                child: Row(
                                                                                  children: [
                                                                                    TextButton(
                                                                                      onPressed: selected.isEmpty
                                                                                          ? null
                                                                                          : () {
                                                                                              selected.clear();
                                                                                              setState(
                                                                                                () {},
                                                                                              );
                                                                                            },
                                                                                      child: Text(
                                                                                        l10n.getString(
                                                                                          'generalClear',
                                                                                        ),
                                                                                      ),
                                                                                    ),
                                                                                    const Spacer(),
                                                                                    TextButton(
                                                                                      onPressed: () =>
                                                                                          Navigator.of(
                                                                                            pickerCtx,
                                                                                          ).pop(
                                                                                            null,
                                                                                          ),
                                                                                      child: Text(
                                                                                        l10n.getString(
                                                                                          'generalCancel',
                                                                                        ),
                                                                                      ),
                                                                                    ),
                                                                                    const SizedBox(
                                                                                      width: 8,
                                                                                    ),
                                                                                    FilledButton(
                                                                                      onPressed: () =>
                                                                                          Navigator.of(
                                                                                            pickerCtx,
                                                                                          ).pop(
                                                                                            selected.toList(
                                                                                              growable: false,
                                                                                            ),
                                                                                          ),
                                                                                      child: Text(
                                                                                        l10n.getString(
                                                                                          'generalApply',
                                                                                        ),
                                                                                      ),
                                                                                    ),
                                                                                  ],
                                                                                ),
                                                                              ),
                                                                            ],
                                                                          ),
                                                                        ),
                                                                      ),
                                                                    );
                                                                  },
                                                            );
                                                          },
                                                        );
                                                      } finally {
                                                        searchDebounce
                                                            ?.cancel();
                                                      }
                                                    }

                                                    final current =
                                                        parseCriteria();
                                                    if (current == null) {
                                                      if (!innerCtx.mounted) {
                                                        return;
                                                      }
                                                      ScaffoldMessenger.of(
                                                        innerCtx,
                                                      ).showSnackBar(
                                                        SnackBar(
                                                          content: Text(
                                                            l10n.getString(
                                                              'adminBroadcastsInvalidJson',
                                                            ),
                                                          ),
                                                        ),
                                                      );
                                                      return;
                                                    }

                                                    final hadOtherFilters =
                                                        current.keys.any(
                                                          (k) =>
                                                              k != 'user_ids' &&
                                                              k != 'all_users',
                                                        );
                                                    final picked =
                                                        await pickRecipients(
                                                          innerCtx,
                                                          initialUserIds:
                                                              asStringList(
                                                                current['user_ids'],
                                                              ),
                                                        );
                                                    if (picked == null) return;
                                                    if (picked.length > 500) {
                                                      if (!innerCtx.mounted) {
                                                        return;
                                                      }
                                                      ScaffoldMessenger.of(
                                                        innerCtx,
                                                      ).showSnackBar(
                                                        const SnackBar(
                                                          content: Text(
                                                            'Max 500 recipients (server cap) – extra trimmed',
                                                          ),
                                                        ),
                                                      );
                                                    }
                                                    final trimmed =
                                                        picked.length > 500
                                                        ? picked.sublist(0, 500)
                                                        : picked;
                                                    final next =
                                                        <String, dynamic>{
                                                          if (trimmed
                                                              .isNotEmpty)
                                                            'user_ids': trimmed
                                                          else
                                                            'all_users': true,
                                                        };
                                                    setCriteria(next);
                                                    if (hadOtherFilters &&
                                                        innerCtx.mounted) {
                                                      ScaffoldMessenger.of(
                                                        innerCtx,
                                                      ).showSnackBar(
                                                        const SnackBar(
                                                          content: Text(
                                                            'Recipients mode is exclusive – other filters cleared',
                                                          ),
                                                        ),
                                                      );
                                                    }
                                                  },
                                            icon: const Icon(
                                              Icons.person_search_outlined,
                                            ),
                                            label: Text(
                                              l10n.getString(
                                                'adminBroadcastsRecipientsButton',
                                              ),
                                            ),
                                          ),
                                        ],
                                      ),
                                      const SizedBox(height: 8),
                                      if (!hasValidCriteria)
                                        Text(
                                          l10n.getString(
                                            'adminBroadcastsInvalidJson',
                                          ),
                                          style: Theme.of(innerCtx)
                                              .textTheme
                                              .bodyMedium
                                              ?.copyWith(
                                                color: Theme.of(
                                                  innerCtx,
                                                ).colorScheme.error,
                                              ),
                                        )
                                      else if (chips.isEmpty)
                                        Text(
                                          l10n.getString(
                                            'adminBroadcastsTargetingEmpty',
                                          ),
                                        )
                                      else
                                        Wrap(
                                          spacing: 8,
                                          runSpacing: 8,
                                          children: chips,
                                        ),
                                      const SizedBox(height: 12),
                                      Wrap(
                                        spacing: 8,
                                        runSpacing: 8,
                                        alignment: WrapAlignment.end,
                                        children: [
                                          TextButton(
                                            onPressed: isSubmitting
                                                ? null
                                                : () => setCriteria(
                                                    <String, dynamic>{
                                                      'all_users': true,
                                                    },
                                                  ),
                                            child: Text(
                                              l10n.getString('generalClear'),
                                            ),
                                          ),
                                        ],
                                      ),
                                      const SizedBox(height: 12),
                                      Row(
                                        children: [
                                          if (isTargetingCounting)
                                            const SizedBox(
                                              width: 16,
                                              height: 16,
                                              child: CircularProgressIndicator(
                                                strokeWidth: 2,
                                              ),
                                            ),
                                          if (isTargetingCounting)
                                            const SizedBox(width: 10),
                                          Expanded(
                                            child: Text(
                                              isTargetingCounting
                                                  ? l10n.getString(
                                                      'generalLoading',
                                                    )
                                                  : targetingCount == null
                                                  ? l10n.getString(
                                                      'adminBroadcastsTargetUnknown',
                                                    )
                                                  : l10n
                                                        .getString(
                                                          'adminBroadcastsTargetCountValue',
                                                        )
                                                        .replaceAll(
                                                          '{count}',
                                                          targetingCount
                                                              .toString(),
                                                        ),
                                              style: Theme.of(innerCtx)
                                                  .textTheme
                                                  .bodyMedium
                                                  ?.copyWith(
                                                    color:
                                                        (!hasValidCriteria ||
                                                                targetingCountFailed ||
                                                                targetingCount ==
                                                                    null) &&
                                                            !isTargetingCounting
                                                        ? Theme.of(
                                                            innerCtx,
                                                          ).colorScheme.error
                                                        : null,
                                                  ),
                                            ),
                                          ),
                                          const SizedBox(width: 10),
                                          OutlinedButton(
                                            onPressed:
                                                (!hasValidCriteria ||
                                                    isTargetingCounting)
                                                ? null
                                                : () async {
                                                    await _openTargetUsersList(
                                                      l10n: l10n,
                                                      criteria:
                                                          deepCloneCriteria(
                                                            safeCriteria,
                                                          ),
                                                      targetCount:
                                                          targetingCount,
                                                      listLimit: 50,
                                                    );
                                                  },
                                            child: Text(
                                              l10n.getString(
                                                'adminBroadcastsViewUsers',
                                              ),
                                            ),
                                          ),
                                        ],
                                      ),
                                    ],
                                  );
                                },
                              ),
                              const SizedBox(height: 16),
                              if (isPerLanguage)
                                Builder(
                                  builder: (innerCtx) {
                                    final criteria = parseCriteria();
                                    final userIds = asStringList(
                                      criteria?['user_ids'],
                                    );
                                    final shouldLimitByRecipients =
                                        userIds.isNotEmpty &&
                                        !recipientsUiLanguagesFailed;
                                    final allowed = shouldLimitByRecipients
                                        ? (recipientsUiLanguages ??
                                              const <String>{})
                                        : const <String>{'en', 'es', 'he'};

                                    final locales = <String>['en', 'es', 'he']
                                        .where((e) => allowed.contains(e))
                                        .toList(growable: false);
                                    final safeLocales = locales.isEmpty
                                        ? const <String>['en']
                                        : locales;

                                    Widget editorForLocale(String locale) {
                                      return switch (locale) {
                                        'es' => _BroadcastLanguageEditor(
                                          l10n: l10n,
                                          titleController: titleEsController,
                                          messageController:
                                              messageEsController,
                                          actionTextController:
                                              actionTextEsController,
                                          preview: previewEs,
                                          isSubmitting: isSubmitting,
                                          allowEmptyFallback: true,
                                          onChanged: () =>
                                              setDialogState(() {}),
                                        ),
                                        'he' => _BroadcastLanguageEditor(
                                          l10n: l10n,
                                          titleController: titleHeController,
                                          messageController:
                                              messageHeController,
                                          actionTextController:
                                              actionTextHeController,
                                          preview: previewHe,
                                          isSubmitting: isSubmitting,
                                          allowEmptyFallback: true,
                                          onChanged: () =>
                                              setDialogState(() {}),
                                        ),
                                        _ => _BroadcastLanguageEditor(
                                          l10n: l10n,
                                          titleController: titleEnController,
                                          messageController:
                                              messageEnController,
                                          actionTextController:
                                              actionTextEnController,
                                          preview: previewEn,
                                          isSubmitting: isSubmitting,
                                          onChanged: () =>
                                              setDialogState(() {}),
                                        ),
                                      };
                                    }

                                    if (shouldLimitByRecipients &&
                                        recipientsUiLanguages == null &&
                                        isRecipientsUiLanguagesLoading) {
                                      return SizedBox(
                                        height: 520,
                                        child: Center(
                                          child: Column(
                                            mainAxisSize: MainAxisSize.min,
                                            children: [
                                              const SizedBox(
                                                width: 18,
                                                height: 18,
                                                child:
                                                    CircularProgressIndicator(
                                                      strokeWidth: 2,
                                                    ),
                                              ),
                                              const SizedBox(height: 10),
                                              Text(
                                                l10n.getString(
                                                  'generalLoading',
                                                ),
                                              ),
                                            ],
                                          ),
                                        ),
                                      );
                                    }

                                    if (safeLocales.length == 1) {
                                      return SizedBox(
                                        height: 520,
                                        child: editorForLocale(
                                          safeLocales.first,
                                        ),
                                      );
                                    }

                                    return DefaultTabController(
                                      length: safeLocales.length,
                                      child: Column(
                                        crossAxisAlignment:
                                            CrossAxisAlignment.stretch,
                                        children: [
                                          TabBar(
                                            tabs: safeLocales
                                                .map(
                                                  (locale) => Tab(
                                                    text: uiLanguageName(
                                                      locale,
                                                      uiLanguageDisplayNames,
                                                    ),
                                                  ),
                                                )
                                                .toList(growable: false),
                                          ),
                                          SizedBox(
                                            height: 520,
                                            child: TabBarView(
                                              children: safeLocales
                                                  .map(editorForLocale)
                                                  .toList(growable: false),
                                            ),
                                          ),
                                        ],
                                      ),
                                    );
                                  },
                                )
                              else
                                Column(
                                  children: [
                                    TextFormField(
                                      controller: titleEnController,
                                      maxLength: kBroadcastTitleMaxChars,
                                      decoration: InputDecoration(
                                        labelText: l10n.getString(
                                          'adminBroadcastsTitle',
                                        ),
                                        helperText: l10n
                                            .getString(
                                              'adminBroadcastsLimitsHintTitle',
                                            )
                                            .replaceAll(
                                              '{chars}',
                                              '$kBroadcastTitleMaxChars',
                                            )
                                            .replaceAll(
                                              '{bytes}',
                                              '$kBroadcastTitleMaxBytes',
                                            ),
                                      ),
                                      validator: (v) =>
                                          _validateBroadcastTitle(v, l10n),
                                      onChanged: (_) => setDialogState(() {}),
                                    ),
                                    _broadcastCounterLine(
                                      titleEnController.text,
                                      kBroadcastTitleMaxChars,
                                      kBroadcastTitleMaxBytes,
                                      ctx,
                                      l10n,
                                    ),
                                    const SizedBox(height: 12),
                                    TextFormField(
                                      controller: messageEnController,
                                      maxLines: 4,
                                      maxLength: kBroadcastMessageMaxChars,
                                      decoration: InputDecoration(
                                        labelText: l10n.getString(
                                          'adminBroadcastsMessage',
                                        ),
                                        helperText: l10n
                                            .getString(
                                              'adminBroadcastsLimitsHintMessage',
                                            )
                                            .replaceAll(
                                              '{chars}',
                                              '$kBroadcastMessageMaxChars',
                                            )
                                            .replaceAll(
                                              '{bytes}',
                                              '$kBroadcastMessageMaxBytes',
                                            ),
                                      ),
                                      validator: (v) =>
                                          _validateBroadcastMessage(v, l10n),
                                      onChanged: (_) => setDialogState(() {}),
                                    ),
                                    _broadcastCounterLine(
                                      messageEnController.text,
                                      kBroadcastMessageMaxChars,
                                      kBroadcastMessageMaxBytes,
                                      ctx,
                                      l10n,
                                    ),
                                    const SizedBox(height: 12),
                                    TextFormField(
                                      controller: actionTextEnController,
                                      maxLength: kBroadcastActionTextMaxChars,
                                      decoration: InputDecoration(
                                        labelText: l10n.getString(
                                          'adminBroadcastsActionUrlText',
                                        ),
                                        helperText: l10n
                                            .getString(
                                              'adminBroadcastsLimitsHintActionText',
                                            )
                                            .replaceAll(
                                              '{chars}',
                                              '$kBroadcastActionTextMaxChars',
                                            ),
                                      ),
                                      validator: (v) =>
                                          _validateBroadcastActionText(v, l10n),
                                      onChanged: (_) => setDialogState(() {}),
                                    ),
                                    _broadcastCounterLine(
                                      actionTextEnController.text,
                                      kBroadcastActionTextMaxChars,
                                      // Action text is ASCII-ish button label; use
                                      // chars as byte proxy so counter stays simple.
                                      kBroadcastActionTextMaxChars,
                                      ctx,
                                      l10n,
                                    ),
                                    const SizedBox(height: 12),
                                    Align(
                                      alignment: Alignment.centerLeft,
                                      child: Text(
                                        l10n.getString(
                                          'adminBroadcastsPreview',
                                        ),
                                        style: Theme.of(
                                          ctx,
                                        ).textTheme.titleSmall,
                                      ),
                                    ),
                                    const SizedBox(height: 8),
                                    previewEn,
                                  ],
                                ),
                            ],
                          ),
                        ),
                      ),
                    ),
                    const SizedBox(height: 12),
                    Row(
                      mainAxisAlignment: MainAxisAlignment.end,
                      children: [
                        TextButton(
                          onPressed: isSubmitting
                              ? null
                              : () => Navigator.of(ctx).pop(),
                          child: Text(l10n.getString('generalCancel')),
                        ),
                        const SizedBox(width: 8),
                        ElevatedButton(
                          onPressed: isSubmitting ? null : submit,
                          child: isSubmitting
                              ? const SizedBox(
                                  width: 18,
                                  height: 18,
                                  child: CircularProgressIndicator(
                                    strokeWidth: 2,
                                  ),
                                )
                              : Text(l10n.getString('generalSave')),
                        ),
                      ],
                    ),
                  ],
                ),
              ),
            ),
          );
        },
      ),
    );

    targetingCountDebounce?.cancel();
    recipientsUiLangDebounce?.cancel();
    for (final c in [
      typeController,
      actionUrlController,
      titleEnController,
      messageEnController,
      actionTextEnController,
      titleEsController,
      messageEsController,
      actionTextEsController,
      titleHeController,
      messageHeController,
      actionTextHeController,
      criteriaController,
    ]) {
      try {
        c.dispose();
      } catch (_) {}
    }
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final filtered = _rows.where(_matchesFilters).toList(growable: false);

    return Column(
      children: [
        Padding(
          padding: const EdgeInsets.fromLTRB(16, 16, 16, 8),
          child: Wrap(
            spacing: 12,
            runSpacing: 12,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: 320,
                child: TextField(
                  decoration: InputDecoration(
                    labelText: l10n.getString('adminBroadcastsSearchHint'),
                    prefixIcon: const Icon(Icons.search),
                  ),
                  onChanged: (v) => setState(() => _query = v),
                ),
              ),
              SizedBox(
                width: 220,
                child: DropdownMenu<String>(
                  width: 220,
                  initialSelection: _status,
                  label: Text(l10n.getString('adminBroadcastsStatus')),
                  dropdownMenuEntries:
                      const [
                            'all',
                            'draft',
                            'scheduled',
                            'sending',
                            'sent',
                            'failed',
                            'cancelled',
                          ]
                          .map(
                            (s) => DropdownMenuEntry(
                              value: s,
                              label: _statusLabel(l10n, s),
                            ),
                          )
                          .toList(growable: false),
                  onSelected: (v) => setState(() => _status = v ?? 'all'),
                ),
              ),
              SizedBox(
                width: 220,
                child: DropdownMenu<String>(
                  width: 220,
                  initialSelection: _timeFilter,
                  label: Text(l10n.getString('adminBroadcastsTimeFilter')),
                  dropdownMenuEntries: const ['all', 'upcoming', 'past']
                      .map(
                        (t) => DropdownMenuEntry(
                          value: t,
                          label: _timeFilterLabel(l10n, t),
                        ),
                      )
                      .toList(growable: false),
                  onSelected: (v) => setState(() => _timeFilter = v ?? 'all'),
                ),
              ),
              ElevatedButton.icon(
                onPressed: _isLoading ? null : () => _showEditor(l10n),
                icon: const Icon(Icons.add),
                label: Text(l10n.getString('adminBroadcastsAdd')),
              ),
              OutlinedButton.icon(
                onPressed: _isLoading ? null : () => _load(force: true),
                icon: const Icon(Icons.refresh),
                label: Text(l10n.getString('generalRefresh')),
              ),
            ],
          ),
        ),
        const Divider(height: 1),
        Expanded(
          child: _isLoading
              ? Center(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      const CircularProgressIndicator(),
                      const SizedBox(height: 12),
                      Text(l10n.getString('generalLoading')),
                    ],
                  ),
                )
              : _errorKey != null
              ? Center(
                  child: ConstrainedBox(
                    constraints: const BoxConstraints(maxWidth: 520),
                    child: Padding(
                      padding: const EdgeInsets.all(24),
                      child: Column(
                        mainAxisSize: MainAxisSize.min,
                        children: [
                          Text(
                            l10n.getString(_errorKey!),
                            textAlign: TextAlign.center,
                          ),
                          const SizedBox(height: 12),
                          OutlinedButton.icon(
                            onPressed: () => _load(force: true),
                            icon: const Icon(Icons.refresh),
                            label: Text(l10n.getString('generalRefresh')),
                          ),
                        ],
                      ),
                    ),
                  ),
                )
              : filtered.isEmpty
              ? Center(child: Text(l10n.getString('adminBroadcastsEmpty')))
              : ListView.builder(
                  itemCount: filtered.length,
                  itemBuilder: (context, index) {
                    final row = filtered[index];
                    final scheduled = row.scheduledAt == null
                        ? ''
                        : _formatAdminDateTime(l10n, row.scheduledAt!);
                    final sent = row.sentAt == null
                        ? ''
                        : _formatAdminDateTime(l10n, row.sentAt!);
                    final langSingle = (row.filterCriteria['ui_language'] ?? '')
                        .toString()
                        .trim();
                    final langMulti = row.filterCriteria['ui_languages'] is List
                        ? (row.filterCriteria['ui_languages'] as List)
                              .map((e) => e.toString().trim().toUpperCase())
                              .where((e) => e.isNotEmpty)
                              .join(', ')
                        : '';
                    final lang = langSingle.isNotEmpty
                        ? langSingle.toUpperCase()
                        : langMulti;
                    final isAnyAutomation = _isAnyAutomation(row);

                    return Padding(
                      padding: const EdgeInsets.fromLTRB(16, 12, 16, 0),
                      child: Card(
                        child: Padding(
                          padding: const EdgeInsets.all(12),
                          child: Column(
                            crossAxisAlignment: CrossAxisAlignment.start,
                            children: [
                              // Title on its own row — beside chips in a Row, Expanded
                              // often gets ~0 width on narrow phones (one letter per line).
                              Text(
                                row.title.trim().isEmpty ? row.id : row.title,
                                style: Theme.of(context).textTheme.titleMedium,
                              ),
                              const SizedBox(height: 8),
                              Wrap(
                                spacing: 8,
                                runSpacing: 8,
                                crossAxisAlignment: WrapCrossAlignment.center,
                                children: [
                                  _MetaChip(
                                    label: l10n.getString(
                                      'adminBroadcastsStatus',
                                    ),
                                    value: _statusLabel(l10n, row.status),
                                  ),
                                  _MetaChip(
                                    label: l10n.getString(
                                      'adminBroadcastsType',
                                    ),
                                    value: _typeLabel(l10n, row.messageType),
                                  ),
                                  if (isAnyAutomation)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsAutomation',
                                      ),
                                      value: _automationLabel(l10n, row),
                                    ),
                                  if (lang.isNotEmpty)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsLanguage',
                                      ),
                                      value: lang.toUpperCase(),
                                    ),
                                ],
                              ),
                              const SizedBox(height: 8),
                              Text(
                                row.message,
                                maxLines: 3,
                                overflow: TextOverflow.ellipsis,
                              ),
                              const SizedBox(height: 12),
                              Wrap(
                                spacing: 8,
                                runSpacing: 8,
                                children: [
                                  if (scheduled.isNotEmpty)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsScheduledAt',
                                      ),
                                      value: scheduled,
                                    ),
                                  if (sent.isNotEmpty)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsSentAt',
                                      ),
                                      value: sent,
                                    ),
                                  if (row.targetUserCount != null)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsTargetCount',
                                      ),
                                      value: row.targetUserCount.toString(),
                                    ),
                                  if (row.actualSentCount > 0)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsActualSent',
                                      ),
                                      value: row.actualSentCount.toString(),
                                    ),
                                  if (row.skippedCount > 0)
                                    _MetaChip(
                                      label: l10n.getString(
                                        'adminBroadcastsSkipped',
                                      ),
                                      value: row.skippedCount.toString(),
                                    ),
                                ],
                              ),
                              const SizedBox(height: 12),
                              Wrap(
                                spacing: 8,
                                runSpacing: 8,
                                children: [
                                  OutlinedButton.icon(
                                    onPressed: () => _showDetails(l10n, row),
                                    icon: const Icon(Icons.open_in_new),
                                    label: Text(
                                      l10n.getString('adminBroadcastsDetails'),
                                    ),
                                  ),
                                  OutlinedButton.icon(
                                    onPressed:
                                        (row.status == 'draft' ||
                                            row.status == 'scheduled' ||
                                            row.status == 'failed' ||
                                            row.status == 'cancelled')
                                        ? () => _showEditor(l10n, existing: row)
                                        : null,
                                    icon: const Icon(Icons.edit),
                                    label: Text(l10n.getString('generalEdit')),
                                  ),
                                  if ((row.status == 'draft' ||
                                          row.status == 'failed' ||
                                          row.status == 'cancelled') &&
                                      !isAnyAutomation)
                                    ElevatedButton.icon(
                                      onPressed: () =>
                                          _scheduleDraft(l10n, row),
                                      icon: const Icon(Icons.schedule),
                                      label: Text(
                                        l10n.getString(
                                          'adminBroadcastsSchedule',
                                        ),
                                      ),
                                    ),
                                  if ((row.status == 'draft' ||
                                          row.status == 'failed' ||
                                          row.status == 'cancelled') &&
                                      !isAnyAutomation)
                                    ElevatedButton.icon(
                                      onPressed: () => _sendNow(l10n, row),
                                      icon: const Icon(Icons.send),
                                      label: Text(
                                        l10n.getString(
                                          'adminBroadcastsSendNow',
                                        ),
                                      ),
                                    ),
                                  if ((row.status == 'scheduled' ||
                                          row.status == 'sending') &&
                                      !isAnyAutomation)
                                    OutlinedButton.icon(
                                      onPressed: () =>
                                          _cancelScheduled(l10n, row),
                                      icon: const Icon(Icons.cancel_outlined),
                                      label: const Text('Cancel'),
                                    ),
                                  if ((row.status == 'sent' ||
                                          row.status == 'failed' ||
                                          row.status == 'cancelled') &&
                                      !isAnyAutomation)
                                    ElevatedButton.icon(
                                      onPressed:
                                          _resendInFlightIds.contains(row.id)
                                          ? null
                                          : () => _resendNow(l10n, row),
                                      icon: _resendInFlightIds.contains(row.id)
                                          ? const SizedBox(
                                              width: 16,
                                              height: 16,
                                              child: CircularProgressIndicator(
                                                strokeWidth: 2,
                                              ),
                                            )
                                          : const Icon(Icons.send),
                                      label: Text(
                                        l10n.getString(
                                          'adminBroadcastsResendNow',
                                        ),
                                      ),
                                    ),
                                  if ((row.status == 'sent' ||
                                          row.status == 'failed' ||
                                          row.status == 'cancelled') &&
                                      !isAnyAutomation)
                                    OutlinedButton.icon(
                                      onPressed: () =>
                                          _rescheduleSent(l10n, row),
                                      icon: const Icon(Icons.schedule),
                                      label: Text(
                                        l10n.getString(
                                          'adminBroadcastsReschedule',
                                        ),
                                      ),
                                    ),
                                  TextButton.icon(
                                    onPressed: () => _delete(l10n, row),
                                    icon: const Icon(Icons.delete_outline),
                                    label: Text(
                                      l10n.getString('generalDelete'),
                                    ),
                                  ),
                                ],
                              ),
                            ],
                          ),
                        ),
                      ),
                    );
                  },
                ),
        ),
      ],
    );
  }
}

class _BroadcastLanguageEditor extends StatelessWidget {
  final LocalizationState l10n;
  final TextEditingController titleController;
  final TextEditingController messageController;
  final TextEditingController actionTextController;
  final Widget preview;
  final bool isSubmitting;
  final VoidCallback onChanged;
  // When true, empty title/message falls back to English at save time.
  final bool allowEmptyFallback;

  const _BroadcastLanguageEditor({
    required this.l10n,
    required this.titleController,
    required this.messageController,
    required this.actionTextController,
    required this.preview,
    required this.isSubmitting,
    required this.onChanged,
    this.allowEmptyFallback = false,
  });

  String? _titleValidator(String? v, LocalizationState l10n) {
    if (allowEmptyFallback && (v ?? '').trim().isEmpty) return null;
    return _validateBroadcastTitle(v, l10n);
  }

  String? _messageValidator(String? v, LocalizationState l10n) {
    if (allowEmptyFallback && (v ?? '').trim().isEmpty) return null;
    return _validateBroadcastMessage(v, l10n);
  }

  @override
  Widget build(BuildContext context) {
    return Padding(
      padding: const EdgeInsets.only(top: 12),
      child: Column(
        children: [
          TextFormField(
            controller: titleController,
            maxLength: kBroadcastTitleMaxChars,
            decoration: InputDecoration(
              labelText: l10n.getString('adminBroadcastsTitle'),
              helperText: allowEmptyFallback
                  ? '${l10n.getString('adminBroadcastsLimitsHintTitle').replaceAll('{chars}', '$kBroadcastTitleMaxChars').replaceAll('{bytes}', '$kBroadcastTitleMaxBytes')} (empty = English fallback)'
                  : l10n
                        .getString('adminBroadcastsLimitsHintTitle')
                        .replaceAll('{chars}', '$kBroadcastTitleMaxChars')
                        .replaceAll('{bytes}', '$kBroadcastTitleMaxBytes'),
            ),
            validator: (v) => _titleValidator(v, l10n),
            enabled: !isSubmitting,
            onChanged: (_) => onChanged(),
          ),
          ValueListenableBuilder(
            valueListenable: titleController,
            builder: (_, _, _) => _broadcastCounterLine(
              titleController.text,
              kBroadcastTitleMaxChars,
              kBroadcastTitleMaxBytes,
              context,
              l10n,
            ),
          ),
          const SizedBox(height: 12),
          TextFormField(
            controller: messageController,
            maxLines: 4,
            maxLength: kBroadcastMessageMaxChars,
            decoration: InputDecoration(
              labelText: l10n.getString('adminBroadcastsMessage'),
              helperText: allowEmptyFallback
                  ? '${l10n.getString('adminBroadcastsLimitsHintMessage').replaceAll('{chars}', '$kBroadcastMessageMaxChars').replaceAll('{bytes}', '$kBroadcastMessageMaxBytes')} (empty = English fallback)'
                  : l10n
                        .getString('adminBroadcastsLimitsHintMessage')
                        .replaceAll('{chars}', '$kBroadcastMessageMaxChars')
                        .replaceAll('{bytes}', '$kBroadcastMessageMaxBytes'),
            ),
            validator: (v) => _messageValidator(v, l10n),
            enabled: !isSubmitting,
            onChanged: (_) => onChanged(),
          ),
          ValueListenableBuilder(
            valueListenable: messageController,
            builder: (_, _, _) => _broadcastCounterLine(
              messageController.text,
              kBroadcastMessageMaxChars,
              kBroadcastMessageMaxBytes,
              context,
              l10n,
            ),
          ),
          const SizedBox(height: 12),
          TextFormField(
            controller: actionTextController,
            maxLength: kBroadcastActionTextMaxChars,
            decoration: InputDecoration(
              labelText: l10n.getString('adminBroadcastsActionUrlText'),
              helperText: l10n
                  .getString('adminBroadcastsLimitsHintActionText')
                  .replaceAll('{chars}', '$kBroadcastActionTextMaxChars'),
            ),
            validator: (v) => _validateBroadcastActionText(v, l10n),
            enabled: !isSubmitting,
            onChanged: (_) => onChanged(),
          ),
          ValueListenableBuilder(
            valueListenable: actionTextController,
            builder: (_, _, _) => _broadcastCounterLine(
              actionTextController.text,
              kBroadcastActionTextMaxChars,
              kBroadcastActionTextMaxChars,
              context,
              l10n,
            ),
          ),
          const SizedBox(height: 12),
          Align(
            alignment: Alignment.centerLeft,
            child: Text(
              l10n.getString('adminBroadcastsPreview'),
              style: Theme.of(context).textTheme.titleSmall,
            ),
          ),
          const SizedBox(height: 8),
          Expanded(child: SingleChildScrollView(child: preview)),
        ],
      ),
    );
  }
}

class _TranslationKeyGroup {
  final String key;
  final Map<String, String> values;

  const _TranslationKeyGroup({required this.key, required this.values});

  bool get isMissingAny => values.values.any((v) => v.trim().isEmpty);

  bool isMissingLocale(String locale) => (values[locale] ?? '').trim().isEmpty;
}

enum _BulkDelimiterMode { auto, tab, pipe }

class _TranslationsScreen extends ConsumerStatefulWidget {
  const _TranslationsScreen();

  @override
  ConsumerState<_TranslationsScreen> createState() =>
      _TranslationsScreenState();
}

class _TranslationsScreenState extends ConsumerState<_TranslationsScreen> {
  bool _isLoading = true;
  String? _errorKey;
  List<_TranslationKeyGroup> _groups = const [];

  String _query = '';
  bool _missingAnyOnly = false;
  String _missingLocale = 'all';

  late final Future<Map<String, String>> _uiLanguageDisplayNamesFuture =
      loadUiLanguageDisplayNames();

  // Realtime + poll fallback so translation changes made by another admin
  // (or the bulk-upsert webhook) appear without a refresh button or restart.
  late final AdminRealtimeRefresher _refresher = AdminRealtimeRefresher(
    channelName: 'admin_translations',
    table: 'translations',
    onChange: () {
      if (mounted && !_isLoading) unawaited(_load(force: true));
    },
  );

  @override
  void initState() {
    super.initState();
    unawaited(_load());
    _refresher.start();
  }

  @override
  void dispose() {
    _refresher.dispose();
    super.dispose();
  }

  _TranslationKeyGroup _groupFromMap(Map<String, dynamic> m) {
    final key = (m['key'] ?? '').toString();
    Map<String, String> values;
    if (m.containsKey('values') && m['values'] is Map) {
      values = Map<String, String>.from(m['values'] as Map);
    } else {
      // Legacy format: {key, en, es, he}
      values = {};
      for (final locale in ['en', 'es', 'he']) {
        final val = (m[locale] ?? '').toString();
        if (val.isNotEmpty) values[locale] = val;
      }
    }
    return _TranslationKeyGroup(key: key, values: values);
  }

  Map<String, dynamic> _groupToMap(_TranslationKeyGroup g) {
    return <String, dynamic>{
      'key': g.key,
      'values': Map<String, String>.from(g.values),
    };
  }

  Future<void> _load({bool force = false}) async {
    List<Map<String, dynamic>> decodeListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final cacheKey = 'admin_cache:translations_screen:groups:v2';
    var hadCached = false;

    if (!force) {
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (cached != null) {
        final list = cached.data.map(_groupFromMap).toList(growable: false)
          ..sort((a, b) => a.key.compareTo(b.key));
        setState(() {
          _groups = list;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached) {
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionData(
          'translation_groups',
        );
        if (hiveData.isNotEmpty && mounted) {
          final list = hiveData.map(_groupFromMap).toList(growable: false)
            ..sort((a, b) => a.key.compareTo(b.key));
          setState(() {
            _groups = list;
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _isLoading = !hadCached;
      _errorKey = null;
    });

    try {
      final currentLocale = ref.read(localizationProvider).locale.languageCode;
      final rows = await publicReferenceDataService
          .fetchTranslations(currentLocale)
          .timeout(const Duration(seconds: 15));

      final list =
          rows.entries
              .where((e) => e.key.trim().isNotEmpty)
              .map(
                (e) => _TranslationKeyGroup(
                  key: e.key.trim(),
                  values: {currentLocale: e.value},
                ),
              )
              .toList(growable: false)
            ..sort((a, b) => a.key.compareTo(b.key));

      final cachePayload = list.map(_groupToMap).toList(growable: false);
      await _AdminCache.write<List<Map<String, dynamic>>>(
        cacheKey,
        (v) => v,
        cachePayload,
      );
      try {
        await AdminLocalDbService.shared.saveSectionData(
          'translation_groups',
          cachePayload,
        );
      } catch (_) {}

      if (!mounted) return;
      setState(() {
        _groups = list;
        _isLoading = false;
      });
    } catch (_) {
      if (!mounted) return;
      if (hadCached) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminTranslationsLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _errorKey = 'adminTranslationsOfflineNotCached';
          _isLoading = false;
        });
      } else {
        setState(() {
          _errorKey = 'adminTranslationsLoadFailed';
          _isLoading = false;
        });
      }
    }
  }

  List<_TranslationKeyGroup> _filtered() {
    final q = _query.trim().toLowerCase();

    bool matchesQuery(_TranslationKeyGroup g) {
      if (q.isEmpty) return true;
      if (g.key.toLowerCase().contains(q)) return true;
      for (final v in g.values.values) {
        if (v.toLowerCase().contains(q)) return true;
      }
      return false;
    }

    bool matchesMissing(_TranslationKeyGroup g) {
      if (_missingLocale != 'all') {
        return g.isMissingLocale(_missingLocale);
      }
      if (_missingAnyOnly) return g.isMissingAny;
      return true;
    }

    return _groups
        .where((g) => matchesQuery(g) && matchesMissing(g))
        .toList(growable: false);
  }

  Future<void> _upsertGroup({
    _TranslationKeyGroup? existing,
    Map<String, String>? uiLanguageDisplayNames,
  }) async {
    final l10n = ref.read(localizationProvider);
    final formKey = GlobalKey<FormState>();
    final names = uiLanguageDisplayNames ?? const <String, String>{};

    String uiLanguageName(String code) {
      final normalized = code.trim().toLowerCase();
      return names[normalized] ?? uiLanguageNameFallback(l10n, normalized);
    }

    final keyController = TextEditingController(text: existing?.key ?? '');
    final allCodes = names.keys.toList(growable: false)..sort();
    final valueControllers = <String, TextEditingController>{};
    for (final code in allCodes) {
      valueControllers[code] = TextEditingController(
        text: existing?.values[code] ?? '',
      );
    }

    var isSubmitting = false;

    Future<void> submit(
      BuildContext dialogCtx,
      void Function(void Function()) setDialogState,
    ) async {
      if (!(formKey.currentState?.validate() ?? false)) return;

      if (!dialogCtx.mounted) return;
      setDialogState(() {
        isSubmitting = true;
      });

      try {
        final key = keyController.text.trim();
        final payload = <Map<String, String>>[];
        for (final code in allCodes) {
          final ctl = valueControllers[code]!;
          payload.add({'locale': code, 'key': key, 'value': ctl.text});
        }

        await Supabase.instance.client
            .rpc('admin_bulk_upsert_translations', params: {'p_items': payload})
            .timeout(const Duration(seconds: 20));

        if (!mounted || !dialogCtx.mounted) return;
        Navigator.of(dialogCtx).pop();
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(l10n.getString('adminSaved'))));
        ref
            .read(localizationProvider.notifier)
            .setLocale(l10n.locale.languageCode);
        unawaited(_load(force: true));
      } catch (_) {
        if (!mounted || !dialogCtx.mounted) return;
        setDialogState(() {
          isSubmitting = false;
        });
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text(l10n.getString('adminTranslationsSaveFailed')),
          ),
        );
      }
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          final isEditing = existing != null;
          return AlertDialog(
            title: Text(
              isEditing
                  ? l10n.getString('adminTranslationsEditKey')
                  : l10n.getString('adminTranslationsAddKey'),
            ),
            content: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 720),
              child: Form(
                key: formKey,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      TextFormField(
                        controller: keyController,
                        enabled: !isEditing,
                        decoration: InputDecoration(
                          labelText: l10n.getString('adminTranslationsKey'),
                        ),
                        validator: (v) {
                          if ((v ?? '').trim().isEmpty) {
                            return l10n.getString(
                              'adminTranslationsKeyRequired',
                            );
                          }
                          return null;
                        },
                      ),
                      ...allCodes.map((code) {
                        final ctl = valueControllers[code]!;
                        final isRtl = code == 'he';
                        return Padding(
                          padding: const EdgeInsets.only(bottom: 12),
                          child: TextFormField(
                            controller: ctl,
                            decoration: InputDecoration(
                              labelText: uiLanguageName(code),
                            ),
                            textDirection: isRtl
                                ? TextDirection.rtl
                                : TextDirection.ltr,
                            textAlign: isRtl
                                ? TextAlign.right
                                : TextAlign.start,
                            maxLines: null,
                          ),
                        );
                      }),
                    ],
                  ),
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: isSubmitting ? null : () => Navigator.of(ctx).pop(),
                child: Text(l10n.getString('generalCancel')),
              ),
              FilledButton(
                onPressed: isSubmitting
                    ? null
                    : () => submit(ctx, setDialogState),
                child: isSubmitting
                    ? const SizedBox(
                        width: 20,
                        height: 20,
                        child: CircularProgressIndicator(strokeWidth: 2),
                      )
                    : Text(l10n.getString('generalSave')),
              ),
            ],
          );
        },
      ),
    );
  }

  Future<void> _deleteGroup(_TranslationKeyGroup group) async {
    final l10n = ref.read(localizationProvider);

    final confirmed = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(l10n.getString('adminTranslationsDeleteTitle')),
        content: Text(
          l10n
              .getString('adminTranslationsDeleteBody')
              .replaceAll('{key}', group.key),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.of(ctx).pop(false),
            child: Text(l10n.getString('generalCancel')),
          ),
          FilledButton(
            onPressed: () => Navigator.of(ctx).pop(true),
            child: Text(l10n.getString('generalDelete')),
          ),
        ],
      ),
    );

    if (confirmed != true) return;

    setState(() {
      _groups = _groups
          .where((g) => g.key != group.key)
          .toList(growable: false);
    });

    try {
      await Supabase.instance.client
          .rpc('admin_delete_translation_key', params: {'p_key': group.key})
          .timeout(const Duration(seconds: 20));
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(l10n.getString('adminDeleted'))));
      ref
          .read(localizationProvider.notifier)
          .setLocale(l10n.locale.languageCode);
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      unawaited(_load(force: true));
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(l10n.getString('adminTranslationsDeleteFailed')),
        ),
      );
    }
  }

  Future<void> _bulkImport() async {
    final l10n = ref.read(localizationProvider);

    final textController = TextEditingController();
    var delimiter = _BulkDelimiterMode.auto;
    var allowEmptyValues = false;
    var parsedCount = 0;

    List<Map<String, String>> parseNow() {
      final raw = textController.text;
      final lines = const LineSplitter()
          .convert(raw)
          .map((l) => l.trimRight())
          .where((l) => l.trim().isNotEmpty)
          .toList(growable: false);

      if (lines.isEmpty) return const [];

      String detectDelimiter(String line) {
        if (delimiter == _BulkDelimiterMode.tab) return '\t';
        if (delimiter == _BulkDelimiterMode.pipe) return '|';
        if (line.contains('\t')) return '\t';
        return '|';
      }

      final items = <Map<String, String>>[];
      for (final line in lines) {
        final delim = detectDelimiter(line);
        final parts = line
            .split(delim)
            .map((p) => p.trim())
            .toList(growable: false);
        if (parts.length < 2) continue;

        final key = parts[0];
        if (key.isEmpty) continue;

        String partAt(int i) => i < parts.length ? parts[i] : '';

        final en = partAt(1);
        final es = partAt(2);
        final he = partAt(3);

        if (allowEmptyValues) {
          items.add({'locale': 'en', 'key': key, 'value': en});
          items.add({'locale': 'es', 'key': key, 'value': es});
          items.add({'locale': 'he', 'key': key, 'value': he});
          continue;
        }

        if (en.isNotEmpty) items.add({'locale': 'en', 'key': key, 'value': en});
        if (es.isNotEmpty) items.add({'locale': 'es', 'key': key, 'value': es});
        if (he.isNotEmpty) items.add({'locale': 'he', 'key': key, 'value': he});
      }

      return items;
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          final items = parseNow();
          parsedCount = items.length;

          return AlertDialog(
            title: Text(l10n.getString('adminTranslationsBulkImportTitle')),
            content: ConstrainedBox(
              constraints: const BoxConstraints(maxWidth: 840),
              child: SingleChildScrollView(
                child: Column(
                  mainAxisSize: MainAxisSize.min,
                  crossAxisAlignment: CrossAxisAlignment.start,
                  children: [
                    Text(l10n.getString('adminTranslationsBulkImportFormat')),
                    const SizedBox(height: 12),
                    DropdownMenu<_BulkDelimiterMode>(
                      initialSelection: delimiter,
                      dropdownMenuEntries: [
                        DropdownMenuEntry(
                          value: _BulkDelimiterMode.auto,
                          label: l10n.getString(
                            'adminTranslationsBulkImportDelimiterAuto',
                          ),
                        ),
                        DropdownMenuEntry(
                          value: _BulkDelimiterMode.tab,
                          label: l10n.getString(
                            'adminTranslationsBulkImportDelimiterTab',
                          ),
                        ),
                        DropdownMenuEntry(
                          value: _BulkDelimiterMode.pipe,
                          label: l10n.getString(
                            'adminTranslationsBulkImportDelimiterPipe',
                          ),
                        ),
                      ],
                      onSelected: (value) {
                        if (value == null) return;
                        setDialogState(() {
                          delimiter = value;
                        });
                      },
                      label: Text(
                        l10n.getString('adminTranslationsBulkImportDelimiter'),
                      ),
                    ),
                    const SizedBox(height: 12),
                    CheckboxListTile(
                      value: allowEmptyValues,
                      onChanged: (v) {
                        setDialogState(() {
                          allowEmptyValues = v ?? false;
                        });
                      },
                      title: Text(
                        l10n.getString('adminTranslationsBulkImportAllowEmpty'),
                      ),
                      controlAffinity: ListTileControlAffinity.leading,
                      contentPadding: EdgeInsets.zero,
                    ),
                    const SizedBox(height: 12),
                    TextField(
                      controller: textController,
                      maxLines: 12,
                      onChanged: (_) => setDialogState(() {}),
                      decoration: InputDecoration(
                        hintText: l10n.getString(
                          'adminTranslationsBulkImportHint',
                        ),
                        border: const OutlineInputBorder(),
                      ),
                    ),
                    const SizedBox(height: 12),
                    Text(
                      l10n
                          .getString('adminTranslationsBulkImportParsedCount')
                          .replaceAll('{count}', parsedCount.toString()),
                      style: Theme.of(ctx).textTheme.labelLarge,
                    ),
                  ],
                ),
              ),
            ),
            actions: [
              TextButton(
                onPressed: () => Navigator.of(ctx).pop(),
                child: Text(l10n.getString('generalCancel')),
              ),
              FilledButton(
                onPressed: parsedCount == 0
                    ? null
                    : () async {
                        try {
                          final payload = parseNow();
                          if (payload.isEmpty) {
                            if (!ctx.mounted) return;
                            ScaffoldMessenger.of(ctx).showSnackBar(
                              SnackBar(
                                content: Text(
                                  l10n.getString(
                                    'adminTranslationsBulkImportNothingParsed',
                                  ),
                                ),
                              ),
                            );
                            return;
                          }

                          await Supabase.instance.client
                              .rpc(
                                'admin_bulk_upsert_translations',
                                params: {'p_items': payload},
                              )
                              .timeout(const Duration(seconds: 20));

                          if (!mounted || !ctx.mounted) return;
                          Navigator.of(ctx).pop();
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(
                              content: Text(l10n.getString('adminSaved')),
                            ),
                          );
                          ref
                              .read(localizationProvider.notifier)
                              .setLocale(l10n.locale.languageCode);
                          unawaited(_load(force: true));
                        } catch (_) {
                          if (!mounted) return;
                          ScaffoldMessenger.of(context).showSnackBar(
                            SnackBar(
                              content: Text(
                                l10n.getString('adminTranslationsSaveFailed'),
                              ),
                            ),
                          );
                        }
                      },
                child: Text(
                  l10n.getString('adminTranslationsBulkImportImport'),
                ),
              ),
            ],
          );
        },
      ),
    );
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);
    final filtered = _filtered();

    return FutureBuilder<Map<String, String>>(
      future: _uiLanguageDisplayNamesFuture,
      builder: (context, snapshot) {
        final uiLanguageDisplayNames =
            snapshot.data ?? const <String, String>{};
        String uiLanguageName(String code) {
          final normalized = code.trim().toLowerCase();
          return uiLanguageDisplayNames[normalized] ??
              uiLanguageNameFallback(l10n, normalized);
        }

        return Scaffold(
          body: Padding(
            padding: const EdgeInsets.all(16),
            child: Column(
              crossAxisAlignment: CrossAxisAlignment.start,
              children: [
                Wrap(
                  spacing: 8,
                  runSpacing: 8,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    Text(
                      l10n
                          .getString('adminTranslationsCount')
                          .replaceAll('{count}', filtered.length.toString()),
                      style: Theme.of(context).textTheme.titleMedium,
                    ),
                    OutlinedButton.icon(
                      onPressed: _isLoading ? null : () => _load(force: true),
                      icon: const Icon(Icons.refresh),
                      label: Text(l10n.getString('generalRefresh')),
                    ),
                    OutlinedButton.icon(
                      onPressed: _isLoading
                          ? null
                          : () => _upsertGroup(
                              uiLanguageDisplayNames: uiLanguageDisplayNames,
                            ),
                      icon: const Icon(Icons.add),
                      label: Text(l10n.getString('adminTranslationsAddKey')),
                    ),
                    OutlinedButton.icon(
                      onPressed: _isLoading ? null : _bulkImport,
                      icon: const Icon(Icons.playlist_add),
                      label: Text(
                        l10n.getString('adminTranslationsBulkImport'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                Wrap(
                  spacing: 12,
                  runSpacing: 12,
                  crossAxisAlignment: WrapCrossAlignment.center,
                  children: [
                    ConstrainedBox(
                      constraints: const BoxConstraints(maxWidth: 460),
                      child: TextField(
                        onChanged: (v) {
                          setState(() {
                            _query = v;
                          });
                        },
                        decoration: InputDecoration(
                          hintText: l10n.getString(
                            'adminTranslationsSearchHint',
                          ),
                          prefixIcon: const Icon(Icons.search),
                          border: const OutlineInputBorder(),
                        ),
                      ),
                    ),
                    DropdownMenu<String>(
                      initialSelection: _missingLocale,
                      dropdownMenuEntries: [
                        DropdownMenuEntry(
                          value: 'all',
                          label: l10n.getString('adminTranslationsAll'),
                        ),
                        ...(uiLanguageDisplayNames.keys.toList(
                          growable: false,
                        )..sort()).map(
                          (code) => DropdownMenuEntry(
                            value: code,
                            label: uiLanguageName(code),
                          ),
                        ),
                      ],
                      onSelected: (value) {
                        if (value == null) return;
                        setState(() {
                          _missingLocale = value;
                        });
                      },
                      label: Text(
                        l10n.getString('adminTranslationsMissingLocale'),
                      ),
                    ),
                    FilterChip(
                      selected: _missingAnyOnly,
                      onSelected: (v) {
                        setState(() {
                          _missingAnyOnly = v;
                        });
                      },
                      label: Text(
                        l10n.getString('adminTranslationsMissingAny'),
                      ),
                    ),
                  ],
                ),
                const SizedBox(height: 12),
                Expanded(
                  child: _isLoading
                      ? const Center(child: CircularProgressIndicator())
                      : _errorKey != null
                      ? Center(
                          child: ConstrainedBox(
                            constraints: const BoxConstraints(maxWidth: 520),
                            child: Padding(
                              padding: const EdgeInsets.all(24),
                              child: Column(
                                mainAxisSize: MainAxisSize.min,
                                children: [
                                  Text(
                                    l10n.getString(_errorKey!),
                                    textAlign: TextAlign.center,
                                  ),
                                  const SizedBox(height: 12),
                                  OutlinedButton.icon(
                                    onPressed: () => _load(force: true),
                                    icon: const Icon(Icons.refresh),
                                    label: Text(
                                      l10n.getString('generalRefresh'),
                                    ),
                                  ),
                                ],
                              ),
                            ),
                          ),
                        )
                      : ListView.separated(
                          itemCount: filtered.length,
                          separatorBuilder: (context, index) =>
                              const SizedBox(height: 8),
                          itemBuilder: (context, index) {
                            final g = filtered[index];
                            return Card(
                              child: Padding(
                                padding: const EdgeInsets.all(12),
                                child: Column(
                                  crossAxisAlignment: CrossAxisAlignment.start,
                                  children: [
                                    Row(
                                      children: [
                                        Expanded(
                                          child: Text(
                                            g.key,
                                            style: Theme.of(
                                              context,
                                            ).textTheme.titleSmall,
                                          ),
                                        ),
                                        IconButton(
                                          tooltip: l10n.getString(
                                            'generalEdit',
                                          ),
                                          onPressed: () => _upsertGroup(
                                            existing: g,
                                            uiLanguageDisplayNames:
                                                uiLanguageDisplayNames,
                                          ),
                                          icon: const Icon(Icons.edit),
                                        ),
                                        IconButton(
                                          tooltip: l10n.getString(
                                            'generalDelete',
                                          ),
                                          onPressed: () => _deleteGroup(g),
                                          icon: const Icon(
                                            Icons.delete_outline,
                                          ),
                                        ),
                                      ],
                                    ),
                                    const SizedBox(height: 8),
                                    ...g.values.keys.map(
                                      (locale) => _KeyPreviewRow(
                                        title: uiLanguageName(locale),
                                        value: g.values[locale] ?? '',
                                      ),
                                    ),
                                  ],
                                ),
                              ),
                            );
                          },
                        ),
                ),
              ],
            ),
          ),
        );
      },
    );
  }
}

class _AdminAppConfigEntry {
  final int id;
  final String configKey;
  final dynamic configValue;
  final String configType;
  final String category;
  final String description;
  final bool isUserConfigurable;
  final num? minValue;
  final num? maxValue;
  final dynamic allowedValues;
  final DateTime? createdAt;
  final DateTime? updatedAt;

  const _AdminAppConfigEntry({
    required this.id,
    required this.configKey,
    required this.configValue,
    required this.configType,
    required this.category,
    required this.description,
    required this.isUserConfigurable,
    required this.minValue,
    required this.maxValue,
    required this.allowedValues,
    required this.createdAt,
    required this.updatedAt,
  });

  factory _AdminAppConfigEntry.fromRow(Map<String, dynamic> row) {
    num? tryNum(dynamic v) {
      if (v == null) return null;
      if (v is num) return v;
      return num.tryParse(v.toString());
    }

    DateTime? tryDate(dynamic v) {
      if (v == null) return null;
      if (v is DateTime) return v;
      return DateTime.tryParse(v.toString());
    }

    return _AdminAppConfigEntry(
      id: (row['id'] as int?) ?? 0,
      configKey: (row['config_key'] as String?) ?? '',
      configValue: row['config_value'],
      configType: (row['config_type'] as String?) ?? '',
      category: (row['category'] as String?) ?? '',
      description: (row['description'] as String?) ?? '',
      isUserConfigurable: (row['is_user_configurable'] as bool?) ?? false,
      minValue: tryNum(row['min_value']),
      maxValue: tryNum(row['max_value']),
      allowedValues: row['allowed_values'],
      createdAt: tryDate(row['created_at']),
      updatedAt: tryDate(row['updated_at']),
    );
  }
}

class _AppConfigScreen extends ConsumerStatefulWidget {
  const _AppConfigScreen();

  @override
  ConsumerState<_AppConfigScreen> createState() => _AppConfigScreenState();
}

class _AppConfigScreenState extends ConsumerState<_AppConfigScreen> {
  bool _isLoading = true;
  String? _errorKey;
  List<_AdminAppConfigEntry> _entries = const [];

  String _query = '';
  String? _category;
  bool? _userConfigurable;

  // Realtime + poll fallback so config changes made by another admin (or a
  // webhook) appear without a refresh button or restart.
  late final AdminRealtimeRefresher _refresher = AdminRealtimeRefresher(
    channelName: 'admin_app_config',
    table: 'app_config',
    onChange: () {
      if (mounted && !_isLoading) unawaited(_load(force: true));
    },
  );

  @override
  void initState() {
    super.initState();
    unawaited(_load());
    _refresher.start();
  }

  @override
  void dispose() {
    _refresher.dispose();
    super.dispose();
  }

  Future<void> _load({bool force = false}) async {
    List<Map<String, dynamic>> decodeListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final cacheKey = 'admin_cache:app_config:v1';
    var hadCached = false;

    if (!force) {
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (cached != null) {
        final list =
            cached.data
                .map((r) => _AdminAppConfigEntry.fromRow(r))
                .toList(growable: false)
              ..sort((a, b) => a.configKey.compareTo(b.configKey));
        setState(() {
          _entries = list;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached) {
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionData(
          'app_config_entries',
        );
        if (hiveData.isNotEmpty && mounted) {
          final list =
              hiveData
                  .map((r) => _AdminAppConfigEntry.fromRow(r))
                  .toList(growable: false)
                ..sort((a, b) => a.configKey.compareTo(b.configKey));
          setState(() {
            _entries = list;
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _isLoading = !hadCached;
      _errorKey = null;
    });

    try {
      final rows = await Supabase.instance.client
          .from('app_config')
          .select(
            'id, config_key, config_value, config_type, category, description, is_user_configurable, min_value, max_value, allowed_values, created_at, updated_at',
          );

      final raw = rows
          .map((r) => Map<String, dynamic>.from(r))
          .toList(growable: false);
      await _AdminCache.write<List<Map<String, dynamic>>>(
        cacheKey,
        (v) => v,
        raw,
      );
      try {
        await AdminLocalDbService.shared.saveSectionData(
          'app_config_entries',
          raw,
        );
      } catch (_) {}

      final list = raw
          .map((r) => _AdminAppConfigEntry.fromRow(r))
          .toList(growable: false);
      list.sort((a, b) => a.configKey.compareTo(b.configKey));

      if (!mounted) return;
      setState(() {
        _entries = list;
        _isLoading = false;
      });
    } catch (_) {
      if (!mounted) return;
      if (hadCached) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(content: Text(l10n.getString('adminAppConfigLoadFailed'))),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _errorKey = 'adminAppConfigOfflineNotCached';
          _isLoading = false;
        });
      } else {
        setState(() {
          _errorKey = 'adminAppConfigLoadFailed';
          _isLoading = false;
        });
      }
    }
  }

  dynamic _normalizeJsonValue(dynamic value) {
    if (value == null) return null;
    if (value is num || value is bool || value is String) return value;
    if (value is List) {
      return value.map(_normalizeJsonValue).toList(growable: false);
    }
    if (value is Map) {
      return Map<String, dynamic>.from(
        value,
      ).map((k, v) => MapEntry(k, _normalizeJsonValue(v)));
    }
    return value.toString();
  }

  String _formatJsonValue(dynamic value) {
    final normalized = _normalizeJsonValue(value);
    try {
      final encoded = jsonEncode(normalized);
      return encoded;
    } catch (_) {
      return (value ?? '').toString();
    }
  }

  Future<void> _upsertEntry({_AdminAppConfigEntry? existing}) async {
    if (existing == null) return; // Only allow editing, not adding

    final l10n = ref.read(localizationProvider);

    final formKey = GlobalKey<FormState>();

    final keyController = TextEditingController(text: existing.configKey);
    final valueController = TextEditingController(
      text: _formatJsonValue(existing.configValue),
    );
    final typeController = TextEditingController(text: existing.configType);
    final categoryController = TextEditingController(text: existing.category);
    final descriptionController = TextEditingController(
      text: existing.description,
    );
    final minController = TextEditingController(
      text: existing.minValue == null ? '' : existing.minValue.toString(),
    );
    final maxController = TextEditingController(
      text: existing.maxValue == null ? '' : existing.maxValue.toString(),
    );
    final allowedValuesController = TextEditingController(
      text: existing.allowedValues == null
          ? ''
          : _formatJsonValue(existing.allowedValues),
    );

    var isUserConfigurable = existing.isUserConfigurable;
    var isSubmitting = false;

    // For boolean values, use a toggle
    final isBoolean = existing.configType == 'boolean';
    bool boolValue = existing.configValue is bool
        ? existing.configValue as bool
        : (existing.configValue.toString().toLowerCase() == 'true');

    // Store original values for dirty tracking
    final bool originalBoolValue = boolValue;
    final String originalValueText = valueController.text;

    // Check if any changes have been made
    bool hasChanges() {
      if (isBoolean) {
        return boolValue != originalBoolValue;
      } else {
        return valueController.text != originalValueText;
      }
    }

    // Revert to original values - call with setDialogState from StatefulBuilder
    void revertChanges(void Function(void Function()) setSt) {
      if (isBoolean) {
        setSt(() {
          boolValue = originalBoolValue;
        });
      } else {
        valueController.text = originalValueText;
        setSt(() {});
      }
    }

    dynamic parseJsonFlexible(String raw) {
      final trimmed = raw.trim();
      if (trimmed.isEmpty) return null;
      try {
        return jsonDecode(trimmed);
      } catch (_) {
        return trimmed;
      }
    }

    Future<void> submit(
      BuildContext dialogCtx,
      void Function(void Function()) setDialogState,
    ) async {
      if (!(formKey.currentState?.validate() ?? false)) return;

      if (!dialogCtx.mounted) return;
      setDialogState(() {
        isSubmitting = true;
      });

      try {
        final configKey = keyController.text.trim();

        await Supabase.instance.client
            .rpc(
              'admin_update_app_config',
              params: {
                'p_config_key': configKey,
                'p_config_value': isBoolean
                    ? boolValue
                    : parseJsonFlexible(valueController.text),
                'p_config_type': typeController.text.trim(),
                'p_category': categoryController.text.trim(),
                'p_description': descriptionController.text.trim(),
                'p_is_user_configurable': isUserConfigurable,
                'p_min_value': num.tryParse(minController.text.trim()),
                'p_max_value': num.tryParse(maxController.text.trim()),
                'p_allowed_values': parseJsonFlexible(
                  allowedValuesController.text,
                ),
              },
            )
            .timeout(const Duration(seconds: 20));

        if (!mounted || !dialogCtx.mounted) return;
        Navigator.of(dialogCtx).pop();
        ScaffoldMessenger.of(
          context,
        ).showSnackBar(SnackBar(content: Text(l10n.getString('adminSaved'))));
        unawaited(_load(force: true));
      } catch (e) {
        if (!mounted || !dialogCtx.mounted) return;
        setDialogState(() {
          isSubmitting = false;
        });
        ScaffoldMessenger.of(context).showSnackBar(
          SnackBar(
            content: Text('${l10n.getString('adminAppConfigSaveFailed')}: $e'),
          ),
        );
      }
    }

    await showDialog<void>(
      context: context,
      builder: (ctx) => StatefulBuilder(
        builder: (ctx, setDialogState) {
          return AlertDialog(
            title: Text(l10n.getString('adminAppConfigEdit')),
            content: SizedBox(
              width: 720,
              child: Form(
                key: formKey,
                child: SingleChildScrollView(
                  child: Column(
                    mainAxisSize: MainAxisSize.min,
                    children: [
                      TextFormField(
                        controller: keyController,
                        enabled: false,
                        decoration: InputDecoration(
                          labelText: l10n.getString('adminAppConfigKey'),
                          filled: true,
                          fillColor: Colors.grey.shade200,
                        ),
                      ),
                      const SizedBox(height: 12),
                      if (isBoolean)
                        SwitchListTile(
                          value: boolValue,
                          onChanged: (v) {
                            setDialogState(() {
                              boolValue = v;
                            });
                          },
                          title: Text(
                            '${l10n.getString('adminAppConfigValue')}: ${boolValue ? "On" : "Off"}',
                          ),
                        )
                      else
                        TextFormField(
                          controller: valueController,
                          decoration: InputDecoration(
                            labelText: l10n.getString('adminAppConfigValue'),
                          ),
                          minLines: 3,
                          maxLines: 10,
                          validator: (v) {
                            final raw = (v ?? '').trim();
                            if (raw.isEmpty) {
                              return l10n.getString(
                                'adminAppConfigValueRequired',
                              );
                            }
                            return null;
                          },
                        ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: typeController,
                        enabled: false,
                        decoration: InputDecoration(
                          labelText: l10n.getString('adminAppConfigType'),
                          filled: true,
                          fillColor: Colors.grey.shade200,
                        ),
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: categoryController,
                        enabled: false,
                        decoration: InputDecoration(
                          labelText: l10n.getString('adminAppConfigCategory'),
                          filled: true,
                          fillColor: Colors.grey.shade200,
                        ),
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: descriptionController,
                        enabled: false,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminAppConfigDescription',
                          ),
                          filled: true,
                          fillColor: Colors.grey.shade200,
                        ),
                        minLines: 2,
                        maxLines: 6,
                      ),
                      const SizedBox(height: 12),
                      SwitchListTile(
                        value: isUserConfigurable,
                        onChanged: null, // Disabled
                        title: Text(
                          l10n.getString('adminAppConfigIsUserConfigurable'),
                        ),
                      ),
                      const SizedBox(height: 12),
                      Row(
                        children: [
                          Expanded(
                            child: TextFormField(
                              controller: minController,
                              enabled: false,
                              decoration: InputDecoration(
                                labelText: l10n.getString(
                                  'adminAppConfigMinValue',
                                ),
                                filled: true,
                                fillColor: Colors.grey.shade200,
                              ),
                              keyboardType: TextInputType.number,
                            ),
                          ),
                          const SizedBox(width: 12),
                          Expanded(
                            child: TextFormField(
                              controller: maxController,
                              enabled: false,
                              decoration: InputDecoration(
                                labelText: l10n.getString(
                                  'adminAppConfigMaxValue',
                                ),
                                filled: true,
                                fillColor: Colors.grey.shade200,
                              ),
                              keyboardType: TextInputType.number,
                            ),
                          ),
                        ],
                      ),
                      const SizedBox(height: 12),
                      TextFormField(
                        controller: allowedValuesController,
                        enabled: false,
                        decoration: InputDecoration(
                          labelText: l10n.getString(
                            'adminAppConfigAllowedValues',
                          ),
                          filled: true,
                          fillColor: Colors.grey.shade200,
                        ),
                        minLines: 2,
                        maxLines: 8,
                      ),
                    ],
                  ),
                ),
              ),
            ),
            actions: [
              // Only show Cancel/Save buttons when there are changes
              if (hasChanges()) ...[
                TextButton(
                  onPressed: isSubmitting
                      ? null
                      : () {
                          revertChanges(setDialogState);
                        },
                  child: Text(l10n.getString('generalCancel')),
                ),
                ElevatedButton(
                  onPressed: isSubmitting
                      ? null
                      : () => submit(ctx, setDialogState),
                  child: isSubmitting
                      ? const SizedBox(
                          width: 18,
                          height: 18,
                          child: CircularProgressIndicator(strokeWidth: 2),
                        )
                      : Text(l10n.getString('generalSave')),
                ),
              ] else
                TextButton(
                  onPressed: () => Navigator.of(ctx).pop(),
                  child: Text(l10n.getString('generalClose')),
                ),
            ],
          );
        },
      ),
    );

    _disposeTextControllersLater([
      keyController,
      valueController,
      typeController,
      categoryController,
      descriptionController,
      minController,
      maxController,
      allowedValuesController,
    ]);
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);

    if (_isLoading) {
      return _MessageScaffold(
        title: l10n.getString('adminNavAppConfig'),
        body: l10n.getString('generalLoading'),
        showSpinner: true,
      );
    }

    if (_errorKey != null) {
      return _MessageScaffold(
        title: l10n.getString('adminNavAppConfig'),
        body: l10n.getString(_errorKey!),
      );
    }

    final categories =
        _entries
            .map((e) => e.category)
            .where((c) => c.trim().isNotEmpty)
            .toSet()
            .toList(growable: false)
          ..sort();

    final normalizedQuery = _query.trim().toLowerCase();

    final filtered = _entries
        .where((e) {
          if (_category != null &&
              _category!.isNotEmpty &&
              e.category != _category) {
            return false;
          }
          if (_userConfigurable != null &&
              e.isUserConfigurable != _userConfigurable) {
            return false;
          }
          if (normalizedQuery.isEmpty) return true;
          return e.configKey.toLowerCase().contains(normalizedQuery) ||
              e.category.toLowerCase().contains(normalizedQuery) ||
              e.configType.toLowerCase().contains(normalizedQuery) ||
              e.description.toLowerCase().contains(normalizedQuery);
        })
        .toList(growable: false);

    return Padding(
      padding: const EdgeInsets.all(16),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.stretch,
        children: [
          Wrap(
            spacing: 12,
            runSpacing: 12,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              OutlinedButton.icon(
                onPressed: () => _load(force: true),
                icon: const Icon(Icons.refresh),
                label: Text(l10n.getString('generalRefresh')),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Wrap(
            spacing: 12,
            runSpacing: 12,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: 320,
                child: TextField(
                  onChanged: (v) {
                    setState(() {
                      _query = v;
                    });
                  },
                  decoration: InputDecoration(
                    hintText: l10n.getString('adminAppConfigSearchHint'),
                    prefixIcon: const Icon(Icons.search),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
              SizedBox(
                width: 240,
                child: DropdownMenu<String>(
                  initialSelection: _category ?? '',
                  dropdownMenuEntries: [
                    DropdownMenuEntry<String>(
                      value: '',
                      label: l10n.getString('adminAppConfigAllCategories'),
                    ),
                    ...categories.map(
                      (c) => DropdownMenuEntry<String>(value: c, label: c),
                    ),
                  ],
                  onSelected: (v) {
                    setState(() {
                      _category = (v == null || v.isEmpty) ? null : v;
                    });
                  },
                  label: Text(l10n.getString('adminAppConfigCategory')),
                  inputDecorationTheme: const InputDecorationTheme(
                    border: OutlineInputBorder(),
                  ),
                ),
              ),
              SizedBox(
                width: 240,
                child: DropdownMenu<String>(
                  initialSelection: switch (_userConfigurable) {
                    true => 'true',
                    false => 'false',
                    null => '',
                  },
                  dropdownMenuEntries: [
                    DropdownMenuEntry<String>(
                      value: '',
                      label: l10n.getString(
                        'adminAppConfigAllUserConfigurable',
                      ),
                    ),
                    DropdownMenuEntry<String>(
                      value: 'true',
                      label: l10n.getString('adminSubscriptionsYes'),
                    ),
                    DropdownMenuEntry<String>(
                      value: 'false',
                      label: l10n.getString('adminSubscriptionsNo'),
                    ),
                  ],
                  onSelected: (v) {
                    setState(() {
                      _userConfigurable = switch (v) {
                        'true' => true,
                        'false' => false,
                        _ => null,
                      };
                    });
                  },
                  label: Text(
                    l10n.getString('adminAppConfigIsUserConfigurable'),
                  ),
                  inputDecorationTheme: const InputDecorationTheme(
                    border: OutlineInputBorder(),
                  ),
                ),
              ),
              TextButton(
                onPressed: () {
                  setState(() {
                    _query = '';
                    _category = null;
                    _userConfigurable = null;
                  });
                },
                child: Text(l10n.getString('adminAppConfigClearFilters')),
              ),
              Text(
                l10n
                    .getString('adminAppConfigCount')
                    .replaceAll('{count}', filtered.length.toString()),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Expanded(
            child: ListView.separated(
              itemCount: filtered.length,
              separatorBuilder: (_, index) => const SizedBox(height: 12),
              itemBuilder: (context, index) {
                final e = filtered[index];
                final valuePreview = _formatJsonValue(e.configValue);
                final shortValue = valuePreview.length > 220
                    ? '${valuePreview.substring(0, 220)}…'
                    : valuePreview;

                return Card(
                  child: Padding(
                    padding: const EdgeInsets.all(16),
                    child: Column(
                      crossAxisAlignment: CrossAxisAlignment.stretch,
                      children: [
                        Row(
                          children: [
                            Expanded(
                              child: Text(
                                e.configKey,
                                style: Theme.of(context).textTheme.titleMedium,
                              ),
                            ),
                            TextButton(
                              onPressed: () => _upsertEntry(existing: e),
                              child: Text(l10n.getString('generalEdit')),
                            ),
                          ],
                        ),
                        const SizedBox(height: 8),
                        Wrap(
                          spacing: 8,
                          runSpacing: 6,
                          children: [
                            _MetaChip(
                              label: l10n.getString('adminAppConfigCategory'),
                              value: e.category,
                            ),
                            _MetaChip(
                              label: l10n.getString('adminAppConfigType'),
                              value: e.configType,
                            ),
                            _MetaChip(
                              label: l10n.getString(
                                'adminAppConfigIsUserConfigurable',
                              ),
                              value: e.isUserConfigurable
                                  ? l10n.getString('adminSubscriptionsYes')
                                  : l10n.getString('adminSubscriptionsNo'),
                            ),
                            if (e.minValue != null)
                              _MetaChip(
                                label: l10n.getString('adminAppConfigMinValue'),
                                value: e.minValue.toString(),
                              ),
                            if (e.maxValue != null)
                              _MetaChip(
                                label: l10n.getString('adminAppConfigMaxValue'),
                                value: e.maxValue.toString(),
                              ),
                          ],
                        ),
                        const SizedBox(height: 12),
                        Text(e.description),
                        const SizedBox(height: 12),
                        Text(
                          shortValue,
                          style: Theme.of(context).textTheme.bodyMedium
                              ?.copyWith(fontFamily: 'monospace'),
                        ),
                        const SizedBox(height: 8),
                        if (e.allowedValues != null)
                          _KeyPreviewRow(
                            title: l10n.getString(
                              'adminAppConfigAllowedValuesShort',
                            ),
                            value: _formatJsonValue(e.allowedValues),
                          ),
                      ],
                    ),
                  ),
                );
              },
            ),
          ),
        ],
      ),
    );
  }
}

class _AdminSubscriptionTier {
  final String id;
  final String revenueCatPackageIdentifier;
  final String titleKey;
  final String? subtitleKey;
  final String featuresKey;
  final String? badgeKey;
  final int sortOrder;
  final bool isActive;

  const _AdminSubscriptionTier({
    required this.id,
    required this.revenueCatPackageIdentifier,
    required this.titleKey,
    required this.subtitleKey,
    required this.featuresKey,
    required this.badgeKey,
    required this.sortOrder,
    required this.isActive,
  });

  factory _AdminSubscriptionTier.fromRow(Map<String, dynamic> row) {
    return _AdminSubscriptionTier(
      id: (row['id'] as String?) ?? '',
      revenueCatPackageIdentifier:
          (row['revenue_cat_package_identifier'] as String?) ?? '',
      titleKey: (row['title_key'] as String?) ?? '',
      subtitleKey: row['subtitle_key'] as String?,
      featuresKey: (row['features_key'] as String?) ?? '',
      badgeKey: row['badge_key'] as String?,
      sortOrder: (row['sort_order'] as int?) ?? 0,
      isActive: (row['is_active'] as bool?) ?? true,
    );
  }
}

class _AdminSubscriptionPlan {
  final String id;
  final String tierId;
  final String duration;
  final String priceDisplay;
  final String? savingsText;
  final String? revenueCatPackageIdentifier;
  final int sortOrder;

  const _AdminSubscriptionPlan({
    required this.id,
    required this.tierId,
    required this.duration,
    required this.priceDisplay,
    required this.savingsText,
    required this.revenueCatPackageIdentifier,
    required this.sortOrder,
  });

  factory _AdminSubscriptionPlan.fromRow(Map<String, dynamic> row) {
    return _AdminSubscriptionPlan(
      id: (row['id'] as String?) ?? '',
      tierId: (row['tier_id'] as String?) ?? '',
      duration: (row['duration'] as String?) ?? '',
      priceDisplay: (row['price_display'] as String?) ?? '',
      savingsText: row['savings_text'] as String?,
      revenueCatPackageIdentifier:
          row['revenue_cat_package_identifier'] as String?,
      sortOrder: (row['sort_order'] as int?) ?? 0,
    );
  }
}

class _SubscriptionsScreen extends ConsumerStatefulWidget {
  const _SubscriptionsScreen();

  @override
  ConsumerState<_SubscriptionsScreen> createState() =>
      _SubscriptionsScreenState();
}

class _SubscriptionsScreenState extends ConsumerState<_SubscriptionsScreen> {
  bool _isLoading = true;
  String? _errorKey;
  List<_AdminSubscriptionTier> _tiers = const [];
  Map<String, List<_AdminSubscriptionPlan>> _plansByTierId = const {};

  // Realtime + poll fallback so catalog changes made by another admin (or a
  // webhook flipping is_active) appear without a refresh button or restart.
  late final List<AdminRealtimeRefresher> _refreshers = [
    AdminRealtimeRefresher(
      channelName: 'admin_subscription_tiers',
      table: 'subscription_tiers',
      onChange: () {
        if (mounted && !_isLoading) unawaited(_load(force: true));
      },
    ),
    AdminRealtimeRefresher(
      channelName: 'admin_subscription_plans',
      table: 'subscription_plans',
      onChange: () {
        if (mounted && !_isLoading) unawaited(_load(force: true));
      },
    ),
  ];

  String _durationLabel(LocalizationState l10n, String duration) {
    return switch (duration) {
      'day' => l10n.getString('paywallPeriodDaily'),
      'week' => l10n.getString('paywallPeriodWeekly'),
      'month' => l10n.getString('paywallPeriodMonthly'),
      'year' => l10n.getString('paywallPeriodAnnual'),
      _ => duration,
    };
  }

  @override
  void initState() {
    super.initState();
    unawaited(_load());
    for (final r in _refreshers) {
      r.start();
    }
  }

  @override
  void dispose() {
    for (final r in _refreshers) {
      r.dispose();
    }
    super.dispose();
  }

  Future<void> _load({bool force = false}) async {
    Map<String, dynamic> decodeMap(Object? raw) {
      if (raw is! Map) return const {};
      return Map<String, dynamic>.from(raw);
    }

    List<Map<String, dynamic>> asListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final cacheKey = 'admin_cache:subscriptions:v1';
    var hadCached = false;

    if (!force) {
      final cached = await _AdminCache.read<Map<String, dynamic>>(
        cacheKey,
        decodeMap,
      );
      if (!mounted) return;
      if (cached != null) {
        final tierRows = asListMap(cached.data['tiers']);
        final planRows = asListMap(cached.data['plans']);

        final tiers = tierRows
            .map(_AdminSubscriptionTier.fromRow)
            .where((t) => t.id.isNotEmpty)
            .toList(growable: false);

        final plans = planRows
            .map(_AdminSubscriptionPlan.fromRow)
            .where((p) => p.id.isNotEmpty && p.tierId.isNotEmpty)
            .toList(growable: false);

        final map = <String, List<_AdminSubscriptionPlan>>{};
        for (final p in plans) {
          (map[p.tierId] ??= <_AdminSubscriptionPlan>[]).add(p);
        }

        setState(() {
          _tiers = tiers;
          _plansByTierId = map;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached) {
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionDataMap(
          'subscriptions',
        );
        if (hiveData != null && mounted) {
          final tierRows = asListMap(hiveData['tiers']);
          final planRows = asListMap(hiveData['plans']);
          final tiers = tierRows
              .map(_AdminSubscriptionTier.fromRow)
              .where((t) => t.id.isNotEmpty)
              .toList(growable: false);
          final plans = planRows
              .map(_AdminSubscriptionPlan.fromRow)
              .where((p) => p.id.isNotEmpty && p.tierId.isNotEmpty)
              .toList(growable: false);
          final map = <String, List<_AdminSubscriptionPlan>>{};
          for (final p in plans) {
            (map[p.tierId] ??= <_AdminSubscriptionPlan>[]).add(p);
          }
          setState(() {
            _tiers = tiers;
            _plansByTierId = map;
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    setState(() {
      _isLoading = !hadCached;
      _errorKey = null;
    });

    try {
      final client = Supabase.instance.client;
      final tierRows = await client
          .from('subscription_tiers')
          .select()
          .order('sort_order', ascending: true);
      final planRows = await client
          .from('subscription_plans')
          .select()
          .order('tier_id', ascending: true)
          .order('sort_order', ascending: true);

      final rawTiers = List<Map<String, dynamic>>.from(
        tierRows,
      ).map((r) => Map<String, dynamic>.from(r)).toList(growable: false);
      final rawPlans = List<Map<String, dynamic>>.from(
        planRows,
      ).map((r) => Map<String, dynamic>.from(r)).toList(growable: false);
      await _AdminCache.write<Map<String, dynamic>>(
        cacheKey,
        (v) => v,
        <String, dynamic>{'tiers': rawTiers, 'plans': rawPlans},
      );
      try {
        await AdminLocalDbService.shared.saveSectionDataMap(
          'subscriptions',
          <String, dynamic>{'tiers': rawTiers, 'plans': rawPlans},
        );
      } catch (_) {}

      final tiers = rawTiers
          .map(_AdminSubscriptionTier.fromRow)
          .where((t) => t.id.isNotEmpty)
          .toList(growable: false);

      final plans = rawPlans
          .map(_AdminSubscriptionPlan.fromRow)
          .where((p) => p.id.isNotEmpty && p.tierId.isNotEmpty)
          .toList(growable: false);

      final map = <String, List<_AdminSubscriptionPlan>>{};
      for (final p in plans) {
        (map[p.tierId] ??= <_AdminSubscriptionPlan>[]).add(p);
      }

      if (!mounted) return;
      setState(() {
        _tiers = tiers;
        _plansByTierId = map;
        _isLoading = false;
      });
    } catch (_) {
      if (!mounted) return;
      if (hadCached) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminSubscriptionsLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _errorKey = 'adminSubscriptionsOfflineNotCached';
          _isLoading = false;
        });
      } else {
        setState(() {
          _errorKey = 'adminSubscriptionsLoadFailed';
          _isLoading = false;
        });
      }
    }
  }

