  Future<void> _deletePlan(_AdminSubscriptionPlan plan) async {
    final l10n = ref.read(localizationProvider);
    final shouldDelete = await showDialog<bool>(
      context: context,
      builder: (ctx) => AlertDialog(
        title: Text(l10n.getString('adminSubscriptionsDeletePlanTitle')),
        content: Text(
          l10n
              .getString('adminSubscriptionsDeletePlanBody')
              .replaceAll('{id}', plan.id),
        ),
        actions: [
          TextButton(
            onPressed: () => Navigator.pop(ctx, false),
            child: Text(l10n.getString('generalCancel')),
          ),
          TextButton(
            onPressed: () => Navigator.pop(ctx, true),
            style: TextButton.styleFrom(
              foregroundColor: Theme.of(ctx).colorScheme.error,
            ),
            child: Text(l10n.getString('generalDelete')),
          ),
        ],
      ),
    );
    if (shouldDelete != true) return;

    setState(() {
      final copy = Map<String, List<_AdminSubscriptionPlan>>.from(
        _plansByTierId,
      );
      final existing = copy[plan.tierId];
      if (existing != null) {
        copy[plan.tierId] = existing
            .where((p) => p.id != plan.id)
            .toList(growable: false);
      }
      _plansByTierId = copy;
    });

    try {
      await Supabase.instance.client
          .rpc('admin_delete_subscription_plan', params: {'p_id': plan.id})
          .timeout(const Duration(seconds: 20));
      if (!mounted) return;
      ScaffoldMessenger.of(
        context,
      ).showSnackBar(SnackBar(content: Text(l10n.getString('adminDeleted'))));
      unawaited(_load(force: true));
    } catch (_) {
      if (!mounted) return;
      unawaited(_load(force: true));
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(
          content: Text(l10n.getString('adminSubscriptionsDeleteFailed')),
        ),
      );
    }
  }

  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);

    if (_isLoading) {
      return Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 720),
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                const CircularProgressIndicator(),
                const SizedBox(height: 16),
                Text(l10n.getString('generalLoading')),
              ],
            ),
          ),
        ),
      );
    }

    final errorKey = _errorKey;
    if (errorKey != null) {
      return Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 720),
          child: Padding(
            padding: const EdgeInsets.all(24),
