}

class _VerificationUserRow {
  final String id;
  final String name;
  final String verificationStatus;
  final bool isVerified;
  final String? profilePhotoPath;
  final String? verificationPhotoPath;
  final DateTime? verificationSubmittedAt;
  final DateTime? verificationReviewedAt;
  final String? verificationReviewerId;
  final String? verificationReviewerName;
  final num? verificationSimilarityScore;
  final Object? verificationAiAnalysis;
  final bool verificationAutoRejected;

  const _VerificationUserRow({
    required this.id,
    required this.name,
    required this.verificationStatus,
    required this.isVerified,
    required this.profilePhotoPath,
    required this.verificationPhotoPath,
    required this.verificationSubmittedAt,
    required this.verificationReviewedAt,
    required this.verificationReviewerId,
    required this.verificationReviewerName,
    required this.verificationSimilarityScore,
    required this.verificationAiAnalysis,
    required this.verificationAutoRejected,
  });

  static DateTime? _tryDate(dynamic v) {
    if (v == null) return null;
    if (v is DateTime) return v;
    return DateTime.tryParse(v.toString());
  }

  factory _VerificationUserRow.fromMap(Map<String, dynamic> row) {
    Object? analysis = row['verification_ai_analysis'];
    if (analysis is String) {
      final trimmed = analysis.trim();
      if (trimmed.startsWith('{') || trimmed.startsWith('[')) {
        try {
          analysis = jsonDecode(trimmed);
        } catch (_) {}
      }
    }
    return _VerificationUserRow(
      id: (row['id'] ?? '').toString(),
      name: (row['name'] ?? '').toString(),
      verificationStatus: (row['verification_status'] ?? 'unverified')
          .toString(),
      isVerified: (row['is_verified'] ?? false) is bool
          ? (row['is_verified'] ?? false) as bool
          : (row['is_verified'] ?? false).toString().toLowerCase() == 'true',
      profilePhotoPath: row['profile_photo_path']?.toString(),
      verificationPhotoPath: row['verification_photo_path']?.toString(),
      verificationSubmittedAt: _tryDate(row['verification_submitted_at']),
      verificationReviewedAt: _tryDate(row['verification_reviewed_at']),
      verificationReviewerId: row['verification_reviewer_id']?.toString(),
      verificationReviewerName: row['verification_reviewer_name']?.toString(),
      verificationSimilarityScore: row['verification_similarity_score'] as num?,
      verificationAiAnalysis: analysis,
      verificationAutoRejected:
          (row['verification_auto_rejected'] ?? false) is bool
          ? (row['verification_auto_rejected'] ?? false) as bool
          : (row['verification_auto_rejected'] ?? false)
                    .toString()
                    .toLowerCase() ==
                'true',
    );
  }
}

class _UserVerificationScreen extends ConsumerStatefulWidget {
  const _UserVerificationScreen();

  @override
  ConsumerState<_UserVerificationScreen> createState() =>
      _UserVerificationScreenState();
}

class _UserVerificationScreenState
    extends ConsumerState<_UserVerificationScreen>
    with WidgetsBindingObserver {
  bool _isLoading = true;
  String? _errorKey;
  List<_VerificationUserRow> _rows = const [];
  int _loadGeneration = 0;

  String _query = '';
  String _status = 'pending';

  RealtimeChannel? _realtimeChannel;
  Timer? _realtimeDebounce;
  Timer? _pollTimer;
  int _realtimeRetries = 0;
  StreamSubscription<bool>? _availabilitySub;
  bool _isAppForeground = true;

  @override
  void initState() {
    super.initState();
    WidgetsBinding.instance.addObserver(this);
    final cur = WidgetsBinding.instance.lifecycleState;
    _isAppForeground =
        cur == null ||
        (cur != AppLifecycleState.paused &&
            cur != AppLifecycleState.hidden &&
            cur != AppLifecycleState.detached);
    _setupRealtime();
    _availabilitySub = adminOfflineCacheManager.availabilityStream.listen((
      available,
    ) {
      if (!mounted) return;
      if (!_isAppForeground) return;
      if (available) {
        unawaited(_load(force: true, silent: true));
      }
    });
    // Poll fallback for when realtime delivery is unavailable: the queue
    // still self-updates in the foreground, just delayed. Realtime makes it
    // instant when it works.
    _pollTimer = Timer.periodic(const Duration(seconds: 30), (_) {
      if (mounted && _isAppForeground && !_isLoading) {
        unawaited(_load(force: true, silent: true));
      }
    });
    unawaited(_load());
  }

  @override
  void dispose() {
    WidgetsBinding.instance.removeObserver(this);
    _realtimeDebounce?.cancel();
    _pollTimer?.cancel();
    _availabilitySub?.cancel();
    final ch = _realtimeChannel;
    if (ch != null) {
      Supabase.instance.client.removeChannel(ch);
    }
    super.dispose();
  }

  @override
  void didChangeAppLifecycleState(AppLifecycleState state) {
    if (state == AppLifecycleState.resumed) {
      if (!_isAppForeground) {
        _isAppForeground = true;
        _scheduleRealtimeReload();
      }
    } else if (state == AppLifecycleState.inactive ||
        state == AppLifecycleState.paused ||
        state == AppLifecycleState.hidden ||
        state == AppLifecycleState.detached) {
      _isAppForeground = false;
      _realtimeDebounce?.cancel();
    }
  }

  void _setupRealtime() {
    try {
      final channel = Supabase.instance.client.channel(
        'admin-user-verification',
      );

      void onUserChange(PostgresChangePayload payload) {
        if (!_isAppForeground) return;
        final newRecord = payload.newRecord;
        final oldRecord = payload.oldRecord;

        final userId = (newRecord['id'] ?? oldRecord['id'])?.toString();
        final newStatus = newRecord['verification_status']?.toString();

        if (userId != null && newStatus != null && mounted) {
          final existingIdx = _rows.indexWhere((r) => r.id == userId);
          if (existingIdx >= 0) {
            if (_status != 'all' && newStatus != _status) {
              setState(() {
                _rows = _rows
                    .where((r) => r.id != userId)
                    .toList(growable: false);
              });
            } else {
              final oldRow = _rows[existingIdx];
              final updatedRow = _VerificationUserRow(
                id: oldRow.id,
                name: (newRecord['name'] ?? oldRow.name).toString(),
                verificationStatus: newStatus,
                isVerified:
                    (newRecord['is_verified'] ?? oldRow.isVerified) is bool
                    ? newRecord['is_verified'] as bool
                    : (newRecord['is_verified'] ?? oldRow.isVerified)
                              .toString()
                              .toLowerCase() ==
                          'true',
                profilePhotoPath: oldRow.profilePhotoPath,
                verificationPhotoPath:
                    newRecord['verification_photo_path']?.toString() ??
                    oldRow.verificationPhotoPath,
                verificationSubmittedAt:
                    _VerificationUserRow._tryDate(
                      newRecord['verification_submitted_at'],
                    ) ??
                    oldRow.verificationSubmittedAt,
                verificationReviewedAt:
                    _VerificationUserRow._tryDate(
                      newRecord['verification_reviewed_at'],
                    ) ??
                    oldRow.verificationReviewedAt,
                verificationReviewerId:
                    newRecord['verification_reviewer_id']?.toString() ??
                    oldRow.verificationReviewerId,
                verificationReviewerName: oldRow.verificationReviewerName,
                verificationSimilarityScore:
                    (newRecord['verification_similarity_score'] as num?) ??
                    oldRow.verificationSimilarityScore,
                verificationAiAnalysis:
                    newRecord['verification_ai_analysis'] ??
                    oldRow.verificationAiAnalysis,
                verificationAutoRejected:
                    (newRecord['verification_auto_rejected'] ??
                            oldRow.verificationAutoRejected)
                        is bool
                    ? (newRecord['verification_auto_rejected'] ??
                              oldRow.verificationAutoRejected)
                          as bool
                    : (newRecord['verification_auto_rejected'] ??
                                  oldRow.verificationAutoRejected)
                              .toString()
                              .toLowerCase() ==
                          'true',
              );
              setState(() {
                final copy = List<_VerificationUserRow>.from(_rows);
                copy[existingIdx] = updatedRow;
                _rows = copy;
              });
            }
          }
        }

        _scheduleRealtimeReload();
      }

      void onDashboardTick(PostgresChangePayload payload) {
        if (!_isAppForeground) return;
        final lastTable =
            (payload.newRecord['last_table'] ?? payload.oldRecord['last_table'])
                ?.toString();
        if (lastTable == null || lastTable.isEmpty || lastTable == 'users') {
          _scheduleRealtimeReload();
        }
      }

      channel.onPostgresChanges(
        event: PostgresChangeEvent.all,
        schema: 'public',
        table: 'users',
        callback: onUserChange,
      );

      channel.onPostgresChanges(
        event: PostgresChangeEvent.all,
        schema: 'public',
        table: 'admin_dashboard_tick',
        callback: onDashboardTick,
      );

      channel.subscribe((status, error) {
        // Bounded re-subscribe when the channel dies without a clean close;
        // the 30s poll covers us in the meantime and afterwards.
        if (mounted &&
            _realtimeRetries < 3 &&
            (error != null ||
                status == RealtimeSubscribeStatus.channelError ||
                status == RealtimeSubscribeStatus.timedOut)) {
          _realtimeRetries++;
          Future.delayed(const Duration(seconds: 3), () {
            if (!mounted) return;
            final old = _realtimeChannel;
            if (old != null) {
              Supabase.instance.client.removeChannel(old);
            }
            _realtimeChannel = null;
            _setupRealtime();
          });
        }
      });
      _realtimeChannel = channel;
    } catch (_) {
      Future.delayed(const Duration(seconds: 5), () {
        if (!mounted) return;
        _setupRealtime();
      });
    }
  }

  void _scheduleRealtimeReload() {
    if (!mounted || !_isAppForeground) return;
    _realtimeDebounce?.cancel();
    _realtimeDebounce = Timer(const Duration(milliseconds: 600), () {
      if (mounted && _isAppForeground) {
        unawaited(_load(force: true, silent: true));
      }
    });
  }

  Future<void> _load({bool force = false, bool silent = false}) async {
    List<Map<String, dynamic>> decodeListMap(Object? raw) {
      if (raw is! List) return const [];
      final out = <Map<String, dynamic>>[];
      for (final item in raw) {
        if (item is Map) out.add(Map<String, dynamic>.from(item));
      }
      return out;
    }

    final generation = ++_loadGeneration;
    if (!mounted) return;
    final queryTrimmed = _query.trim();
    final queryKey = queryTrimmed.isEmpty
        ? 'none'
        : base64UrlEncode(utf8.encode(queryTrimmed));
    final cacheKey = 'admin_cache:verification:v1:$_status:$queryKey';
    var hadCached = false;

    if (!force) {
      final cached = await _AdminCache.read<List<Map<String, dynamic>>>(
        cacheKey,
        decodeListMap,
      );
      if (!mounted) return;
      if (generation != _loadGeneration) return;
      if (cached != null) {
        final mapped = cached.data
            .map((e) => _VerificationUserRow.fromMap(e))
            .toList(growable: false);
        setState(() {
          _rows = mapped;
          _isLoading = false;
          _errorKey = null;
        });
        hadCached = true;
        if (cached.isFresh) return;
      }
    }

    if (!hadCached && !silent) {
      final hiveKey = 'verification_users:$_status:$queryKey';
      try {
        final hiveData = await AdminLocalDbService.shared.loadSectionData(
          hiveKey,
        );
        if (hiveData.isNotEmpty && mounted) {
          if (generation != _loadGeneration) return;
          final mapped = hiveData
              .map((e) => _VerificationUserRow.fromMap(e))
              .toList(growable: false);
          setState(() {
            _rows = mapped;
            _isLoading = false;
            _errorKey = null;
          });
          hadCached = true;
        }
      } catch (_) {}
    }

    if (!mounted) return;
    if (generation != _loadGeneration) return;
    if (!silent || _rows.isEmpty) {
      setState(() {
        _isLoading = !hadCached && _rows.isEmpty;
        _errorKey = null;
      });
    }

    try {
      final result = await Supabase.instance.client
          .rpc(
            'admin_list_verification_users',
            params: {
              'p_status': _status == 'all' ? null : _status,
              'p_query': queryTrimmed.isEmpty ? null : queryTrimmed,
              'p_limit': 200,
              'p_offset': 0,
            },
          )
          .timeout(const Duration(seconds: 12));

      final list = (result as List<dynamic>).cast<dynamic>();
      final raw = list
          .map((e) => Map<String, dynamic>.from(e as Map))
          .toList(growable: false);
      await _AdminCache.write<List<Map<String, dynamic>>>(
        cacheKey,
        (v) => v,
        raw,
      );
      try {
        final hiveKey = 'verification_users:$_status:$queryKey';
        await AdminLocalDbService.shared.saveSectionData(hiveKey, raw);
      } catch (_) {}
      final mapped = raw
          .map((e) => _VerificationUserRow.fromMap(e))
          .toList(growable: false);

      if (!mounted) return;
      if (generation != _loadGeneration) return;
      setState(() {
        _rows = mapped;
        _errorKey = null;
      });
    } catch (_) {
      if (!mounted) return;
      if (generation != _loadGeneration) return;
      if (silent && _rows.isNotEmpty) {
        return;
      }
      if (hadCached || _rows.isNotEmpty) {
        if (!adminOfflineCacheManager.shouldUseCachedData()) {
          final l10n = ref.read(localizationProvider);
          ScaffoldMessenger.of(context).showSnackBar(
            SnackBar(
              content: Text(l10n.getString('adminVerificationLoadFailed')),
            ),
          );
        }
      } else if (adminOfflineCacheManager.shouldUseCachedData()) {
        setState(() {
          _errorKey = 'adminVerificationOfflineNotCached';
        });
      } else {
        setState(() {
          _errorKey = 'adminVerificationLoadFailed';
        });
      }
    } finally {
      if (mounted && generation == _loadGeneration) {
        setState(() {
          _isLoading = false;
        });
      }
    }
  }

  String _statusLabel(LocalizationState l10n, String status) {
    return switch (status) {
      'pending' => l10n.getString('adminStatusPending'),
      'approved' => l10n.getString('adminStatusApproved'),
      'rejected' => l10n.getString('adminStatusRejected'),
      'analyzing' => l10n.getString('adminStatusAnalyzing'),
      'unverified' => l10n.getString('adminStatusUnverified'),
      _ => status,
    };
  }

  String _normalizeStorageObjectPath(String bucket, String objectPath) {
    var clean = objectPath.trim();
    if (clean.startsWith('http://') || clean.startsWith('https://')) {
      try {
        final uri = Uri.parse(clean);
        final segments = uri.pathSegments;
        final idx = segments.indexOf(bucket);
        if (idx >= 0 && idx < segments.length - 1) {
          return segments.sublist(idx + 1).join('/');
        }
      } catch (_) {}
    }
    if (clean.startsWith('/')) clean = clean.substring(1);
    final prefix = '$bucket/';
    if (clean.startsWith(prefix)) clean = clean.substring(prefix.length);
    return clean;
  }

  Future<String?> _getSignedUrlFor(String bucket, String objectPath) async {
    final clean = _normalizeStorageObjectPath(bucket, objectPath);
    if (clean.isEmpty) return null;
    final signedUrlCacheKey = 'admin_cache:signed_url:v1:$bucket:$clean';
    final cached = await _AdminCache.read<String>(
      signedUrlCacheKey,
      (raw) => (raw ?? '').toString(),
    );
    final cachedUrl = cached?.data.trim() ?? '';
    if (cachedUrl.isNotEmpty && (cached?.isFresh ?? false)) {
      return cachedUrl;
    }

    try {
      final dynamic resp = await Supabase.instance.client.storage
          .from(bucket)
          .createSignedUrl(clean, 600);

      if (resp == null) return null;
      String? resolveRelativeUrl(String url) {
        final trimmed = url.trim();
        if (trimmed.isEmpty) return null;
        if (trimmed.startsWith('http://') || trimmed.startsWith('https://')) {
          return trimmed;
        }
        if (!trimmed.startsWith('/')) return trimmed;
        try {
          final dynamic c = Supabase.instance.client;
          final base = (c.supabaseUrl as String?)?.trim();
          if (base == null || base.isEmpty) return trimmed;
          return Uri.parse(base).resolve(trimmed).toString();
        } catch (_) {
          return trimmed;
        }
      }

      bool looksSigned(String url) {
        try {
          final uri = Uri.parse(url);
          if (uri.queryParameters.containsKey('token')) return true;
          if (uri.query.isNotEmpty &&
              (uri.query.contains('X-Amz-') ||
                  uri.query.contains('X-Amz-Signature'))) {
            return true;
          }
        } catch (_) {}
        return false;
      }

      String attachTokenIfNeeded(String url, String? token) {
        if (token == null || token.trim().isEmpty) return url;
        if (url.contains('token=')) return url;
        final sep = url.contains('?') ? '&' : '?';
        return '$url${sep}token=${Uri.encodeQueryComponent(token.trim())}';
      }

      if (resp is String) {
        final resolved = resolveRelativeUrl(resp);
        if (resolved == null) return null;
        final out = looksSigned(resolved) ? resolved : null;
        if (out != null) {
          await _AdminCache.write<String>(signedUrlCacheKey, (v) => v, out);
        }
        return out ?? (cachedUrl.isNotEmpty ? cachedUrl : null);
      }
      if (resp is Map) {
        final token = resp['token']?.toString();
        final rawUrl =
            (resp['signedUrl'] ??
                    resp['signed_url'] ??
                    resp['signedurl'] ??
                    resp['signedURL'] ??
                    resp['signed_url'])
                ?.toString();
        if (rawUrl != null && rawUrl.trim().isNotEmpty) {
          final resolved = resolveRelativeUrl(rawUrl);
          if (resolved == null) return null;
          final withToken = attachTokenIfNeeded(resolved, token);
          final out = looksSigned(withToken) ? withToken : null;
          if (out != null) {
            await _AdminCache.write<String>(signedUrlCacheKey, (v) => v, out);
          }
          return out ?? (cachedUrl.isNotEmpty ? cachedUrl : null);
        }
        final data = resp['data'];
        if (data is Map) {
          final nestedToken = data['token']?.toString() ?? token;
          final nestedUrl =
              (data['signedUrl'] ??
                      data['signed_url'] ??
                      data['signedurl'] ??
                      data['signedURL'] ??
                      data['signed_url'])
                  ?.toString();
          if (nestedUrl != null && nestedUrl.trim().isNotEmpty) {
            final resolved = resolveRelativeUrl(nestedUrl);
            if (resolved == null) return null;
            final withToken = attachTokenIfNeeded(resolved, nestedToken);
            final out = looksSigned(withToken) ? withToken : null;
            if (out != null) {
              await _AdminCache.write<String>(signedUrlCacheKey, (v) => v, out);
            }
            return out ?? (cachedUrl.isNotEmpty ? cachedUrl : null);
          }
        }
      }
      try {
        final maybe =
            (resp as dynamic).signedUrl ?? (resp as dynamic).data?.signedUrl;
        if (maybe is String && maybe.trim().isNotEmpty) {
          final resolved = resolveRelativeUrl(maybe);
          if (resolved == null) return null;
          final out = looksSigned(resolved) ? resolved : null;
          if (out != null) {
            await _AdminCache.write<String>(signedUrlCacheKey, (v) => v, out);
          }
          return out ?? (cachedUrl.isNotEmpty ? cachedUrl : null);
        }
      } catch (_) {}
      return cachedUrl.isNotEmpty ? cachedUrl : null;
    } catch (_) {
      return cachedUrl.isNotEmpty ? cachedUrl : null;
    }
  }

  Future<void> _showPhotoViewer({
    required LocalizationState l10n,
    required String titleKey,
    required String bucket,
    required String path,
  }) async {
    final clean = _normalizeStorageObjectPath(bucket, path);
    if (clean.isEmpty) return;

    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (ctx) {
        return Dialog.fullscreen(
          child: Column(
            children: [
              Material(
                color: Theme.of(ctx).colorScheme.surface,
                child: SafeArea(
                  bottom: false,
                  child: Row(
                    children: [
                      const SizedBox(width: 12),
                      Expanded(
                        child: Text(
                          l10n.getString(titleKey),
                          style: Theme.of(ctx).textTheme.titleMedium,
                        ),
                      ),
                      IconButton(
                        onPressed: () => Navigator.of(ctx).pop(),
                        icon: const Icon(Icons.close),
                      ),
                      const SizedBox(width: 8),
                    ],
                  ),
                ),
              ),
              Expanded(
                child: ColoredBox(
                  color: Colors.black,
                  child: Center(
                    child: FutureBuilder<String?>(
                      future: _getSignedUrlFor(bucket, clean),
                      builder: (ctx, snap) {
                        if (snap.connectionState != ConnectionState.done) {
                          return Text(
                            l10n.getString('generalLoading'),
                            style: const TextStyle(color: Colors.white),
                          );
                        }
                        final url = snap.data;
                        if (url == null || url.trim().isEmpty) {
                          return Text(
                            l10n.getString('adminVerificationPhotoLoadFailed'),
                            style: const TextStyle(color: Colors.white),
                          );
                        }
                        final cacheKey = 'admin_image_cache:v1:$bucket:$clean';
                        return InteractiveViewer(
                          child: CachedNetworkImage(
                            imageUrl: url,
                            cacheKey: cacheKey,
                            useOldImageOnUrlChange: true,
                            fit: BoxFit.contain,
                            placeholder: (context, url) => Text(
                              l10n.getString('generalLoading'),
                              style: const TextStyle(color: Colors.white),
                            ),
                            errorWidget: (context, url, error) => Text(
                              l10n.getString(
                                'adminVerificationPhotoLoadFailed',
                              ),
                              style: const TextStyle(color: Colors.white),
                            ),
                          ),
                        );
                      },
                    ),
                  ),
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _photoSection({
    required LocalizationState l10n,
    required String titleKey,
    required String emptyKey,
    required String bucket,
    required String? path,
    double? maxHeight,
  }) {
    final clean = (path ?? '').trim();
    if (clean.isEmpty) {
      return Center(child: Text(l10n.getString(emptyKey)));
    }

    final normalized = _normalizeStorageObjectPath(bucket, clean);
    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        Text(
          l10n.getString(titleKey),
          style: Theme.of(context).textTheme.titleSmall,
        ),
        const SizedBox(height: 8),
        ConstrainedBox(
          constraints: BoxConstraints(
            maxHeight: maxHeight ?? 520,
            minHeight: 160,
          ),
          child: ClipRRect(
            borderRadius: BorderRadius.circular(12),
            child: DecoratedBox(
              decoration: BoxDecoration(
                border: Border.all(color: Theme.of(context).dividerColor),
              ),
              child: FutureBuilder<String?>(
                future: _getSignedUrlFor(bucket, normalized),
                builder: (ctx, snap) {
                  if (snap.connectionState != ConnectionState.done) {
                    return Center(
                      child: Text(l10n.getString('generalLoading')),
                    );
                  }
                  final url = snap.data;
                  if (url == null || url.trim().isEmpty) {
                    return Center(
                      child: Text(
                        l10n.getString('adminVerificationPhotoLoadFailed'),
                      ),
                    );
                  }
                  final cacheKey = 'admin_image_cache:v1:$bucket:$normalized';
                  return MouseRegion(
                    cursor: SystemMouseCursors.click,
                    child: InkWell(
                      onTap: () => _showPhotoViewer(
                        l10n: l10n,
                        titleKey: titleKey,
                        bucket: bucket,
                        path: normalized,
                      ),
                      child: CachedNetworkImage(
                        imageUrl: url,
                        cacheKey: cacheKey,
                        useOldImageOnUrlChange: true,
                        fit: BoxFit.contain,
                        placeholder: (context, url) => Center(
                          child: Text(l10n.getString('generalLoading')),
                        ),
                        errorWidget: (context, url, error) => Center(
                          child: Text(
                            l10n.getString('adminVerificationPhotoLoadFailed'),
                          ),
                        ),
                      ),
                    ),
                  );
                },
              ),
            ),
          ),
        ),
      ],
    );
  }

  Map<String, dynamic>? _coerceAnalysisMap(Object? raw) {
    if (raw == null) return null;
    if (raw is Map) return Map<String, dynamic>.from(raw);
    if (raw is String) {
      final trimmed = raw.trim();
      if (trimmed.isEmpty) return null;
      try {
        final decoded = jsonDecode(trimmed);
        if (decoded is Map) return Map<String, dynamic>.from(decoded);
      } catch (_) {}
    }
    return null;
  }

  String? _firstStringValue(Map<String, dynamic> m, List<String> keys) {
    for (final k in keys) {
      final v = m[k];
      if (v == null) continue;
      final s = v.toString().trim();
      if (s.isNotEmpty) return s;
    }
    return null;
  }

  num? _firstNumValue(Map<String, dynamic> m, List<String> keys) {
    for (final k in keys) {
      final v = m[k];
      if (v == null) continue;
      if (v is num) return v;
      final parsed = num.tryParse(v.toString());
      if (parsed != null) return parsed;
    }
    return null;
  }

  bool? _firstBoolValue(Map<String, dynamic> m, List<String> keys) {
    for (final k in keys) {
      final v = m[k];
      if (v == null) continue;
      if (v is bool) return v;
      final s = v.toString().trim().toLowerCase();
      if (s == 'true') return true;
      if (s == 'false') return false;
    }
    return null;
  }

  List<String> _stringListValue(Map<String, dynamic> m, List<String> keys) {
    for (final k in keys) {
      final v = m[k];
      if (v == null) continue;
      if (v is List) {
        final list = v
            .map((e) => e?.toString().trim() ?? '')
            .where((s) => s.isNotEmpty)
            .toList(growable: false);
        if (list.isNotEmpty) return list;
      }
      final s = v.toString().trim();
      if (s.isNotEmpty) return [s];
    }
    return const [];
  }

  String _formatConfidence(num value) {
    if (value >= 0 && value <= 1) {
      return '${(value * 100).toStringAsFixed(1)}%';
    }
    if (value > 1 && value <= 100) {
      return '${value.toStringAsFixed(1)}%';
    }
    return value.toStringAsFixed(2);
  }

  String _titleCaseWords(String input) {
    final parts = input
        .trim()
        .split(RegExp(r'\s+'))
        .where((p) => p.trim().isNotEmpty)
        .toList(growable: false);
    if (parts.isEmpty) return '';
    return parts
        .map((w) {
          final lower = w.toLowerCase();
          if (lower == 'ai') return 'AI';
          if (lower.isEmpty) return '';
          return '${lower[0].toUpperCase()}${lower.substring(1)}';
        })
        .join(' ');
  }

  String _humanizeKey(String key) {
    var s = key.trim();
    if (s.isEmpty) return s;
    s = s.replaceAll(RegExp(r'[_\-]+'), ' ');
    s = s.replaceAllMapped(
      RegExp(r'([a-z0-9])([A-Z])'),
      (m) => '${m.group(1)} ${m.group(2)}',
    );
    s = s.replaceAllMapped(
      RegExp(r'([A-Z]+)([A-Z][a-z])'),
      (m) => '${m.group(1)} ${m.group(2)}',
    );
    s = s.replaceAll(RegExp(r'\s+'), ' ').trim();
    return _titleCaseWords(s);
  }

  String _aiLabelForKey(LocalizationState l10n, String key) {
    final trimmed = key.trim();
    if (trimmed.isEmpty) return l10n.getString('adminUnknown');
    if (trimmed.startsWith('#')) return trimmed;

    final normalized = trimmed.replaceAll('-', '_');
    return switch (normalized) {
      'authenticityAudit' || 'authenticity_audit' => l10n.getString(
        'adminVerificationAiFieldAuthenticityAudit',
      ),
      'authentic' => l10n.getString('adminVerificationAiFieldAuthentic'),
      'comparedAt' ||
      'compared_at' => l10n.getString('adminVerificationAiFieldComparedAt'),
      'confidence' => l10n.getString('adminVerificationAiFieldConfidence'),
      'gestureCode' ||
      'gesture_code' => l10n.getString('adminVerificationAiFieldGesture'),
      'gesturePrompt' || 'gesture_prompt' => l10n.getString(
        'adminVerificationAiFieldGestureRequirement',
      ),
      'isMatch' ||
      'is_match' => l10n.getString('adminVerificationAiFieldMatch'),
      'note' => l10n.getString('adminVerificationAiFieldNote'),
      'reasoning' => l10n.getString('adminVerificationAiFieldReasoning'),
      'service' => l10n.getString('adminVerificationAiFieldService'),
      'similarity' => l10n.getString('adminVerificationAiFieldSimilarity'),
      _ => _humanizeKey(trimmed),
    };
  }

  String _formatAiEnum(String value) {
    final raw = value.trim();
    if (raw.isEmpty) return raw;

    final upper = raw.toUpperCase();
    if (upper.contains('_')) {
      final words = upper
          .split('_')
          .where((w) => w.trim().isNotEmpty)
          .toList(growable: false);
      if (words.length >= 2 &&
          words.last == 'HAND' &&
          (words[words.length - 2] == 'RIGHT' ||
              words[words.length - 2] == 'LEFT')) {
        final dir = words[words.length - 2].toLowerCase();
        final prefix = words
            .sublist(0, words.length - 2)
            .join(' ')
            .toLowerCase();
        return '${_titleCaseWords(prefix)} ($dir hand)';
      }
      final lower = words.join(' ').toLowerCase();
      return _titleCaseWords(lower);
    }

    if (raw.contains('_')) {
      return _titleCaseWords(raw.replaceAll('_', ' ').toLowerCase());
    }
    return raw;
  }

  String _formatAiValue(LocalizationState l10n, String key, Object? value) {
    if (value == null) return '';

    if (value is bool) {
      return value ? l10n.getString('adminYes') : l10n.getString('adminNo');
    }

    final normalizedKey = key.trim().replaceAll('-', '_');
    if (value is num) {
      final asInt = value % 1 == 0
          ? value.toInt().toString()
          : value.toStringAsFixed(2);
      if (normalizedKey == 'confidence') return asInt;
      if (normalizedKey == 'similarity') return asInt;
      return asInt;
    }

    final s = value.toString().trim();
    if (s.isEmpty) return '';

    if (normalizedKey == 'comparedAt' || normalizedKey == 'compared_at') {
      final dt = DateTime.tryParse(s);
      if (dt != null) return _formatAdminDateTime(l10n, dt);
    }

    if (normalizedKey == 'gestureCode' || normalizedKey == 'gesture_code') {
      return _formatAiEnum(s);
    }
    if (normalizedKey == 'service') {
      return _formatAiEnum(s);
    }

    if (normalizedKey == 'confidence') {
      final parsed = num.tryParse(s);
      if (parsed != null) {
        return parsed % 1 == 0 ? parsed.toInt().toString() : parsed.toString();
      }
    }
    if (normalizedKey == 'similarity') {
      final parsed = num.tryParse(s);
      if (parsed != null) {
        return parsed % 1 == 0 ? parsed.toInt().toString() : parsed.toString();
      }
    }

    return s;
  }

  Widget _aiFieldRow(LocalizationState l10n, String rawKey, Object? rawValue) {
    final label = _aiLabelForKey(l10n, rawKey);
    final value = _formatAiValue(l10n, rawKey, rawValue).trim();
    if (value.isEmpty) return const SizedBox.shrink();
    return LayoutBuilder(
      builder: (context, constraints) {
        final labelWidth = (constraints.maxWidth * 0.28).clamp(140.0, 240.0);
        return Padding(
          padding: const EdgeInsets.symmetric(vertical: 8),
          child: Row(
            crossAxisAlignment: CrossAxisAlignment.start,
            children: [
              SizedBox(
                width: labelWidth,
                child: Text(
                  label,
                  style: Theme.of(context).textTheme.labelMedium,
                ),
              ),
              const SizedBox(width: 12),
              Expanded(
                child: SelectableText(
                  value,
                  textAlign: isRtlText(value)
                      ? TextAlign.right
                      : TextAlign.left,
                  textDirection: isRtlText(value)
                      ? TextDirection.rtl
                      : TextDirection.ltr,
                ),
              ),
            ],
          ),
        );
      },
    );
  }

  Widget _analysisTreeNode(
    LocalizationState l10n,
    String label,
    Object? value,
    int depth,
  ) {
    final normalizedLabel = _aiLabelForKey(l10n, label);

    if (depth >= 6) {
      return _aiFieldRow(l10n, label, value);
    }

    if (value is Map) {
      final map = Map<String, dynamic>.from(value);
      final keys = map.keys.map((k) => k.toString()).toList(growable: false)
        ..sort((a, b) => a.compareTo(b));
      return ExpansionTile(
        initiallyExpanded:
            depth == 0 &&
            (label == 'authenticityAudit' || label == 'authenticity_audit'),
        title: Text(normalizedLabel),
        childrenPadding: const EdgeInsets.only(left: 12, right: 12, bottom: 8),
        children: [
          for (final k in keys) _analysisTreeNode(l10n, k, map[k], depth + 1),
        ],
      );
    }

    if (value is List) {
      final items = value.cast<dynamic>();
      return ExpansionTile(
        title: Text('$normalizedLabel (${items.length})'),
        childrenPadding: const EdgeInsets.only(left: 12, right: 12, bottom: 8),
        children: [
          for (var i = 0; i < items.length; i++)
            _analysisTreeNode(l10n, '#${i + 1}', items[i], depth + 1),
        ],
      );
    }

    final s = (value ?? '').toString().trim();
    return _aiFieldRow(l10n, label, s);
  }

  Widget _aiAnalysisContent(
    LocalizationState l10n,
    Object? analysis, {
    bool showSummary = true,
  }) {
    final map = _coerceAnalysisMap(analysis);
    if (map == null) {
      return Align(
        alignment: Alignment.centerLeft,
        child: Text(l10n.getString('adminVerificationNoAnalysis')),
      );
    }

    final decision = showSummary
        ? _firstStringValue(map, const [
            'decision',
            'verdict',
            'result',
            'status',
            'label',
            'classification',
          ])
        : null;
    final match = showSummary
        ? _firstBoolValue(map, const [
            'match',
            'is_match',
            'face_match',
            'same_person',
            'verified',
          ])
        : null;
    final confidence = showSummary
        ? _firstNumValue(map, const [
            'confidence',
            'match_confidence',
            'probability',
            'score',
            'similarity',
            'similarity_score',
          ])
        : null;
    final reasons = showSummary
        ? _stringListValue(map, const [
            'reasons',
            'reason',
            'rejection_reasons',
            'issues',
            'notes',
            'explanations',
          ])
        : const <String>[];
    final flags = showSummary
        ? _stringListValue(map, const [
            'flags',
            'warnings',
            'alerts',
            'signals',
          ])
        : const <String>[];

    final summaryChips = showSummary
        ? <Widget>[
            if (decision != null)
              _MetaChip(
                label: l10n.getString('adminVerificationAiDecision'),
                value: decision,
              ),
            if (match != null)
              _MetaChip(
                label: l10n.getString('adminVerificationAiMatch'),
                value: match
                    ? l10n.getString('adminYes')
                    : l10n.getString('adminNo'),
              ),
            if (confidence != null)
              _MetaChip(
                label: l10n.getString('adminVerificationAiConfidence'),
                value: _formatConfidence(confidence),
              ),
          ]
        : const <Widget>[];

    final priority = <String>[
      'authenticityAudit',
      'authenticity_audit',
      'comparedAt',
      'compared_at',
      'confidence',
      'gestureCode',
      'gesture_code',
      'gesturePrompt',
      'gesture_prompt',
      'isMatch',
      'is_match',
      'similarity',
      'service',
      'note',
      'reasoning',
    ];
    final allKeys = map.keys.map((k) => k.toString()).toSet();
    final ordered = <String>[
      for (final k in priority)
        if (allKeys.contains(k)) k,
      ...allKeys.where((k) => !priority.contains(k)).toList()..sort(),
    ];

    return Column(
      crossAxisAlignment: CrossAxisAlignment.start,
      children: [
        if (showSummary) ...[
          Text(
            l10n.getString('adminVerificationAiSummaryTitle'),
            style: Theme.of(context).textTheme.titleSmall,
          ),
          const SizedBox(height: 8),
          if (summaryChips.isEmpty)
            Align(
              alignment: Alignment.centerLeft,
              child: Text(
                l10n.getString('adminVerificationAiSummaryUnavailable'),
              ),
            )
          else
            Wrap(spacing: 8, runSpacing: 8, children: summaryChips),
          if (reasons.isNotEmpty) ...[
            const SizedBox(height: 12),
            Text(
              l10n.getString('adminVerificationAiReasons'),
              style: Theme.of(context).textTheme.titleSmall,
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [for (final r in reasons) Chip(label: Text(r))],
            ),
          ],
          if (flags.isNotEmpty) ...[
            const SizedBox(height: 12),
            Text(
              l10n.getString('adminVerificationAiFlags'),
              style: Theme.of(context).textTheme.titleSmall,
            ),
            const SizedBox(height: 8),
            Wrap(
              spacing: 8,
              runSpacing: 8,
              children: [for (final f in flags) Chip(label: Text(f))],
            ),
          ],
          const SizedBox(height: 12),
        ],
        for (final k in ordered) ...[
          _analysisTreeNode(l10n, k, map[k], 0),
          const Divider(height: 1),
        ],
        ExpansionTile(
          title: Text(l10n.getString('adminVerificationAiRawJson')),
          childrenPadding: const EdgeInsets.only(
            left: 12,
            right: 12,
            bottom: 12,
          ),
          children: [
            SelectableText(const JsonEncoder.withIndent('  ').convert(map)),
          ],
        ),
      ],
    );
  }

