      if (!mounted) return;
      ScaffoldMessenger.of(context).showSnackBar(
        SnackBar(content: Text(l10n.getString('adminVerificationNoPhoto'))),
      );
      return;
    }

    if (!mounted) return;
    await showDialog<void>(
      context: context,
      builder: (ctx) {
        final maxHeight =
            (MediaQuery.of(ctx).size.height -
                MediaQuery.of(ctx).viewPadding.vertical) *
