        final statusLabel = _statusLabel(l10n, row.status);
        String fmt(DateTime? v) =>
            v == null ? '' : _formatAdminDateTime(l10n, v);

        String fieldLabel(String key) {
          switch (key) {
            case 'name':
              return l10n.getString('profileEditFieldLabelName');
            case 'date_of_birth':
              return l10n.getString('profileEditFieldLabelDateOfBirth');
            case 'gender':
              return l10n.getString('profileEditFieldLabelGender');
