        final reviewerName = row.reviewerName.trim();
        final reviewerId = row.reviewedBy.trim();
        final reviewerNote = row.reviewerNote.trim();

        final showUpdatedEvent =
            row.updatedAt != null &&
            row.createdAt != null &&
            row.updatedAt!.millisecondsSinceEpoch !=
                row.createdAt!.millisecondsSinceEpoch &&
