  @override
  Widget build(BuildContext context) {
    final l10n = ref.watch(localizationProvider);

    if (_isLoading) {
      return Center(child: Text(l10n.getString('generalLoading')));
    }

    if (_errorKey != null) {
      return Center(
        child: ConstrainedBox(
          constraints: const BoxConstraints(maxWidth: 520),
          child: Padding(
            padding: const EdgeInsets.all(24),
            child: Column(
              mainAxisSize: MainAxisSize.min,
              children: [
                Text(l10n.getString(_errorKey!), textAlign: TextAlign.center),
                const SizedBox(height: 12),
                ElevatedButton.icon(
                  onPressed: () => _load(force: true),
                  icon: const Icon(Icons.refresh),
                  label: Text(l10n.getString('generalRefresh')),
                ),
              ],
            ),
          ),
        ),
      );
    }

    final filtered = _rows
        .where((r) {
          if (_status == 'completed' && !r.changeComplete) return false;
          final q = _query.trim().toLowerCase();
          if (q.isEmpty) return true;
          return r.userId.toLowerCase().contains(q) ||
              r.userName.toLowerCase().contains(q) ||
              r.requestedFields.join(',').toLowerCase().contains(q) ||
              r.message.toLowerCase().contains(q);
        })
        .toList(growable: false);

    return Padding(
      padding: const EdgeInsets.all(24),
      child: Column(
        crossAxisAlignment: CrossAxisAlignment.start,
        children: [
          Wrap(
            spacing: 12,
            runSpacing: 12,
            crossAxisAlignment: WrapCrossAlignment.center,
            children: [
              SizedBox(
                width: 320,
                child: TextField(
                  onChanged: (v) => setState(() => _query = v),
                  decoration: InputDecoration(
                    hintText: l10n.getString('adminProfileEditsSearchHint'),
                    prefixIcon: const Icon(Icons.search),
                    border: const OutlineInputBorder(),
                  ),
                ),
              ),
              DropdownMenu<String>(
                initialSelection: _status,
                dropdownMenuEntries: [
                  DropdownMenuEntry(
                    value: 'all',
                    label: l10n.getString('adminStatusAll'),
                  ),
                  DropdownMenuEntry(
                    value: 'pending',
                    label: l10n.getString('adminStatusPending'),
                  ),
                  DropdownMenuEntry(
                    value: 'approved',
                    label: l10n.getString('adminStatusApproved'),
                  ),
                  DropdownMenuEntry(
                    value: 'rejected',
                    label: l10n.getString('adminStatusRejected'),
                  ),
                  DropdownMenuEntry(
                    value: 'completed',
                    label: l10n.getString('adminStatusComplete'),
                  ),
                ],
                onSelected: (v) {
                  if (v == null) return;
                  setState(() {
                    _status = v;
                  });
                  unawaited(_load(force: true));
                },
                label: Text(l10n.getString('adminProfileEditsStatusFilter')),
                inputDecorationTheme: const InputDecorationTheme(
                  border: OutlineInputBorder(),
                ),
              ),
              Text(
                l10n
                    .getString('adminProfileEditsCount')
                    .replaceAll('{count}', filtered.length.toString()),
              ),
            ],
          ),
          const SizedBox(height: 12),
          Expanded(
            child: filtered.isEmpty
                ? Center(child: Text(l10n.getString('adminProfileEditsEmpty')))
                : ListView.separated(
                    itemCount: filtered.length,
                    separatorBuilder: (context, index) =>
                        const SizedBox(height: 8),
                    itemBuilder: (context, i) {
                      final row = filtered[i];
                      final statusLabel = _statusLabel(l10n, row.status);
                      final created = row.createdAt == null
                          ? ''
                          : _formatAdminDateTime(l10n, row.createdAt!);
                      final reviewedAt = row.reviewedAt == null
                          ? ''
                          : _formatAdminDateTime(l10n, row.reviewedAt!);
                      final reviewer = maskUserDisplayName(
                        row.reviewerName.trim(),
                      );
                      final reviewerNote = row.reviewerNote.trim();
                      final reason = row.message.trim();
                      String shortNote(String v) {
                        final singleLine = v
                            .replaceAll(RegExp(r'\s+'), ' ')
                            .trim();
                        if (singleLine.length <= 80) return singleLine;
                        return '${singleLine.substring(0, 77)}…';
                      }

                      String shortReason(String v) {
                        final singleLine = v
                            .replaceAll(RegExp(r'\s+'), ' ')
                            .trim();
                        if (singleLine.length <= 220) return singleLine;
                        return '${singleLine.substring(0, 217)}…';
                      }

                      final reviewed = [
                        if (reviewedAt.isNotEmpty) reviewedAt,
                        if (reviewerNote.isNotEmpty) shortNote(reviewerNote),
                        if (reviewer.isNotEmpty) reviewer,
                      ].join(' • ');

                      String requestedFieldSummary(List<String> fields) {
                        final clean = fields
                            .map((e) => e.trim())
                            .where((e) => e.isNotEmpty)
                            .toList(growable: false);
                        if (clean.isEmpty) return '';
                        if (clean.length == 1) return clean.first;
                        return '${clean.first} +${clean.length - 1}';
                      }

                      Widget statusBadge() {
                        if (row.changeComplete) {
                          final scheme = Theme.of(context).colorScheme;
                          return DecoratedBox(
                            decoration: ShapeDecoration(
                              color: scheme.primary.withAlpha(25),
                              shape: StadiumBorder(
                                side: BorderSide(
                                  color: scheme.primary.withAlpha(77),
                                ),
                              ),
                            ),
                            child: Padding(
                              padding: const EdgeInsets.symmetric(
                                horizontal: 10,
                                vertical: 6,
                              ),
                              child: Text(
                                l10n.getString('adminStatusComplete'),
                                style: Theme.of(context).textTheme.labelMedium
                                    ?.copyWith(color: scheme.primary),
                              ),
                            ),
                          );
                        }
                        final scheme = Theme.of(context).colorScheme;
                        final (bg, fg, border) = switch (row.status) {
                          'approved' => (
                            Colors.green.shade700,
                            Colors.white,
                            null,
                          ),
                          'rejected' => (
                            Colors.red.shade700,
                            Colors.white,
                            null,
                          ),
                          _ => (
                            scheme.surface,
                            scheme.onSurface,
                            BorderSide(color: Theme.of(context).dividerColor),
                          ),
                        };
                        return DecoratedBox(
                          decoration: ShapeDecoration(
                            color: bg,
                            shape: StadiumBorder(
                              side: border ?? BorderSide.none,
                            ),
                          ),
                          child: Padding(
                            padding: const EdgeInsets.symmetric(
                              horizontal: 10,
                              vertical: 6,
                            ),
                            child: Text(
                              statusLabel,
                              style: Theme.of(
                                context,
                              ).textTheme.labelMedium?.copyWith(color: fg),
                            ),
                          ),
                        );
                      }

                      final fieldSummary = requestedFieldSummary(
                        row.requestedFields,
                      );

                      return Card(
                        child: InkWell(
                          onTap: () => _showDetails(l10n, row),
                          child: Padding(
                            padding: const EdgeInsets.all(12),
                            child: Column(
                              crossAxisAlignment: CrossAxisAlignment.start,
                              children: [
                                Row(
                                  crossAxisAlignment: CrossAxisAlignment.center,
                                  children: [
                                    Flexible(
                                      child: Text(
                                        row.userName.trim().isEmpty
                                            ? row.userId
                                            : maskUserDisplayName(row.userName),
                                        style: Theme.of(
                                          context,
                                        ).textTheme.titleMedium,
                                        overflow: TextOverflow.ellipsis,
                                        textDirection:
                                            isRtlText(
                                              row.userName.trim().isEmpty
                                                  ? row.userId
                                                  : maskUserDisplayName(
                                                      row.userName,
                                                    ),
                                            )
                                            ? TextDirection.rtl
                                            : TextDirection.ltr,
                                      ),
                                    ),
                                    if (fieldSummary.isNotEmpty) ...[
                                      const SizedBox(width: 8),
                                      DecoratedBox(
                                        decoration: BoxDecoration(
                                          border: Border.all(
                                            color: Theme.of(
                                              context,
                                            ).dividerColor,
                                          ),
                                          borderRadius: BorderRadius.circular(
                                            999,
                                          ),
                                        ),
                                        child: Padding(
                                          padding: const EdgeInsets.symmetric(
                                            horizontal: 10,
                                            vertical: 6,
                                          ),
                                          child: Text(
                                            fieldSummary,
                                            style: Theme.of(
                                              context,
                                            ).textTheme.labelMedium,
                                          ),
                                        ),
                                      ),
                                    ],
                                    const SizedBox(width: 8),
                                    Wrap(
                                      spacing: 8,
                                      runSpacing: 8,
                                      children: [statusBadge()],
                                    ),
                                  ],
                                ),
                                const SizedBox(height: 8),
                                Wrap(
                                  spacing: 8,
                                  runSpacing: 8,
                                  children: [
                                    if (created.isNotEmpty)
                                      _MetaChip(
                                        label: l10n.getString(
                                          'adminProfileEditsCreated',
                                        ),
                                        value: created,
                                      ),
                                    if (reviewed.isNotEmpty)
                                      _MetaChip(
                                        label: l10n.getString(
                                          'adminVerificationReviewed',
                                        ),
                                        value: reviewed,
                                      ),
                                    if (row.attachments.isNotEmpty)
                                      _MetaChip(
                                        label: l10n.getString(
                                          'adminProfileEditsAttachmentsShort',
                                        ),
                                        value: row.attachments.length
                                            .toString(),
                                      ),
                                  ],
                                ),
                                if (reason.isNotEmpty) ...[
                                  const SizedBox(height: 10),
                                  Text(
                                    shortReason(reason),
                                    maxLines: 3,
                                    overflow: TextOverflow.ellipsis,
                                    textAlign: isRtlText(reason)
                                        ? TextAlign.right
                                        : TextAlign.left,
                                    textDirection: isRtlText(reason)
                                        ? TextDirection.rtl
                                        : TextDirection.ltr,
                                    style: Theme.of(
                                      context,
                                    ).textTheme.bodyMedium,
                                  ),
                                ],
                                const SizedBox(height: 12),
                                Align(
                                  alignment: Alignment.centerRight,
                                  child: Wrap(
                                    spacing: 8,
                                    runSpacing: 8,
                                    alignment: WrapAlignment.end,
                                    children: [
                                      OutlinedButton.icon(
                                        onPressed: () =>
                                            _showDetails(l10n, row),
                                        icon: const Icon(Icons.open_in_new),
                                        label: Text(
                                          l10n.getString(
                                            'adminProfileEditsDetails',
                                          ),
                                        ),
                                      ),
                                      ElevatedButton.icon(
                                        onPressed:
                                            (row.status == 'approved' ||
                                                row.changeComplete)
                                            ? null
                                            : () => _review(
                                                l10n,
                                                row,
                                                'approved',
                                              ),
                                        style: ElevatedButton.styleFrom(
                                          backgroundColor:
                                              Colors.green.shade700,
                                          foregroundColor: Colors.white,
                                          disabledBackgroundColor: Theme.of(
                                            context,
                                          ).colorScheme.surfaceContainerHighest,
                                          disabledForegroundColor: Theme.of(
                                            context,
                                          ).colorScheme.onSurface.withAlpha(97),
                                        ),
                                        icon: const Icon(Icons.check),
                                        label: Text(
                                          l10n.getString('adminApprove'),
                                        ),
                                      ),
                                      ElevatedButton.icon(
                                        onPressed:
                                            (row.status == 'rejected' ||
                                                row.changeComplete)
                                            ? null
                                            : () => _review(
                                                l10n,
                                                row,
                                                'rejected',
                                              ),
                                        style: ElevatedButton.styleFrom(
                                          backgroundColor: Colors.red.shade700,
                                          foregroundColor: Colors.white,
                                          disabledBackgroundColor: Theme.of(
                                            context,
                                          ).colorScheme.surfaceContainerHighest,
                                          disabledForegroundColor: Theme.of(
                                            context,
                                          ).colorScheme.onSurface.withAlpha(97),
                                        ),
                                        icon: const Icon(Icons.close),
                                        label: Text(
                                          l10n.getString('adminReject'),
                                        ),
                                      ),
                                    ],
                                  ),
                                ),
                              ],
                            ),
                          ),
                        ),
                      );
                    },
                  ),
          ),
        ],
      ),
    );
  }
}

